G.bankAll({"k1":{"pre":[{"q":"Vad betyder det att ett fett är mättat?","o":["Det har bara enkelbindningar mellan kolatomerna","Det har många dubbelbindningar","Det är flytande vid rumstemperatur","Det innehåller fosfat"],"why":"Mättat fett har bara enkelbindningar. Kedjan blir rak och fettet fast vid rumstemperatur.","src":"PPT Bi2 bild 10","id":"k1p1nx1m48"},{"q":"Vad består sackaros (strösocker) av?","o":["Glukos + fruktos","Två glukos","Glukos + laktos","Glycerol + fettsyror"],"why":"En ring glukos och en ring fruktos ger sackaros.","src":"PPT Bi2 bild 6","id":"k1pj4urnn"},{"q":"Varför har ishavsfiskar mycket fleromättade fettsyror i sina cellmembran?","o":["Annars skulle membranen stelna i det kalla vattnet","För att de ska flyta bättre","För att de lagrar energi till vintern","För att de saknar kolesterol"],"why":"Knyckiga fleromättade fettsyror håller membranet flytande vid låg temperatur.","src":"s. 18","t":["membran"],"id":"k1p10y5va0"},{"q":"Vilka tre delar har en nukleotid?","o":["Fosfatgrupp, socker och kvävebas","Glycerol och tre fettsyror","Huvud och två svansar","Aminosyror och vatten"],"why":"Nukleotid = fosfatgrupp + monosackarid + kvävebas.","src":"PPT Bi2 bild 27","id":"k1pq79od1"},{"q":"Hur många aminosyror är essentiella enligt läraren?","o":["8","12","20","4"],"why":"Cellerna kan tillverka 12 av 20. De övriga 8 måste fås via maten.","src":"PPT Bi2 bild 16","id":"k1p1uhu7l4"}],"cards":[{"f":"Vad består celler främst av, förutom vatten?","b":"Kolföreningar (organiska ämnen): kolhydrater, lipider och proteiner (och nukleinsyror).","ty":"b","src":"PPT Bi2 bild 3","id":"k1cci8nsh"},{"f":"Vad kallas de oorganiska ämnen som celler behöver?","b":"Närsalter eller mineralämnen, till exempel kväve och fosfor.","ty":"b","src":"PPT Bi2 bild 3 · s. 244","p":1,"id":"k1cb8ht8a"},{"f":"Vad betyder \"organiskt ämne\" i biologin?","b":"En kolförening.","ty":"b","src":"PPT Bi2 bild 3","id":"k1chbroio"},{"f":"Vilka atomer bygger kolhydrater?","b":"Kol, väte och syre. Kol-hydrat = kol + vatten.","ty":"b","src":"PPT Bi2 bild 4","id":"k1c1e8wjvw"},{"f":"Vad är en monosackarid?","b":"En enkel sockerart med en sockerring, t.ex. glukos och fruktos.","ty":"b","src":"PPT Bi2 bild 5","id":"k1c1yz6661"},{"f":"Glukos kemiska formel?","b":"C₆H₁₂O₆ (6 kol, 12 väte, 6 syre).","ty":"s","src":"PPT Bi2 bild 5","id":"k1c14dmmm3"},{"f":"Vardagsnamnet på glukos?","b":"Druvsocker.","ty":"s","src":"PPT Bi2 bild 5","id":"k1c1gb1fh5"},{"f":"Vardagsnamnet på fruktos?","b":"Fruktsocker.","ty":"s","src":"PPT Bi2 bild 5","id":"k1cbi72iq"},{"f":"Var finns enkla sockerarter enligt läraren?","b":"Till exempel i bär, frukt och honung.","ty":"s","src":"PPT Bi2 bild 5","id":"k1c99cpem"},{"f":"Hur skiljer sig α-glukos från β-glukos?","b":"OH-gruppen vid kol 1 pekar nedåt i α och uppåt i β.","ty":"j","src":"PPT Bi2 bild 4","id":"k1coxykpq"},{"f":"Vad är en disackarid?","b":"Två sockerringar ihopkopplade, en sammansatt sockerart.","ty":"b","src":"PPT Bi2 bild 6","id":"k1ctmx3bd"},{"f":"Vad består sackaros av, och vad kallas det i vardagen?","b":"Glukos + fruktos. Vanligt socker (strösocker).","ty":"s","src":"PPT Bi2 bild 6","id":"k1ctzg8n7"},{"f":"Vad heter mjölksocker och maltsocker kemiskt?","b":"Laktos och maltos. Båda är disackarider.","ty":"s","src":"PPT Bi2 bild 6","id":"k1cyfd4ln"},{"f":"Vad är en polysackarid? Ge två exempel.","b":"Många sockerringar i en kedja. Cellulosa och stärkelse.","ty":"b","src":"PPT Bi2 bild 7","id":"k1c1bk7m8v"},{"f":"Var finns cellulosa?","b":"I växternas cellväggar.","ty":"s","t":["vagg"],"src":"PPT Bi2 bild 7 · s. 244","p":1,"id":"k1c1xz6hgb"},{"f":"Varför kallas cellulosa kostfiber, och varför är de nyttiga?","b":"Människan kan inte bryta ner cellulosa, så den passerar tarmen. Den motverkar förstoppning och ger mättnadskänsla.","ty":"v","src":"PPT Bi2 bild 7","id":"k1c26tl9y"},{"f":"Var finns stärkelse, och var lagras den i växten?","b":"T.ex. i potatis. Leukoplaster (färglösa plastider) lagrar stärkelse i potatisens stamknölar.","ty":"s","src":"PPT Bi2 bild 7 · s. 247","p":1,"id":"k1cdx6zt6"},{"f":"Hur lagrar levercellerna energi?","b":"Som glykogen i inklusionskroppar.","ty":"s","src":"s. 21","id":"k1c15q6tea"},{"f":"Vad är glykokalyx?","b":"Kolhydratlagret (sockerkedjor på lipider och proteiner) som täcker en eukaryot cell och skyddar den.","ty":"b","t":["membran"],"src":"s. 19–20 · korsord 8 vågrätt","id":"k1c1pnom00"},{"f":"Vad är lipider?","b":"Ämnen som är olösliga eller mycket svårlösliga i vatten, t.ex. fetter och fosfolipider.","ty":"b","src":"PPT Bi2 bild 8","id":"k1cdbc98y"},{"f":"Vad är en fettmolekyl byggd av?","b":"En glycerol och tre fettsyror. Fettsyrorna domineras av en lång kolkedja.","ty":"b","src":"PPT Bi2 bild 9","id":"k1c4wr19e"},{"f":"Vad sitter i ena änden av en fettsyra i lärarens strukturformel?","b":"En karboxylgrupp (COOH), ritad i rött.","ty":"i","src":"PPT Bi2 bild 11","id":"k1cykvjuh"},{"f":"Vad är mättat fett?","b":"Fett där det bara finns enkelbindningar mellan kolatomerna. Raka kedjor, fast vid rumstemperatur.","ty":"b","src":"PPT Bi2 bild 10","id":"k1c2iye4s"},{"f":"Två exempel på mättat fett enligt läraren?","b":"Animaliskt fett och kokosfett.","ty":"s","src":"PPT Bi2 bild 10","id":"k1c26xh0i"},{"f":"Vilken hälsorisk kopplar läraren till mättat fett?","b":"Ökad risk för åderförkalkning.","ty":"s","src":"PPT Bi2 bild 10","id":"k1c8mtocn"},{"f":"Omättat jämfört med fleromättat fett?","b":"Omättat har en dubbelbindning mellan kolatomerna, fleromättat har fler än en.","ty":"j","src":"PPT Bi2 bild 12","id":"k1c18y335f"},{"f":"Exempel på omättat fett, och hur det beter sig vid rumstemperatur?","b":"Vegetabiliskt fett och fiskfett. Flytande vid rumstemperatur.","ty":"s","src":"PPT Bi2 bild 12","id":"k1c1g8i2jt"},{"f":"Vad händer med fettsyrakedjan vid en dubbelbindning?","b":"Den får en knyck. Fler dubbelbindningar ger fler knyckar och mer böjd kedja.","ty":"i","src":"PPT Bi2 bild 11, 13","id":"k1c15ytbgi"},{"f":"Varför är omättat fett flytande men mättat fast?","b":"Knyckarna gör att omättade kedjor inte kan packas tätt. Avståndet blir större och van der Waals-krafterna svagare. Raka mättade kedjor packas tätt.","ty":"v","t":["membran"],"src":"s. 18 · PPT Bi2 bild 10–13","p":1,"id":"k1c12x93p2"},{"f":"Hur påverkar omättade fettsyror cellmembranet?","b":"Membranet hålls flytande vid lägre temperatur, eftersom veckade svansar ger större avstånd och svagare van der Waals-krafter.","ty":"v","t":["membran"],"src":"s. 18","p":1,"id":"k1c1bg4z6"},{"f":"Varför har ishavsfisk mycket fleromättade fettsyror?","b":"Annars skulle det kalla vattnet få cellmembranen att stelna och sluta fungera.","ty":"v","t":["membran"],"src":"s. 18","p":1,"id":"k1c1pddz7h"},{"f":"Hur påverkar fettsyrornas längd membranet?","b":"Längre fettsyror ger större yta för van der Waals-krafter och därför ett mer trögflytande membran (högre fryspunkt).","ty":"v","t":["membran"],"src":"s. 18","id":"k1cchqbwn"},{"f":"Vilka krafter håller ihop fosfolipiderna i membranet?","b":"De relativt svaga van der Waals-krafterna.","ty":"s","t":["membran"],"src":"s. 18","id":"k1cudvirb"},{"f":"Vad bygger upp cellernas membran enligt läraren?","b":"Fosfolipider tillsammans med en mindre mängd kolesterol.","ty":"b","t":["membran"],"src":"PPT Bi2 bild 14 · s. 17–18","p":1,"id":"k1c1bdmxzs"},{"f":"Fosfolipidens två delar?","b":"Hydrofilt huvud med en fosfatgrupp (vattenlösligt) och hydrofob svans (fettlöslig).","ty":"b","t":["membran"],"src":"PPT Bi2 bild 14 · s. 17","p":1,"id":"k1c1nluh3c"},{"f":"Hydrofil jämfört med hydrofob?","b":"Hydrofil = vattenälskande, vattenlöslig (huvudet). Hydrofob = vattenskyende, fettlöslig (svansen).","ty":"j","t":["membran"],"src":"PPT Bi2 bild 14","p":1,"id":"k1c3t3idn"},{"f":"Hur ligger fosfolipiderna i cellmembranet?","b":"I ett dubbelt lager med fettsyrasvansarna mot varandra och de hydrofila huvudena utåt mot cellens inre och yttre miljö.","ty":"i","t":["membran"],"src":"s. 17 · PPT Bi2 bild 14","p":1,"id":"k1c1metlh2"},{"f":"Vad gör kolesterolet i cellmembranet?","b":"Det hjälper djurcellens membran att hålla sig lagom flytande. Kolesterol är en steroid.","ty":"b","t":["membran"],"src":"s. 18 · PPT Bi2 bild 14 · korsord 9 vågrätt","p":1,"id":"k1c1wtjkst"},{"f":"LDL och HDL enligt boken?","b":"Partiklar av kolesterol + protein. LDL har mer kolesterol per protein (\"det onda\"). HDL för överskottskolesterol till levern (\"det goda\").","ty":"j","src":"s. 36 · PPT Bi2 bild 14","p":1,"id":"k1c10bp0lg"},{"f":"Provfälla: LDL och HDL är två sorters kolesterol?","b":"Nej, enligt boken är de partiklar som transporterar kolesterol. Läraren skriver \"olika typer av kolesterol\", men använd bokens formulering.","ty":"f","src":"s. 36 · PPT Bi2 bild 14","id":"k1c1nmylqv"},{"f":"Provfälla: är fosfolipider fetter?","b":"Läraren kallar dem både \"lipider\" (bild 8) och \"en grupp av fetter\" (bild 14). Säg lipider.","ty":"f","src":"PPT Bi2 bild 8, 14","id":"k1cb1n8as"},{"f":"Tre saker som proteiner är eller gör enligt läraren?","b":"Byggmaterial till cellerna. Vissa hormoner och enzymer. Blodfärgämnet hemoglobin.","ty":"s","src":"PPT Bi2 bild 15","id":"k1c58ieki"},{"f":"Vad består ett protein av?","b":"Upp till 20 olika sorters aminosyror sammanlänkade i en viss ordning.","ty":"b","src":"PPT Bi2 bild 15","id":"k1cfp40h1"},{"f":"Vad är essentiella aminosyror, och hur många är de?","b":"Aminosyror som cellerna inte kan tillverka och som måste ingå i födan. 8 av 20 (cellerna tillverkar 12).","ty":"s","src":"PPT Bi2 bild 16","id":"k1c174znfj"},{"f":"Exempel på proteinrik mat?","b":"Ägg, fisk, mjölk, ärtor och bönor.","ty":"s","src":"PPT Bi2 bild 16","id":"k1c1p1ahl0"},{"f":"Var tillverkas proteinerna i cellen?","b":"På ribosomerna.","ty":"s","t":["ribosom"],"src":"PPT Bi2 bild 22 · s. 23","p":1,"id":"k1cyoaibd"},{"f":"Vad är en nukleotid uppbyggd av?","b":"Fosfatgrupp + monosackarid (ribos eller deoxiribos) + kvävebas.","ty":"b","src":"PPT Bi2 bild 27","id":"k1c1gtmcw6"},{"f":"Vilka två roller har nukleotider?","b":"De bygger upp nukleinsyror (DNA, RNA) och är energibärare (ATP).","ty":"b","t":["atp"],"src":"PPT Bi2 bild 28","id":"k1c1wp24nh"},{"f":"De fem kvävebaserna, och vilka är dubbelringar?","b":"Adenin, guanin (dubbelringar), cytosin, tymin, uracil (enkelringar).","ty":"s","src":"PPT Bi2 bild 27","id":"k1cvlj4xh"},{"f":"DNA jämfört med RNA: socker och baser?","b":"DNA: deoxiribos, A T C G. RNA: ribos, A U C G.","ty":"j","src":"PPT Bi2 bild 27","id":"k1c1crtqob"},{"f":"Ribos jämfört med deoxiribos?","b":"Deoxiribos har ett H i stället för ett OH på ett kol, alltså en syreatom mindre.","ty":"j","src":"PPT Bi2 bild 27","id":"k1c1uwbyj6"},{"f":"Vad är ATP byggt av?","b":"Adenin + ribos + tre fosfatgrupper. När den tredje fosfatgruppen lossnar frigörs energi.","ty":"b","t":["atp"],"src":"PPT Bi2 bild 29 · s. 35","id":"k1cofwj7o"},{"f":"Nukleotid jämfört med nukleinsyra?","b":"Nukleotiden är byggstenen. Nukleinsyran (DNA eller RNA) är kedjan av nukleotider.","ty":"j","src":"PPT Bi2 bild 27–28","id":"k1c17n7po7"}],"quiz":{"f":[{"q":"Vilka tre grupper av organiska ämnen nämner läraren först?","o":["Kolhydrater, lipider och proteiner","Vatten, salter och syre","Närsalter, mineraler och vitaminer","DNA, RNA och ATP"],"why":"PPT Bi2 bild 3. Nukleinsyrorna kommer på bild 28.","src":"PPT Bi2 bild 3","id":"k1q1m7l7rq"},{"q":"Vad kallas oorganiska ämnen som kväve och fosfor som växter tar upp?","o":["Närsalter","Kolhydrater","Organiska ämnen","Enzymer"],"why":"Bok s. 244 och PPT Bi2 bild 3: närsalter eller mineralämnen.","src":"s. 244 · PPT Bi2 bild 3","id":"k1q1bxo609"},{"q":"Vad är glukos kemiska formel?","o":["C₆H₁₂O₆","C₁₂H₂₂O₁₁","H₂O","CO₂"],"why":"Glukos (druvsocker) har 6 kol, 12 väte och 6 syre.","src":"PPT Bi2 bild 5","id":"k1q1dvl1ns"},{"q":"Vilken av molekylerna är en disackarid?","o":["Laktos","Glukos","Fruktos","Cellulosa"],"why":"Laktos (mjölksocker) är två sockerringar. Glukos och fruktos är monosackarider, cellulosa en polysackarid.","src":"PPT Bi2 bild 6","id":"k1q1ge7zb3"},{"q":"Vilka två monosackarider bildar sackaros?","o":["Glukos och fruktos","Glukos och glukos","Fruktos och laktos","Maltos och glukos"],"why":"PPT Bi2 bild 6.","src":"PPT Bi2 bild 6","id":"k1q15172br"},{"q":"Vilken polysackarid kan människan inte bryta ner?","o":["Cellulosa","Stärkelse","Glykogen","Sackaros"],"why":"Cellulosa passerar tarmen som kostfiber.","src":"PPT Bi2 bild 7","id":"k1qztiv4t"},{"q":"Var lagrar potatisen stärkelse enligt boken?","o":["I leukoplaster i stamknölarna","I kloroplasterna i bladen","I cellväggen","I vakuolen i rötterna"],"why":"Bok s. 247: leukoplaster är färglösa plastider som lagrar stärkelse, t.ex. i potatisens stamknölar.","src":"s. 247 · PPT Bi2 bild 7","id":"k1qsrxego"},{"q":"Vad skiljer α-glukos från β-glukos?","o":["Riktningen på OH-gruppen vid kol 1","Antalet kolatomer","α-glukos är en femring","β-glukos saknar syre"],"why":"OH vid kol 1 nedåt i α, uppåt i β (röda pilar på bild 4).","src":"PPT Bi2 bild 4","id":"k1qcj88hf"},{"q":"Vad är en fettmolekyl byggd av?","o":["En glycerol och tre fettsyror","Tre glycerol och en fettsyra","En fosfatgrupp och två fettsyror","Aminosyror"],"why":"PPT Bi2 bild 9.","src":"PPT Bi2 bild 9","id":"k1q4wr19e"},{"q":"Vilket fett ger läraren som exempel på mättat fett?","o":["Kokosfett","Fiskfett","Olivolja","Rapsolja"],"why":"Animaliskt fett och kokosfett är mättade.","src":"PPT Bi2 bild 10","id":"k1q1i75eyb"},{"q":"Hur många dubbelbindningar har en fleromättad fettsyra?","o":["Fler än en","Ingen","Exakt en","Bara enkelbindningar"],"why":"PPT Bi2 bild 12.","src":"PPT Bi2 bild 12","id":"k1qrz4rzh"},{"q":"Vilka krafter håller ihop fosfolipiderna i membranet enligt boken?","o":["Van der Waals-krafter","Kovalenta bindningar","Magnetiska krafter","Jonbindningar"],"why":"Bok s. 18: de relativt svaga van der Waals-krafterna.","src":"s. 18","t":["membran"],"id":"k1qehgxoz"},{"q":"Vilket djur har ovanligt mycket fleromättade fettsyror i cellmembranen?","o":["Ishavsfisk","Kamel","Ko","Bakterier i varma källor"],"why":"Det kalla vattnet skulle annars få membranen att stelna.","src":"s. 18","t":["membran"],"id":"k1qcngcn5"},{"q":"Vad har fosfolipidens hydrofila huvud?","o":["En fosfatgrupp","Tre fettsyror","En kvävebas","Kolesterol"],"why":"PPT Bi2 bild 14: hydrofilt huvud med en fosfatgrupp.","src":"PPT Bi2 bild 14","t":["membran"],"id":"k1q7ux1kz"},{"q":"Vad hjälper djurcellens membran att hålla sig lagom flytande?","o":["Kolesterol","Cellulosa","Hemoglobin","Stärkelse"],"why":"Bok s. 18, korsord 9 vågrätt.","src":"s. 18","t":["membran"],"id":"k1q109bt24"},{"q":"Hur många av de 20 aminosyrorna kan cellerna tillverka själva enligt läraren?","o":["12","8","20","2"],"why":"12 tillverkas, 8 är essentiella.","src":"PPT Bi2 bild 16","id":"k1qyxcs3y"},{"q":"Vilket ämne är ett protein?","o":["Hemoglobin","Glukos","Kolesterol","Cellulosa"],"why":"Det röda blodfärgämnet hemoglobin består av protein.","src":"PPT Bi2 bild 15","id":"k1qnc8hzd"},{"q":"Vilket socker finns i DNA?","o":["Deoxiribos","Ribos","Glukos","Fruktos"],"why":"DNA = deoxiribonukleinsyra.","src":"PPT Bi2 bild 27","id":"k1q1vp7kkw"},{"q":"Vilka kvävebaser är dubbelringar?","o":["Adenin och guanin","Cytosin och tymin","Uracil och tymin","Cytosin och uracil"],"why":"PPT Bi2 bild 27.","src":"PPT Bi2 bild 27","id":"k1q179t6b3"}],"u":[{"q":"Ett fett är fast vid rumstemperatur. Vad kan du säga om dess fettsyror?","o":["De är troligen mättade, med raka kedjor som packas tätt","De har många dubbelbindningar","De är mycket korta och knyckiga","Fettet saknar glycerol"],"why":"Mättade, raka kedjor packas tätt och ger starkare sammanhållning, så fettet blir fast.","src":"PPT Bi2 bild 10 · s. 18","id":"k1q1sqdv8h"},{"q":"Varför blir van der Waals-krafterna svagare när fettsyrasvansarna är veckade?","o":["Avståndet mellan molekylerna blir större","Dubbelbindningar stöter bort varandra elektriskt","Veckade svansar är kortare och lättare","Veckade svansar löser sig i vatten"],"why":"Bok s. 18: veckade svansar ger större avstånd mellan molekylerna, och då blir krafterna svagare.","src":"s. 18","t":["membran"],"id":"k1qd6dd38"},{"q":"En fisk flyttas från tropiskt vatten till iskallt vatten. Vilken förändring i membranen skulle hjälpa den?","o":["Fler fleromättade och kortare fettsyror","Fler mättade fettsyror","Längre, raka fettsyror","Mindre kolesterol och fler raka svansar"],"why":"Knyckar och korta kedjor ger svagare sammanhållning och håller membranet flytande i kyla (bok s. 18).","src":"s. 18","t":["membran"],"id":"k1q9qnzgu"},{"q":"Varför vänder fosfolipidernas svansar sig mot varandra i membranet?","o":["Svansarna är hydrofoba och undviker vattnet på båda sidor","Svansarna är laddade och attraherar varandra","Huvudena är fettlösliga","Kolesterolet drar ihop svansarna"],"why":"Det finns vatten både utanför och inuti cellen. Huvudena är vattenlösliga och vänds utåt, svansarna gömmer sig inuti.","src":"s. 17 · PPT Bi2 bild 14","t":["membran"],"id":"k1qp5587u"},{"q":"Varför ger cellulosa mättnadskänsla men nästan ingen energi för oss?","o":["Vi kan inte bryta ner den, så den passerar tarmen","Den bryts ner till fett","Den innehåller inga kolatomer","Den är ett protein"],"why":"Människan kan inte bryta ner cellulosa. Den fyller tarmen som kostfiber.","src":"PPT Bi2 bild 7","id":"k1q166z3nh"},{"q":"Cellulosa och stärkelse är båda kedjor av glukos. Vad är det viktigaste som skiljer dem för oss?","o":["Stärkelse kan vi bryta ner, cellulosa inte","Stärkelse finns i cellväggar, cellulosa i potatis","Cellulosa är en monosackarid","Stärkelse innehåller kväve"],"why":"Stärkelse är ett viktigt näringsämne (potatis). Cellulosa i cellväggar kan vi inte bryta ner.","src":"PPT Bi2 bild 7","id":"k1qk94u3"},{"q":"En person äter inte tillräckligt av vissa aminosyror. Vilka är det som riskerar att saknas?","o":["De essentiella, eftersom cellerna inte kan tillverka dem","De 12 som cellerna tillverkar","Alla 20 lika mycket","Inga, cellerna gör alla"],"why":"De 8 essentiella måste ingå i födan.","src":"PPT Bi2 bild 16","id":"k1q1w6cxig"},{"q":"En nukleotid innehåller uracil. Vilken nukleinsyra hör den troligen till?","o":["RNA","DNA","Båda lika ofta","Ingen, uracil är en aminosyra"],"why":"U finns i RNA. DNA har T i stället.","src":"PPT Bi2 bild 27","id":"k1q17odnc6"},{"q":"Varför är ATP en nukleotid?","o":["Den har en kvävebas (adenin), ett socker (ribos) och fosfatgrupper","Den är byggd av aminosyror","Den har glycerol och fettsyror","Den är en sockerring"],"why":"Alla tre delarna i en nukleotid finns i ATP, men med tre fosfat.","src":"PPT Bi2 bild 27–29","t":["atp"],"id":"k1qwa1mk0"},{"q":"Läraren skriver att HDL \"transporterar bort fett\". Vad säger boken mer exakt?","o":["HDL för överskott av kolesterol från vävnaderna till levern","HDL är ett fett som fastnar i kärlen","HDL bryter ner glukos","HDL är ett sorts protein utan kolesterol"],"why":"Bok s. 36: HDL transporterar kolesterol till levern, där det bryts ner.","src":"s. 36 · PPT Bi2 bild 14","id":"k1qag18e8"},{"q":"Varför kallar man kolhydrater just kol-hydrat?","o":["De består av kol samt väte och syre, som i vatten","De bildas bara i vatten","De innehåller kväve","De löser sig inte i vatten"],"why":"Hydrat syftar på vatten (H₂O), alltså väte och syre.","src":"PPT Bi2 bild 4","id":"k1q1u45u4m"}],"o":[{"q":"Beskriv hur en fettmolekyl är uppbyggd och förklara skillnaden mellan mättat, omättat och fleromättat fett. Ge exempel och koppla till cellmembranet.","model":"En fettmolekyl består av en glycerol och tre fettsyror, som domineras av en lång kolkedja. Mättat fett har bara enkelbindningar. Kedjorna blir raka och packas tätt, och fettet är fast vid rumstemperatur, t.ex. animaliskt fett och kokosfett. Omättat fett har en dubbelbindning och fleromättat flera. Dubbelbindningen ger kedjan en knyck, så molekylerna inte kan packas tätt, och fettet är flytande, t.ex. vegetabiliskt fett och fiskfett. I cellmembranet gör veckade omättade fettsyror att avståndet blir större och van der Waals-krafterna svagare, så membranet hålls flytande vid lägre temperatur. Därför har ishavsfisk mycket fleromättade fettsyror.","kw":[["glycerol"],["fettsyr"],["enkelbind"],["dubbelbind"],["fast"],["flytande"],["van der waals","avstånd"],["ishavsfisk"]],"src":"PPT Bi2 bild 9–13 · s. 18","t":["membran"],"id":"k1o1w5vdnf"},{"q":"Beskriv en fosfolipid och förklara hur fosfolipiderna bygger upp cellmembranet.","model":"En fosfolipid är en lipid med ett hydrofilt huvud som innehåller en fosfatgrupp och är vattenlösligt, och en hydrofob svans av fettsyror som är fettlöslig. I cellmembranet bildar fosfolipiderna ett dubbelt lager där fettsyrasvansarna pekar mot varandra och huvudena utåt, mot cellens inre och yttre miljö, eftersom det finns vatten på båda sidor. Membranets inre blir därför fettälskande och vattenhatande, och bara fettlösliga ämnen passerar fritt. Fosfolipiderna glider runt varandra som en tvådimensionell vätska. Hos djurceller finns också kolesterol som håller membranet lagom flytande.","kw":[["hydrofil"],["fosfat"],["hydrofob"],["dubbel"],["mot varandra","inåt"],["kolesterol"],["fettlösl"]],"src":"PPT Bi2 bild 14 · s. 17–18","t":["membran"],"id":"k1o1rmwgna"},{"q":"Redogör för kolhydraterna: vad de består av, de tre grupperna med exempel, och vad cellulosa och stärkelse betyder för oss.","model":"Kolhydrater består av kol, väte och syre (kol + hydrat). Monosackarider är en sockerring, enkla sockerarter som glukos (druvsocker, C6H12O6) och fruktos (fruktsocker) i bär, frukt och honung. Disackarider är två ringar, t.ex. sackaros (glukos + fruktos, strösocker), laktos (mjölksocker) och maltos (maltsocker). Polysackarider är många ringar, t.ex. cellulosa och stärkelse. Cellulosa finns i växternas cellväggar och kan inte brytas ner av människan, men som kostfiber motverkar den förstoppning och ger mättnadskänsla. Stärkelse är ett av våra viktigaste näringsämnen och lagras t.ex. i potatisens stamknölar.","kw":[["kol"],["mono"],["di"],["poly"],["glukos"],["sackaros"],["cellulosa"],["stärkelse"]],"src":"PPT Bi2 bild 4–7 · s. 247","id":"k1o18vk9wy"}]},"kan":[{"q":"Kan du berätta vad celler består av?","a":"Förutom vatten består celler främst av kolföreningar, organiska ämnen: kolhydrater, lipider och proteiner, och dessutom nukleinsyror. Celler är också beroende av oorganiska ämnen som kallas närsalter eller mineralämnen. Boken säger att växter måste ta upp kväve, fosfor och andra mineraler, som kallas närsalter.","kw":[["vatten"],["kolförening","organisk"],["kolhydrat"],["lipid","fett"],["protein"],["närsalt","mineral"]],"src":"PPT Bi2 bild 3 · s. 244","id":"k1k16q0yzt"},{"q":"Kan du skilja på mono-, di- och polysackarider och ge exempel?","a":"Monosackarider är en sockerring, enkla sockerarter som glukos (druvsocker, C6H12O6) och fruktos (fruktsocker). Disackarider är två ringar, sammansatta sockerarter som sackaros (glukos + fruktos, strösocker), laktos (mjölksocker) och maltos (maltsocker). Polysackarider är många ringar, till exempel cellulosa och stärkelse.","kw":[["mono","en ring","enkla"],["di","två"],["poly","många"],["glukos"],["sackaros"],["cellulosa","stärkelse"]],"src":"PPT Bi2 bild 5–7","id":"k1knhnb8x"},{"q":"Kan du förklara varför kostfiber är nyttiga fast vi inte kan bryta ner dem?","a":"Cellulosa är en polysackarid i växternas cellväggar. Människan kan inte bryta ner den, och därför passerar den tarmen som kostfiber. Kostfiber motverkar förstoppning och ger mättnadskänsla.","kw":[["cellulosa"],["bryta ner","nedbryt","smält"],["förstoppning"],["mätt"]],"src":"PPT Bi2 bild 7","id":"k1k1yfjava"},{"q":"Kan du beskriva en fettmolekyl och skillnaden mellan mättat och omättat fett?","a":"En fettmolekyl är byggd av en glycerol och tre fettsyror, som domineras av en lång kolkedja. Mättat fett har bara enkelbindningar, kedjan blir rak och fettet är fast vid rumstemperatur, till exempel animaliskt fett och kokosfett. Omättat fett har en dubbelbindning och fleromättat flera. Dubbelbindningen ger en knyck, och därför är fettet flytande, till exempel vegetabiliskt fett och fiskfett.","kw":[["glycerol"],["tre fettsyr","3 fettsyr"],["enkelbind"],["dubbelbind"],["fast"],["flytande"]],"src":"PPT Bi2 bild 9–12","id":"k1ks9cs4f"},{"q":"Kan du förklara varför omättade fettsyror gör cellmembranet mer flytande?","a":"Omättade fettsyror har dubbelbindningar som gör svansen veckad. Då blir avståndet mellan molekylerna större, och de redan svaga van der Waals-krafterna blir ännu svagare. Därför hålls membranet flytande vid en lägre temperatur än med raka, mättade fettsyror. Därför har ishavsfisk mycket fleromättade fettsyror. Längre fettsyror ger däremot ett trögare membran.","kw":[["dubbelbind"],["veckad","knyck"],["avstånd"],["van der waals"],["ishavsfisk"],["lägre temperatur","kyla","kall"]],"src":"s. 18","id":"k1k1ytq5t8"},{"q":"Kan du beskriva en fosfolipid och hur fosfolipiderna bildar cellmembranet?","a":"En fosfolipid har ett hydrofilt huvud med en fosfatgrupp, som är vattenlösligt, och en hydrofob svans av fettsyror, som är fettlöslig. I cellmembranet bildar fosfolipiderna ett dubbelt lager med svansarna riktade mot varandra och huvudena utåt mot vattnet på cellens in- och utsida. Kolesterol hjälper djurcellens membran att hålla sig lagom flytande.","kw":[["hydrofil"],["fosfat"],["hydrofob"],["dubbel"],["mot varandra","inåt"],["kolesterol"]],"src":"PPT Bi2 bild 14 · s. 17–18","t":["membran"],"id":"k1kr6s2vv"},{"q":"Kan du berätta vad proteiner gör och vad essentiella aminosyror är?","a":"Proteiner är viktigt byggmaterial i cellerna. Vissa hormoner och enzymer är proteiner, och blodfärgämnet hemoglobin är ett protein. Ett protein består av upp till 20 olika aminosyror sammanlänkade i en viss ordning. Cellerna kan tillverka 12 av dem. De övriga 8 måste ingå i födan och kallas essentiella aminosyror. Proteinerna tillverkas på ribosomerna.","kw":[["byggmaterial"],["enzym","hormon"],["hemoglobin"],["aminosyr"],["20"],["essentiell","födan","maten"]],"src":"PPT Bi2 bild 15–16","id":"k1kvlqlps"},{"q":"Kan du beskriva en nukleotid och skillnaden mellan DNA och RNA?","a":"En nukleotid består av en fosfatgrupp, en monosackarid och en kvävebas. Nukleotider bygger upp nukleinsyror och fungerar som energibärare. DNA har sockret deoxiribos och baserna A, T, C och G. RNA har ribos och baserna A, U, C och G. Deoxiribos har en syreatom mindre än ribos. A och G är dubbelringar, C, T och U enkelringar.","kw":[["fosfat"],["socker","monosackarid","ribos"],["kvävebas","bas"],["deoxiribos"],["uracil"," u "],["energi"]],"src":"PPT Bi2 bild 27–28","id":"k1k1dfnm4s"}],"kompis":[{"q":"Förklara för en kompis varför olivolja är flytande men smör fast, och vad det har med ishavsfisk att göra.","model":"Fett är glycerol + tre fettsyror. I smör (animaliskt fett) är fettsyrorna mest mättade: bara enkelbindningar, raka kedjor som packas tätt. Då verkar van der Waals-krafterna på nära håll och fettet blir fast. I vegetabiliska oljor finns dubbelbindningar som ger kedjorna knyckar. Molekylerna kan inte packas tätt, avståndet blir större, krafterna svagare och fettet flytande. Samma sak gäller fosfolipiderna i cellmembranet. Ishavsfisk har mycket fleromättade fettsyror i membranen, eftersom membranen annars skulle stelna i det kalla vattnet.","kw":[["mättad","enkelbind"],["rak","tätt"],["dubbelbind","knyck"],["van der waals","avstånd"],["membran"],["ishavsfisk","kallt"]],"src":"PPT Bi2 bild 10–13 · s. 18","t":["membran"],"id":"k1e98l98v"},{"q":"Förklara för en kompis hur en fosfolipid ser ut och varför den automatiskt bildar ett dubbelt lager i vatten.","model":"Fosfolipiden har ett hydrofilt huvud med en fosfatgrupp och en hydrofob svans av fettsyror. Huvudet trivs i vatten men svansen inte. I cellen finns vatten både utanför och inuti, och därför ordnar sig fosfolipiderna i två lager: huvudena vänds ut mot vattnet på båda sidor och svansarna gömmer sig inne i lagret, riktade mot varandra. Därför får membranet ett fettälskande inre som släpper igenom fettlösliga ämnen men inte joner.","kw":[["hydrofil"],["hydrofob"],["fosfat"],["vatten"],["dubbel","två lager"],["mot varandra","inåt"]],"src":"PPT Bi2 bild 14 · s. 17","t":["membran"],"id":"k1e133877l"},{"q":"Förklara för en kompis skillnaden mellan glukos, sackaros och stärkelse.","model":"Alla tre är kolhydrater, byggda av kol, väte och syre. Glukos (druvsocker, C6H12O6) är en monosackarid, en enda sockerring. Sackaros (strösocker) är en disackarid, en ring glukos och en ring fruktos ihopkopplade. Stärkelse är en polysackarid, en lång kedja av många sockerringar, och ett av våra viktigaste näringsämnen. Den finns till exempel i potatis, där leukoplaster lagrar den i stamknölarna.","kw":[["monosackarid","en ring"],["disackarid","två"],["polysackarid","många"],["fruktos"],["potatis"],["c6h12o6","druvsocker"]],"src":"PPT Bi2 bild 5–7 · s. 247","id":"k1eqy6riz"}],"gloss":[{"w":"Organiskt ämne","d":"Kolförening, t.ex. kolhydrater, lipider och proteiner.","src":"PPT Bi2 bild 3","lek":1},{"w":"Närsalter","d":"Oorganiska ämnen (mineralämnen) som celler behöver, t.ex. kväve och fosfor.","src":"Bok s. 244 · PPT Bi2 bild 3"},{"w":"Kolhydrat","d":"Molekyl av kol, väte och syre, ofta formad som sockerringar.","src":"PPT Bi2 bild 4","lek":1},{"w":"Monosackarid","d":"Enkel sockerart med en sockerring, t.ex. glukos och fruktos.","src":"PPT Bi2 bild 5","lek":1},{"w":"Disackarid","d":"Två sockerringar ihopkopplade, t.ex. sackaros, laktos och maltos.","src":"PPT Bi2 bild 6","lek":1},{"w":"Polysackarid","d":"Många sockerringar i en kedja, t.ex. cellulosa och stärkelse.","src":"PPT Bi2 bild 7","lek":1},{"w":"Glukos","d":"Druvsocker, C₆H₁₂O₆. Finns som α- och β-glukos.","src":"PPT Bi2 bild 4–5","lek":1},{"w":"Fruktos","d":"Fruktsocker, en monosackarid.","src":"PPT Bi2 bild 5","lek":1},{"w":"Sackaros","d":"Strösocker, glukos + fruktos.","src":"PPT Bi2 bild 6","lek":1},{"w":"Laktos","d":"Mjölksocker, en disackarid.","src":"PPT Bi2 bild 6","lek":1},{"w":"Maltos","d":"Maltsocker, en disackarid.","src":"PPT Bi2 bild 6","lek":1},{"w":"Cellulosa","d":"Polysackarid i växternas cellväggar. Kan inte brytas ner av människan (kostfiber).","src":"PPT Bi2 bild 7 · bok s. 244"},{"w":"Kostfiber","d":"Växtämnen som cellulosa som vi inte kan bryta ner. Motverkar förstoppning och ger mättnadskänsla.","src":"PPT Bi2 bild 7","lek":1},{"w":"Stärkelse","d":"Polysackarid och viktigt näringsämne, t.ex. i potatis.","src":"PPT Bi2 bild 7 · bok s. 247"},{"w":"Glykogen","d":"Lagrad energi i leverceller (inklusionskroppar).","src":"Bok s. 21"},{"w":"Lipider","d":"Ämnen som är olösliga eller mycket svårlösliga i vatten, t.ex. fetter och fosfolipider.","src":"PPT Bi2 bild 8"},{"w":"Glycerol","d":"Molekylen som de tre fettsyrorna sitter på i en fettmolekyl.","src":"PPT Bi2 bild 9","lek":1},{"w":"Fettsyra","d":"Lång kedja av kolatomer med en karboxylgrupp i ena änden.","src":"PPT Bi2 bild 9, 11"},{"w":"Mättat fett","d":"Bara enkelbindningar mellan kolatomerna. Fast vid rumstemperatur.","src":"PPT Bi2 bild 10 · bok s. 18"},{"w":"Omättat fett","d":"En dubbelbindning mellan kolatomerna. Flytande vid rumstemperatur.","src":"PPT Bi2 bild 12 · bok s. 18"},{"w":"Fleromättat fett","d":"Fler än en dubbelbindning. Flytande.","src":"PPT Bi2 bild 12 · bok s. 18"},{"w":"Dubbelbindning","d":"Bindning med två elektronpar mellan två kolatomer. Ger fettsyran en knyck.","src":"PPT Bi2 bild 11"},{"w":"Van der Waals-krafter","d":"Relativt svaga krafter som håller ihop fosfolipiderna.","src":"Bok s. 18"},{"w":"Åderförkalkning","d":"Förträngning av blodkärlen. Mättat fett ökar risken enligt läraren.","src":"PPT Bi2 bild 10","lek":1},{"w":"Fosfolipid","d":"Lipid med hydrofilt huvud (fosfatgrupp) och hydrofob svans. Bygger cellmembranet.","src":"PPT Bi2 bild 14 · bok s. 17"},{"w":"Hydrofil","d":"Vattenälskande, vattenlöslig.","src":"PPT Bi2 bild 14 · bok s. 17"},{"w":"Hydrofob","d":"Vattenskyende, fettlöslig.","src":"PPT Bi2 bild 14 · bok s. 18"},{"w":"Kolesterol","d":"Steroid i djurcellers membran som håller det lagom flytande.","src":"Bok s. 18 · PPT Bi2 bild 14"},{"w":"LDL / HDL","d":"Partiklar av kolesterol + protein i blodet. LDL \"det onda\", HDL för kolesterol till levern.","src":"Bok s. 36 · PPT Bi2 bild 14"},{"w":"Protein","d":"Kedja av upp till 20 sorters aminosyror i en viss ordning.","src":"PPT Bi2 bild 15","lek":1},{"w":"Aminosyra","d":"Byggsten i proteiner.","src":"PPT Bi2 bild 15","lek":1},{"w":"Essentiell aminosyra","d":"Aminosyra som cellen inte kan tillverka och som måste ingå i födan (8 enligt läraren).","src":"PPT Bi2 bild 16","lek":1},{"w":"Hemoglobin","d":"Det röda blodfärgämnet, ett protein.","src":"PPT Bi2 bild 15","lek":1},{"w":"Enzym","d":"Protein som får kemiska reaktioner att ske.","src":"PPT Bi2 bild 15 · bok s. 18"},{"w":"Nukleotid","d":"Fosfatgrupp + socker (ribos/deoxiribos) + kvävebas. Byggsten i nukleinsyror och energibärare.","src":"PPT Bi2 bild 27–28","lek":1},{"w":"Nukleinsyra","d":"DNA eller RNA, en kedja av nukleotider.","src":"PPT Bi2 bild 27–28","lek":1},{"w":"Kvävebas","d":"Adenin, guanin (dubbelringar), cytosin, tymin, uracil (enkelringar).","src":"PPT Bi2 bild 27","lek":1},{"w":"Ribos / deoxiribos","d":"Sockret i RNA respektive DNA. Deoxiribos har en syreatom mindre.","src":"PPT Bi2 bild 27","lek":1}],"snabb":{"keys":["Organiska ämnen :: kolföreningar: kolhydrater, lipider, proteiner","Närsalter :: oorganiska ämnen, t.ex. kväve och fosfor","Glukos :: druvsocker, C₆H₁₂O₆, monosackarid","Sackaros :: strösocker = glukos + fruktos (disackarid)","Polysackarider :: cellulosa (cellväggar, kostfiber) och stärkelse (potatis)","Fett :: glycerol + tre fettsyror","Mättat fett :: bara enkelbindningar, rak, fast (animaliskt, kokos)","Omättat fett :: dubbelbindning, knyck, flytande (vegetabiliskt, fisk)","Fosfolipid :: hydrofilt huvud (fosfatgrupp) + hydrofob svans","Kolesterol :: håller djurcellens membran lagom flytande","Protein :: upp till 20 aminosyror i viss ordning","Nukleotid :: fosfatgrupp + socker + kvävebas","DNA / RNA :: deoxiribos, T / ribos, U"],"nums":[["C₆H₁₂O₆","glukos: 6 kol, 12 väte, 6 syre"],["3","fettsyror per fettmolekyl (+ 1 glycerol)"],["20","olika aminosyror"],["12","aminosyror som cellen kan tillverka"],["8","essentiella aminosyror (läraren)"],["5","kvävebaser: A, G, C, T, U"],["1","kol nummer 1, där α- och β-glukos skiljer sig"]],"chains":[["Dubbelbindning","knyck i kedjan","molekylerna packas glest","svagare van der Waals-krafter","flytande"],["Kallt hav","risk att membranen stelnar","ishavsfisk har fleromättade fettsyror","membranen förblir flytande"],["Cellulosa","kan inte brytas ner","kostfiber","mindre förstoppning, mättnad"],["Fosfolipider i vatten","huvuden ut mot vattnet","svansar in mot varandra","dubbelt lager"]],"traps":["Sackaros är en disackarid, inte en monosackarid.","Mättat = inga dubbelbindningar. Omättat = minst en.","Längre fettsyror ger trögare membran, inte mer flytande.","Hydrofilt huvud, hydrofob svans. Inte tvärtom.","LDL och HDL är partiklar (bok s. 36), inte två sorters kolesterol.","Essentiell aminosyra = cellen kan INTE göra den själv.","T finns i DNA, U i RNA."]}},"k2":{"pre":[{"q":"Vad skiljer en prokaryot cell från en eukaryot cell?","o":["Den prokaryota cellen saknar en avgränsad cellkärna","Den prokaryota cellen saknar DNA","Den prokaryota cellen saknar cellmembran","Den prokaryota cellen är alltid större"],"why":"Eukaryot = med cellkärna, prokaryot = utan avgränsad cellkärna. Prokaryoter har DNA, men det ligger fritt i cytoplasman.","src":"s. 180 · PPT Bi2 bild 26","id":"k2p1ktob3l"},{"q":"Vad är \"blågröna alger\" egentligen?","o":["Cyanobakterier, alltså prokaryoter","Encelliga växter med kloroplaster","Svampar som gör fotosyntes","Arkéer"],"why":"Boken kallar dem cyanobakterier. De gör fotosyntes men är bakterier och saknar cellkärna.","src":"s. 181 · PPT Bi2 bild 20","id":"k2pqbozb9"},{"q":"Vilken del har växtcellen men inte djurcellen?","o":["Cellvägg","Cellmembran","Mitokondrie","Ribosomer"],"why":"Växtcellen har cellvägg, stor vakuol och kloroplaster. Membran, mitokondrier och ribosomer har båda.","src":"s. 244 · PPT Bi2 bild 25","t":["vagg"],"id":"k2p1709yvs"},{"q":"Vad bildar flera likadana celler tillsammans?","o":["En vävnad","Ett organ","En organism","En organell"],"why":"Likadana celler bildar vävnad. Olika vävnader bildar tillsammans ett organ.","src":"PPT Bi2 bild 18","id":"k2p1jvoveu"},{"q":"Varför slokar en växt som inte får vatten?","o":["Vakuolen innehåller för lite vatten, så trycket mot cellväggen (turgor) minskar","Cellväggen löses upp","Kloroplasterna slutar göra klorofyll","Mitokondrierna slutar arbeta"],"why":"Vakuolen trycker mot cellväggen och ger turgor. Vid vattenbrist minskar trycket och växten slokar.","src":"s. 246","t":["osmos"],"id":"k2p1sgwzra"}],"cards":[{"f":"Vad är livets minsta enhet?","b":"Cellen.","ty":"b","src":"PPT Bi2 bild 20","id":"k2c1nzvd6a"},{"f":"Eukaryot","b":"En cell med cellkärna (eu = äkta, karyon = kärna).","ty":"b","src":"PPT Bi2 bild 26 · s. 180","p":1,"id":"k2c5gt0vd"},{"f":"Prokaryot","b":"En cell som saknar avgränsad cellkärna och membranomslutna organeller. DNA ligger fritt i cytoplasman.","ty":"b","src":"PPT Bi2 bild 26 · s. 180","p":1,"id":"k2c1e9sr9a"},{"f":"Vilka tre celltyper talar läraren om?","b":"Prokaryota celler (bakterier och blågröna alger), eukaryota djurceller och eukaryota växtceller.","ty":"s","src":"PPT Bi2 bild 20","id":"k2c13dseoe"},{"f":"Vilka tre huvudgrupper delar boken in allt levande i?","b":"Bakterier, arkéer och eukaryoter.","ty":"s","src":"s. 178","id":"k2cb6i9lk"},{"f":"Arkéer","b":"Prokaryoter som saknar cellkärna, men vars cellmembran är byggt annorlunda än hos bakterier och eukaryoter.","ty":"b","t":["membran"],"src":"s. 178, 180","id":"k2c1gsdzgp"},{"f":"Cyanobakterier","b":"Bokens namn på \"blågröna alger\". De gör fotosyntes men är bakterier, alltså prokaryoter.","ty":"b","src":"s. 181 · PPT Bi2 bild 20","p":1,"id":"k2cnkhecm"},{"f":"Är \"blågröna alger\" alger?","b":"Nej. De är cyanobakterier, prokaryoter utan cellkärna. Riktiga alger är eukaryoter med kloroplaster.","ty":"f","src":"s. 181","id":"k2cfsedvn"},{"f":"Har prokaryoter DNA?","b":"Ja. Det ligger bara fritt i cytoplasman, eftersom det inte finns någon kärna.","ty":"f","src":"s. 180","id":"k2cebeb74"},{"f":"Vilka eukaryoter nämner boken utöver djur och växter?","b":"Svampar, alger och encelliga eukaryoter som jäst och malariaparasiten.","ty":"s","src":"s. 178","id":"k2c1r5rjqn"},{"f":"Prokaryot och eukaryot: hur många celler?","b":"Prokaryoter är alltid encelliga. Eukaryoter kan vara encelliga eller flercelliga.","ty":"j","src":"s. 178","id":"k2c1qojrk5"},{"f":"Varför tror man att mitokondrien och kloroplasten en gång var fria prokaryoter?","b":"Eftersom de har dubbla membran och eget, ringformat DNA (endosymbios).","ty":"v","t":["endo"],"src":"s. 27, 247","id":"k2c17laigt"},{"f":"Hur förökar sig celler enligt läraren?","b":"Genom att dela sig till två dotterceller. Många celler i kroppen dör och byts ut mot nya.","ty":"b","src":"PPT Bi2 bild 18","id":"k2c11yqxos"},{"f":"Vävnad","b":"Flera likadana celler, t.ex. muskelceller som bildar muskelvävnad.","ty":"b","src":"PPT Bi2 bild 18–19 · s. 244","p":1,"id":"k2cgdff9e"},{"f":"Organ","b":"Olika vävnader tillsammans, t.ex. hjärta, lever och lungor.","ty":"b","src":"PPT Bi2 bild 18–19","id":"k2ci0k3pu"},{"f":"Ge tre exempel på celler och deras vävnad (läraren).","b":"Muskelceller → muskelvävnad, nervceller → nervvävnad, benceller → benvävnad.","ty":"s","src":"PPT Bi2 bild 19","id":"k2c6edx97"},{"f":"Är hjärtat en vävnad?","b":"Nej, ett organ. Det består av olika vävnader.","ty":"f","src":"PPT Bi2 bild 18–19","id":"k2c1mbr029"},{"f":"Vad gör att celler kan fästa till varandra och bilda vävnader?","b":"Proteiner i cellmembranet.","ty":"b","t":["membran"],"src":"s. 17","id":"k2c1ja1kd2"},{"f":"Generalist","b":"Cell hos en encellig organism. Den gör samtliga funktioner, eftersom den är ensam.","ty":"b","src":"PPT Bi2 bild 20","id":"k2c4dekjl"},{"f":"Specialist","b":"Cell hos en flercellig organism, specialiserad på vissa funktioner. Det gör energianvändningen effektivare.","ty":"b","src":"PPT Bi2 bild 20 · s. 21","p":1,"id":"k2ccxrhok"},{"f":"Varför kan celler i en flercellig organism se så olika ut?","b":"Eftersom de är specialiserade på olika arbetsuppgifter.","ty":"v","src":"s. 21","p":1,"id":"k2caa53aq"},{"f":"Vad är det enda skyddet djurcellen har mot omgivningen?","b":"Cellmembranet (samt vissa ämnen som utsöndras ur cellen), eftersom djurcellen saknar cellvägg.","ty":"v","t":["membran","vagg"],"src":"s. 21","p":1,"id":"k2ctqjm52"},{"f":"Cytoplasma","b":"Tjock vätska med lösta ämnen innanför membranet. Där sker många av cellens kemiska reaktioner. Den omger organellerna och inklusionskropparna.","ty":"b","src":"s. 21 · PPT Bi2 bild 21","p":1,"id":"k2c19fre66"},{"f":"Cellplasma eller cytoplasma?","b":"Samma sak. Läraren skriver cellplasma (bild 22), boken och lärarens bild säger cytoplasma.","ty":"f","src":"s. 21 · PPT Bi2 bild 21–22","id":"k2c1gcg01v"},{"f":"Inklusionskroppar","b":"Lagrad energi (glykogen i leverceller, fett i fettceller) eller cellprodukter (melanin i hudceller, slem). Finns inte i alla celler.","ty":"b","src":"s. 21","id":"k2c1iz45xj"},{"f":"Cellmembran (lärarens definition)","b":"Yttre skydd som släpper in och ut vissa ämnen.","ty":"b","t":["membran"],"src":"PPT Bi2 bild 22 · s. 17","p":1,"id":"k2curgaoe"},{"f":"Cellkärna (lärarens definition)","b":"Innehåller gener (arvsanlagen) som består av DNA. Boken: nästan all arvsmassa.","ty":"b","src":"PPT Bi2 bild 22 · s. 22","p":1,"id":"k2c1ad02re"},{"f":"Mitokondrie (lärarens definition)","b":"Cellens kraftverk. Energirik näring förbränns (cellandningen).","ty":"b","t":["endo"],"src":"PPT Bi2 bild 22 · s. 27","p":1,"id":"k2c1cdg1ld"},{"f":"Ribosomer (lärarens definition)","b":"Här tillverkar cellen proteiner.","ty":"b","src":"PPT Bi2 bild 22 · s. 23–24","p":1,"id":"k2c95ncck"},{"f":"Endoplasmatiska nätverket, ER (lärarens definition)","b":"Ett membransystem som transporterar kemiska föreningar.","ty":"b","src":"PPT Bi2 bild 22 · s. 24","p":1,"id":"k2cb9bmf2"},{"f":"Varför innehåller kärnan bara nästan all arvsmassa?","b":"Eftersom mitokondrierna (och kloroplasterna) har eget DNA.","ty":"v","t":["endo"],"src":"s. 22","id":"k2c1a93ox1"},{"f":"Vilka etiketter har lärarens enkla djurcellsbild?","b":"Cellmembran, arvsmassa DNA, cellkärna, lysosom, golgiapparaten, cytoplasma, mitokondrie, endoplasmatiska nätverket och ribosomer (två linjer).","ty":"i","src":"PPT Bi2 bild 21","id":"k2chxfg24"},{"f":"Vad har bokens djurcell som lärarens bild saknar?","b":"Bland annat centrioler, kärnmembran, ER med ribosomer och en liten vakuol.","ty":"i","src":"s. 21 · PPT Bi2 bild 21","id":"k2c1ic2qkc"},{"f":"Varför kallas bokens djurcell \"genomsnittlig\"?","b":"Eftersom specialiserade celler kan se väldigt olika ut.","ty":"v","src":"s. 21","id":"k2cf8odf4"},{"f":"Vilka tre delar har växtcellen men inte djurcellen?","b":"Cellvägg, stor vakuol och kloroplaster (VVK).","ty":"j","t":["vagg"],"src":"s. 244 · PPT Bi2 bild 25","p":1,"id":"k2cl2b2ww"},{"f":"Vilka två delar saknar växtcellen som djurcellen har?","b":"Lysosomer och centrioler.","ty":"j","src":"s. 244","id":"k2c16vpmgr"},{"f":"Cellvägg (växtcell)","b":"Stödjande vägg av cellulosa utanför cellmembranet. Ger form, skydd och stadga.","ty":"b","t":["vagg"],"src":"s. 244–245 · PPT Bi2 bild 25","p":1,"id":"k2c1slad16"},{"f":"Varför spricker inte en växtcell i destillerat vatten?","b":"Eftersom cellväggen tar emot trycket när vatten strömmar in.","ty":"v","t":["osmos","vagg"],"src":"s. 245","id":"k2c14vht5n"},{"f":"Plasmodesmata","b":"Kanaler i cellväggen genom vilka växtceller för över ämnen till varandra.","ty":"b","t":["vagg"],"src":"s. 245","id":"k2c1tg279a"},{"f":"Vad är yttersta lagret i en växtcell?","b":"Cellväggen. Cellmembranet ligger innanför den, fast läraren kallar membranet \"yttre skydd\".","ty":"f","t":["vagg","membran"],"src":"s. 245 · PPT Bi2 bild 25","id":"k2c1hyh5rw"},{"f":"Vakuol (lärarens definition)","b":"En vätskefylld blåsa (cellsaftrum). Utgör tillsammans med cellväggarna växternas skelett.","ty":"b","t":["osmos"],"src":"PPT Bi2 bild 25 · s. 245","p":1,"id":"k2c1v7yuq0"},{"f":"Hur stor del av växtcellen kan vakuolen uppta?","b":"Upp till 90 % av volymen.","ty":"s","src":"s. 245","p":1,"id":"k2ccye0mr"},{"f":"Hur bildas den stora vakuolen?","b":"Hos äldre celler, när många små vakuoler smälter samman.","ty":"b","src":"s. 245","id":"k2ckvie3d"},{"f":"Varför sägs vakuolen göra lysosomernas jobb?","b":"Eftersom den innehåller enzymer som kan spjälka makromolekyler.","ty":"v","src":"s. 246","id":"k2c242lo7"},{"f":"Turgor","b":"Vakuolens tryck mot cellväggen. Gör att växten står upprätt trots att den saknar skelett och muskler.","ty":"b","t":["osmos","vagg"],"src":"s. 246","p":1,"id":"k2crgm2t0"},{"f":"Kloroplast (lärarens definition)","b":"Innehåller klorofyll som gör att växterna kan utnyttja ljusenergi från solen (fotosyntes). Finns hos växter och alger.","ty":"b","t":["endo"],"src":"PPT Bi2 bild 25 · s. 246–247","p":1,"id":"k2c858iu7"},{"f":"Plastider","b":"Organellgrupp som kloroplasterna hör till. Finns bara hos växter och alger.","ty":"b","src":"s. 246","id":"k2comvvdh"},{"f":"Har växtceller mitokondrier?","b":"Ja. De förbränner näring precis som djurceller. Kloroplasten ersätter inte kraftverket.","ty":"f","t":["endo"],"src":"s. 244 · PPT Bi2 bild 23–25","p":1,"id":"k2c1k40foz"},{"f":"Vilka stavfel finns i lärarens växtcellsbild (bild 23)?","b":"\"Vacuol\" (rätt: vakuol) och \"Golgieapparat\" (rätt: golgiapparat).","ty":"i","src":"PPT Bi2 bild 23","id":"k2cef0cih"},{"f":"Vad kännetecknar lärarens växtcellsbild 24?","b":"Vakuolen fyller nästan hela cellen, och organellerna ligger i ett tunt lager cytoplasma längs kanterna.","ty":"i","src":"PPT Bi2 bild 24","id":"k2c1cve8v6"},{"f":"Cellvägg hos växt och bakterie: skillnaden?","b":"Växtens vägg är av cellulosa, bakteriens av peptidoglykan. Djurceller saknar vägg.","ty":"j","t":["vagg"],"src":"s. 244 · s. 180–181","id":"k2c1oul0cm"},{"f":"Har bakterier mitokondrier, ER och golgi?","b":"Nej, eftersom de är prokaryoter utan membranomslutna organeller. Ribosomer har de däremot.","ty":"j","src":"s. 180","id":"k2c1jeo8e0"}],"quiz":{"f":[{"q":"Vad betyder \"eukaryot\"?","o":["En cell med cellkärna","En cell utan cellkärna","En cell med cellvägg","En cell med kloroplaster"],"why":"Eu = äkta, karyon = kärna. Eukaryot = cell med cellkärna.","src":"PPT Bi2 bild 26 · s. 180","id":"k2q1ndikz0"},{"q":"Vilken organism är prokaryot?","o":["En bakterie","En jästcell","En malariaparasit","En alg"],"why":"Bakterier saknar cellkärna. Jäst, malariaparasiten och alger är encelliga eller flercelliga eukaryoter.","src":"s. 178, 180","id":"k2qv5cmli"},{"q":"Vilka är bokens tre huvudgrupper av liv?","o":["Bakterier, arkéer och eukaryoter","Djur, växter och svampar","Prokaryoter, djurceller och växtceller","Bakterier, virus och eukaryoter"],"why":"Boken: bakterier, arkéer och eukaryoter. Prokaryoter/djurceller/växtceller är lärarens tre celltyper.","src":"s. 178","id":"k2q1tawokx"},{"q":"Vad har arkéer gemensamt med bakterier?","o":["De saknar cellkärna","De har kloroplaster","Deras cellmembran är byggt likadant","De är flercelliga"],"why":"Båda är prokaryoter. Arkéernas cellmembran är däremot byggt annorlunda.","src":"s. 180","t":["membran"],"id":"k2q1fbwupy"},{"q":"Var ligger DNA i en prokaryot cell?","o":["Fritt i cytoplasman","I cellkärnan","I mitokondrierna","I cellväggen"],"why":"Prokaryoten saknar avgränsad cellkärna, så DNA ligger fritt i cytoplasman.","src":"s. 180","id":"k2q1svb6t"},{"q":"Vad bildar olika vävnader tillsammans?","o":["Ett organ","En cell","En organell","En vävnad"],"why":"Likadana celler → vävnad. Olika vävnader → organ.","src":"PPT Bi2 bild 18","id":"k2q1uxmbtw"},{"q":"Vilket av följande är ett organ enligt läraren?","o":["Lever","Muskelvävnad","Nervcell","Bencell"],"why":"Hjärta, lever och lungor är organ. Muskelvävnad är en vävnad, nerv- och benceller är celler.","src":"PPT Bi2 bild 19","id":"k2q1xwoynf"},{"q":"Hur kallas cellerna hos encelliga organismer enligt läraren?","o":["Generalister","Specialister","Prokaryoter","Dotterceller"],"why":"En enda cell måste klara samtliga funktioner, och därför är den en generalist.","src":"PPT Bi2 bild 20","id":"k2qqmtu7b"},{"q":"Vad är cellmembranet enligt läraren?","o":["Yttre skydd som släpper in och ut vissa ämnen","Stödjande vägg av cellulosa","Ett membransystem som transporterar kemiska föreningar","En vätskefylld blåsa"],"why":"Lärarens definition. Stödjande vägg = cellvägg, membransystem = ER, vätskefylld blåsa = vakuol.","src":"PPT Bi2 bild 22 · s. 17","t":["membran"],"id":"k2q1p50lvf"},{"q":"Var tillverkar cellen proteiner?","o":["På ribosomerna","I mitokondrierna","I vakuolen","I cellväggen"],"why":"\"Ribosomer = Här tillverkar cellen proteiner.\"","src":"PPT Bi2 bild 22 · s. 23","id":"k2qelwk7c"},{"q":"Vilken organell kallas cellens kraftverk?","o":["Mitokondrien","Kloroplasten","Cellkärnan","Ribosomen"],"why":"I mitokondrien förbränns energirik näring (cellandningen).","src":"PPT Bi2 bild 22 · s. 27","id":"k2qlapruj"},{"q":"Vilket är ett exempel på en inklusionskropp?","o":["Glykogen i en levercell","Ribosom","Mitokondrie","Cellmembran"],"why":"Inklusionskroppar är lagrad energi (glykogen, fett) eller cellprodukter (melanin, slem). De andra är organeller eller membran.","src":"s. 21","id":"k2qrgwanl"},{"q":"Vad kallar läraren vakuolen också?","o":["Cellsaftrum","Cellplasma","Plastid","Plasmodesma"],"why":"\"Vakuol = En vätskefylld blåsa (cellsaftrum).\"","src":"PPT Bi2 bild 25","id":"k2q1i2zbny"},{"q":"Hur stor del av växtcellens volym kan vakuolen uppta?","o":["Upp till 90 %","Upp till 10 %","Upp till 50 %","Exakt hälften"],"why":"Boken: upp till 90 % av cellens volym.","src":"s. 245","id":"k2q901b4v"},{"q":"Vad är växtcellens cellvägg gjord av?","o":["Cellulosa","Peptidoglykan","Fosfolipider","Stärkelse"],"why":"Växtens vägg är av cellulosa. Peptidoglykan finns i bakteriers vägg.","src":"s. 244 · PPT Bi2 bild 25","t":["vagg"],"id":"k2q16yyk9o"},{"q":"Vad heter kanalerna i cellväggen som förbinder växtceller?","o":["Plasmodesmata","Kärnporer","Tylakoider","Inklusionskroppar"],"why":"Genom plasmodesmata för cellerna över ämnen till varandra.","src":"s. 245","t":["vagg"],"id":"k2q1iedwwi"},{"q":"Vilka två delar saknar växtcellen jämfört med djurcellen?","o":["Lysosomer och centrioler","Mitokondrier och ribosomer","Cellmembran och kärna","ER och golgi"],"why":"Boken s. 244: växtcellen saknar lysosomer och centrioler.","src":"s. 244","id":"k2q12tf68m"},{"q":"Vad innehåller kloroplasten enligt läraren?","o":["Klorofyll","Cellulosa","Glykogen","Melanin"],"why":"Klorofyllet gör att växterna kan utnyttja ljusenergi från solen (fotosyntes).","src":"PPT Bi2 bild 25 · s. 247","id":"k2qiyuh4u"}],"u":[{"q":"En cell har DNA, ribosomer och cellvägg men ingen cellkärna. Vad är det troligen?","o":["En bakterie","En växtcell","En djurcell","En jästcell"],"why":"Ingen kärna = prokaryot. Växt- och jästceller har kärna, djurceller saknar dessutom vägg.","src":"s. 180","id":"k2q3ezlcg"},{"q":"Varför är \"blågröna alger\" inte riktiga alger?","o":["De saknar cellkärna och är därför bakterier","De gör inte fotosyntes","De har cellvägg av cellulosa","De är flercelliga"],"why":"Cyanobakterier gör fotosyntes men saknar kärna, så de är prokaryoter. Riktiga alger är eukaryoter.","src":"s. 181","id":"k2qxopeah"},{"q":"Varför är cellerna i en flercellig organism specialister?","o":["Energin kan användas effektivare när varje cell gör vissa funktioner","Varje cell måste klara samtliga funktioner","De saknar cellkärna","De kan inte dela sig"],"why":"Läraren: specialisering gör energin effektivare. Att klara allt är generalistens lott.","src":"PPT Bi2 bild 20 · s. 21","id":"k2q1avwqeq"},{"q":"Vad händer med en djurcell i destillerat vatten, och varför?","o":["Den sväller och kan spricka, eftersom den saknar cellvägg","Den krymper, eftersom vatten går ut","Ingenting, eftersom cellmembranet är ogenomträngligt för vatten","Den bildar en stor vakuol"],"why":"Vatten strömmar in genom osmos. Djurcellen har bara cellmembranet som skydd, så den kan spricka.","src":"s. 21, 245","t":["osmos","vagg"],"id":"k2q10qodxj"},{"q":"En krukväxt har inte vattnats på länge och slokar. Vad är förklaringen?","o":["Vakuolerna innehåller för lite vatten och turgor minskar","Cellväggarna har lösts upp","Kloroplasterna har blivit för många","Mitokondrierna har tagit över vakuolens plats"],"why":"Turgor, vakuolens tryck mot cellväggen, håller växten upprätt. Vid vattenbrist minskar trycket.","src":"s. 246","t":["osmos"],"id":"k2q7pn42r"},{"q":"Varför klarar sig växtcellen utan lysosomer?","o":["Vakuolen innehåller enzymer som kan spjälka makromolekyler","Cellväggen bryter ner avfall","Kloroplasterna tar hand om avfallet","Växtceller bildar inget avfall"],"why":"Vakuolens enzymer gör att den fyller ungefär samma funktion som lysosomerna.","src":"s. 246","id":"k2q1iys20r"},{"q":"Varför behöver en växtcell mitokondrier fast den har kloroplaster?","o":["Den måste förbränna näring i cellandningen precis som djurcellen","Mitokondrierna tillverkar klorofyll","Mitokondrierna bygger cellväggen","Det behöver den inte, växtceller saknar mitokondrier"],"why":"Kloroplasten fångar ljusenergi, men energin i näringen frigörs i mitokondrien. Kloroplasten ersätter inte kraftverket.","src":"s. 244 · PPT Bi2 bild 25","t":["endo"],"id":"k2qnv9en5"},{"q":"Vilken del är den yttersta i en växtcell?","o":["Cellväggen","Cellmembranet","Vakuolen","Cytoplasman"],"why":"Cellmembranet ligger innanför cellväggen, fast läraren kallar membranet \"yttre skydd\".","src":"s. 245 · PPT Bi2 bild 25","t":["vagg","membran"],"id":"k2q1hms4sb"},{"q":"Vilken del finns i djurcell, växtcell OCH bakterie?","o":["Ribosomer","Mitokondrier","Cellkärna","Kloroplaster"],"why":"Alla celler har ribosomer och cellmembran. Bakterier saknar kärna och mitokondrier, djurceller saknar kloroplaster.","src":"s. 180, 244","id":"k2q1jw4rej"},{"q":"Vad har växtceller och bakterier gemensamt som djurceller saknar?","o":["En cellvägg, men av olika material","En cellkärna","Kloroplaster","Lysosomer"],"why":"Båda har vägg: växten av cellulosa, bakterien av peptidoglykan. Djurceller saknar vägg.","src":"s. 180–181, 244","t":["vagg"],"id":"k2q13zb7fa"},{"q":"Varför tror man att mitokondrier och kloroplaster en gång var fritt levande prokaryoter?","o":["De har dubbla membran och eget, ringformat DNA","De saknar DNA","De finns bara i bakterier","De tillverkar cellväggen"],"why":"Dubbla membran och eget ringformat DNA tyder på endosymbios.","src":"s. 27, 247","t":["endo"],"id":"k2qd97n7"},{"q":"Läraren säger att kärnan innehåller cellens DNA. Hur preciserar boken det?","o":["Kärnan innehåller nästan all arvsmassa, eftersom mitokondrierna har eget DNA","Kärnan innehåller hälften av arvsmassan","Kärnan innehåller bara RNA","Allt DNA finns i ribosomerna"],"why":"Boken s. 22: nästan all arvsmassa. Mitokondrier (och kloroplaster) har eget DNA.","src":"s. 22 · PPT Bi2 bild 22","t":["endo"],"id":"k2q1vw445u"}],"o":[{"q":"Jämför djurcellen, växtcellen och bakteriecellen. Ange minst fyra skillnader.","model":"Djurcell och växtcell är eukaryoter med cellkärna, mitokondrier, ER och golgi. Bakterien är en prokaryot och saknar cellkärna och membranomslutna organeller, så dess DNA ligger fritt i cytoplasman. Växtcellen har cellvägg av cellulosa, en stor vakuol (upp till 90 % av volymen) och kloroplaster med klorofyll. Djurcellen saknar vägg, så cellmembranet är dess enda skydd, och den har lysosomer och centrioler som växtcellen saknar. Bakterien har också cellvägg, men av peptidoglykan. Alla tre har cellmembran och ribosomer.","kw":[["kärna"],["cellvägg","vägg"],["cellulosa","peptidoglykan"],["vakuol"],["kloroplast"],["lysosom","centriol"]],"src":"s. 21, 180–181, 244–246 · PPT Bi2 bild 21–26","t":["vagg"],"id":"k2of8oruo"},{"q":"Beskriv växtcellens vakuol och cellvägg, och förklara hur de tillsammans gör att växten kan stå upprätt.","model":"Cellväggen är en stödjande vägg av cellulosa utanför cellmembranet. Den ger cellen form, skydd och stadga, och väggarna hänger ihop i ett nätverk. Vakuolen är en vätskefylld blåsa (cellsaftrum) med vatten och lösta joner som kan uppta upp till 90 % av cellens volym. Den fyller hela utrymmet innanför väggen och trycker mot den. Trycket kallas turgor och gör att växten kan stå upprätt trots att den saknar skelett och muskler. Vid vattenbrist minskar turgor och växten slokar. Läraren uttrycker det som att vakuolen och cellväggarna är växternas skelett.","kw":[["cellulosa"],["vakuol"],["turgor","tryck"],["upprätt","stadga"],["slok","vattenbrist"],["90","cellsaftrum"]],"src":"s. 244–246 · PPT Bi2 bild 25","t":["osmos","vagg"],"id":"k2o1lpcf6n"},{"q":"Förklara begreppen prokaryot och eukaryot, och ge exempel på organismer i båda grupperna. Hur skiljer sig lärarens indelning från bokens?","model":"Eukaryot = cell med cellkärna och membranomslutna organeller. Prokaryot = cell utan avgränsad cellkärna, med DNA fritt i cytoplasman. Prokaryoter är bakterier, inklusive cyanobakterier (\"blågröna alger\"), och arkéer. Eukaryoter är djur, växter, svampar, alger och encelliga eukaryoter som jäst. Läraren talar om tre celltyper: prokaryota celler, eukaryota djurceller och eukaryota växtceller. Boken delar in allt levande i bakterier, arkéer och eukaryoter, och nämner att arkéerna har ett annorlunda byggt cellmembran.","kw":[["kärna"],["bakteri"],["arké","arke"],["cyanobakteri","blågrön"],["djur","växt","svamp"],["tre"]],"src":"s. 178, 180–181 · PPT Bi2 bild 20, 26","id":"k2oonjjkb"}]},"kan":[{"q":"Kan du förklara skillnaden mellan prokaryota och eukaryota celler?","a":"En eukaryot cell har en cellkärna och organeller som omges av membran, till exempel mitokondrier, ER och golgi. En prokaryot cell saknar en avgränsad cellkärna och membranomslutna organeller, och därför ligger dess DNA fritt i cytoplasman. Prokaryoter är alltid encelliga: bakterier (inklusive cyanobakterier) och arkéer. Eukaryoter är djur, växter, svampar, alger och encelliga eukaryoter.","kw":[["kärna"],["organell"],["dna"],["bakteri"],["arké","arke"],["djur","växt"]],"src":"s. 178, 180 · PPT Bi2 bild 20, 26","id":"k2kz8zcji"},{"q":"Kan du berätta vilka tre celltyper läraren talar om, och vad boken lägger till?","a":"Läraren talar om i princip tre celltyper: prokaryota celler utan cellkärna (bakterier och blågröna alger), eukaryota djurceller och eukaryota växtceller. Boken delar in allt levande i bakterier, arkéer och eukaryoter. Arkéerna saknar också cellkärna men har ett annorlunda byggt cellmembran. De blågröna algerna kallas i boken cyanobakterier, eftersom de är bakterier. Svampar och encelliga eukaryoter är också eukaryoter.","kw":[["prokaryot"],["djurcell"],["växtcell"],["arké","arke"],["cyanobakteri"],["svamp","encellig"]],"src":"s. 178, 180–181 · PPT Bi2 bild 20","id":"k2k1rjb9b5"},{"q":"Kan du förklara vad en vävnad och ett organ är, med exempel?","a":"Flera likadana celler bildar en vävnad, till exempel bildar muskelceller muskelvävnad, nervceller nervvävnad och benceller benvävnad. Olika vävnader kan tillsammans bilda ett organ, till exempel hjärta, lever och lungor. Proteiner i cellmembranet gör att cellerna kan fästa till varandra och bilda vävnader.","kw":[["likadana"],["vävnad"],["organ"],["muskel","nerv","ben"],["hjärta","lever","lung"]],"src":"PPT Bi2 bild 18–19 · s. 17","id":"k2ksdrmcl"},{"q":"Kan du förklara skillnaden mellan generalister och specialister?","a":"Celler hos encelliga organismer är generalister, eftersom den enda cellen måste klara samtliga funktioner. Hos flercelliga organismer är cellerna specialister, specialiserade på vissa funktioner, och på så sätt kan energin användas effektivare. Boken säger att flercelliga organismer består av en mängd specialiserade celltyper, och därför kan de se väldigt olika ut.","kw":[["generalist"],["specialist"],["encellig"],["flercellig"],["energi","effektiv"],["samtliga","allt","alla funktioner"]],"src":"PPT Bi2 bild 20 · s. 21","id":"k2k1422o09"},{"q":"Kan du räkna upp djurcellens delar och vad de gör enligt läraren?","a":"Cellmembranet är ett yttre skydd som släpper in och ut vissa ämnen. Cellkärnan innehåller generna, som består av DNA. Cellplasman (cytoplasman) innehåller de specialiserade celldelarna och mycket vatten. Mitokondrien är cellens kraftverk där energirik näring förbränns i cellandningen. Ribosomerna tillverkar proteiner, och ER är ett membransystem som transporterar kemiska föreningar.","kw":[["membran"],["kärna","dna"],["plasma"],["mitokondri","kraftverk"],["ribosom","protein"],["er","endoplasmatisk"]],"src":"PPT Bi2 bild 22 · s. 21–27","id":"k2k119l80n"},{"q":"Kan du beskriva cytoplasman och inklusionskropparna?","a":"Innanför membranet finns cytoplasman, en tjock vätska med lösta ämnen där många av cellens kemiska reaktioner sker. Den omger organellerna och inklusionskropparna. Inklusionskroppar finns inte i alla celler. De flesta är lagrad energi, som glykogen i leverceller och fett i fettceller, eller cellprodukter, som melanin i hudceller och slem.","kw":[["tjock vätska","vätska"],["reaktion"],["inklusionskropp"],["glykogen"],["fett"],["melanin","slem"]],"src":"s. 21","id":"k2kydlw4c"},{"q":"Kan du förklara vad växtcellen har som djurcellen saknar, och tvärtom?","a":"Växtcellen har en cellvägg av cellulosa, en stor vakuol och kloroplaster med klorofyll. Den saknar lysosomer och centrioler, som djurcellen har. Vakuolens enzymer gör ungefär lysosomernas jobb. Båda celltyperna har cellmembran, cellkärna, cytoplasma, ribosomer, ER, golgi och mitokondrier, eftersom båda är eukaryoter.","kw":[["cellvägg"],["vakuol"],["kloroplast"],["lysosom"],["centriol"],["mitokondri"]],"src":"s. 244, 246 · PPT Bi2 bild 21–25","id":"k2ktyyubi"},{"q":"Kan du förklara hur vakuolen och cellväggen håller växten upprätt?","a":"Vakuolen kan uppta upp till 90 % av cellens volym och innehåller en vattenlösning med många lösta joner. Den anpassar sin storlek så att cellen fyller hela utrymmet innanför cellväggen, och därför trycker den mot väggen. Trycket kallas turgor och gör att växten kan stå upprätt trots att den saknar skelett och muskler. Vid vattenbrist minskar trycket och växten slokar. Läraren säger att vakuolen och cellväggarna tillsammans är växternas skelett.","kw":[["vakuol"],["turgor","tryck"],["cellvägg","vägg"],["upprätt"],["slok","vattenbrist"],["90"]],"src":"s. 245–246 · PPT Bi2 bild 25","t":["osmos","vagg"],"id":"k2kix46cd"}],"kompis":[{"q":"Förklara för en kompis varför en djurcell kan spricka i rent vatten men inte en växtcell.","model":"Rent vatten är en hypoton lösning, så vatten strömmar in i cellen genom osmos. Djurcellen har ingen cellvägg, och cellmembranet är dess enda skydd mot omgivningen. Därför sväller den och kan spricka. Växtcellen har en cellvägg av cellulosa utanför cellmembranet. Väggen tar emot trycket, så cellen spricker inte. I stället fylls vakuolen och trycker mot väggen, turgor, och cellen blir spänd.","kw":[["osmos"],["hypoton","rent vatten"],["cellvägg","vägg"],["cellulosa"],["membran"],["turgor","tryck"]],"src":"s. 21, 245–246","t":["osmos","vagg"],"id":"k2e1kk8kzn"},{"q":"Förklara för en kompis varför \"blågröna alger\" inte är alger.","model":"Riktiga alger är eukaryoter, och de har cellkärna och kloroplaster. De \"blågröna algerna\" saknar cellkärna och membranomslutna organeller. Därför är de prokaryoter, närmare bestämt bakterier, och boken kallar dem cyanobakterier. De gör fotosyntes, och det är därför de förr räknades som alger. Läraren räknar dem till de prokaryota cellerna tillsammans med bakterierna.","kw":[["cyanobakteri"],["prokaryot"],["kärna"],["fotosyntes"],["eukaryot"],["bakteri"]],"src":"s. 181 · PPT Bi2 bild 20","id":"k2e11wgmow"},{"q":"Förklara för en kompis hur kroppen är organiserad från cell till organ, och varför flercelliga organismer har specialiserade celler.","model":"Cellen är livets minsta enhet. Flera likadana celler bildar en vävnad, till exempel muskelceller som bildar muskelvävnad. Olika vävnader bildar tillsammans ett organ, till exempel hjärtat. En encellig organism måste klara allt i en enda cell och är en generalist. I en flercellig organism är cellerna specialister på vissa funktioner, och därför kan energin användas effektivare. Celler förökar sig genom att dela sig till två dotterceller, och många celler dör och byts ut.","kw":[["minsta enhet"],["vävnad"],["organ"],["generalist"],["specialist"],["energi","effektiv"]],"src":"PPT Bi2 bild 18–20 · s. 21","id":"k2e1m1yuv4"}],"gloss":[{"w":"Cell","d":"Livets minsta enhet.","src":"PPT Bi2 bild 20","lek":1},{"w":"Eukaryot","d":"Cell med cellkärna och membranomslutna organeller.","src":"Bok s. 180 · PPT Bi2 bild 26"},{"w":"Prokaryot","d":"Cell som saknar avgränsad cellkärna och membranomslutna organeller. Alltid encellig.","src":"Bok s. 180 · PPT Bi2 bild 26"},{"w":"Bakterier","d":"Encelliga prokaryoter, en av livets tre huvudgrupper.","src":"Bok s. 178, 180"},{"w":"Arkéer","d":"Prokaryoter med annorlunda byggt cellmembran. En av livets tre huvudgrupper.","src":"Bok s. 178, 180"},{"w":"Cyanobakterier","d":"Fotosyntetiserande bakterier, förr kallade blågröna alger.","src":"Bok s. 181 · PPT Bi2 bild 20"},{"w":"Encellig organism","d":"Organism som består av en enda cell, t.ex. bakterier, arkéer, jäst och vissa alger.","src":"Bok s. 178 · PPT Bi2 bild 18"},{"w":"Dotterceller","d":"De två celler som bildas när en cell delar sig.","src":"PPT Bi2 bild 18","lek":1},{"w":"Vävnad","d":"Flera likadana celler, t.ex. muskelvävnad.","src":"PPT Bi2 bild 18–19 · bok s. 244"},{"w":"Organ","d":"Olika vävnader tillsammans, t.ex. hjärta, lever och lungor.","src":"PPT Bi2 bild 18–19","lek":1},{"w":"Generalist","d":"Cell hos encellig organism som gör samtliga funktioner.","src":"PPT Bi2 bild 20","lek":1},{"w":"Specialist","d":"Cell hos flercellig organism, specialiserad på vissa funktioner.","src":"PPT Bi2 bild 20 · bok s. 21"},{"w":"Cellmembran","d":"Yttre skydd som släpper in och ut vissa ämnen. Djurcellens enda skydd mot omgivningen.","src":"Bok s. 17, 21 · PPT Bi2 bild 22"},{"w":"Cytoplasma (cellplasma)","d":"Tjock vätska med lösta ämnen innanför membranet, där många kemiska reaktioner sker.","src":"Bok s. 21 · PPT Bi2 bild 21–22"},{"w":"Inklusionskroppar","d":"Lagrad energi (glykogen, fett) eller cellprodukter (melanin, slem) i cytoplasman.","src":"Bok s. 21"},{"w":"Organell","d":"Avgränsad del i cellen med en egen uppgift, t.ex. mitokondrie eller kärna.","src":"Bok s. 21, 180"},{"w":"Cellkärna","d":"Innehåller generna (DNA), nästan all arvsmassa.","src":"Bok s. 22 · PPT Bi2 bild 22"},{"w":"Mitokondrie","d":"Cellens kraftverk. Energirik näring förbränns (cellandningen).","src":"Bok s. 27 · PPT Bi2 bild 22"},{"w":"Ribosomer","d":"Här tillverkar cellen proteiner.","src":"Bok s. 23–24 · PPT Bi2 bild 22"},{"w":"Endoplasmatiska nätverket (ER)","d":"Membransystem som transporterar kemiska föreningar.","src":"Bok s. 24 · PPT Bi2 bild 22"},{"w":"Golgiapparaten","d":"Staplade membransäckar som modifierar och packar proteiner (detaljer i K4).","src":"Bok s. 25 · PPT Bi2 bild 21"},{"w":"Lysosom","d":"Membranblåsa med enzymer, cellens sopförbränning. Saknas i växtceller.","src":"Bok s. 26, 244 · PPT Bi2 bild 21"},{"w":"Centrioler","d":"Finns i djurceller men saknas i växtceller.","src":"Bok s. 21, 244"},{"w":"Cellvägg","d":"Stödjande vägg av cellulosa utanför cellmembranet hos växtceller. Bakterier har vägg av peptidoglykan.","src":"Bok s. 244–245 · PPT Bi2 bild 25"},{"w":"Extracellulär matrix","d":"Material utanför cellen. Hos växtcellen i form av cellväggen.","src":"Bok s. 244"},{"w":"Plasmodesmata","d":"Kanaler i cellväggen som låter växtceller föra över ämnen till varandra.","src":"Bok s. 245"},{"w":"Vakuol (cellsaftrum)","d":"Vätskefylld blåsa, upp till 90 % av växtcellens volym, med joner och enzymer.","src":"Bok s. 245–246 · PPT Bi2 bild 25"},{"w":"Turgor","d":"Vakuolens tryck mot cellväggen, som håller växten upprätt.","src":"Bok s. 246"},{"w":"Kloroplast","d":"Innehåller klorofyll och utnyttjar ljusenergi (fotosyntes). Finns hos växter och alger.","src":"Bok s. 246–247 · PPT Bi2 bild 25"},{"w":"Klorofyll","d":"Grönt färgämne i kloroplasten som fångar ljusenergi.","src":"Bok s. 247 · PPT Bi2 bild 25"},{"w":"Plastider","d":"Organellgrupp som kloroplasterna hör till. Finns bara hos växter och alger.","src":"Bok s. 246"},{"w":"Fotosyntes","d":"Utnyttjande av solens ljusenergi för att bygga näring.","src":"PPT Bi2 bild 25 · bok s. 181"},{"w":"Cellandning","d":"Förbränning av energirik näring i mitokondrien.","src":"PPT Bi2 bild 22","lek":1},{"w":"Peptidoglykan","d":"Materialet i bakteriers cellvägg.","src":"Bok s. 180–181"},{"w":"Endosymbios","d":"Teorin att mitokondrier och kloroplaster en gång var fria prokaryoter som flyttade in i en cell.","src":"Bok s. 27, 247"}],"snabb":{"keys":["Eukaryot :: cell med cellkärna","Prokaryot :: cell utan avgränsad cellkärna, DNA i cytoplasman","Bokens tre huvudgrupper :: bakterier, arkéer, eukaryoter","Lärarens tre celltyper :: prokaryota, eukaryota djurceller, eukaryota växtceller","Blågröna alger :: cyanobakterier, prokaryoter","Vävnad :: flera likadana celler","Organ :: olika vävnader tillsammans","Generalist :: encellig, gör allt","Specialist :: flercellig, energieffektiv","Cytoplasma :: tjock vätska där många reaktioner sker (= cellplasma)","Växtcellens extra :: cellvägg, stor vakuol, kloroplaster","Växtcellen saknar :: lysosomer och centrioler","Turgor :: vakuolens tryck mot cellväggen","Plasmodesmata :: kanaler i cellväggen"],"nums":[["3","celltyper enligt läraren"],["3","huvudgrupper av liv enligt boken"],["2","dotterceller när en cell delar sig"],["90 %","av växtcellens volym kan vakuolen uppta"]],"chains":[["Cell","flera likadana","vävnad","olika vävnader","organ"],["Flercellig organism","specialiserade celler","energin används effektivare"],["Djurcell i rent vatten","vatten in (osmos)","ingen cellvägg","kan spricka"],["Vakuolen fylls","trycker mot cellväggen","turgor","växten står upprätt"],["Vattenbrist","för lite vatten i vakuolen","turgor minskar","växten slokar"]],"traps":["\"Blågröna alger\" är bakterier, inte alger.","Prokaryoter har DNA, bara ingen kärna.","Hjärtat är ett organ, inte en vävnad.","Växtceller har mitokondrier.","Cellmembranet ligger innanför cellväggen i växtcellen.","Cellplasma och cytoplasma är samma sak.","Växtens vägg är cellulosa, bakteriens peptidoglykan.","Kärnan har nästan all arvsmassa, inte all."]}},"k3":{"pre":[{"q":"Vilka ämnen kan passera fritt genom cellmembranet?","o":["Fettlösliga ämnen","Vattenlösliga ämnen","Alla små ämnen","Inga ämnen alls"],"why":"Membranets inre är fettälskande och vattenhatande. Därför passerar fettlösliga ämnen fritt, medan vattenlösliga behöver transportproteiner. {{src:s. 17}}","id":"k3p6t3kmy"},{"q":"Ungefär hur många cellmembran behöver man lägga på varandra för att nå tjockleken av en boksida?","o":["Minst 10 000","Ungefär 10","Ungefär 100","Ungefär 1 miljard"],"why":"Boken säger minst 10 000. Membranet är extremt tunt. {{src:s. 17}}","id":"k3p6j9ero"},{"q":"Varför har ishavsfiskar mycket fleromättade fettsyror i sina cellmembran?","o":["Så att membranen inte stelnar i det kalla vattnet","Så att membranen blir stelare i kylan","För att lagra energi inför vintern","För att hålla saltet ute"],"why":"Fleromättade fettsyror är veckade och håller membranet flytande vid låg temperatur. {{src:s. 18}}","id":"k3p10y5va0"},{"q":"Vad kallas kolhydratlagret som täcker ytan på en eukaryot cell?","o":["Glykokalyx","Glykogen","Kollagen","Kromatin"],"why":"Glykokalyx bildas av sockerkedjor på glykolipider och glykoproteiner. {{src:s. 20 · korsord 8 vågrätt}}","id":"k3p1arwd20"},{"q":"Vad händer med röda blodkroppar om proteinet spektrin är muterat?","o":["De blir sfäriska, går lätt sönder och personen får anemi","De blir större och bär mer syre","De fastnar i kärlväggen och bildar proppar","Ingenting, eftersom spektrin finns i musklerna"],"why":"Spektrin håller de röda blodkropparna platta och hållfasta. {{src:s. 21}}","id":"k3ppl6taz"}],"cards":[{"f":"Vad är ett annat namn för cellmembranet?","b":"Plasmamembran.","ty":"b","src":"s. 17","id":"k3ctbtrov"},{"f":"Nämn cellmembranets fyra funktioner.","b":"Avgränsning mot omvärlden, kontroll av in- och uttransport av ämnen, kommunikation mellan cell och omgivning och bindning till närliggande celler.","ty":"b","src":"s. 17 · PPT Bi2 bild 22","p":1,"t":["membran"],"id":"k3cfqran"},{"f":"Hur definierar läraren cellmembranet?","b":"\"Yttre skydd som släpper in och ut vissa ämnen.\"","ty":"b","src":"PPT Bi2 bild 22 · s. 17","p":1,"id":"k3c2gdqjb"},{"f":"Vad säger boken om cellmembranet och livet?","b":"Det är en av förutsättningarna för liv. Utan cellmembran ingen cell.","ty":"b","src":"s. 17","id":"k3chirog0"},{"f":"Vad vinner cellen på att membranet avgränsar den?","b":"Stora molekyler som enzymer och organeller hålls instängda, och cellen kan reglera salthalt och pH, eftersom den har en egen inre miljö.","ty":"v","src":"s. 17","id":"k3cohkt66"},{"f":"Varför passerar fettlösliga ämnen fritt genom membranet?","b":"Eftersom membranets inre är fettälskande och vattenhatande.","ty":"v","src":"s. 17","p":1,"id":"k3c1wcq6kd"},{"f":"Hur kommer vattenlösliga ämnen igenom membranet enligt s. 17?","b":"Med hjälp av speciella transportproteiner bland fosfolipiderna. Därför kan cellen reglera transporten.","ty":"v","src":"s. 17","id":"k3c1qag55q"},{"f":"Hur kan celler kommunicera via membranet?","b":"En molekyl från en cell binder till en receptor på en annan cell, i närheten eller långt bort, och påverkar den cellens aktivitet.","ty":"v","src":"s. 17","t":["nyckel"],"id":"k3c1gtmtmi"},{"f":"Hur kan celler bilda vävnader?","b":"Proteiner i membranet gör att celler kan fästa mer eller mindre hårt vid varandra.","ty":"b","src":"s. 17","id":"k3cb8tc3g"},{"f":"Hur tunt är cellmembranet?","b":"Minst 10 000 membran på varandra behövs för att nå tjockleken av en boksida.","ty":"s","src":"s. 17","id":"k3c17nteq3"},{"f":"Vilka tre sorters molekyler bygger upp membranet?","b":"Lipider (huvudsakligen), proteiner och kolhydrater.","ty":"b","src":"s. 17","id":"k3c3cjxpi"},{"f":"Var sitter membranets kolhydrater?","b":"Fästa på lipider och proteiner. De sticker ut på cellens utsida.","ty":"b","src":"s. 17","id":"k3c37vc6j"},{"f":"Hur ligger fosfolipiderna i membranet?","b":"I ett dubbelt lager. Fettsyrasvansarna pekar mot varandra och de hydrofila huvudena pekar ut mot cellens inre och yttre miljö.","ty":"b","src":"s. 17 · PPT Bi2 bild 14","p":1,"t":["membran"],"id":"k3c1xi2yiu"},{"f":"Vad innehåller fosfolipidens huvud enligt läraren?","b":"En fosfatgrupp. Huvudet är hydrofilt (vattenlösligt) och svansen hydrofob (fettlöslig).","ty":"b","src":"PPT Bi2 bild 14","id":"k3c1gm7oj1"},{"f":"Hydrofil eller hydrofob: fosfolipidens huvud?","b":"Hydrofilt, vattenälskande. Därför vänds huvudena mot vattnet.","ty":"j","src":"s. 17 · PPT Bi2 bild 14","p":1,"id":"k3c14cp959"},{"f":"Vad bygger cellernas membran enligt läraren?","b":"Fosfolipider tillsammans med en mindre mängd kolesterol.","ty":"b","src":"PPT Bi2 bild 14 · s. 18","p":1,"id":"k3cnofb6b"},{"f":"Varför kallas membranet en tvådimensionell vätska?","b":"Fosfolipider och proteiner glider ständigt runt varandra. Membranet är ingen fast hinna.","ty":"v","src":"s. 17","t":["membran"],"id":"k3c11lha8c"},{"f":"Vad gör att membranet kan bilda membranblåsor?","b":"Att det är flytande. Det kan ändra form, och blåsorna kan smälta samman med andra blåsor eller med cellmembranet.","ty":"v","src":"s. 17–18","t":["membran"],"id":"k3c3c2uz3"},{"f":"Vilka krafter håller ihop fosfolipiderna?","b":"Van der Waals-krafter, som är relativt svaga.","ty":"b","src":"s. 18","id":"k3csl85v7"},{"f":"Varför gör omättade fettsyror membranet mer flytande?","b":"Dubbelbindningarna gör svansarna veckade. Avståndet mellan molekylerna blir större och van der Waals-krafterna svagare.","ty":"v","src":"s. 18 · PPT Bi2 bild 11–13","p":1,"id":"k3cb4djl4"},{"f":"Omättad eller fleromättad: en fettsyra med fler än en dubbelbindning?","b":"Fleromättad. En dubbelbindning ger omättad (enkelomättad).","ty":"j","src":"PPT Bi2 bild 12–13 · s. 18","p":1,"id":"k3c1s26fgz"},{"f":"Vilket fett är flytande vid rumstemperatur enligt läraren?","b":"Omättat och fleromättat fett, till exempel vegetabiliskt fett och fiskfett.","ty":"b","src":"PPT Bi2 bild 12","id":"k3cmlozl5"},{"f":"Varför har ishavsfiskar mycket fleromättade fettsyror?","b":"Annars skulle det kalla vattnet få membranen att stelna, och då skulle de sluta fungera.","ty":"v","src":"s. 18","p":1,"id":"k3cttiiy4"},{"f":"Hur påverkar fettsyrornas längd membranet?","b":"Längre fettsyror ger större yta för van der Waals-krafterna och därför ett trögare membran. Längden påverkar fryspunkten.","ty":"v","src":"s. 18","id":"k3cchqbwn"},{"f":"Vilken steroid håller djurcellens membran lagom flytande?","b":"Kolesterol.","ty":"b","src":"s. 18 · korsord 9 vågrätt","p":1,"id":"k3c11bhnq3"},{"f":"Provfälla: Blir membranet mer flytande av längre fettsyror?","b":"Nej. Längre fettsyror ger större yta för krafterna och ett trögare membran.","ty":"f","src":"s. 18","id":"k3cv3wduy"},{"f":"Hur kan ett protein sitta i membranet?","b":"Rakt genom hela membranet eller nedsänkt i ena sidan.","ty":"b","src":"s. 18","id":"k3c1nc4s3q"},{"f":"Vilket krav gäller för den del av proteinet som sitter i membranet?","b":"Den måste vara hydrofob, eftersom membranets inre är vattenhatande.","ty":"v","src":"s. 18","id":"k3c5u2kza"},{"f":"Nämn membranproteinernas fem jobb (TERKA).","b":"Transport, Enzymaktivitet, Receptorer, Koppla ihop med andra celler eller ECM, Ankare för cellskelettet.","ty":"b","src":"s. 18","id":"k3cjzi9gh"},{"f":"Vad är ett kanalprotein?","b":"Ett transportprotein som bildar en kanal i sig självt där ämnen kan ta sig igenom.","ty":"b","src":"s. 19","id":"k3cox0rx2"},{"f":"Hur fungerar den andra typen av transportprotein?","b":"Den ändrar form när molekylen som ska transporteras binder till den och hjälper molekylen genom membranet.","ty":"b","src":"s. 19","id":"k3c901m0f"},{"f":"Kräver transportproteiner energi?","b":"Vissa kräver energi, andra inte.","ty":"f","src":"s. 19","t":["atp"],"id":"k3c1b98d25"},{"f":"Var sker kemiska reaktioner förutom i cytoplasman?","b":"På cellmembranets in- och utsida. Där sitter enzymer insprängda bland fosfolipiderna.","ty":"b","src":"s. 19","id":"k3cu9xo0g"},{"f":"Ge bokens exempel på ett enzym i cellmembranet.","b":"På utsidan av tunntarmsceller finns ett enzym som bryter ner dipeptider till fria aminosyror. Aminosyrorna tas sedan upp med ett transportprotein.","ty":"b","src":"s. 19","id":"k3cuv0i8q"},{"f":"Vad är en dipeptid?","b":"Två aminosyror som sitter ihop.","ty":"b","src":"s. 19","id":"k3c74k96n"},{"f":"Hur fungerar en receptor enligt boken?","b":"En viss molekyl passar som nyckeln i ett lås till en viss receptor och kan låsa upp aktiviteter i cellen.","ty":"v","src":"s. 19","t":["nyckel"],"id":"k3cayu17u"},{"f":"Varför kan vissa celler ta emot nervimpulser?","b":"De har receptorer för neurotransmittorer i sitt membran.","ty":"v","src":"s. 20","t":["nyckel"],"id":"k3cejwi00"},{"f":"Varför kan de flesta celler anpassa sitt beteende efter signaler i kroppen?","b":"De har receptorer för hormoner och andra signalämnen.","ty":"v","src":"s. 20","t":["nyckel"],"id":"k3cdbrlue"},{"f":"Vad avgör om och hur mycket en cell påverkas av ett visst ämne?","b":"Hur många receptorer och vilka typer av receptorer celltypen har.","ty":"v","src":"s. 20","t":["nyckel"],"id":"k3cp1ggue"},{"f":"Hur stabiliserar proteiner cellmembranet?","b":"De fungerar som ankare dit proteintrådar som ger stöd åt cellen kan binda och kopplas ihop.","ty":"b","src":"s. 20","id":"k3cilpubn"},{"f":"Vad är glykokalyx?","b":"Ett kolhydratlager på eukaryota cellers yta, av glykolipider och glykoproteiner som är kovalent bundna till sockerkedjor.","ty":"b","src":"s. 20 · korsord 8 vågrätt","p":1,"id":"k3c1pnom00"},{"f":"Glykolipid eller glykoprotein: socker bundet till en lipid?","b":"Glykolipid. Glykoprotein är socker bundet till ett protein.","ty":"j","src":"s. 20","p":1,"id":"k3cc4tipg"},{"f":"Vad jämför boken glykokalyxens sockerkedjor med?","b":"Kläder hos olika yrkesgrupper, som läkarrock och polisuniform. Därför kan en cell \"förstå\" vilken celltyp den har invid sig.","ty":"b","src":"s. 20","p":1,"id":"k3c8iprti"},{"f":"Vilka skydd ger glykokalyx?","b":"Skydd mot mekanisk och kemisk påverkan och mot \"oönskade\" kontakter med attackerande celler.","ty":"b","src":"s. 20","p":1,"id":"k3ccp2guh"},{"f":"Varför blir cellytan slemmig?","b":"Kolhydraterna i glykokalyx absorberar vatten.","ty":"v","src":"s. 20","p":1,"id":"k3c1olkle"},{"f":"Hur hjälper den slemmiga ytan vita blodkroppar?","b":"De kan lättare ta sig ut mellan cellerna i blodkapillärernas väggar och jaga bakterier i vävnaden.","ty":"v","src":"s. 20","id":"k3c1p8foac"},{"f":"Varför fastnar inte röda blodkroppar i varandra?","b":"Deras glatta yta minskar risken att de fäster till varandra eller till blodkärlens väggar.","ty":"v","src":"s. 20","id":"k3chggqkt"},{"f":"Har djurceller cellvägg?","b":"Nej. Det har växtceller (av cellulosa enligt läraren). Djurcellen har cellmembran och extracellulär matrix.","ty":"f","src":"s. 20–21 · PPT Bi2 bild 25","p":1,"t":["vagg"],"id":"k3c3j2syr"},{"f":"Vad är extracellulär matrix?","b":"Ett skikt utanför cellen av glykoproteiner och andra kolhydratinnehållande molekyler som cellen själv utsöndrar.","ty":"b","src":"s. 20","t":["vagg"],"id":"k3c1g0urdx"},{"f":"Var går gränsen mellan glykokalyx och ECM?","b":"Den är något otydlig enligt boken.","ty":"j","src":"s. 20","id":"k3c1wqn8mt"},{"f":"Vad består matrixen i senor och brosk mest av?","b":"Kollagen. Cellerna ligger utspridda i det som russin i en kaka.","ty":"b","src":"s. 20","id":"k3c9tmcq1"},{"f":"Hur fäster kollagenet vid cellen?","b":"Med speciella proteinmolekyler som fäster till proteintrådar inuti cellen.","ty":"b","src":"s. 20","id":"k3c1nqb5x9"},{"f":"Vad gör kollagen med vävnaden?","b":"Gör den elastisk, så att den kan tänjas utan att cellerna går sönder.","ty":"v","src":"s. 20","id":"k3c1vglnyx"},{"f":"Vad är spektrin?","b":"Proteintrådar som bildar ett stabiliserande nät ovanpå de röda blodkropparnas cellmembran. Det ger platt form och ökad hållfasthet.","ty":"b","src":"s. 21","id":"k3c1yw18z1"},{"f":"Vad händer vid en mutation i spektrin?","b":"Blodkropparna blir mer sfäriska och går lätt sönder. Personen blir anemisk (får blodbrist).","ty":"v","src":"s. 21","id":"k3c5step4"},{"f":"Hur kan ECM påverka cellernas beteende?","b":"Den bildar geler med porer som filtrerar vilka molekyler som når membranet. Porerna binder tillväxtfaktorer och signaler, eller blockerar och underlättar molekylernas rörelse.","ty":"v","src":"s. 21","id":"k3c1e1u011"},{"f":"Vilken del av bokens figur s. 18 har sockerkedjor på utsidan?","b":"Markören, ett protein med grenade sockerkedjor som visar celltypen.","ty":"i","src":"s. 18","id":"k3c1i0vfjm"},{"f":"Vad visar pilen från A till B i bokens figur s. 18?","b":"Ett enzym i membranet som omvandlar ämne A till ämne B.","ty":"i","src":"s. 18","id":"k3c145jeqh"},{"f":"Vad heter trådarna under membranet i bokens modell s. 19?","b":"Cellskelett. Fibrerna ovanför membranet är fibrer i extracellulär matrix.","ty":"i","src":"s. 19","id":"k3c1q1nysc"},{"f":"Vilka tre liknelser använder boken i kapitlet?","b":"Nyckel i lås (receptorer), kläder hos yrkesgrupper (glykokalyx) och russin i en kaka (celler i kollagen).","ty":"f","src":"s. 19–20","id":"k3c9kzb55"}],"quiz":{"f":[{"q":"Vad kallas cellmembranet också?","o":["Plasmamembran","Kärnmembran","Cellvägg","Glykokalyx"],"why":"Boken skriver att cellmembranet också kallas plasmamembran. Kärnmembranet omger kärnan. {{src:s. 17}}","src":"s. 17","id":"k3q1ngthm9"},{"q":"Vilken är INTE en av cellmembranets fyra funktioner enligt boken?","o":["Tillverkning av proteiner","Avgränsning mot omvärlden","Kommunikation mellan cell och omgivning","Bindning till närliggande celler"],"why":"Proteiner tillverkas av ribosomerna. De fyra funktionerna är avgränsning, kontroll av transport, kommunikation och bindning.","src":"s. 17","t":["membran"],"id":"k3q10glrew"},{"q":"Hur tar sig vattenlösliga ämnen igenom membranet enligt s. 17?","o":["Med hjälp av transportproteiner","Fritt genom fosfolipiderna","Genom kolesterolet","Genom glykokalyx"],"why":"Det vattenhatande inre stoppar dem, så de behöver transportproteiner.","src":"s. 17","id":"k3qkh9azh"},{"q":"Vad består membranet huvudsakligen av?","o":["Lipider","Proteiner","Kolhydrater","Nukleinsyror"],"why":"Membranet består huvudsakligen av lipider men innehåller också proteiner och kolhydrater.","src":"s. 17","id":"k3q1mvasbg"},{"q":"Var sitter kolhydraterna i membranet?","o":["På utsidan, fästa på lipider och proteiner","På insidan, mot cytoplasman","Inne mellan fettsyrasvansarna","Fritt i cytoplasman"],"why":"Kolhydraterna sticker ut på cellens utsida.","src":"s. 17","id":"k3qc0nb4a"},{"q":"Åt vilket håll pekar fosfolipidernas hydrofila huvuden?","o":["Utåt mot cellens inre och yttre miljö","Inåt mot varandra","Bara mot cellens utsida","Bara mot cytoplasman"],"why":"Huvudena är vattenälskande och vänds mot vattnet på båda sidor. Svansarna pekar mot varandra.","src":"s. 17 · PPT Bi2 bild 14","t":["membran"],"id":"k3q1k5q00v"},{"q":"Vad innehåller fosfolipidens hydrofila huvud enligt läraren?","o":["En fosfatgrupp","Kolesterol","En sockerkedja","En aminosyra"],"why":"PPT bild 14: hydrofilt huvud med en fosfatgrupp och hydrofob svans.","src":"PPT Bi2 bild 14","id":"k3q1elipn5"},{"q":"Vilka krafter håller ihop fosfolipiderna med varandra?","o":["Van der Waals-krafter","Kovalenta bindningar","Jonbindningar","Peptidbindningar"],"why":"Boken säger relativt svaga van der Waals-krafter.","src":"s. 18","id":"k3q1jz5u54"},{"q":"Vad har ishavsfiskar ovanligt mycket av i sina cellmembran?","o":["Fleromättade fettsyror","Mättade fettsyror","Kolesterol","Kollagen"],"why":"Fleromättade fettsyror håller membranen flytande i det kalla vattnet.","src":"s. 18","id":"k3q1hu115e"},{"q":"Vad kallas en fettsyra med fler än en dubbelbindning?","o":["Fleromättad","Mättad","Enkelomättad","Hydrofil"],"why":"En dubbelbindning ger omättad, fler ger fleromättad.","src":"PPT Bi2 bild 12","id":"k3q1qbvr7p"},{"q":"Vad gör kolesterol i djurcellers membran?","o":["Hjälper membranet att hålla sig lagom flytande","Bildar kanaler för vatten","Fungerar som receptor för hormoner","Bryter ner dipeptider"],"why":"Kolesterolet håller membranet lagom flytande. {{src:korsord 9 vågrätt}}","src":"s. 18","id":"k3q1vzmnjw"},{"q":"Vad måste gälla för den yta av ett membranprotein som ligger inne i membranet?","o":["Den måste vara hydrofob","Den måste vara hydrofil","Den måste ha sockerkedjor","Den måste vara laddad"],"why":"Membranets inre är vattenhatande, så den delen av proteinet måste också vara det.","src":"s. 18","id":"k3q1yoj978"},{"q":"Vad kallas transportproteiner som bildar en kanal i sig själva?","o":["Kanalproteiner","Receptorer","Markörer","Glykoproteiner"],"why":"Kanalproteiner bildar en kanal där ämnen kan ta sig igenom.","src":"s. 19","id":"k3qoxxvrn"},{"q":"Vad bryter enzymet på tunntarmscellernas utsida ner?","o":["Dipeptider","Fettsyror","Stärkelse","Väteperoxid"],"why":"Dipeptider bryts ner till fria aminosyror som tas upp med transportprotein.","src":"s. 19","id":"k3q12hgpr2"},{"q":"Vad jämför boken receptorn och signalmolekylen med?","o":["Lås och nyckel","Russin i en kaka","Kläder hos yrkesgrupper","En tvådimensionell vätska"],"why":"En viss molekyl passar som nyckeln i ett lås till en viss receptor.","src":"s. 19","t":["nyckel"],"id":"k3qbps36f"},{"q":"Vilka receptorer gör att en cell kan ta emot nervimpulser?","o":["Receptorer för neurotransmittorer","Receptorer för hormoner","Receptorer för kolesterol","Receptorer för kollagen"],"why":"Neurotransmittorer bär signaler från nervsystemet.","src":"s. 20","t":["nyckel"],"id":"k3q1fvjkfp"},{"q":"Vad bildar glykokalyx?","o":["Glykolipider och glykoproteiner med kovalent bundna sockerkedjor","Kollagen och spektrin","Fosfolipidernas huvuden","Cellskelettets trådar"],"why":"Sockerkedjorna sitter kovalent bundna till lipider och proteiner i membranet.","src":"s. 20","id":"k3q1kf3vaw"},{"q":"Vad gör kolhydraterna i glykokalyx med vatten?","o":["Absorberar vatten, så ytan blir slemmig","Stöter bort vatten, så ytan blir torr","Pumpar ut vatten ur cellen","Bryter ner vatten"],"why":"Den slemmiga ytan hjälper vita blodkroppar ut ur kapillärerna.","src":"s. 20","id":"k3qgsb3bm"},{"q":"I vilka vävnader består matrixen till stor del av kollagen enligt boken?","o":["Senor och brosk","Blod och lymfa","Hjärna och nerver","Lever och njurar"],"why":"Cellerna i senor och brosk ligger i kollagenet som russin i en kaka.","src":"s. 20","id":"k3q1hp74fr"},{"q":"Vad gör spektrin?","o":["Ger röda blodkroppar platt form och ökad hållfasthet","Gör senor elastiska","Binder neurotransmittorer","Håller membranet lagom flytande"],"why":"Spektrin bildar ett stabiliserande nät hos röda blodkroppar.","src":"s. 21","id":"k3q1vhigq6"},{"q":"Vad saknar djurceller till skillnad från växtceller?","o":["Cellvägg","Cellmembran","Ribosomer","Mitokondrier"],"why":"Djurceller saknar cellvägg. Läraren: cellväggen finns i växtceller.","src":"s. 20–21 · PPT Bi2 bild 25","t":["vagg"],"id":"k3q10xsrta"}],"u":[{"q":"En cell lever i en omgivning med en annan salthalt än cellens insida. Vilken av membranets funktioner gör det möjligt?","o":["Avgränsning, som skapar en egen inre miljö","Kommunikation via receptorer","Bindning till närliggande celler","Enzymaktivitet på utsidan"],"why":"Membranet skiljer cellen från omgivningen, och därför kan cellen reglera salthalt och pH.","src":"s. 17","id":"k3qe032xv"},{"q":"Ett nytt läkemedel är mycket fettlösligt. Vad är troligast?","o":["Det tar sig fritt genom cellmembranet","Det behöver ett kanalprotein","Det stoppas helt av membranet","Det fastnar i glykokalyx"],"why":"Membranets inre är fettälskande, så fettlösliga ämnen passerar fritt.","src":"s. 17","id":"k3q10gp6w4"},{"q":"Varför kan membranblåsor smälta samman med cellmembranet?","o":["Membranet är flytande, eftersom fosfolipiderna glider runt varandra","Membranet är en stel hinna som spricker","Blåsorna är gjorda av kollagen","Blåsorna har cellvägg"],"why":"Membranet är en tvådimensionell vätska och kan därför ändra form och smälta ihop.","src":"s. 17–18","t":["membran"],"id":"k3qnepeln"},{"q":"Två membran har lika långa fettsyror. Membran A har raka fettsyror och membran B veckade. Vilket stelnar först när det blir kallt?","o":["A, eftersom raka svansar packas tätt och ger starkare van der Waals-krafter","B, eftersom veckade svansar ger starkare krafter","Båda samtidigt, eftersom längden är lika","Inget av dem, eftersom membran aldrig stelnar"],"why":"Veckade svansar ger större avstånd och svagare krafter, så B förblir flytande längre.","src":"s. 18","id":"k3q1xqmdb9"},{"q":"Två membran har samma sorts mättade fettsyror, men i membran A är de längre. Vilket är trögast?","o":["A, eftersom längre fettsyror ger större yta för van der Waals-krafterna","B, eftersom kortare fettsyror packas tätare","Lika tröga, eftersom typen är samma","Det beror bara på kolesterolet"],"why":"Ju längre fettsyror, desto större yta för krafterna och desto trögare membran.","src":"s. 18","id":"k3qqiyq2"},{"q":"Varför är olja flytande men smör fast vid rumstemperatur, enligt samma princip som membranet?","o":["Olja har mer omättade fettsyror med knäckar som inte packas tätt","Olja har längre fettsyror","Smör innehåller mer vatten","Olja innehåller mer kolesterol"],"why":"Omättade fetter är flytande vid rumstemperatur (läraren). Knäckarna ger större avstånd och svagare krafter.","src":"PPT Bi2 bild 10–12 · s. 18","id":"k3q1isf4g4"},{"q":"Ett hormon finns i hela blodet, men bara vissa celler reagerar. Varför?","o":["Bara de cellerna har receptorer för hormonet","Hormonet når bara vissa celler","De andra cellerna saknar cellmembran","Hormonet bryts ner i glykokalyx"],"why":"Antalet och typen av receptorer avgör om och hur mycket en cell påverkas.","src":"s. 20","t":["nyckel"],"id":"k3qbru146"},{"q":"Vad har tunntarmens dipeptid-enzym och ett transportprotein gemensamt i bokens exempel?","o":["Båda är membranproteiner som samarbetar så att aminosyror kan tas upp","Båda är receptorer för hormoner","Båda sitter i lysosomerna","Båda är kolhydrater"],"why":"Enzymet bryter ner dipeptiden på utsidan och transportproteinet tar in aminosyrorna.","src":"s. 19","id":"k3qi0irg3"},{"q":"Hur kan en cell 'veta' vilken celltyp som ligger bredvid den?","o":["Genom grannens glykokalyx, vars sockerkedjor är olika för olika celltyper","Genom att läsa grannens DNA","Genom grannens kolesterol","Genom att mäta grannens pH"],"why":"Sockerkedjorna fungerar som kläder hos olika yrkesgrupper.","src":"s. 20","id":"k3qfoi30q"},{"q":"Varför är en slemmig cellyta en fördel i blodkärlen?","o":["Vita blodkroppar glider lätt ut ur kapillärerna och röda blodkroppar fastnar inte","Den gör att röda blodkroppar klumpar ihop sig","Den stoppar allt vatten","Den gör kärlväggen stelare"],"why":"Kolhydraterna binder vatten. Det hjälper både vita och röda blodkroppar.","src":"s. 20","id":"k3q1b427dk"},{"q":"Varför går en sena inte sönder när den tänjs?","o":["Kollagenet i matrixen gör vävnaden elastisk","Spektrin håller cellerna platta","Glykokalyx gör senan slemmig","Cellväggen håller emot"],"why":"Kollagen gör att vävnaden kan tänjas utan att cellerna går sönder.","src":"s. 20","id":"k3q1g3b1l9"},{"q":"Vilken skillnad mellan glykokalyx och ECM stämmer med boken?","o":["Glykokalyx sitter på cellytan i membranet, ECM ligger utanför och utsöndras av cellen","Glykokalyx finns bara i växtceller","ECM består av fosfolipider","Det finns ingen likhet mellan dem"],"why":"Båda innehåller kolhydrater, men ECM utsöndras och ligger utanför. Gränsen är något otydlig.","src":"s. 20","id":"k3q15zx8bx"},{"q":"ECM kan binda tillväxtfaktorer i sina porer. Vad blir följden?","o":["ECM påverkar vilka signaler som når cellen och därmed cellens beteende","Cellen får en cellvägg","Membranet blir mer flytande","Cellen kan inte längre ta upp fett"],"why":"Gelen fungerar som ett filter för signaler.","src":"s. 21","id":"k3qf2gl33"}],"o":[{"q":"Beskriv cellmembranets uppbyggnad och förklara varför det släpper igenom fettlösliga men inte vattenlösliga ämnen.","model":"Membranet består mest av lipider, men också av proteiner och kolhydrater som sticker ut på utsidan. Grunden är ett dubbelt lager av fosfolipider. De hydrofila huvudena (med fosfatgrupp) pekar ut mot vattnet på båda sidor och de hydrofoba fettsyrasvansarna pekar mot varandra. Inre delen är alltså fettälskande och vattenhatande. Därför kan fettlösliga ämnen passera fritt, medan vattenlösliga ämnen behöver transportproteiner. På så sätt kan cellen reglera vad som går in och ut.","kw":[["lipid","fosfolipid"],["dubbel"],["hydrofil","huvud"],["hydrofob","svans"],["fettlösl"],["transportprotein"]],"src":"s. 17 · PPT Bi2 bild 14","t":["membran"],"id":"k3o16pjonl"},{"q":"Förklara vad som påverkar hur flytande ett cellmembran är. Ge ett exempel från boken.","model":"Fosfolipiderna hålls ihop av relativt svaga van der Waals-krafter. Omättade fettsyror har dubbelbindningar som gör svansarna veckade. Då blir avståndet större och krafterna svagare, och membranet förblir flytande vid lägre temperatur än med raka, mättade fettsyror. Längre fettsyror ger större yta för krafterna och därför ett trögare membran. Kolesterol håller djurcellers membran lagom flytande. Exempel: ishavsfiskar har mycket fleromättade fettsyror så att membranen inte stelnar i det kalla vattnet.","kw":[["van der waals"],["omättad","dubbelbind","veckad"],["avstånd"],["längd","längre"],["kolesterol"],["ishavsfisk","fisk"]],"src":"s. 18","id":"k3ojj64a4"},{"q":"Redogör för membranproteinernas funktioner med bokens exempel.","model":"Membranproteiner kan gå genom hela membranet eller sitta i ena sidan, och delen i membranet måste vara hydrofob. De sköter transport: kanalproteiner bildar kanaler, andra ändrar form när molekylen binder, och vissa kräver energi. De kan vara enzymer, till exempel enzymet på tunntarmscellernas utsida som bryter ner dipeptider till aminosyror. De kan vara receptorer där signalmolekyler passar som nyckel i lås, för neurotransmittorer och hormoner. Antalet och typen avgör hur mycket cellen påverkas. De kopplar ihop cellen med andra celler eller ECM och fungerar som ankare för cellskelettet.","kw":[["transport","kanal"],["enzym"],["dipeptid","tunntarm"],["receptor"],["nyckel","lås"],["ankar","cellskelett"],["koppla","matrix","andra celler"]],"src":"s. 18–20","t":["nyckel"],"id":"k3o1wfd5v3"},{"q":"Jämför glykokalyx och extracellulär matrix. Ge exempel på vad de gör.","model":"Glykokalyx är ett kolhydratlager på cellytan som bildas av glykolipider och glykoproteiner i membranet med kovalent bundna sockerkedjor. Kedjorna fungerar som kläder hos olika yrkesgrupper så att celler känner igen varandra. Glykokalyx skyddar mot mekanisk och kemisk påverkan och mot attackerande celler, och eftersom kolhydraterna binder vatten blir ytan slemmig. Då kan vita blodkroppar ta sig ut ur kapillärerna och röda blodkroppar fastnar inte. ECM är ett skikt utanför cellen av glykoproteiner och andra kolhydratinnehållande molekyler som cellen utsöndrar, eftersom djurceller saknar cellvägg. Exempel är kollagen i senor och brosk som gör vävnaden elastisk och spektrin som ger röda blodkroppar platt form. ECM kan också bilda geler som filtrerar signaler. Gränsen mellan dem är otydlig.","kw":[["glykolipid","glykoprotein"],["kläder","känna igen"],["skydd"],["slemmig","vatten"],["utsöndr","utanför"],["kollagen"],["spektrin"]],"src":"s. 20–21","id":"k3oix6lsz"}]},"kan":[{"q":"Kan du nämna cellmembranets fyra funktioner?","a":"Cellmembranet avgränsar cellen mot omvärlden, kontrollerar in- och uttransport av ämnen, sköter kommunikationen mellan cellen och omgivningen och binder cellen till närliggande celler. Läraren sammanfattar det som ett yttre skydd som släpper in och ut vissa ämnen.","kw":[["avgräns"],["kontroll","in- och ut","transport"],["kommunik"],["bind","fäst","närliggande"]],"src":"s. 17 · PPT Bi2 bild 22","id":"k3kprova0"},{"q":"Kan du förklara varför fettlösliga ämnen passerar fritt men inte vattenlösliga?","a":"Membranets inre består av fettsyrasvansar och är fettälskande och vattenhatande. Därför kan fettlösliga ämnen ta sig igenom fritt. Vattenlösliga ämnen stoppas och behöver transportproteiner, och därför kan cellen reglera vad som går in och ut.","kw":[["fettälsk","hydrofob","fettlösl"],["vattenhat"],["transportprotein"],["reglera","kontroll"]],"src":"s. 17","id":"k3k1iuvo1a"},{"q":"Kan du beskriva hur fosfolipiderna ligger i membranet?","a":"De bildar ett dubbelt lager. De hydrofoba fettsyrasvansarna pekar mot varandra i mitten och de hydrofila huvudena, med en fosfatgrupp, pekar ut mot vattnet på cellens insida och utsida. Därför skyddas svansarna från vattnet.","kw":[["dubbel","två lager"],["svans"],["huvud"],["hydrofil","vattenälsk"],["hydrofob","vattenhat"]],"src":"s. 17 · PPT Bi2 bild 14","id":"k3kie9r2s"},{"q":"Kan du förklara vad boken menar med att membranet är en tvådimensionell vätska?","a":"Fosfolipiderna och proteinerna glider ständigt runt varandra i membranet, så membranet är ingen fast hinna. Delarna flyter omkring i membranets plan. Därför kan membranet ändra form och bilda membranblåsor som smälter samman med andra blåsor eller med cellmembranet.","kw":[["glider","flyter","rör sig"],["fast hinna","inte fast","vätska"],["ändra form"],["membranblås","blåsor","vesik"]],"src":"s. 17–18","id":"k3k1bcwblj"},{"q":"Kan du förklara hur fettsyrornas typ påverkar hur flytande membranet är?","a":"Fosfolipiderna hålls ihop av relativt svaga van der Waals-krafter. Omättade fettsyror har dubbelbindningar som gör svansarna veckade. Då blir avståndet mellan molekylerna större och krafterna svagare, och därför är membranet flytande vid lägre temperatur än med raka, mättade fettsyror.","kw":[["van der waals"],["omättad","dubbelbind"],["veckad","knäck"],["avstånd"],["lägre temperatur","kyla","kallt"]],"src":"s. 18","id":"k3ka0dc3t"},{"q":"Kan du förklara hur fettsyrornas längd och kolesterolet påverkar membranet?","a":"Längre fettsyror ger större yta för van der Waals-krafterna att verka på. Därför blir membranet mer trögflytande, och längden påverkar fryspunkten. Kolesterol, som finns i djurcellers membran, hjälper membranet att hålla sig lagom flytande.","kw":[["längre","längd"],["yta"],["trög"],["kolesterol"],["lagom"]],"src":"s. 18","id":"k3k19s28lw"},{"q":"Kan du nämna membranproteinernas fem funktioner?","a":"Transport av ämnen genom membranet, enzymaktivitet, att fungera som receptorer, att koppla ihop cellen med andra celler eller med extracellulär matrix, och att förankra cellskelettets proteinkedjor i membranet.","kw":[["transport"],["enzym"],["receptor"],["koppla","ihop","matrix"],["ankar","förankr","cellskelett"]],"src":"s. 18","id":"k3k19dl1fk"},{"q":"Kan du beskriva de två typerna av transportproteiner som boken nämner?","a":"Kanalproteiner bildar en kanal i sig själva som ämnen kan ta sig igenom. Andra transportproteiner ändrar form när molekylen som ska transporteras binder till dem, och hjälper på så sätt molekylen genom membranet. Vissa transportproteiner kräver energi och andra inte.","kw":[["kanal"],["ändrar form","formändr"],["bind"],["energi"]],"src":"s. 19","id":"k3kflfoez"},{"q":"Kan du förklara hur receptorer fungerar och vad som avgör hur mycket en cell påverkas av ett ämne?","a":"En viss signalmolekyl passar i en viss receptor som en nyckel i ett lås och låser upp aktiviteter i cellen. Det finns receptorer för neurotransmittorer och för hormoner. Antalet och typen av receptorer på celltypen avgör om och hur mycket cellen påverkas.","kw":[["nyckel","lås"],["neurotransmitt","hormon","signal"],["antal","hur många"],["typ","vilka"]],"src":"s. 19–20","id":"k3koxwi16"},{"q":"Kan du förklara vad glykokalyx är och vad den gör?","a":"Glykokalyx är ett kolhydratlager på eukaryota cellers yta. Det bildas av glykolipider och glykoproteiner som är kovalent bundna till sockerkedjor. Kedjorna är olika som kläder hos olika yrken, så celler känner igen varandra. Glykokalyx skyddar mot mekanisk och kemisk påverkan och mot attackerande celler, och eftersom kolhydraterna binder vatten blir ytan slemmig.","kw":[["kolhydrat","socker"],["glykolipid"],["glykoprotein"],["kläder","uniform","känna igen","celltyp"],["skydd"],["slemmig","vatten"]],"src":"s. 20","id":"k3kxlr919"},{"q":"Kan du beskriva extracellulär matrix och ge bokens två exempel?","a":"Djurceller saknar cellvägg. Utanför cellen finns i stället ett skikt av glykoproteiner och andra kolhydratinnehållande molekyler som cellen utsöndrar. I senor och brosk består matrixen mycket av kollagen, och cellerna ligger som russin i en kaka. Röda blodkroppar har spektrin som håller dem platta och hållfasta.","kw":[["cellvägg"],["glykoprotein"],["utsöndr"],["kollagen"],["spektrin"]],"src":"s. 20–21","id":"k3k1vcadj1"}],"kompis":[{"q":"Förklara för en kompis varför ishavsfisken inte fryser fast inifrån.","model":"Membranet hålls ihop av van der Waals-krafter, som är relativt svaga. I kallt vatten skulle ett membran med raka, mättade fettsyror packas tätt och stelna, och då slutar det fungera. Ishavsfiskar har ovanligt mycket fleromättade fettsyror. De har flera dubbelbindningar som gör svansarna veckade, så molekylerna hamnar längre ifrån varandra och krafterna blir svagare. Därför förblir membranet flytande även i kylan.","kw":[["van der waals"],["fleromätt","omättad","dubbelbind"],["veckad","knäck"],["avstånd"],["stelna"]],"src":"s. 18","id":"k3e1axoouf"},{"q":"Förklara för en kompis hur en vit blodkropp får hjälp av glykokalyx när den jagar bakterier.","model":"Glykokalyx är cellernas sockerpäls av glykolipider och glykoproteiner. Kolhydraterna absorberar vatten, och därför blir cellytan slemmig. Det gör det mycket lättare för vita blodkroppar att glida ut genom öppningarna mellan cellerna i blodkapillärernas väggar. Där ute i vävnaden kan de jaga bakterier och andra inkräktare.","kw":[["glykokalyx","sockerpäls","kolhydrat"],["vatten"],["slemmig"],["kapillär"],["bakterie","inkräkt"]],"src":"s. 20","id":"k3e1wljpbw"},{"q":"Förklara för en kompis varför en mutation i spektrin ger blodbrist.","model":"Spektrin är proteintrådar som bildar ett stabiliserande nät som ger röda blodkroppar deras platta form och ökad hållfasthet. Boken räknar det till blodkropparnas extracellulära matrix. Om spektrin är muterat blir blodkropparna mer sfäriska och går lätt sönder. När många blodkroppar går sönder blir det för få kvar, och personen blir anemisk, alltså får blodbrist.","kw":[["spektrin"],["platt"],["sfärisk","rund"],["sönder"],["anemi","blodbrist"]],"src":"s. 21","id":"k3egy6au7"}],"gloss":[{"w":"Cellmembran","d":"Det tunna fosfolipiddubbelskiktet med proteiner som omger cellen. Avgränsar, kontrollerar transport, kommunicerar och binder till andra celler.","src":"Bok s. 17 · PPT Bi2 bild 22"},{"w":"Plasmamembran","d":"Annat namn för cellmembranet.","src":"Bok s. 17"},{"w":"Lipid","d":"Fettämne. Membranet består huvudsakligen av lipider.","src":"Bok s. 17"},{"w":"Fosfolipid","d":"Lipid med ett hydrofilt huvud (med fosfatgrupp) och hydrofoba fettsyrasvansar. Bygger membranets dubbelskikt.","src":"Bok s. 17 · PPT Bi2 bild 14"},{"w":"Hydrofil","d":"Vattenälskande. Fosfolipidens huvud är hydrofilt.","src":"Bok s. 17"},{"w":"Hydrofob","d":"Vattenhatande. Fettsyrasvansarna och den del av ett membranprotein som ligger i membranet är hydrofoba.","src":"Bok s. 17–18"},{"w":"Dubbelskikt","d":"Två lager fosfolipider med svansarna mot varandra och huvudena utåt.","src":"Bok s. 17"},{"w":"Tvådimensionell vätska","d":"Bokens bild av membranet. Fosfolipider och proteiner glider runt varandra i membranets plan.","src":"Bok s. 17"},{"w":"Membranblåsa","d":"Liten blåsa av membran (vesikel) som kan smälta samman med andra blåsor eller med cellmembranet.","src":"Bok s. 17–18"},{"w":"Van der Waals-krafter","d":"Relativt svaga krafter som håller ihop fosfolipiderna. Blir svagare när avståndet ökar.","src":"Bok s. 18"},{"w":"Mättad fettsyra","d":"Rak fettsyra med bara enkelbindningar. Packas tätt och ger trögare membran.","src":"Bok s. 18 · PPT Bi2 bild 10–13"},{"w":"Omättad fettsyra","d":"Fettsyra med en dubbelbindning som ger en knäck. Ger mer flytande membran.","src":"Bok s. 18 · PPT Bi2 bild 11–13"},{"w":"Fleromättad fettsyra","d":"Fettsyra med fler än en dubbelbindning. Ishavsfiskar har mycket sådana.","src":"Bok s. 18 · PPT Bi2 bild 12–13"},{"w":"Kolesterol","d":"Steroid i djurcellers membran som håller membranet lagom flytande.","src":"Bok s. 18 · PPT Bi2 bild 14 · korsord"},{"w":"Membranprotein","d":"Protein som går genom membranet eller sitter i ena sidan. Delen i membranet är hydrofob.","src":"Bok s. 18"},{"w":"Transportprotein","d":"Membranprotein som hjälper ämnen genom membranet. Vissa kräver energi, andra inte.","src":"Bok s. 17–19"},{"w":"Kanalprotein","d":"Transportprotein som bildar en kanal i sig självt.","src":"Bok s. 19"},{"w":"Enzym","d":"Protein som katalyserar en kemisk reaktion. Vissa sitter i membranet, t.ex. tunntarmscellernas dipeptid-enzym.","src":"Bok s. 19"},{"w":"Dipeptid","d":"Två aminosyror som sitter ihop.","src":"Bok s. 19"},{"w":"Receptor","d":"Protein som tar emot en signalmolekyl som passar som nyckel i lås.","src":"Bok s. 17, 19–20"},{"w":"Neurotransmittor","d":"Signalämne från nervsystemet. Celler med receptorer för det kan ta emot nervimpulser.","src":"Bok s. 20"},{"w":"Hormon","d":"Signalämne i kroppen. De flesta celler har receptorer för hormoner.","src":"Bok s. 20"},{"w":"Markör","d":"Protein med sockerkedjor i bokens figur s. 18, som visar vilken celltyp det är.","src":"Bok s. 18"},{"w":"Glykokalyx","d":"Kolhydratlager på eukaryota cellers yta, av glykolipider och glykoproteiner.","src":"Bok s. 20 · korsord"},{"w":"Glykolipid","d":"Lipid i membranet som är kovalent bunden till en sockerkedja.","src":"Bok s. 20"},{"w":"Glykoprotein","d":"Protein med en sockergrupp (kovalent bunden sockerkedja).","src":"Bok s. 20"},{"w":"Extracellulär matrix (ECM)","d":"Skikt utanför djurceller av glykoproteiner och andra kolhydratinnehållande molekyler som cellen utsöndrar.","src":"Bok s. 20–21"},{"w":"Extracellulär","d":"Utanför cellen.","src":"Bok s. 20"},{"w":"Kollagen","d":"Protein som bygger matrixen i senor och brosk och gör vävnaden elastisk.","src":"Bok s. 20"},{"w":"Spektrin","d":"Proteintrådar som ger röda blodkroppar platt form och hållfasthet. Mutation ger anemi.","src":"Bok s. 21"},{"w":"Anemi","d":"Blodbrist.","src":"Bok s. 21"},{"w":"Tillväxtfaktor","d":"Signalämne för celler. Kan bindas i ECM:s porer.","src":"Bok s. 21"},{"w":"Cellvägg","d":"Vägg utanför cellmembranet hos växtceller (av cellulosa). Djurceller saknar cellvägg.","src":"Bok s. 20–21 · PPT Bi2 bild 25"}],"snabb":{"keys":["Plasmamembran :: annat namn för cellmembranet","Membranets 4 funktioner :: avgränsning, kontroll av transport, kommunikation, bindning","Passerar fritt :: fettlösliga ämnen (inre är fettälskande)","Vattenlösliga ämnen :: behöver transportproteiner","Membranets molekyler :: lipider (mest), proteiner, kolhydrater på utsidan","Fosfolipidens huvud :: hydrofilt, med fosfatgrupp, pekar utåt","Tvådimensionell vätska :: delarna glider runt varandra, membranet kan bilda blåsor","Omättade fettsyror :: veckade, större avstånd, svagare van der Waals, mer flytande","Kolesterol :: håller djurcellens membran lagom flytande","TERKA :: transport, enzym, receptor, koppla ihop, ankare","Receptor :: lås där rätt signalmolekyl (nyckel) passar","Glykokalyx :: sockerpäls av glykolipider och glykoproteiner","ECM :: glykoproteiner utanför cellen, t.ex. kollagen och spektrin","Spektrin muterat :: sfäriska röda blodkroppar, går sönder, anemi"],"nums":[["10 000","membran på varandra behövs för att nå en boksidas tjocklek (minst)"],["4","funktioner hos cellmembranet"],["5","funktioner hos membranproteinerna"],["2","lager fosfolipider i membranet"],["1 / fler än 1","dubbelbindningar i en omättad / fleromättad fettsyra (läraren)"]],"chains":[["Fettälskande inre","fettlösliga ämnen passerar fritt","vattenlösliga behöver transportprotein","cellen reglerar transporten"],["Dubbelbindning","veckad svans","större avstånd","svagare van der Waals-krafter","flytande vid lägre temperatur"],["Längre fettsyror","större yta för krafterna","trögare membran"],["Kolhydrater binder vatten","slemmig yta","vita blodkroppar tar sig ut ur kapillärerna"],["Mutation i spektrin","sfäriska röda blodkroppar","går lätt sönder","anemi"],["Dipeptid","enzym på tunntarmscellens utsida","fria aminosyror","tas upp med transportprotein"]],"traps":["Det är FETTlösliga ämnen som passerar fritt, inte vattenlösliga.","Längre fettsyror ger ett TRÖGARE membran.","Kolesterolet finns enligt boken i DJURcellers membran och håller det LAGOM flytande.","Nyckel i lås = receptorer. Kläder = glykokalyx. Russin i kaka = celler i kollagen.","Djurceller saknar cellvägg. Deras skydd är cellmembranet och det som cellen utsöndrar.","Matrix i mitokondrien och extracellulär matrix är två helt olika saker.","Boken lägger spektrin i röda blodkroppars ECM ovanpå membranet. Svara som boken."]}},"k4":{"pre":[{"q":"Var i cellen tillverkas proteinerna?","o":["I ribosomerna","I lysosomerna","I golgiapparaten","I cellkärnan"],"why":"Ribosomerna är platsen för proteinsyntesen. Golgiapparaten ändrar och skickar vidare proteiner men tillverkar dem inte.","src":"s. 23 · PPT Bi2 bild 22","t":["ribosom"],"id":"k4p1m6omcp"},{"q":"Vilken organell kallas cellens kraftverk?","o":["Mitokondrien","Kärnan","Golgiapparaten","Peroxisomen"],"why":"De flesta ATP-molekyler bildas i mitokondrien, och därför kallas den cellens kraftverk.","src":"s. 27 · PPT Bi2 bild 22","t":["atp"],"id":"k4plapruj"},{"q":"Varför bryter inte lysosomens enzymer ner hela cellen om en lysosom går sönder?","o":["Enzymerna fungerar sämre i cytoplasmans högre pH","Enzymerna förstörs direkt av katalas","Cytoplasman saknar makromolekyler","Lysosomer kan aldrig gå sönder"],"why":"Enzymerna fungerar bäst vid det låga pH-värdet i lysosomen. I cytoplasman är pH högre, och därför fungerar de sämre där.","src":"s. 26","id":"k4p1aoufm"},{"q":"Varför tror man att mitokondrien en gång var en bakterie?","o":["Den har två membran, eget ringformat DNA och bakterieliknande ribosomer","Den kan dela sig utanför cellen","Den har en cellvägg av cellulosa","Den tillverkar antibiotika"],"why":"Det är endosymbiosteorins bevis enligt boken. Det inre membranet kommer från bakteriens cellmembran.","src":"s. 27","t":["endo"],"id":"k4p1jummd"},{"q":"Var tillverkas fosfolipiderna till cellens membran?","o":["I slätt ER (SER)","I kornigt ER (RER)","I ribosomerna","I lysosomerna"],"why":"SER saknar ribosomer och sköter lipidmetabolismen. Där bildas fosfolipiderna som fyller på membranen med byggmaterial.","src":"s. 24","t":["membran"],"id":"k4p1cjaark"}],"cards":[{"f":"Varför ser celler i en flercellig organism olika ut?","b":"De är specialiserade på olika arbetsuppgifter, och därför har de inte bara olika funktion utan också olika utseende. Lärobokens djurcell är en \"genomsnittlig\" cell.","ty":"v","src":"s. 21 · PPT Bi2 bild 20","p":1,"id":"k4cl11t2a"},{"f":"Vad är djurcellens enda skydd mot omgivningen?","b":"Cellmembranet, tillsammans med vissa ämnen som cellen utsöndrar. Djurceller har ingen cellvägg, till skillnad från växtceller.","ty":"b","t":["vagg","membran"],"src":"s. 21 · PPT Bi2 bild 25","p":1,"id":"k4c1hyftau"},{"f":"Vad är cytoplasma?","b":"En tjock vätska innanför cellmembranet med många ämnen lösta i vatten. Där sker många av cellens kemiska reaktioner, och den omger organellerna och inklusionskropparna.","ty":"b","src":"s. 21 · PPT Bi2 bild 22 · korsord 5 vågrätt","p":1,"id":"k4c9o06ei"},{"f":"Vad kallar läraren cytoplasman, och hur beskriver hon den?","b":"Cellplasma: \"Innehåller specialiserade celldelar samt mycket vatten.\" Båda orden passar i korsordet.","ty":"b","src":"PPT Bi2 bild 22 · korsord 5 vågrätt","id":"k4cvkit7j"},{"f":"Vad är inklusionskroppar?","b":"Kemiska ämnen i cytoplasman som hör ihop med just den celltypen. Därför finns de inte i alla celler.","ty":"b","src":"s. 21–22","id":"k4cc9xnkv"},{"f":"Ge fyra exempel på inklusionskroppar.","b":"Lagrad energi: glykogen i leverceller och fett i fettceller. Cellprodukter: melanin (pigment) i hudceller och slem i slemproducerande celler.","ty":"s","src":"s. 21–22","id":"k4c9nwa78"},{"f":"Vilka 13 etiketter har bokens djurcell på s. 21?","b":"Cytoplasma, cellmembran, ER, ER med ribosomer, ribosomer, golgiapparat, centrioler, mitokondrie, DNA, kärnmembran, kärna, vakuol och lysosom.","ty":"i","src":"s. 21","id":"k4c1x5gjnj"},{"f":"Vilka två delar i bokens djurcell förklaras inte i texten på s. 17–27?","b":"En liten vakuol och centrioler. Du ska kunna peka ut dem i bilden.","ty":"i","src":"s. 21","id":"k4cxttm6l"},{"f":"Vilka två organeller beskriver boken i texten men saknar etikett i djurcellsbilden?","b":"Peroxisomer och cellskelettet.","ty":"i","src":"s. 21, 26–27","id":"k4c8mauiv"},{"f":"Vilka nio etiketter har lärarens enkla djurcell (bild 21)?","b":"Cellmembran, arvsmassa DNA, cellkärna, lysosom, golgiapparaten, cytoplasma, mitokondrie, endoplasmatiska nätverket och ribosomer (både på ER och fria).","ty":"i","src":"PPT Bi2 bild 21 · s. 21","p":1,"id":"k4c1wg17jz"},{"f":"Har djurceller vakuoler?","b":"Bokens djurcell har en liten vakuol. Den stora vätskefyllda vakuolen (cellsaftrum) är typisk för växtcellen.","ty":"f","src":"s. 21 · PPT Bi2 bild 25","p":1,"id":"k4c1ikiphc"},{"f":"Vad finns i cellkärnan och vad omges den av?","b":"Det allra mesta av cellens arvsmassa. Kärnan omges av ett dubbelt membran, kärnmembranet.","ty":"b","src":"s. 22 · PPT Bi2 bild 22 · korsord 10 lodrätt","p":1,"id":"k4c1covaf0"},{"f":"Provfälla: finns ALL arvsmassa i kärnan?","b":"Nej, det allra mesta. Mitokondrien har eget DNA.","ty":"f","t":["endo"],"src":"s. 22, 27","id":"k4c1i9tiwn"},{"f":"Vad är nukleoplasma?","b":"Den geléliknande vätska som kärnmembranet omsluter. Den innehåller ett nätverk av proteintrådar som ger stöd åt kärnan, enzymer och nukleotider.","ty":"b","src":"s. 22 · korsord 7 lodrätt","p":1,"id":"k4crwfkwn"},{"f":"Vad är kärnporer och vad är de bra för?","b":"Ganska stora porer i kärnmembranet som underlättar transport genom membranet. Genom dem tar sig t.ex. mRNA ut till ribosomerna.","ty":"b","src":"s. 22","id":"k4cecldc1"},{"f":"Vilken organell är kärnmembranet ihopkopplat med?","b":"Endoplasmatiska nätverket (ER), på flera ställen.","ty":"b","src":"s. 22–24","id":"k4c1kz63jq"},{"f":"Hur är DNA ordnat i kärnan?","b":"Lindat kring histonproteiner till trådar som är ungefär 30 nm tjocka. Trådarna hänger med ojämna mellanrum i proteiner på kärnmembranets insida, och därför bildas loopar.","ty":"b","src":"s. 22","id":"k4cpcekc1"},{"f":"Vad har man sett om generna på samma loop?","b":"Proteiner som regleras gemensamt och används i samma situationer ligger ofta på samma loop (boken skriver proteiner men menar generna för dem).","ty":"b","src":"s. 22","id":"k4c16zqicg"},{"f":"Vad är kromatin?","b":"Blandningen av DNA och proteiner i cellkärnan.","ty":"b","src":"s. 22 · korsord 9 lodrätt","p":1,"id":"k4c1evumyy"},{"f":"Tätpackat eller löspackat kromatin: vilka gener kan användas?","b":"Generna i löspackat kromatin, eftersom enzymerna kommer fram och bildar budbärar-RNA. I tätpackat kromatin kommer enzymerna inte åt.","ty":"j","src":"s. 22","id":"k4cmevfsz"},{"f":"Hur stänger en specialiserad cell av gener den inte behöver?","b":"Den gör kromatinet tätpackat i de regionerna, och därför kommer enzymerna inte åt generna.","ty":"v","src":"s. 22","id":"k4c1ci2xzp"},{"f":"När kan man se kromosomerna i ett vanligt ljusmikroskop?","b":"Bara vid celldelning. Då upphör kärnan, kärnmembranet löses upp och kromatinets loopar förs ihop till kroppar som är så stora att de syns.","ty":"b","src":"s. 22","id":"k4c1xx5sff"},{"f":"Provfälla: boken skriver att cellmembranet löses upp vid celldelningen. Stämmer det?","b":"Nej, det är ett tryckfel. Det är kärnmembranet som löses upp, eftersom det är kärnan som upphör att existera.","ty":"f","src":"s. 22","id":"k4c14f5j5j"},{"f":"Vad är en nukleol?","b":"Ett mörkfärgat parti i kärnan (syns i elektronmikroskop). Den bildas runt DNA-regioner som kodar för rRNA och består mest av rRNA som väntar på att föras ut genom en kärnpor.","ty":"b","src":"s. 23 · korsord 4 lodrätt","p":1,"id":"k4c1a0oo3c"},{"f":"Varför syns nukleolerna extra tydligt i celler som gör mycket protein?","b":"De behöver många ribosomer och därför mycket rRNA, som bildas i nukleolerna.","ty":"v","t":["ribosom"],"src":"s. 23","id":"k4c7h5zyx"},{"f":"Nukleol, nukleoplasma eller nukleotid?","b":"Nukleol = mörk klump av rRNA i kärnan. Nukleoplasma = vätskan i kärnan. Nukleotid = byggsten i DNA och RNA.","ty":"j","src":"s. 22–23 · PPT Bi2 bild 27–28","p":1,"id":"k4cx489i7"},{"f":"Vilka etiketter har bokens figur av kärnan på s. 23?","b":"Nukleol, cytoplasma, kromatin (kromosomer), ER med ribosomer, ER, ribosomer och kärnmembran.","ty":"i","src":"s. 23","id":"k4c1m80h94"},{"f":"Vad händer i ribosomerna?","b":"Proteinsyntesen. Läraren: \"Här tillverkar cellen proteiner.\"","ty":"b","t":["ribosom"],"src":"s. 23 · PPT Bi2 bild 22 · korsord 1 vågrätt","p":1,"id":"k4c1c55bpo"},{"f":"Vad består en ribosom av?","b":"Två subenheter som båda består av rRNA och proteiner. De cirkulerar fritt i cytoplasman.","ty":"b","t":["ribosom"],"src":"s. 23","id":"k4c1dh8fsb"},{"f":"Vilken subenhet fäster först på mRNA?","b":"Den lilla. Sedan fäster den stora.","ty":"f","t":["ribosom"],"src":"s. 23","id":"k4c1ucriy5"},{"f":"Vad gör tRNA vid proteinsyntesen?","b":"Levererar aminosyror, som med ribosomens hjälp radas upp i rätt ordning längs mRNA.","ty":"b","src":"s. 23","id":"k4cvsy1ku"},{"f":"Vilka proteiner görs på ER-bundna ribosomer?","b":"Proteiner som ska exporteras ut ur cellen, sitta i cellmembranet eller arbeta i lysosomerna. De förs in i ER.","ty":"b","t":["ribosom"],"src":"s. 23","id":"k4c1v45kuq"},{"f":"Vilka proteiner görs på fria ribosomer?","b":"Proteiner som ska finnas i cytoplasman eller i andra organeller.","ty":"b","t":["ribosom"],"src":"s. 23","id":"k4c1f353qm"},{"f":"Vad är proteinets adresslapp?","b":"En kort bit precis i början av aminosyrakedjan som ser till att proteinet lyfts in i rätt organell. Därefter klipps den bort.","ty":"b","src":"s. 23–24","id":"k4c1knxflj"},{"f":"Vad är ER?","b":"Endoplasmatiska nätverket (endoplasmatiskt retikulum). Ett nätverk av membran i kontakt med kärnmembranet, som ett förgrenat kanalsystem med vätska inuti där proteiner transporteras.","ty":"b","src":"s. 24 · PPT Bi2 bild 22 · korsord 2 lodrätt","p":1,"id":"k4c1oi5q5i"},{"f":"Hur beskriver läraren ER?","b":"\"Ett membransystem som transporterar kemiska föreningar.\"","ty":"b","src":"PPT Bi2 bild 22","p":1,"id":"k4c1ltt6ct"},{"f":"Hur stor del av cellens membran är ER?","b":"Ungefär hälften.","ty":"s","src":"s. 24","id":"k4c19wokzy"},{"f":"Vad är organellernas membran byggda av?","b":"Fosfolipider, precis som cellmembranet. Därför kan blåsor smälta ihop med organeller och med cellmembranet.","ty":"v","t":["membran"],"src":"s. 24–25","id":"k4ccwv585"},{"f":"Varför sker ingen proteinsyntes i SER, och vad sker i stället?","b":"SER saknar ribosomer. I stället sker lipidmetabolism, syntes och nedbrytning av kolesterol och fett.","ty":"v","src":"s. 24","id":"k4cibcc1s"},{"f":"Varför behövs fosfolipiderna från SER när en cell har delat sig?","b":"Cellen växer, och då behövs byggmaterial (fosfolipider och kolesterol) till cellmembranet.","ty":"v","t":["membran"],"src":"s. 24","id":"k4cii6v5g"},{"f":"Varför är testosteronproducerande celler i testikeln fulla av SER?","b":"Steroidhormoner (testosteron, östrogener) är lipider som tillverkas av kolesterol i SER.","ty":"v","src":"s. 24","id":"k4cntftk7"},{"f":"Varför har leverceller, och storkonsumenter av alkohol, mycket SER?","b":"SER avgiftar giftiga ämnen med enzymer, och levercellerna sköter avgiftningen.","ty":"v","src":"s. 24","id":"k4crez348"},{"f":"Vad händer med proteinerna i RER?","b":"De veckar snabbt ihop sig till rätt tredimensionell struktur, många får kolhydrater, och de paketeras i membranblåsor till golgiapparaten.","ty":"b","src":"s. 24","id":"k4ctl4fit"},{"f":"Provfälla: var tillverkas membranets fosfolipider och var dess proteiner?","b":"Fosfolipiderna i SER, membranproteinerna i RER.","ty":"f","t":["membran"],"src":"s. 24","id":"k4c1084kl8"},{"f":"Hur är golgiapparaten uppbyggd?","b":"Av membran, ofta sex böjda, platta membranblåsor som kallas cisterner.","ty":"b","src":"s. 25 · korsord 13 vågrätt","p":1,"id":"k4c6lcplj"},{"f":"Varför kan blåsorna från RER släppa in sina proteiner i golgiapparaten?","b":"Både blåsorna och golgiapparaten har membran av fosfolipider, och därför kan de smälta ihop.","ty":"v","t":["membran"],"src":"s. 25","id":"k4c1vqn3i8"},{"f":"Vilka fyra sorters grupper kan golgiapparaten fästa på proteinerna?","b":"Sockermolekyler, fettsyror, metylgrupper och fosfatgrupper.","ty":"s","src":"s. 25","id":"k4c17m0ihs"},{"f":"Vilka tre sorters blåsor knoppas av från golgiapparaten?","b":"Blåsor med byggmaterial till cellmembranet (alla celler), lysosomer (stannar i cellen) och sekretoriska blåsor (vissa celler).","ty":"s","src":"s. 25","p":1,"id":"k4ctl72s5"},{"f":"Vad gör sekretoriska blåsor, och i vilka celler finns de?","b":"De har proteinet tätt packat och väntar nära cellmembranet på den signal som säger att innehållet ska släppas ut. De finns i celler som snabbt måste utsöndra mycket av ett visst protein.","ty":"b","src":"s. 25","id":"k4c1kb2svi"},{"f":"Provfälla: hur många cisterner har golgiapparaten?","b":"Texten säger ofta sex, men bokens figur visar tre. Figuren skriver också \"Lysom\", ett tryckfel för lysosom.","ty":"f","src":"s. 25","id":"k4cdnvidb"},{"f":"Vilka etiketter har bokens figur över golgiapparatens funktion?","b":"ER med ribosomer (RER), ribosom, membranblåsor med proteiner, golgiapparat (cisterner), lysosom, sekretorisk vesikel, vesikel med byggmaterial till cellmembranet och cellmembran.","ty":"i","src":"s. 25","id":"k4c11pmyjc"},{"f":"Vad är en lysosom och var bildas den?","b":"En membranblåsa fylld med enzymer som katalyserar nedbrytning av makromolekyler. Den bildas i golgiapparaten.","ty":"b","src":"s. 25–26 · PPT Bi2 bild 21 · korsord 11 vågrätt","p":1,"id":"k4cwysohj"},{"f":"Vad händer med en gammal mitokondrie i lysosomen?","b":"Membranen smälter ihop, enzymerna bryter ner den, byggstenarna släpps ut i cytoplasman och återvinns och avfallet förs ut med exocytos.","ty":"b","src":"s. 26","id":"k4cn9pqpf"},{"f":"Varför är lysosomens låga pH en fördel?","b":"Enzymerna fungerar bäst vid lågt pH. Läcker en lysosom hamnar enzymerna i cytoplasmans högre pH, där de fungerar sämre och inte kan bryta ner cellen.","ty":"v","src":"s. 26","id":"k4c15125js"},{"f":"Vad händer när en cell har skadats eller dött?","b":"Enzymer från ett stort antal lysosomer läcker ut och bryter ner cellen, trots att pH inte är optimalt. Hur det går till vet man inte.","ty":"b","src":"s. 26","id":"k4ceekt3b"},{"f":"Vilka tre exempel ger boken på att lysosomer bryter ner muskelvävnad?","b":"En kroppsbyggare som slutar styrketräna, en nyförlöst mammas livmoder som krymper och ett grodyngel som tappar svansen.","ty":"s","src":"s. 26","id":"k4c1n95hpv"},{"f":"Hur hjälper lysosomer till i försvaret mot bakterier?","b":"Vita blodkroppar omsluter bakterien med cellmembranet i en membranblåsa. Blåsan smälter ihop med lysosomer, och bakterien bryts ner.","ty":"b","src":"s. 26","id":"k4cam18dz"},{"f":"Vad gör peroxisomer?","b":"De bryter ner och utvinner energi ur fettsyror. De är små membranbubblor och finns i alla eukaryota celler.","ty":"b","src":"s. 26 · korsord 6 lodrätt","p":1,"id":"k4ch1b70r"},{"f":"Vad gör katalas i peroxisomen?","b":"Oskadliggör väteperoxid, ett starkt oxiderande ämne som bildas när fettsyrorna bryts ner.","ty":"b","src":"s. 26","id":"k4c1vfyqd1"},{"f":"Varför tror man att peroxisomer finns?","b":"För att stänga in nedbrytningen tillsammans med katalas, så att väteperoxiden inte stör resten av cellen.","ty":"v","src":"s. 26","id":"k4cr9zr8y"},{"f":"Provfälla: bildas peroxisomer i golgiapparaten som lysosomerna?","b":"Nej. De liknar små lysosomer men bildas genom avknoppning från befintliga peroxisomer.","ty":"f","src":"s. 26","id":"k4c1vawdem"},{"f":"Lysosom eller peroxisom: storlek och ursprung?","b":"Lysosomen är större och bildas i golgiapparaten. Peroxisomen är mindre och bildas genom avknoppning från andra peroxisomer.","ty":"j","src":"s. 25–26","id":"k4c1l1tsqm"},{"f":"Hur ser mitokondrien ut?","b":"Den ritas ofta som en ubåt, men kan vara allt från kort och tjock till lång och smal. Den har ett yttre och ett inre membran.","ty":"b","src":"s. 27","id":"k4csgpmeh"},{"f":"Varför är mitokondriens inre membran starkt veckat?","b":"Vecken ger stor yta för de membranförankrade enzymerna i elektrontransportkedjan, som bildar ATP.","ty":"v","t":["atp"],"src":"s. 27","id":"k4c1oclv44"},{"f":"Vad är matrix i mitokondrien?","b":"Vattenlösningen i mitokondriens inre. Den innehåller enzymer som utvinner energi ur födan.","ty":"b","src":"s. 27","id":"k4c1bmvr1e"},{"f":"Provfälla: matrix i mitokondrien och extracellulär matrix, samma sak?","b":"Nej. Matrix är vätskan inuti mitokondrien. Extracellulär matrix är skiktet utanför cellen.","ty":"f","src":"s. 20–21, 27","id":"k4coedkql"},{"f":"Varför kallas mitokondrien cellens kraftverk?","b":"De flesta ATP-molekyler bildas där, och de driver cellens energikrävande processer. Mycket energi avgår dock som spillvärme.","ty":"v","t":["atp"],"src":"s. 27 · PPT Bi2 bild 22 · korsord 14 vågrätt","p":1,"id":"k4c1k41n7y"},{"f":"Hur beskriver läraren mitokondrien?","b":"\"Cellens kraftverk. Energirik näring förbränns (cellandningen).\" Ordet cellandning står inte på bokens s. 27.","ty":"b","src":"PPT Bi2 bild 22","id":"k4c1pu8pif"},{"f":"Varför har muskelceller extra många mitokondrier?","b":"De har högt energibehov, och de flesta ATP bildas i mitokondrierna.","ty":"v","t":["atp"],"src":"s. 27","p":1,"id":"k4cih2j13"},{"f":"Vad säger endosymbiosteorin?","b":"Mitokondrien är en före detta bakterie som slukades av föregångaren till den eukaryota cellen och började leva i symbios med den.","ty":"b","t":["endo"],"src":"s. 27","id":"k4cc3djvd"},{"f":"Vilka bevis för endosymbiosteorin ger boken?","b":"Två membran, eget DNA, ringformat DNA som hos bakterier och ribosomer av bakterietyp. Minnesknep: 2 membran, D, R, R.","ty":"s","t":["endo"],"src":"s. 27","id":"k4c1r16b8m"},{"f":"Var kommer mitokondriens två membran ifrån enligt teorin?","b":"Det inre från bakteriens cellmembran, det yttre från cellmembranet hos cellen som slukade bakterien.","ty":"v","t":["endo","membran"],"src":"s. 27","id":"k4c1ojw3ml"},{"f":"Vilka etiketter har bokens mitokondriefigur?","b":"DNA, ribosomer, yttre membran och inre membran. Matrix står i texten men inte i figuren.","ty":"i","src":"s. 27","id":"k4cz3cuj3"},{"f":"Vad är cellskelettet?","b":"Ett nätverk av mycket tunna proteintrådar som organellerna är kopplade till. De flyter alltså inte fritt i cytoplasman.","ty":"b","src":"s. 27 · korsord 5 lodrätt","p":1,"id":"k4cbsz912"},{"f":"Vilka tre typer av trådar bygger cellskelettet?","b":"Mikrotubuli, intermediära filament och mikrofilament.","ty":"s","src":"s. 27 · korsord 12 vågrätt","p":1,"id":"k4cpworau"},{"f":"Vilka fem funktioner har cellskelettet?","b":"Cellrörelse, celldelning, transport i cellen, mekaniskt stöd och arrangemang av organellerna.","ty":"s","src":"s. 27","id":"k4c1upqkxs"},{"f":"Vilka trådar kan kopplas till motorproteiner, och vad ger det?","b":"Mikrotubuli och mikrofilament. Därför kan organeller och blåsor transporteras längs trådarna.","ty":"f","src":"s. 27","id":"k4chdw191"},{"f":"Vad visar bokens fluorescensfoto av cellskelettet?","b":"Aktinfilament i rött och cellkärnor i blått. Mikrofilament är byggda av aktin.","ty":"i","src":"s. 27","id":"k4c5bbfqj"},{"f":"I vilken ordning passerar ett protein för export organellerna?","b":"Kärnan (mRNA) → kärnpor → ribosom på ER → RER → membranblåsa → golgiapparaten → sekretorisk blåsa → cellmembranet.","ty":"s","t":["ribosom"],"src":"s. 22–25","id":"k4c1hl8e7a"},{"f":"Djurcell eller växtcell: vad har växtcellen som djurcellen saknar?","b":"Cellvägg av cellulosa, kloroplaster med klorofyll och en stor vakuol (cellsaftrum).","ty":"j","t":["vagg"],"src":"PPT Bi2 bild 25 · s. 21, 244","p":1,"id":"k4cgh1271"}],"quiz":{"f":[{"q":"Vad kallas den tjocka vätskan innanför cellmembranet där många reaktioner sker?","o":["Cytoplasma","Nukleoplasma","Matrix","Extracellulär matrix"],"why":"Cytoplasman (lärarens cellplasma) är vätskan i cellen. Nukleoplasma finns i kärnan och matrix i mitokondrien.","src":"s. 21 · PPT Bi2 bild 22 · korsord 5 vågrätt","id":"k4qawd0nd"},{"q":"Vilket är ett exempel på inklusionskropp enligt boken?","o":["Glykogen i leverceller","Ribosomer i cytoplasman","Kromatin i kärnan","Katalas i peroxisomen"],"why":"Inklusionskroppar är ämnen som hör till celltypen: glykogen i leverceller, fett i fettceller, melanin i hudceller, slem i slemceller.","src":"s. 21–22","id":"k4q1c7y1ni"},{"q":"Vad omsluter kärnmembranet?","o":["Nukleoplasma","Cytoplasma","Matrix","Cisterner"],"why":"Kärnmembranet omsluter nukleoplasman, en geléliknande vätska med proteintrådar, enzymer och nukleotider.","src":"s. 22 · korsord 7 lodrätt","id":"k4q15sqyto"},{"q":"Vad kallas blandningen av DNA och proteiner i cellkärnan?","o":["Kromatin","Nukleol","Nukleoplasma","Histon"],"why":"Kromatin är DNA plus proteiner. Histonerna är bara proteinerna som DNA lindas kring.","src":"s. 22 · korsord 9 lodrätt","id":"k4qhv2x7k"},{"q":"Hur tjocka är kromatintrådarna av DNA lindat kring histoner?","o":["Ungefär 30 nm","Ungefär 3 µm","Ungefär 0,3 mm","Ungefär 300 nm"],"why":"Boken anger ungefär 30 nm.","src":"s. 22","id":"k4q15hefcy"},{"q":"Vad bildas i nukleolen?","o":["Ribosomalt RNA (rRNA)","Budbärar-RNA för alla gener","Lysosomer","Histonproteiner"],"why":"Nukleolen bildas runt DNA-regioner som kodar för rRNA och består mest av rRNA som väntar på att föras ut.","src":"s. 23 · korsord 4 lodrätt","t":["ribosom"],"id":"k4q1tunigk"},{"q":"Vad består ribosomens två subenheter av?","o":["rRNA och proteiner","DNA och histoner","Fosfolipider och kolesterol","mRNA och tRNA"],"why":"Båda subenheterna består av RNA-molekyler (rRNA) och proteiner.","src":"s. 23","t":["ribosom"],"id":"k4q12o11as"},{"q":"Vilken subenhet fäster först på mRNA?","o":["Den lilla","Den stora","Båda samtidigt","Ingen, de sitter redan ihop"],"why":"Först fastnar den lilla subenheten, sedan den stora.","src":"s. 23","t":["ribosom"],"id":"k4q1ucriy5"},{"q":"Vad levererar aminosyrorna till ribosomen?","o":["tRNA","mRNA","rRNA","Golgiblåsor"],"why":"tRNA levererar aminosyror, som radas upp i rätt ordning längs mRNA.","src":"s. 23","id":"k4q15j0yw0"},{"q":"Hur stor del av cellens membran består av ER?","o":["Ungefär hälften","Ungefär en tiondel","Nästan allt","En fjärdedel"],"why":"Boken: ungefär hälften av en cells totala membran är ER.","src":"s. 24","id":"k4qt7ovr0"},{"q":"Vad tillverkas i slätt ER?","o":["Lipider som fosfolipider, kolesterol och steroidhormoner","Proteiner för export","Ribosomer","Lysosomenzymer"],"why":"SER saknar ribosomer och sköter lipidmetabolismen.","src":"s. 24","id":"k4qoin2tn"},{"q":"Hur många cisterner har golgiapparaten ofta enligt bokens text?","o":["Sex","Tre","Två","Tolv"],"why":"Texten säger ofta sex böjda, platta membranblåsor. Figuren visar tre.","src":"s. 25","id":"k4qlkv5hp"},{"q":"Vilken modifiering nämner boken INTE för golgiapparaten?","o":["Ribosomer fästs vid proteinet","Sockermolekyler fästs","Metylgrupper fästs","Fosfatgrupper fästs"],"why":"Boken nämner socker, fettsyror, metylgrupper och fosfatgrupper. Ribosomer sitter på RER.","src":"s. 25","id":"k4qjmofph"},{"q":"Var bildas lysosomerna?","o":["I golgiapparaten","Genom avknoppning från andra lysosomer","I nukleolen","I slätt ER"],"why":"Lysosomer knoppas av från golgiapparaten. Det är peroxisomerna som bildas genom avknoppning.","src":"s. 25–26 · korsord 11 vågrätt","id":"k4q1r1ok44"},{"q":"Vilket enzym oskadliggör väteperoxid i peroxisomen?","o":["Katalas","Amylas","Lysozym","Histon"],"why":"Katalas gör den starkt oxiderande väteperoxiden oskadlig.","src":"s. 26","id":"k4q6042mt"},{"q":"Vad bryter peroxisomer ner?","o":["Fettsyror","Gamla mitokondrier","Bakterier","Glykogen"],"why":"Peroxisomer bryter ner och utvinner energi ur fettsyror. Gamla organeller och bakterier tas om hand av lysosomer.","src":"s. 26 · korsord 6 lodrätt","id":"k4qtl1tmx"},{"q":"Vad kallas vätskan i mitokondriens inre?","o":["Matrix","Nukleoplasma","Cytoplasma","Cisterner"],"why":"Matrix innehåller enzymer som utvinner energi ur födan.","src":"s. 27","id":"k4qcqsw5d"},{"q":"Vilket är INTE ett bevis för endosymbiosteorin enligt boken?","o":["Mitokondrien har en cellvägg","Mitokondrien har två membran","Mitokondrien har ringformat DNA","Mitokondrien har bakterieliknande ribosomer"],"why":"Boken anger två membran, eget ringformat DNA och ribosomer av bakterietyp. Ingen cellvägg nämns.","src":"s. 27","t":["endo"],"id":"k4q116tqks"},{"q":"Vilka är cellskelettets tre trådtyper?","o":["Mikrotubuli, intermediära filament och mikrofilament","Kollagen, spektrin och aktin","Histoner, kromatin och mikrotubuli","Cisterner, vesiklar och mikrofilament"],"why":"Boken: mikrotubuli, intermediära filament och mikrofilament.","src":"s. 27 · korsord 12 vågrätt","id":"k4q97ycv5"},{"q":"Vad saknar djurceller till skillnad från växtceller?","o":["Cellvägg","Cellmembran","Mitokondrier","Ribosomer"],"why":"Djurceller skyddas bara av cellmembranet och utsöndrade ämnen. Växtceller har cellvägg.","src":"s. 21 · PPT Bi2 bild 25","t":["vagg"],"id":"k4q10xsrta"},{"q":"Vilken etikett finns i bokens djurcell trots att texten inte förklarar den?","o":["Centrioler","Peroxisom","Cellskelett","Nukleoplasma"],"why":"Centrioler och en liten vakuol har etiketter men förklaras inte. Peroxisom och cellskelett beskrivs men har ingen etikett.","src":"s. 21","id":"k4q1iqmex6"}],"u":[{"q":"En cell tillverkar ett protein som ska utsöndras. Var sitter ribosomen?","o":["På ER (kornigt ER)","Fritt i cytoplasman","Inne i golgiapparaten","Inne i kärnan"],"why":"Proteiner för export, cellmembran och lysosomer görs på ER-bundna ribosomer och förs in i ER.","src":"s. 23","t":["ribosom"],"id":"k4qn4ux13"},{"q":"Ett enzym ska arbeta i cytoplasman. Var görs det?","o":["På fria ribosomer","På ER-bundna ribosomer","I golgiapparaten","I lysosomerna"],"why":"Proteiner för cytoplasman och andra organeller görs på fria ribosomer.","src":"s. 23","t":["ribosom"],"id":"k4q18diclw"},{"q":"En cell har mycket stora, tydliga nukleoler. Vad kan man dra för slutsats?","o":["Den tillverkar stora mängder protein","Den är på väg att dö","Den bryter ner mycket fett","Den saknar ribosomer"],"why":"Mycket protein kräver många ribosomer och därför mycket rRNA, som bildas i nukleolerna.","src":"s. 23","id":"k4q1lwhvo6"},{"q":"En levercell hos en person som dricker mycket alkohol har ovanligt mycket av en organell. Vilken?","o":["Slätt ER","Kornigt ER","Golgiapparaten","Peroxisomer"],"why":"SER avgiftar med enzymer, och storkonsumenter av alkohol har extra mycket SER.","src":"s. 24","id":"k4qq3yefs"},{"q":"Varför är celler i testikeln som gör testosteron fulla av SER?","o":["Steroidhormoner tillverkas av kolesterol i SER","Testosteron är ett protein som görs på ribosomer","SER lagrar spermier","SER bildar ATP"],"why":"Steroidhormoner är lipider, och lipidmetabolismen sker i SER.","src":"s. 24","id":"k4q1651o5t"},{"q":"Varför kan en membranblåsa från RER smälta ihop med golgiapparaten?","o":["Båda har membran av fosfolipider","Golgiapparaten saknar membran","Blåsan har en cellvägg","Kärnporerna leder dit"],"why":"Fosfolipiderna kan blandas med varandra, eftersom membranen är av samma slag.","src":"s. 25","t":["membran"],"id":"k4qbqu9gi"},{"q":"En specialiserad muskelcell använder inte generna för magsaft. Hur stänger den av dem?","o":["Den gör kromatinet tätpackat där","Den klipper bort generna","Den skickar ut generna genom kärnporerna","Den löser upp kärnmembranet"],"why":"I tätpackat kromatin kommer enzymerna inte åt generna. Så stänger specialiserade celler av regioner de inte behöver.","src":"s. 22","id":"k4qkn3mf4"},{"q":"En lysosom spricker i en frisk cell. Vad händer?","o":["Lite, eftersom enzymerna fungerar sämre i cytoplasmans högre pH","Cellen bryts genast ner","Peroxisomerna tar över","Cytoplasman blir sur och cellen dör"],"why":"Det låga pH-värdet är en säkerhetsspärr. Först när många lysosomer läcker, i en skadad eller död cell, bryts cellen ner.","src":"s. 26","id":"k4q1flxv5t"},{"q":"En kroppsbyggare slutar träna och musklerna krymper. Vilken organell är aktiv?","o":["Lysosomen","Peroxisomen","Golgiapparaten","Nukleolen"],"why":"Lysosomer bryter ner muskelvävnad som inte används, som också i livmodern efter förlossning och grodynglets svans.","src":"s. 26","id":"k4q1n50idd"},{"q":"Varför har fettceller många peroxisomer?","o":["De bryter ofta ner fett, och peroxisomerna bryter ner fettsyror","De lagrar fett i peroxisomerna","Peroxisomerna bildar fett","De behöver mycket katalas till membranen"],"why":"Peroxisomer utvinner energi ur fettsyror, och celler som ofta bryter ner fett har extra många.","src":"s. 26","id":"k4q160u4ql"},{"q":"Vad skulle hända om mitokondriens inre membran inte var veckat?","o":["Mindre yta för elektrontransportkedjans enzymer, så mindre ATP","Mitokondrien skulle sakna DNA","Mer ATP, eftersom membranet blir tunnare","Ingenting, vecken har ingen funktion"],"why":"Vecken ger stor yta för de membranförankrade enzymerna som bildar ATP.","src":"s. 27","t":["atp"],"id":"k4qj39p7f"},{"q":"Vilken iakttagelse stöder att det inre mitokondriemembranet kommer från en bakterie?","o":["Mitokondrien har ringformat DNA och bakterieribosomer","Mitokondrien finns i alla celler","Mitokondrien bildar ATP","Mitokondrien är ubåtsformad"],"why":"Ringformat DNA och ribosomer av bakterietyp är, liksom de två membranen, bokens bevis för endosymbiosteorin.","src":"s. 27","t":["endo"],"id":"k4q18ftfjf"},{"q":"En blåsa ska köras från golgi till cellmembranet. Vilka delar av cellskelettet används?","o":["Mikrotubuli eller mikrofilament med motorproteiner","Intermediära filament med motorproteiner","Kärnporerna","Kromatinets loopar"],"why":"Boken: mikrotubuli och mikrofilament kan kopplas till motorproteiner som transporterar organeller och vesiklar.","src":"s. 27","id":"k4qxgwn3y"},{"q":"Vilket påstående om peroxisomer och lysosomer är rätt?","o":["Peroxisomen är mindre och bildas genom avknoppning","Båda bildas i golgiapparaten","Lysosomen bryter ner fettsyror med katalas","Peroxisomen har lågt pH som säkerhetsspärr"],"why":"Peroxisomer är mindre, bildas genom avknoppning och använder katalas. Lysosomen har det låga pH-värdet.","src":"s. 26","id":"k4qeyuqvi"}],"o":[{"q":"Beskriv vägen för ett protein som ska utsöndras ur cellen, från gen till utsläpp.","model":"Genen ligger i löspackat kromatin, och enzymer bildar mRNA som tar sig ut genom en kärnpor. Ribosomens lilla subenhet fäster först, sedan den stora, och tRNA levererar aminosyror. Eftersom proteinet ska exporteras fästs ribosomen på ER. Proteinet förs in i kornigt ER, veckas till rätt 3D-form och får ofta kolhydrater. Det paketeras i en membranblåsa som smälter ihop med golgiapparaten, eftersom båda har fosfolipidmembran. Där modifieras det, t.ex. med socker eller fosfatgrupper, och flyttas cistern för cistern. En sekretorisk blåsa knoppas av och väntar vid cellmembranet tills en signal kommer, och då släpps innehållet ut.","kw":[["mrna"],["kärnpor"],["ribosom"],["rer","kornigt"],["golgi"],["sekretor"],["signal","cellmembran"]],"src":"s. 22–25","t":["ribosom"],"id":"k4o12p3wlv"},{"q":"Jämför slätt och kornigt ER med avseende på byggnad, uppgifter och exempel på celler där de är vanliga.","model":"Båda är delar av ER, ett förgrenat kanalsystem med vätska som har kontakt med kärnmembranet. SER saknar ribosomer, så där sker ingen proteinsyntes utan lipidmetabolism: fosfolipider och kolesterol till membranen, fett och steroidhormoner som testosteron. Därför är testikelns testosteronceller fulla av SER. SER avgiftar också, därför har leverceller mycket SER, och deltar i jontransport i nerv- och muskelceller. RER har ribosomer och gör proteiner för export, cellmembran och lysosomer. De veckas, får kolhydrater och skickas i blåsor till golgi.","kw":[["ribosom"],["lipid","fett","kolesterol"],["steroid","testosteron"],["avgift","lever"],["export"],["golgi","veck"]],"src":"s. 24","id":"k4onb3i6b"},{"q":"Redogör för endosymbiosteorin och de bevis boken ger. Förklara också varför mitokondrien kallas cellens kraftverk.","model":"Endosymbiosteorin säger att mitokondrien var en bakterie som slukades av föregångaren till den eukaryota cellen och sedan levde i symbios med den. Bevisen är två membran, där det inre kommer från bakteriens cellmembran och det yttre från värdcellens, eget DNA som är ringformat som hos bakterier, och ribosomer av bakterietyp. Det inre membranet är starkt veckat, vilket ger stor yta för elektrontransportkedjans enzymer. Där fångas energi och ATP bildas. De flesta ATP bildas i mitokondrien, och därför kallas den kraftverket.","kw":[["bakterie"],["symbios","slukad"],["två membran"],["ringformat","dna"],["ribosom"],["atp"]],"src":"s. 27","t":["endo","atp"],"id":"k4ofsutpo"},{"q":"Jämför lysosomer och peroxisomer: byggnad, ursprung, uppgifter och skydd för cellen.","model":"Båda är membranblåsor med enzymer. Lysosomen är större, bildas i golgiapparaten och bryter ner makromolekyler, gamla organeller, slukade bakterier och muskelvävnad som inte används. Byggstenar återvinns och avfall går ut med exocytos. Dess enzymer fungerar bäst vid lågt pH, och därför skadar de inte cellen om de läcker ut i cytoplasmans högre pH. Peroxisomen är mindre, finns i alla eukaryota celler och bildas genom avknoppning. Den bryter ner fettsyror och utvinner energi. Väteperoxiden som bildas oskadliggörs av katalas, och processen stängs in så att resten av cellen inte störs.","kw":[["golgi"],["avknopp"],["makromolekyl","organell","bakterie"],["ph"],["fettsyr"],["katalas","väteperoxid"]],"src":"s. 25–26","id":"k4o1ddezay"}]},"kan":[{"q":"Kan du beskriva cellkärnans uppbyggnad?","a":"Kärnan har det allra mesta av arvsmassan och omges av ett dubbelt kärnmembran med ganska stora kärnporer, där t.ex. mRNA tar sig ut. Kärnmembranet är på flera ställen ihopkopplat med ER. Innanför finns nukleoplasma, en geléliknande vätska med proteintrådar som ger stöd, enzymer och nukleotider. DNA ligger lindat kring histonproteiner som kromatin, och i kärnan finns en eller flera nukleoler.","kw":[["dubbelt"],["kärnpor","por"],["nukleoplasma"],["kromatin","histon"],["nukleol"],["er","endoplasmat"]],"src":"s. 22–23","id":"k4k18bt54q"},{"q":"Kan du förklara skillnaden mellan tätpackat och löspackat kromatin och varför den är viktig?","a":"Kromatin är blandningen av DNA och proteiner i kärnan. I tätpackat kromatin kommer enzymerna inte åt generna, och därför kan generna inte användas. I löspackat kromatin kommer enzymerna fram och bildar budbärar-RNA, så generna kan utnyttjas. När celler specialiserar sig stänger de av regioner som de inte behöver genom att göra kromatinet tätpackat.","kw":[["tätpack"],["löspack"],["enzym"],["mrna","budbärar"],["speciali"],["stäng"]],"src":"s. 22","id":"k4k1thkhxy"},{"q":"Kan du förklara vad en nukleol är och varför den syns extra tydligt i vissa celler?","a":"En nukleol är ett mörkfärgat parti i kärnan som syns i elektronmikroskop. Den bildas runt de regioner på DNA som kodar för ribosomalt RNA och består till stor del av rRNA som väntar på att föras ut genom en kärnpor. Celler som gör stora mängder protein behöver många ribosomer, och därför syns deras nukleoler extra tydligt.","kw":[["mörk"],["rrna","ribosomalt"],["kärnpor","por"],["ribosom"],["protein"]],"src":"s. 23","id":"k4kqzcine"},{"q":"Kan du beskriva ribosomen och förklara när den är fri och när den är ER-bunden?","a":"Ribosomen är platsen för proteinsyntesen. Den består av två subenheter av rRNA och proteiner som cirkulerar fritt i cytoplasman. När de stöter på mRNA fastnar först den lilla subenheten och sedan den stora, och tRNA levererar aminosyror. Ska proteinet exporteras, sitta i cellmembranet eller arbeta i lysosomerna fästs ribosomen på ER. Ska proteinet finnas i cytoplasman eller andra organeller stannar den fri, och en adresslapp i kedjans början styr proteinet till rätt organell.","kw":[["subenhet"],["rrna"],["lilla","liten"],["trna"],["er-bund","er"],["fri"],["adresslapp"]],"src":"s. 23–24","t":["ribosom"],"id":"k4k10kqrb6"},{"q":"Kan du jämföra slätt och kornigt ER?","a":"ER är ett förgrenat kanalsystem med vätska inuti, i kontakt med kärnmembranet, och utgör ungefär hälften av cellens membran. Slätt ER saknar ribosomer och sköter lipidmetabolism: fosfolipider till membranen, kolesterol, fett och steroidhormoner. Det avgiftar också, och därför har leverceller mycket SER, och det deltar i jontransport i nerv- och muskelceller. Kornigt ER har ribosomer och tillverkar proteiner för export, cellmembran och lysosomer, som veckas, får kolhydrater och skickas i blåsor till golgi.","kw":[["ribosom"],["lipid","fett","kolesterol"],["steroid"],["avgift","lever"],["export"],["golgi"]],"src":"s. 24","id":"k4k11k579"},{"q":"Kan du beskriva golgiapparatens uppbyggnad och vad den gör?","a":"Golgiapparaten består ofta av sex böjda, platta membranblåsor, cisterner. På ena sidan kommer blåsor med proteiner från RER, och eftersom båda har fosfolipidmembran smälter de ihop. Proteinerna modifieras genom att sockermolekyler, fettsyror, metylgrupper eller fosfatgrupper fästs, och flyttas cistern för cistern. På andra sidan knoppas tre sorters blåsor av: blåsor med byggmaterial till cellmembranet, lysosomer och i vissa celler sekretoriska blåsor.","kw":[["cistern"],["rer","er"],["smält"],["modifier","socker","fosfat"],["lysosom"],["sekretor"]],"src":"s. 25","id":"k4k1xab48r"},{"q":"Kan du förklara lysosomens uppgifter och varför det låga pH-värdet är en säkerhetsspärr?","a":"Lysosomer bildas i golgiapparaten och är membranblåsor med enzymer som bryter ner makromolekyler. De håller rent och återvinner, t.ex. gamla mitokondrier, där byggstenarna återvinns och avfallet förs ut med exocytos. De bryter ner muskelvävnad som inte används och bakterier som vita blodkroppar slukat. Enzymerna fungerar bäst vid lågt pH. Om en lysosom går sönder fungerar de sämre i cytoplasmans högre pH, och därför bryts cellen inte ner.","kw":[["golgi"],["enzym"],["återvinn"],["ph"],["högre"],["bakterie","vita blod"]],"src":"s. 25–26","id":"k4k1c4ixou"},{"q":"Kan du beskriva mitokondrien och förklara varför den kallas cellens kraftverk?","a":"Mitokondrien har ett yttre och ett starkt veckat inre membran. Vecken ger stor yta för de membranförankrade enzymerna i elektrontransportkedjan, som bildar ATP. Matrix, vätskan inuti, har enzymer som utvinner energi ur födan. Mycket energi avgår som spillvärme, men en del fångas och bildar ATP. De flesta ATP bildas här, och därför kallas den cellens kraftverk. Muskelceller har högt energibehov och därför extra många mitokondrier.","kw":[["två membran","yttre","inre"],["veck"],["elektrontransport"],["atp"],["matrix"],["muskel"]],"src":"s. 27 · PPT Bi2 bild 22","t":["atp"],"id":"k4k1hq9h1e"},{"q":"Kan du redogöra för endosymbiosteorin och bevisen för den?","a":"Endosymbiosteorin säger att mitokondrien är en före detta bakterie som slukades av föregångaren till den eukaryota cellen och började leva i symbios med den. Bevisen är att mitokondrien har två membran, där det inre kommer från bakteriens cellmembran och det yttre från värdcellens. Den har eget DNA, som är ringformat precis som hos bakterier, och ribosomer av samma typ som bakterier.","kw":[["bakterie"],["slukad","symbios"],["två membran"],["eget dna","dna"],["ring"],["ribosom"]],"src":"s. 27","t":["endo"],"id":"k4khpxct5"},{"q":"Kan du beskriva cellskelettet, dess trådar och funktioner?","a":"Organellerna flyter inte fritt utan är kopplade till cellskelettet, ett nätverk av mycket tunna proteintrådar. Det finns tre sorters trådar: mikrotubuli, intermediära filament och mikrofilament. Cellskelettet ger stöd, form och rörelseförmåga och står för cellrörelse, celldelning, transport i cellen, mekaniskt stöd och arrangemang av organellerna. Mikrotubuli och mikrofilament kan kopplas till motorproteiner, och därför kan organeller och blåsor transporteras längs trådarna.","kw":[["mikrotubuli"],["intermediär"],["mikrofilament"],["motorprotein"],["stöd"],["transport"]],"src":"s. 27","id":"k4k1wvr6kd"}],"kompis":[{"q":"Förklara för en kompis vägen för ett protein som ska utsöndras ur cellen.","model":"Genen ligger i löspackat kromatin, så enzymer kommer åt och bildar mRNA. mRNA går ut genom en kärnpor. Ribosomens lilla subenhet fäster först, sedan den stora, och tRNA levererar aminosyror. Eftersom proteinet ska exporteras fästs ribosomen på ER, och proteinet förs in i kornigt ER, veckas och får ofta kolhydrater. Det packas i en membranblåsa som smälter ihop med golgiapparaten, eftersom båda har fosfolipidmembran. Där modifieras det och flyttas cistern för cistern. En sekretorisk blåsa knoppas av och väntar vid cellmembranet tills en signal säger att innehållet ska släppas ut.","kw":[["mrna"],["kärnpor"],["ribosom"],["er","rer"],["golgi"],["sekretor","blåsa"],["signal","släpp"]],"src":"s. 22–25","t":["ribosom"],"id":"k4eynswxe"},{"q":"Förklara för en kompis hur lysosomen tar hand om en gammal mitokondrie och varför cellen inte bryter ner sig själv.","model":"Den gamla mitokondriens membran smälter ihop med lysosomens membran, och mitokondrien tas in i lysosomen. Där bryter enzymerna ner den. Användbara byggstenar släpps ut i cytoplasman och återvinns, och avfallet förs ut ur cellen med exocytos. Enzymerna fungerar bäst vid lysosomens låga pH. Om en lysosom läcker hamnar enzymerna i cytoplasmans högre pH, och där fungerar de sämre, så cellen bryts inte ner. När en cell skadats eller dött läcker däremot många lysosomer, och då bryts cellen ner ändå. Hur det går till vet man inte.","kw":[["smält"],["enzym"],["återvinn","byggsten"],["exocytos"],["ph"],["många","skadad","död"]],"src":"s. 26","id":"k4e1kyltpu"},{"q":"Förklara för en kompis varför mitokondrien har två membran och vad det inre membranet är bra för.","model":"Enligt endosymbiosteorin var mitokondrien en bakterie som slukades av föregångaren till den eukaryota cellen. Det inre membranet kommer från bakteriens eget cellmembran, och det yttre från cellmembranet hos cellen som slukade den. Det inre membranet är starkt veckat, och därför får det en stor yta för de membranförankrade enzymerna i elektrontransportkedjan, som bildar ATP. Därför bildas de flesta ATP i mitokondrien, och celler med högt energibehov, som muskelceller, har många mitokondrier.","kw":[["bakterie"],["slukad","endosymbios"],["inre"],["yttre"],["veck","yta"],["atp"]],"src":"s. 27","t":["endo","atp"],"id":"k4e1avurkk"}],"gloss":[{"w":"Adresslapp","d":"Kort bit i början av en aminosyrakedja som styr proteinet till rätt organell. Klipps sedan bort.","src":"Bok s. 23–24"},{"w":"Aktinfilament","d":"Det boken visar i rött på fluorescensfotot av cellskelettet. Mikrofilament byggs av aktin.","src":"Bok s. 27"},{"w":"Avgiftning","d":"Giftiga ämnen oskadliggörs med enzymer, bland annat i SER i leverceller.","src":"Bok s. 24"},{"w":"Avknoppning","d":"Så bildas nya peroxisomer, från de peroxisomer som redan finns.","src":"Bok s. 26"},{"w":"Budbärar-RNA (mRNA)","d":"RNA med instruktionerna för vilka aminosyror som ska fogas ihop. Bildas i kärnan och tar sig ut genom kärnporerna.","src":"Bok s. 22–23"},{"w":"Cellandning","d":"Lärarens ord för förbränningen av energirik näring i mitokondrien.","src":"PPT Bi2 bild 22","lek":1},{"w":"Cellplasma","d":"Lärarens ord för cytoplasma: specialiserade celldelar och mycket vatten.","src":"PPT Bi2 bild 22","lek":1},{"w":"Cellskelett","d":"Nätverk av mycket tunna proteintrådar (mikrotubuli, intermediära filament, mikrofilament) som ger stöd, form och rörelse.","src":"Bok s. 27"},{"w":"Centrioler","d":"Del med etikett i bokens djurcell, som texten inte förklarar.","src":"Bok s. 21"},{"w":"Cisterner","d":"Golgiapparatens böjda, platta membranblåsor, ofta sex.","src":"Bok s. 25"},{"w":"Cytoplasma","d":"Tjock vätska innanför cellmembranet med ämnen lösta i vatten. Där sker många reaktioner.","src":"Bok s. 21"},{"w":"Elektrontransportkedjan","d":"Membranförankrade enzymer på mitokondriens inre membran som ger ATP.","src":"Bok s. 27"},{"w":"Endoplasmatiska nätverket (ER)","d":"Nätverk av membran i kontakt med kärnmembranet, ett förgrenat kanalsystem med vätska där proteiner transporteras.","src":"Bok s. 24"},{"w":"Endosymbiosteorin","d":"Teorin att mitokondrien är en före detta bakterie som slukades av den eukaryota cellens föregångare och levde i symbios med den.","src":"Bok s. 27"},{"w":"ER-bunden ribosom","d":"Ribosom fäst på ER. Gör proteiner för export, cellmembran och lysosomer.","src":"Bok s. 23"},{"w":"Fri ribosom","d":"Ribosom i cytoplasman. Gör proteiner för cytoplasman och andra organeller.","src":"Bok s. 23"},{"w":"Golgiapparaten","d":"Organell av cisterner där proteiner från RER modifieras och knoppas av i blåsor.","src":"Bok s. 25"},{"w":"Histonproteiner","d":"Proteiner som DNA lindas kring i kärnan.","src":"Bok s. 22"},{"w":"Inklusionskroppar","d":"Ämnen i cytoplasman som hör till celltypen, t.ex. glykogen, fett, melanin och slem.","src":"Bok s. 21–22"},{"w":"Intermediära filament","d":"En av cellskelettets tre trådtyper.","src":"Bok s. 27"},{"w":"Katalas","d":"Enzym som oskadliggör väteperoxid i peroxisomen.","src":"Bok s. 26"},{"w":"Kornigt ER (RER)","d":"ER med ribosomer, rough endoplasmic reticulum. Gör proteiner för export, membran och lysosomer.","src":"Bok s. 24"},{"w":"Kromatin","d":"Blandningen av DNA och proteiner i cellkärnan. Kan vara tätpackat eller löspackat.","src":"Bok s. 22"},{"w":"Kromosom","d":"En DNA-molekyl. Syns i ljusmikroskop bara vid celldelning.","src":"Bok s. 22"},{"w":"Kärnmembran","d":"Det dubbla membranet runt cellkärnan.","src":"Bok s. 22"},{"w":"Kärnporer","d":"Ganska stora porer i kärnmembranet som underlättar transport, t.ex. av mRNA.","src":"Bok s. 22"},{"w":"Lipidmetabolism","d":"Syntes och nedbrytning av kolesterol och fett, sker i SER.","src":"Bok s. 24"},{"w":"Lysosom","d":"Membranblåsa från golgiapparaten med enzymer som bryter ner makromolekyler. Cellens sopförbränning.","src":"Bok s. 25–26"},{"w":"Löspackat kromatin","d":"Kromatin där enzymer kommer fram och bildar mRNA, så generna kan användas.","src":"Bok s. 22"},{"w":"Matrix (mitokondrien)","d":"Vattenlösningen i mitokondriens inre, med enzymer som utvinner energi ur födan.","src":"Bok s. 27"},{"w":"Membranblåsa (vesikel)","d":"Liten blåsa av membran som transporterar ämnen mellan organeller och till cellmembranet.","src":"Bok s. 24–25"},{"w":"Mikrofilament","d":"En av cellskelettets tre trådtyper. Kan kopplas till motorproteiner.","src":"Bok s. 27"},{"w":"Mikrotubuli","d":"En av cellskelettets tre trådtyper. Kan kopplas till motorproteiner.","src":"Bok s. 27"},{"w":"Mitokondrie","d":"Organell med två membran där de flesta ATP bildas. Cellens kraftverk.","src":"Bok s. 27"},{"w":"Motorproteiner","d":"Proteiner på organeller och blåsor som kör dem längs mikrotubuli och mikrofilament.","src":"Bok s. 27"},{"w":"Nukleol","d":"Mörkfärgat parti i kärnan, bildas runt DNA som kodar för rRNA och består mest av rRNA.","src":"Bok s. 23"},{"w":"Nukleoplasma","d":"Geléliknande vätska i kärnan med proteintrådar, enzymer och nukleotider.","src":"Bok s. 22"},{"w":"Organell","d":"En del i cellen med en bestämd uppgift, t.ex. mitokondrie eller golgiapparat.","src":"Bok s. 21–22"},{"w":"Peroxisom","d":"Liten membranbubbla med enzymer som bryter ner fettsyror. Katalas oskadliggör väteperoxiden.","src":"Bok s. 26"},{"w":"Ribosom","d":"Platsen för proteinsyntesen. Två subenheter av rRNA och proteiner.","src":"Bok s. 23"},{"w":"Ribosomalt RNA (rRNA)","d":"RNA som bygger upp ribosomerna. Bildas i nukleolen.","src":"Bok s. 23"},{"w":"Sekretorisk blåsa (vesikel)","d":"Blåsa med tätt packat protein som väntar vid cellmembranet på signal att släppa ut innehållet.","src":"Bok s. 25"},{"w":"Slätt ER (SER)","d":"ER utan ribosomer, smooth endoplasmic reticulum. Lipidmetabolism, steroidhormoner, avgiftning, jontransport.","src":"Bok s. 24"},{"w":"Spillvärme","d":"Energi som avgår som värme i mitokondrien i stället för att bilda ATP.","src":"Bok s. 27"},{"w":"Steroidhormoner","d":"Lipider, t.ex. testosteron och östrogener, som tillverkas av kolesterol i SER.","src":"Bok s. 24"},{"w":"Subenhet","d":"En av ribosomens två delar, en liten och en stor.","src":"Bok s. 23"},{"w":"Tätpackat kromatin","d":"Kromatin där enzymerna inte kommer åt generna, så de stängs av.","src":"Bok s. 22"},{"w":"tRNA","d":"RNA som levererar aminosyror till ribosomen.","src":"Bok s. 23"},{"w":"Vakuol","d":"Vätskefylld blåsa. Liten i bokens djurcell, stor (cellsaftrum) i växtcellen.","src":"Bok s. 21 · PPT Bi2 bild 25"},{"w":"Väteperoxid","d":"Starkt oxiderande ämne som bildas när peroxisomen bryter ner fettsyror.","src":"Bok s. 26"}],"snabb":{"keys":["Cytoplasma :: tjock vätska innanför cellmembranet, många reaktioner (läraren: cellplasma)","Kärnan :: det allra mesta av arvsmassan, dubbelt kärnmembran med kärnporer","Kromatin :: DNA + proteiner; tätpackat = av, löspackat = på","Nukleol :: mörkt parti runt rRNA-gener, mest rRNA","Ribosom :: proteinsyntes, två subenheter av rRNA + protein, lilla först","ER-bunden / fri ribosom :: export, membran, lysosomer / cytoplasma och andra organeller","SER :: inga ribosomer; lipider, steroidhormoner, avgiftning, jontransport","RER :: ribosomer; proteiner för export, membran, lysosomer; veckning, kolhydrater","Golgi :: ofta 6 cisterner; modifierar (socker, fettsyror, metyl, fosfat); 3 sorters blåsor","Lysosom :: från golgi, enzymer bryter ner makromolekyler, lågt pH = säkerhetsspärr","Peroxisom :: mindre, fettsyror, katalas mot väteperoxid, bildas genom avknoppning","Mitokondrie :: två membran, veckat inre, matrix, de flesta ATP","Endosymbios-bevis :: 2 membran, eget DNA, ringformat DNA, bakterieribosomer","Cellskelett :: mikrotubuli, intermediära filament, mikrofilament; M-trådarna har motorproteiner"],"nums":[["30 nm","tjocklek på DNA-trådarna lindade kring histoner (s. 22)"],["≈ 1/2","av cellens membran är ER (s. 24)"],["ofta 6","cisterner i golgiapparaten enligt texten, 3 i figuren (s. 25)"],["2","subenheter i ribosomen (s. 23)"],["3","sorters blåsor från golgi (s. 25)"],["4","sorters grupper som golgi fäster: socker, fettsyror, metyl, fosfat (s. 25)"],["3","exempel på muskelnedbrytning: kroppsbyggare, livmoder, grodyngel (s. 26)"],["2","membran runt mitokondrien och runt kärnan (s. 22, 27)"],["3","trådtyper i cellskelettet (s. 27)"],["5","funktioner hos cellskelettet (s. 27)"],["13","etiketter i bokens djurcell (s. 21)"],["9","etiketter i lärarens djurcell (Bi2 bild 21)"]],"chains":[["Löspackat kromatin","enzymer når genen","mRNA bildas","mRNA ut genom kärnpor","protein görs på ribosom"],["Mycket protein","många ribosomer behövs","mycket rRNA","tydliga nukleoler"],["Protein för export","ribosom fästs på ER","veckas och får kolhydrater i RER","blåsa till golgi","modifieras","sekretorisk blåsa","signal → ut"],["Lysosom läcker","enzymer i cytoplasmans högre pH","fungerar sämre","cellen skyddas"],["Fettsyra bryts ner i peroxisomen","väteperoxid bildas","katalas oskadliggör den","resten av cellen störs inte"],["Veckat inre membran","stor yta","många enzymer i elektrontransportkedjan","mycket ATP"],["Bakterie slukas","lever i symbios","mitokondrie med två membran, ringformat DNA och bakterieribosomer"]],"traps":["Kärnan har det ALLRA MESTA av arvsmassan, inte allt (mitokondrien har eget DNA).","Vid celldelning löses KÄRNmembranet upp (boken skriver fel: cellmembranet).","Den LILLA subenheten fäster först på mRNA.","Fosfolipider görs i SER, membranproteiner i RER.","Peroxisomer bildas genom avknoppning, inte i golgi.","Matrix i mitokondrien är inte extracellulär matrix.","Bara mikrotubuli och mikrofilament har motorproteiner enligt boken.","Golgi: ofta sex cisterner i texten, tre i figuren; \"Lysom\" är tryckfel för lysosom."]}},"k5":{"pre":[{"q":"Vilket av ämnena tar sig lättast rakt genom cellmembranet?","o":["Syre","Natriumjoner","Glukos","Vätejoner"],"why":"Syre är litet, oladdat och hydrofobt, och fosfolipidskiktet är fettlösligt. Joner och glukos har det mycket svårare.","src":"s. 31","id":"k5p2v0fro"},{"q":"Vad händer med en röd blodkropp som läggs i rent (destillerat) vatten?","o":["Den sväller och kan spricka","Den krymper","Ingenting","Den blir platt och taggig"],"why":"Vattenkoncentrationen är högre utanför än inuti cellen, och därför diffunderar vatten in genom osmos.","src":"s. 33","t":["osmos"],"id":"k5p1vjklsu"},{"q":"Hur stor del av cellens ATP går till natrium-kaliumpumpen enligt boken?","o":["Ungefär 40 %","Ungefär 1 %","Ungefär 90 %","Ingenting, den drivs av ljus"],"why":"Boken: ungefär 40 % av det ATP som produceras i en cell går till natrium-kaliumpumpen. Läraren skriver 10–40 %.","src":"s. 35","t":["atp"],"id":"k5p1mz4x2w"},{"q":"Varför får patienter med svår diarré dricka en lösning med både salt och glukos?","o":["Natrium tas upp i tarmen tillsammans med glukos","Glukoset dödar bakterierna","Saltet stoppar diarrén direkt","Glukoset ger energi till hjärnan"],"why":"Natriumjoner tas upp via tarmens epitelceller genom kopplad transport till glukos, två Na⁺ per glukos.","src":"s. 35","id":"k5px9cjjy"},{"q":"Vad heter det när en vit blodkropp slukar en bakterie?","o":["Fagocytos","Pinocytos","Exocytos","Osmos"],"why":"Fagocytos betyder cellätande. Membranet bildar två armar som sluter sig runt bakterien.","src":"s. 36","id":"k5ptgch9f"}],"cards":[{"f":"Vad är en akvaporin enligt filmen?","b":"En proteinkanal i cellmembranet som bara släpper igenom vattenmolekyler. Boken skriver aquaporin.","ty":"b","t":["osmos"],"src":"Film Osmos","id":"k5c1s8hwx9"},{"f":"Varför behövs akvaporiner?","b":"Vatten är polärt, medan membranets inre består av opolära fettsyror. Därför passerar vatten mycket långsamt utan akvaporiner.","ty":"v","t":["osmos","membran"],"src":"Film Osmos","id":"k5c1j8skj"},{"f":"Vilka celler är extra beroende av akvaporiner enligt filmen?","b":"Njurceller och blodkärlsceller.","ty":"s","t":["osmos"],"src":"Film Osmos","id":"k5c14umsbj"},{"f":"Hur vänds vattenmolekylerna rätt inne i akvaporinen?","b":"Aminosyror med positivt laddade sidogrupper drar till sig vattnets partiellt negativa syreatom, och därför passerar vattnet vänt åt rätt håll i en enda rad.","ty":"v","t":["osmos"],"src":"Film Osmos","id":"k5c145doky"},{"f":"Varför kan protoner (H⁺) inte passera en akvaporin?","b":"De positiva laddningarna i kanalen bildar en barriär mot protoner, och därför bevaras cellens elektriska balans.","ty":"v","t":["osmos"],"src":"Film Osmos","id":"k5c4aavvg"},{"f":"Vad är osmolalitet?","b":"Ett mått på antalet osmotiskt aktiva partiklar per kilogram lösningsmedel. Enhet osmol/kg eller mOsm/kg.","ty":"b","t":["osmos"],"src":"Film Osmos","id":"k5ctl9qq"},{"f":"Vad är osmotiskt aktiva partiklar?","b":"Ämnen som kan dra till sig och binda vatten, t.ex. sockermolekyler och saltjoner. De minskar antalet fria vattenmolekyler.","ty":"b","t":["osmos"],"src":"Film Osmos","id":"k5c1rtp71k"},{"f":"Åt vilket håll går nettoflödet av vatten, räknat i osmolalitet?","b":"Från låg till hög osmolalitet, eftersom många partiklar binder vatten och lämnar färre fria vattenmolekyler.","ty":"v","t":["osmos"],"src":"Film Osmos","id":"k5c103xqa9"},{"f":"Skillnad: osmolalitet och osmolaritet?","b":"Osmolalitet räknar partiklar per kilogram lösningsmedel (mOsm/kg). Osmolaritet räknar per liter lösning (mOsm/L), som ofta används i sjukvården.","ty":"j","t":["osmos"],"src":"Film Osmos","id":"k5cmtzora"},{"f":"Vilken osmolalitet är isoton med blodplasman?","b":"Ca 280–295 mOsmol/kg, ungefär samma som cytosolen.","ty":"s","t":["osmos"],"src":"Film Osmos","id":"k5c6aptnx"},{"f":"Vad betyder 1 osmol/kg?","b":"1 mol, ungefär 6,022 × 10²³, osmotiskt aktiva partiklar per kilogram lösningsmedel.","ty":"s","src":"Film Osmos","id":"k5c6vn2yg"},{"f":"Varför kan en röd blodkropp i en hyperton lösning transportera sämre syre?","b":"Vatten lämnar cellen, och därför packas hemoglobinet tätare och cellens form förändras.","ty":"v","t":["osmos"],"src":"Film Osmos","id":"k5c1lghico"},{"f":"Vad är hemolys?","b":"När röda blodkroppar sväller och spricker i en hypoton lösning. Det sker eftersom djurceller saknar cellvägg.","ty":"b","t":["osmos"],"src":"Film Osmos","id":"k5ckm5wf8"},{"f":"Vad är plasmolys?","b":"När en växtcell i en hyperton lösning förlorar vatten så att cellmembranet drar sig bort från den stela cellväggen. Växten slokar, eftersom turgortrycket försvinner.","ty":"b","t":["osmos","vagg"],"src":"Film Osmos","id":"k5ct1i1cn"},{"f":"Turgid, flaccid och plasmolyzed: vilken lösning hör till vilket ord?","b":"Turgid (spänd) i hypoton lösning, flaccid (slapp) i isoton lösning och plasmolyzed i hyperton lösning.","ty":"j","t":["osmos"],"src":"Film Osmos","id":"k5c1iu06ye"},{"f":"Provfälla: varför skadar övervattning en växt?","b":"Cellerna spricker inte, eftersom cellväggen håller emot. Faran är syrebrist i rötterna, eftersom blöt jord blir syrefattig.","ty":"f","t":["osmos"],"src":"Film Osmos","id":"k5c1gcm0t0"},{"f":"Varför håller saltad eller sockrad mat längre?","b":"Mycket salt eller socker ger hög osmolalitet utanför mikroorganismerna. Vatten lämnar deras celler genom osmos, cellerna krymper och tillväxt och förökning hämmas.","ty":"v","t":["osmos"],"src":"Film Osmos","id":"k5c16d56c7"},{"f":"Ge exempel på mat som konserveras med salt och med socker.","b":"Salt: saltad fisk, skinka, pickles. Socker: sylt, marmelad, koncentrerad fruktjuice.","ty":"s","src":"Film Osmos","id":"k5c1ju05x9"},{"f":"Vad är hyponatremi?","b":"Låg natriumkoncentration i blodplasman och andra kroppsvätskor. Den kan bero på överdrivet vattenintag, sjukdomar, njurproblem eller läkemedel.","ty":"b","t":["osmos"],"src":"Lektion","id":"k5c90xyil"},{"f":"Skillnad: hypoton och hyperton hyponatremi?","b":"Båda har låg Na⁺. Hypoton (vanligast) har låg osmolalitet och kan ge hjärnödem. Hyperton har hög osmolalitet, t.ex. vid mycket högt blodsocker.","ty":"j","t":["osmos"],"src":"Lektion","id":"k5c1uyii6a"},{"f":"Varför är hjärnödem livsfarligt?","b":"Hjärnan ligger i ett hårt kranium. Trycket stiger, blodkärlen pressas ihop och hjärnan får syrebrist. Hjärnstammen, som styr andning och hjärtfrekvens, kan pressas ner mot skallbasen.","ty":"v","t":["osmos"],"src":"Lektion","id":"k5c3tt8l2"},{"f":"Hur mycket vatten klarar kroppen, och hur mycket bör en vuxen få i sig?","b":"Normalt 2–3 liter per dag. Mer än 3–4 liter på kort tid kan ge hypoton hyponatremi. Vuxna bör få ca 2–2,5 liter vätska per dag från dryck och mat.","ty":"s","src":"Lektion","id":"k5cb2bx9g"},{"f":"Varför är destillerat vatten farligare än kranvatten i stora mängder?","b":"Destillerat vatten saknar saltjoner och sänker därför natrium och osmolalitet snabbare. Kranvatten har lite Ca²⁺, Mg²⁺, Na⁺ och K⁺ som mildrar effekten.","ty":"v","t":["osmos"],"src":"Lektion","id":"k5cc01svm"},{"f":"Salthalt och osmolalitet i blodplasma och havsvatten?","b":"Blodplasma ca 0,9 % salt och 280–295 mOsm/kg. Havsvatten ca 3,5 % salt och ca 1 000 mOsm/kg.","ty":"s","t":["osmos"],"src":"Lektion","id":"k5c1m1okji"},{"f":"Varför kan man inte dricka havsvatten?","b":"I tarmen drar saltet ut vatten och ger diarré. I blodet ökar osmolaliteten och drar vatten ur cellerna. Njurarna måste använda mer vatten för att få ut saltet, och därför blir uttorkningen värre.","ty":"v","t":["osmos"],"src":"Lektion","id":"k5c1s55s53"},{"f":"Räkna: 0,9 % NaCl till mOsmol/L.","b":"0,9 % = 9 g/L = 154 mmol/L Na⁺. Varje NaCl ger två partiklar, och därför blir det 154 × 2 = 308 mOsmol/L.","ty":"s","t":["osmos"],"src":"Lektion","id":"k5c1imsl6m"},{"f":"Provfälla: är fysiologisk koksaltlösning isoton?","b":"Funktionellt isoton, men tekniskt svagt hyperton, eftersom 308 mOsmol/L ligger över 280–295.","ty":"f","t":["osmos"],"src":"Lektion","id":"k5cx7evql"},{"f":"Hur togs fysiologisk koksaltlösning fram?","b":"På 1800-talet testade man olika NaCl-halter på blodkroppar. 0,9 % bevarade formen bäst. Teoretiskt är 0,86 % mer exakt.","ty":"s","src":"Lektion","id":"k5ctpd2e9"},{"f":"Vad används fysiologisk koksaltlösning till?","b":"Vid uttorkning (kräkningar, diarré, svettning), vid blodförlust för blodvolym och blodtryck, och som bärare för läkemedel. Den är isoton och ger därför ingen hyponatremi.","ty":"b","src":"Lektion","id":"k5c1fzkcf7"},{"f":"Varför används Ringer-Acetat ibland i stället för koksalt?","b":"Den innehåller buffrande ämnen som stabiliserar pH. Därför är den bättre vid stora vätskeförluster, kirurgi och långa infusioner, eftersom mycket koksalt kan påverka blodets pH.","ty":"j","src":"Lektion","id":"k5c1jskael"},{"f":"Varför ges aldrig rent vatten i dropp?","b":"Det är hypotont. Vatten skulle strömma in i blodkropparna och hjärncellerna, och därför skulle det ge hemolys och hjärnödem.","ty":"f","t":["osmos"],"src":"Lektion","id":"k5c1oz4zac"},{"f":"Vilka två huvudtyper av aktiv transport beskriver filmen?","b":"Proteinpumpar (klassisk aktiv transport, en typ av bärarprotein) och vesikeltransport (endocytos och exocytos).","ty":"b","t":["atp"],"src":"Film Aktiv transport","id":"k5cnetp3d"},{"f":"Provfälla: går vesikeltransport alltid mot gradienten?","b":"Nej. Den kan gå med eller mot gradienten, men ATP krävs alltid för att bilda och flytta vesiklarna.","ty":"f","t":["atp"],"src":"Film Aktiv transport","id":"k5cvzz6ul"},{"f":"Varför behöver cellen aktiv transport? Ge fyra skäl.","b":"Samla ämnen (glukos, joner), pumpa ut skadliga ämnen för en stabil inre miljö, bygga laddningsskillnad i nerv- och muskelceller och ta in eller ut stora partiklar.","ty":"v","t":["atp"],"src":"Film Aktiv transport","id":"k5c10w0qqu"},{"f":"Natrium-kaliumpumpens åtta steg?","b":"3 Na⁺ binder, ATP spjälkas och fosfat binds, formen ändras utåt, Na⁺ släpps ut, 2 K⁺ binder, fosfatet släpper, formen ändras tillbaka, K⁺ släpps in.","ty":"s","t":["atp"],"src":"Film Aktiv transport","id":"k5c9ohr8b"},{"f":"Vad är vesiklarnas adresslappar?","b":"Kemiska markörer, proteiner eller kolhydratkedjor, som vesiklarna får i ER eller golgi. De passar som nycklar i lås (receptorer) på rätt målmembran.","ty":"b","t":["nyckel"],"src":"Film Aktiv transport","id":"k5c1ybnxho"},{"f":"Varför kräver exocytos och endocytos ATP?","b":"Energi behövs för att omforma och flytta membranet, och motorproteiner som drar vesiklarna längs mikrotubuli använder ATP.","ty":"v","t":["atp"],"src":"Film Aktiv transport","id":"k5c1kaj05e"},{"f":"Vad utlöser exocytosen i en synaps?","b":"Nervimpulsen öppnar Ca²⁺-kanaler, Ca²⁺ strömmar in, och då smälter vesiklarna med signalämne ihop med membranet.","ty":"v","src":"Film Aktiv transport","id":"k5c1d7atzp"},{"f":"Hur tar sig SARS-CoV-2 in i cellen?","b":"Det binder till ACE2-receptorer, membranet buktar in, vesikeln förs in och arvsmassan frigörs. Viruset kapar cellens vesikeltransport.","ty":"v","t":["nyckel"],"src":"Film Aktiv transport","id":"k5ct83vjl"},{"f":"Vilka immunceller gör främst fagocytos enligt filmen?","b":"Makrofager och neutrofiler.","ty":"s","src":"Film Aktiv transport","id":"k5c1sgnivs"},{"f":"Vilka delar har cellmembranet på lärarens bild 2?","b":"Ett dubbellager av fosfolipider med hydrofila huvuden och hydrofoba svansar, kolesterol, kanalprotein, membranbundna proteiner, glykolipid, kolhydrater och proteintrådar i cellskelettet. Extracellulär vätska ovanför, cytoplasma (cellvätska) under.","ty":"i","t":["membran"],"src":"PPT Transport bild 2 · s. 17–19","id":"k5c1bqez2o"},{"f":"Vilka fyra faktorer avgör hur lätt ett ämne tar sig igenom cellmembranet?","b":"Laddning, storlek, form och fettlöslighet. Minnesknep: Lilla Stina Fryser om Fötterna.","ty":"s","t":["membran"],"src":"s. 31 · PPT Transport bild 4 · Arbetsblad","p":1,"id":"k5c1u8cl4z"},{"f":"Varför passerar syre och koldioxid fritt genom cellmembranet?","b":"De är små, oladdade och hydrofoba, och fosfolipidskiktet är fettlösligt. Därför glider de rakt igenom.","ty":"v","t":["membran"],"src":"s. 31 · PPT Transport bild 4","p":1,"id":"k5cvluxrm"},{"f":"Varför kan inte ens vätejonen ta sig genom fosfolipidskiktet?","b":"Den attraherar, liksom andra joner, vattenmolekyler och omges av ett skal av vattenmolekyler. Därför är den hydrofil och kommer inte igenom.","ty":"v","src":"s. 31","id":"k5cbmi8y0"},{"f":"Provfälla: vätejonen är minst av alla joner. Kommer den då lätt igenom membranet?","b":"Nej. Laddningen och vattenskalet stoppar den. Steroidhormoner är tvärtom stora men passerar, eftersom de är fettlösliga.","ty":"f","src":"s. 31","id":"k5cntyx50"},{"f":"Vilka hydrofoba molekyler visar bokens figur på s. 31?","b":"O₂, CO₂, N₂ och steroidhormoner. De passerar fritt.","ty":"i","src":"s. 31","id":"k5cejzku5"},{"f":"Vilka oladdade polära molekyler visar figuren på s. 31, och hur går det för dem?","b":"Små: H₂O och glycerol. En del tar sig igenom, men de flesta studsar tillbaka. Stora: glukos. Mycket lite kommer igenom.","ty":"i","src":"s. 31","id":"k5c1lvx0rq"},{"f":"Vilka joner står i figuren på s. 31?","b":"H⁺, Na⁺, HCO₃⁻, K⁺, Ca²⁺, Cl⁻ och Mg²⁺. Ingen av dem kommer igenom fosfolipidskiktet.","ty":"s","src":"s. 31","id":"k5cuc5znk"},{"f":"Vad säger bildtexten på s. 31 om vilka molekyler som lättast tar sig igenom?","b":"Ju mindre molekylen är och framförallt ju mer hydrofob den är, desto lättare tar den sig in genom fosfolipidlagret. Fettlösligheten väger tyngst.","ty":"b","src":"s. 31","id":"k5c1jmhk4q"},{"f":"Vad är diffusion?","b":"Transport från hög till låg koncentration. Den kräver ingen energi, eftersom ämnet följer sin koncentrationsgradient.","ty":"b","src":"s. 31 · PPT Transport bild 5 · Arbetsblad","p":1,"id":"k5cm860hq"},{"f":"Vad är passiv transport?","b":"Diffusion genom ett cellmembran. Den kallas passiv eftersom den inte kostar cellen någon energi.","ty":"b","src":"s. 31 · PPT Transport bild 7","p":1,"id":"k5c1ugh7i"},{"f":"Vad är en koncentrationsgradient?","b":"Skillnaden mellan hög och låg koncentration. Ett ämne som diffunderar följer gradienten, från hög till låg.","ty":"b","src":"s. 31 · PPT Transport bild 6 · Arbetsblad","p":1,"id":"k5c1ydcoyy"},{"f":"Varför kräver diffusion ingen energi? Använd bokens backe.","b":"Gradienten är som en nedförsbacke. Ett föremål uppe på backen har potentiell energi (lägesenergi), och på samma sätt finns det potentiell energi i gradienten. Därför \"rullar\" ämnet av sig självt.","ty":"v","src":"s. 31 · PPT Transport bild 5","p":1,"id":"k5cxnawd8"},{"f":"Hur kan sockret i teet spridas åt ett bestämt håll när varje molekyl rör sig slumpmässigt?","b":"Varje molekyls rörelse är slumpmässig, men transporten totalt sett går från hög koncentration (sockerbiten) till låg, tills sockret är jämnt fördelat.","ty":"v","src":"s. 31","id":"k5c1regsgx"},{"f":"Provfälla: slutar molekylerna att röra sig när sockret är jämnt fördelat?","b":"Nej. Partiklar är i ständig rörelse. Det blir bara ingen nettoförflyttning längre.","ty":"f","src":"s. 31","id":"k5c1mnuv4n"},{"f":"Beror ett ämnes diffusion på koncentrationen av andra ämnen?","b":"Nej. Varje substans rör sig längs sin egen koncentrationsgradient.","ty":"b","src":"s. 31 · PPT Transport bild 7","p":1,"id":"k5ce89j8h"},{"f":"Varifrån kommer energin för diffusionen enligt läraren?","b":"Från molekylernas värmerörelse. Ingen ytterligare energi behövs.","ty":"b","src":"PPT Transport bild 5","id":"k5c14ehg0z"},{"f":"Vilket vardagsexempel på diffusion använder boken, och vilket använder läraren?","b":"Boken: en sockerbit i en kopp te. Läraren: grädde som blandas med kaffe.","ty":"s","src":"s. 31 · PPT Transport bild 5","id":"k5cf3z5dr"},{"f":"Hur definierar läraren koncentrationsgradienten?","b":"Skillnaden mellan hög och låg koncentration i förhållande till avståndet. Den är ett mått på hur snabb diffusionen är, och koncentrationen är högst närmast källan.","ty":"b","src":"PPT Transport bild 6","id":"k5c14huobz"},{"f":"Hur kan en cell \"andas\" utan att använda energi?","b":"Syre och koldioxid har fri passage. Syrehalten är högre utanför, så syre diffunderar in. Koldioxidhalten är högre inuti, så koldioxid diffunderar ut. Båda följer sin egen gradient.","ty":"v","src":"s. 32 · PPT Transport bild 7","p":1,"id":"k5c1co2et2"},{"f":"Provfälla: åt vilket håll går syret om syrehalten är högre inuti cellen än utanför?","b":"Ut. Syre följer alltid sin koncentrationsgradient, och cellen har ingen pump för syre.","ty":"f","src":"s. 32","id":"k5capqjzb"},{"f":"Vad är underlättad diffusion?","b":"Diffusion med hjälp av proteiner i membranet, för ämnen som inte kan slinka igenom fosfolipidlagret. Den går med gradienten och kräver ingen energi.","ty":"b","src":"s. 32 · PPT Transport bild 8","p":1,"id":"k5c8qbbx3"},{"f":"Vad heter underlättad diffusion hos läraren, och vad kallas bärarproteinet på bild 11?","b":"Faciliterad diffusion (samma sak). Bärarproteinet kallas passiv transportör.","ty":"b","src":"PPT Transport bild 8, 11","id":"k5c1bnml3n"},{"f":"Vad är ett kanalprotein?","b":"En öppning i membranet, en vattenfylld kanal, som bara ämnen med rätt storlek, form och laddning kan slinka igenom, t.ex. vatten och joner.","ty":"b","src":"s. 32 · PPT Transport bild 8–9","p":1,"id":"k5cox0rx2"},{"f":"Vad är ett bärarprotein?","b":"Ett protein som binder ett visst ämne, t.ex. glukos, och lyfter det genom membranet genom att ändra form.","ty":"b","src":"s. 32 · PPT Transport bild 10 · Arbetsblad","p":1,"id":"k5c180ewfq"},{"f":"Vilka tre sorters stimuli kan öppna och stänga kanalproteiner?","b":"Kemiska, elektriska och mekaniska (KEM).","ty":"s","src":"s. 32 · PPT Transport bild 9","p":1,"id":"k5c1osdx10"},{"f":"Vad är jonkanaler?","b":"Kanalproteiner som är specialiserade på joner. Det finns t.ex. jonkanaler som bara släpper igenom Na⁺ och andra som bara släpper igenom K⁺.","ty":"b","src":"s. 32 · PPT Transport bild 9 · Arbetsblad","p":1,"id":"k5clk5yus"},{"f":"Vad betyder det att transportproteiner är specifika?","b":"De underlättar transporten för bara ett visst ämne, ungefär som ett lås som bara passar en nyckel.","ty":"b","t":["nyckel"],"src":"s. 32","id":"k5c17z07tk"},{"f":"Kanalprotein eller bärarprotein: vad är skillnaden?","b":"Kanalproteinet är en vattenfylld öppning som öppnas och stängs av stimuli. Bärarproteinet binder ämnet och ändrar form. Båda är specifika och passiva.","ty":"j","src":"s. 32","p":1,"id":"k5c1a04dhy"},{"f":"Vilka extra membranord finns på lärarens bild 9?","b":"Integralt membranprotein (går genom hela membranet), perifert membranprotein (sitter på ytan), glykoprotein (protein med socker) och glykolipid (lipid med socker).","ty":"b","src":"PPT Transport bild 9","id":"k5c1al4wh4"},{"f":"Vad är aquaporiner?","b":"Vattenkanaler i cellmembranet, som vattenmolekyler kan diffundera genom. Antalet varierar mellan celler, och vissa kan stängas vid behov.","ty":"b","t":["osmos"],"src":"s. 33 · Arbetsblad","p":1,"id":"k5cic0kk8"},{"f":"Varför behöver vatten aquaporiner trots att molekylen är liten?","b":"Vattenmolekylen är polär, och därför har den svårt att ta sig genom fosfolipidskiktet.","ty":"v","t":["osmos"],"src":"s. 33","id":"k5c1cvvun1"},{"f":"Definiera osmos.","b":"\"Vattnets diffusion över ett semipermeabelt membran.\"","ty":"b","t":["osmos"],"src":"s. 33 · PPT Transport bild 13 · Arbetsblad","p":1,"id":"k5c3mqlwj"},{"f":"Varför rör sig vatten lättare in i och ut ur en cell än andra ämnen?","b":"Cellen har många fler vattenkanaler än jonkanaler och bärarproteiner.","ty":"v","t":["osmos"],"src":"s. 33 · Arbetsblad","p":1,"id":"k5clilwv3"},{"f":"Varför har en saltlösning lägre vattenkoncentration än rent vatten?","b":"De lösta jonerna tar upp det utrymme som vattenmolekylerna hade förut.","ty":"v","t":["osmos"],"src":"s. 33","id":"k5c12cofc6"},{"f":"Vad betyder hypoton, isoton och hyperton lösning?","b":"Hypoton: låg halt av lösta ämnen, t.ex. destillerat vatten. Isoton: samma halt som inuti cellen. Hyperton: hög halt av lösta ämnen.","ty":"b","t":["osmos"],"src":"s. 33","p":1,"id":"k5c3no2al"},{"f":"Vad händer med en röd blodkropp i en stark saltlösning, och varför?","b":"Den krymper. Saltlösningen har lägre vattenkoncentration, så vatten går från den högre vattenkoncentrationen inuti cellen ut i lösningen.","ty":"v","t":["osmos"],"src":"s. 33 · PPT Transport bild 13","p":1,"id":"k5c1i5ga1t"},{"f":"Vad händer med en röd blodkropp i destillerat vatten, och varför?","b":"Vattenkoncentrationen är högre utanför, så vatten diffunderar in. Cellen sväller och kanske till slut sprängs.","ty":"v","t":["osmos"],"src":"s. 33 · PPT Transport bild 13","p":1,"id":"k5cmhcq13"},{"f":"Varför påverkas inte en röd blodkropp i en isoton lösning?","b":"Lösningen har samma koncentration av lösta ämnen som cytoplasman. Då är vattenkoncentrationen densamma, och lika många vattenmolekyler diffunderar in som ut.","ty":"v","t":["osmos"],"src":"s. 33","id":"k5c7r1zyb"},{"f":"Varför följer inte saltjonerna med vattnet vid osmos, enligt boken?","b":"Det finns färre jonkanaler än vattenkanaler, och därför är transporten av saltjoner mycket långsammare.","ty":"v","t":["osmos"],"src":"s. 33 · Arbetsblad","p":1,"id":"k5c13m3g3l"},{"f":"Boken och läraren förklarar olika varför saltet inte följer med vid osmos. Hur?","b":"Boken: färre jonkanaler än vattenkanaler, så saltet rör sig mycket långsammare. Läraren: saltjonerna är för stora för membranets porer. Svara som boken på provet.","ty":"j","t":["osmos"],"src":"s. 33 · PPT Transport bild 13","id":"k5c1deop8g"},{"f":"Provfälla: vad beskriver orden hypoton och hyperton?","b":"Halten lösta ämnen i lösningen utanför cellen. Hypoton = lite löst ämne = mycket vatten, och därför går vattnet in.","ty":"f","t":["osmos"],"src":"s. 33","id":"k5coyadl6"},{"f":"Vad menar boken med högre vattenpotential?","b":"Högre vattenkoncentration. Vatten diffunderar från högre vattenpotential till lägre.","ty":"b","t":["osmos"],"src":"s. 33","id":"k5c6bagrh"},{"f":"Vilka två villkor krävs för osmos enligt lärarens bild?","b":"De lösta ämnena kan inte passera membranet, men lösningsmedlet kan. Och de lösta partiklarna är ojämnt fördelade på de två sidorna.","ty":"s","t":["osmos"],"src":"PPT Transport bild 13","id":"k5c1biga7r"},{"f":"Bilden på s. 33: hur ser blodkropparna ut i de tre lösningarna?","b":"Hypoton: uppsvälld och spricker, H₂O in. Isoton: normal skiva, H₂O in och ut lika mycket. Hyperton: skrynklig och taggig, H₂O ut.","ty":"i","t":["osmos"],"src":"s. 33","id":"k5co62py3"},{"f":"Vad är aktiv transport?","b":"Transport över ett cellmembran mot koncentrationsgradienten, från lägre till högre koncentration. Den kräver energi och ett membrantransportprotein som binder specifikt till ämnet.","ty":"b","t":["atp"],"src":"s. 34 · PPT Transport bild 15 · Arbetsblad","p":1,"id":"k5ch5iz3x"},{"f":"Vilka två sätt finns att lösa den energikrävande transporten?","b":"Kopplad transport och ATP-drivna proteinpumpar.","ty":"s","src":"s. 34 · PPT Transport bild 15","p":1,"id":"k5c1dh0e4g"},{"f":"Vilka organismer har proteinpumpar som drivs av solenergi?","b":"Vissa bakterier och arkéer.","ty":"s","src":"s. 34","id":"k5c19hzm7b"},{"f":"Provfälla: räcker det att säga att aktiv transport kräver energi?","b":"Nej. Den kräver också ett membrantransportprotein som binder specifikt till ämnet.","ty":"f","src":"s. 34 · PPT Transport bild 15","p":1,"id":"k5c1ck69u3"},{"f":"Bokens översiktsbild s. 34: åt vilket håll pekar pilarna?","b":"Vid diffusion, kanalprotein och bärarprotein pekar pilarna nedåt, med gradienten (passiv transport). Vid proteinpumpen pekar pilen uppåt, mot gradienten, och energi krävs (aktiv transport).","ty":"i","src":"s. 34","id":"k5cjljr9v"},{"f":"Vad är kopplad transport (co-transport)?","b":"Transporten av ett ämne mot sin gradient kopplas till ett annat ämne som diffunderar med sin gradient.","ty":"b","t":["atp"],"src":"s. 34 · PPT Transport bild 17 · Arbetsblad","p":1,"id":"k5c1islbja"},{"f":"Förklara kopplad transport med bokens vattenfall.","b":"Lägesenergin när vattnet faller kan driva ett hjul som lyfter något uppför fallet. Ämnet som diffunderar är vattnet, och ämnet som följer med är det som lyfts uppför.","ty":"v","src":"s. 34","id":"k5c1ag6bvz"},{"f":"Varför kräver kopplad transport ATP, fast indirekt?","b":"Gradienten för det ämne som diffunderar måste upprätthållas. Utan gradient ingen diffusion. Ämnet måste pumpas tillbaka, och det kräver ATP.","ty":"v","t":["atp"],"src":"s. 34 · PPT Transport bild 18","p":1,"id":"k5c1w6mwjs"},{"f":"Vilka två delar har den kopplade transporten?","b":"Del 1 bygger upp en koncentrationsgradient, vanligen av natrium- eller vätejoner. Del 2 använder deras diffusion för att driva transporten av det andra ämnet.","ty":"b","src":"s. 35","id":"k5c1emjzx6"},{"f":"Symport eller antiport?","b":"Symport: två ämnen åt samma håll, t.ex. Na⁺ och glukos in i tarmcellen. Antiport: åt motsatta håll, t.ex. Na⁺ ut och K⁺ in.","ty":"j","src":"PPT Transport bild 18","id":"k5c17ntrdv"},{"f":"Hur många natriumjoner tas upp per glukosmolekyl i tarmen?","b":"Två Na⁺ per glukos.","ty":"s","src":"s. 35 · PPT Transport bild 18","p":1,"id":"k5c8exqib"},{"f":"Vem upptäckte den kopplade transporten av natrium och glukos i tarmceller, och vad har upptäckten betytt?","b":"Robert K. Crane (1919–2010). Upptäckten har räddat massor av människor från att dö av uttorkning vid diarré, t.ex. vid kolera, och minskat barndödligheten i många U-länder.","ty":"s","src":"s. 35","id":"k5c11nl6g9"},{"f":"Varför får patienter med vätskebrist dricka en lösning med både salt och glukos?","b":"Natrium tas upp i tarmens epitelceller genom kopplad transport till glukos. Utan glukos tas natriumet inte upp.","ty":"v","src":"s. 35 · PPT Transport bild 18","p":1,"id":"k5c1021xrk"},{"f":"Varför kan diarré, t.ex. vid kolera, leda till döden?","b":"Avföringen passerar så snabbt att natriumjonerna inte hinner reabsorberas (återupptas). Förlusten av natrium stör kroppens jonbalans, och man torkar ut.","ty":"v","src":"s. 35","id":"k5c18r5w0k"},{"f":"Provfälla: vilket ämne går med sin gradient i tarmcellens kopplade transport?","b":"Natrium går med sin gradient, in i cellen. Glukos går mot sin.","ty":"f","src":"s. 35 · PPT Transport bild 18","p":1,"id":"k5c17e7fdx"},{"f":"Hur får en ATP-driven proteinpump sin energi?","b":"ATP hydrolyseras till ADP (\"tappar\" ett fosfat). Energin som frigörs överförs till pumpen, så att ämnet som binder kan föras till andra sidan.","ty":"v","t":["atp"],"src":"s. 35 · PPT Transport bild 16","p":1,"id":"k5ctw2vxu"},{"f":"Vad är den stora fördelen med ATP-drivna proteinpumpar?","b":"De fungerar oberoende av koncentrationsgradienter, eftersom energin kommer direkt från ATP.","ty":"b","t":["atp"],"src":"s. 35","id":"k5c1k3cyxv"},{"f":"Hur stor del av cellens ATP går till natrium-kaliumpumpen?","b":"Ungefär 40 % enligt boken. Läraren skriver 10–40 %.","ty":"s","t":["atp"],"src":"s. 35 · PPT Transport bild 19","p":1,"id":"k5c1ldov8e"},{"f":"Vad gör natrium-kaliumpumpen för cellen?","b":"Den upprätthåller jonbalansen. Den håller Na⁺ högre utanför cellen och K⁺ högre innanför.","ty":"v","src":"s. 35 · PPT Transport bild 19","p":1,"id":"k5c1sjpdyy"},{"f":"Provfälla: åt vilket håll pumpas natrium och kalium, och hur många?","b":"Na⁺ ut och K⁺ in. Tre ut och två in per ATP (lärarens bild 19).","ty":"f","t":["atp"],"src":"PPT Transport bild 16, 19","id":"k5c1ille43"},{"f":"Vad händer med fosfatet när ATP driver natrium-kaliumpumpen, enligt läraren?","b":"ATP hydrolyseras, och en fosfatgrupp binds till pumpen.","ty":"b","t":["atp"],"src":"PPT Transport bild 19","id":"k5cfmf4pp"},{"f":"Hur verkar hjärtläkemedlet digoxin enligt läraren?","b":"Digoxin hämmar Na⁺/K⁺-pumpen. Natriumhalten i cellen ökar, Na⁺/Ca²⁺-pumpen kan inte fungera, och hjärtmuskelns kontraktionskraft ökar.","ty":"v","src":"PPT Transport bild 16","id":"k5c1x29mtk"},{"f":"Bärarprotein eller proteinpump?","b":"Båda binder ämnet. Bärarproteinet går med gradienten utan energi. Pumpen går mot gradienten och drivs av ATP.","ty":"j","src":"s. 32, 35","id":"k5c1o9ifz7"},{"f":"Primär eller sekundär aktiv transport?","b":"Primär: pumpen använder ATP direkt, t.ex. natrium-kaliumpumpen. Sekundär (kopplad transport): drivs av en gradient som en ATP-pump har byggt upp.","ty":"j","t":["atp"],"src":"PPT Transport bild 16–18","id":"k5c1xdg5fs"},{"f":"Hur är cellmembranet laddat på lärarens bild 16?","b":"Positivt på utsidan (+ + +) och negativt på insidan (– – –).","ty":"b","src":"PPT Transport bild 16","id":"k5c1j6t8r4"},{"f":"Hur bidrar natrium-kaliumpumpen till laddningen över membranet?","b":"Den flyttar ut tre positiva Na⁺ men in bara två positiva K⁺. Därför hamnar mer positiv laddning utanför. K⁺ läcker dessutom ut längs sin gradient.","ty":"v","t":["atp"],"src":"PPT Transport bild 16, 19","id":"k5c1b7d99x"},{"f":"Vad är en elektrokemisk gradient?","b":"Koncentrationsskillnaden och laddningsskillnaden över membranet tillsammans. Den styr åt vilket håll joner vill röra sig.","ty":"b","src":"PPT Transport bild 16 · Extra","id":"k5cnbaiug"},{"f":"Vilka värden har hjärtmuskelcellens aktionspotential på lärarens bild?","b":"Vila ca −96 mV, topp ca +52 mV, och ca 200 ms från fas 0 till slutet av fas 3.","ty":"s","src":"PPT Transport bild 20","id":"k5cn366pq"},{"f":"Vilka joner styr aktionspotentialens faser i hjärtmuskelcellen?","b":"Fas 0: Na⁺ in. Fas 1: K⁺ och Cl⁻, kort utåtriktad ström. Fas 2: Ca²⁺ in och K⁺ ut (platå). Fas 3: K⁺ ut. Fas 4: vila.","ty":"v","src":"PPT Transport bild 20","id":"k5c1b3s2f6"},{"f":"Vad är endocytos och exocytos?","b":"Endocytos: något tas in i cellen med membranblåsor. Exocytos: något utsöndras ur cellen med membranblåsor. Båda kräver energi.","ty":"b","t":["membran"],"src":"s. 35 · PPT Transport bild 21 · Arbetsblad","p":1,"id":"k5cdoq7ol"},{"f":"Varför tas vissa ämnen upp med endocytos i stället för med transportproteiner, och vad gör rörelsen möjlig?","b":"De är för stora för transportproteinerna. Därför omsluter delar av cellmembranet dem i stället, och mikrofilamenten (aktin) i cellskelettet gör det möjligt. Läraren: \"endo-\" betyder inre, och alla celler använder endocytos, eftersom de flesta viktiga substanser är polära och stora och inte kan passera det hydrofoba plasmamembranet.","ty":"v","src":"s. 36 · PPT Transport bild 22","p":1,"id":"k5coglvti"},{"f":"Fagocytos eller pinocytos?","b":"Fagocytos (\"cellätande\"): stora partiklar, till och med hela celler, och membranet buktar ut i armar. Pinocytos (\"celldrickande\"): vattenlösliga makromolekyler, och membranet buktar in.","ty":"j","src":"s. 36 · PPT Transport bild 22–23 · Arbetsblad","p":1,"id":"k5cpk3lyr"},{"f":"Hur skiljer sig bokens och lärarens beskrivning av endocytos?","b":"Boken: två typer, fagocytos (stora partiklar, t.ex. bakterier) och pinocytos (vattenlösliga makromolekyler, med receptorer). Läraren: tre typer, där pinocytos är att extracellulär vätska förs in och receptormedierad endocytos är en egen typ. Skriv bokens två och nämn gärna den tredje.","ty":"j","src":"s. 36 · PPT Transport bild 21–23","id":"k5c1vfwp8m"},{"f":"Hur tas ett ämne upp via receptorer vid pinocytos?","b":"Molekylerna binder till receptorer, membranet buktar in där, ju fler som binder desto mer buktar det in, och till sist snörs bubblan av och förs in i cellen.","ty":"v","t":["nyckel"],"src":"s. 36 · PPT Transport bild 23","p":1,"id":"k5c1s22br"},{"f":"Varför kan armarna vid fagocytos smälta samman?","b":"Cellmembranet går att jämföra med en trögflytande vätska. Därför smälter armarna ihop där de möts, och en membranbubbla bildas.","ty":"v","t":["membran"],"src":"s. 36","id":"k5c1o5kgo7"},{"f":"Vad kallas de vita blodkroppar som gör fagocytos, och vad händer med vesikeln efter upptaget?","b":"Fagocyter. Vesikeln smälter ihop med lysosomer, och lysosomernas enzymer bryter ner det som tagits upp, t.ex. en bakterie.","ty":"v","src":"s. 36","id":"k5c19wgj62"},{"f":"Vilka tre typer av endocytos nämner läraren, och vad är vesikulär transport?","b":"Fagocytos, pinocytos och receptormedierad endocytos. Vesikulär transport är transport med vesiklar, små blåsor omgivna av ett lipidlager, in i, ut ur eller inom cellen.","ty":"s","src":"PPT Transport bild 21","id":"k5c94kdz4"},{"f":"Vad är pseudopodier och en fagosom på lärarens bild?","b":"Pseudopodier är utskotten som omsluter partikeln vid fagocytos. Fagosomen (näringsvakuolen) är bubblan som bildas runt partikeln.","ty":"i","src":"PPT Transport bild 23","id":"k5ce4nnf2"},{"f":"Vad är en klatrinbelagd grop?","b":"Gropen som membranet bildar vid receptormedierad endocytos. Den snörs av till en klatrinbelagd vesikel. På lärarens bild står också \"Kaspid\" vid vesikelns hölje.","ty":"i","src":"PPT Transport bild 23","id":"k5c4mlzrk"},{"f":"Provfälla: är det bara pinocytos som kräver receptorer?","b":"Nej. Enligt boken kräver även fagocytos receptorer.","ty":"f","src":"s. 36","id":"k5clgiocb"},{"f":"Hur transporteras kolesterol i blodet?","b":"I små partiklar där kolesterolmolekyler och protein bildar en vattenlöslig enhet.","ty":"b","src":"s. 36 · PPT Bi2 bild 14","p":1,"id":"k5c1rk2r1e"},{"f":"LDL eller HDL?","b":"LDL (low density lipoprotein) har mer kolesterol per protein, släpper kolesterolet lättare, och höga halter ger hjärt-kärlsjukdom (\"onda\"). HDL (high density lipoprotein) för överskott av kolesterol till levern, där det bryts ner (\"goda\").","ty":"j","src":"s. 36 · PPT Bi2 bild 14","p":1,"id":"k5c1sjdg0k"},{"f":"Provfälla: är LDL och HDL två sorters kolesterol?","b":"Enligt boken är de partiklar av kolesterol och protein. Läraren skriver \"olika typer av kolesterol\", men svara som boken.","ty":"f","src":"s. 36 · PPT Bi2 bild 14","id":"k5c2lrbb3"},{"f":"Varför blir LDL-halten hög om genen för LDL-receptorn är felaktig?","b":"LDL tas upp i cellerna via endocytos med hjälp av receptorn. Utan fungerande receptor stannar LDL i blodet.","ty":"v","t":["nyckel"],"src":"s. 36","id":"k5cmqsksf"},{"f":"Varför kallas sjukdomen med felaktig LDL-receptor kodominant?","b":"En felaktig gen ger mycket höga halter och två ger extremt höga. Båda generna påverkar alltså.","ty":"v","src":"s. 36","id":"k5c153owq5"},{"f":"Vad blir följden av en felaktig LDL-receptorgen på en respektive båda kromosomerna?","b":"En: mycket höga LDL-halter och kraftigt ökad risk för hjärtinfarkt och stroke i vuxen ålder. Båda: extremt höga halter, och man avlider ofta tidigt i hjärt- och kärlsjukdom.","ty":"j","src":"s. 36","id":"k5cq4vit2"},{"f":"Hur många bär en felaktig LDL-receptorgen, och vad kan de göra?","b":"Mer än en person av tusen. Ett gentest visar det, och risken minskar radikalt med kolesterolfattig mat, regelbunden motion och medicinering.","ty":"s","src":"s. 36","id":"k5ci7eygs"},{"f":"Vad betyder exocytos, och vilka celler använder den?","b":"\"Ut ur cellen\". Det är motsatsen till endocytos. Alla celler använder exocytos, t.ex. för att föra ut glykoproteiner som bygger upp cellmembranet och ECM.","ty":"b","src":"s. 37 · PPT Transport bild 24 · Arbetsblad","p":1,"id":"k5cmtu2p3"},{"f":"Hur går exocytos till enligt boken?","b":"Golgiapparaten producerar membranblåsor, som transporteras till cellmembranet. Fosfolipiderna blandas, membranen smälter ihop och innehållet släpps ut.","ty":"v","src":"s. 37 · PPT Transport bild 24","p":1,"id":"k5c1srk3rc"},{"f":"Varför växer inte cellen hela tiden trots exocytos?","b":"Exocytos tillför fosfolipider till cellmembranet, men vid endocytos försvinner fosfolipider. Processerna tar ut varandra.","ty":"v","t":["membran"],"src":"s. 37","id":"k5c7t5mkf"},{"f":"Ge två exempel på sekretoriska celler från boken.","b":"Cellerna som producerar insulin i bukspottkörteln och nervceller som lagrar neurotransmittorer i synapsblåsor.","ty":"s","src":"s. 37 · PPT Transport bild 24","p":1,"id":"k5crdmrkh"},{"f":"Vilken väg tar ett protein som ska ut med exocytos, enligt läraren?","b":"Ribosomer på korniga ER → ER:s hålrum → vesikel till golgiapparatens cis-sida → modifieras → lämnar via trans-sidan → vesikeln går upp i cellmembranet och innehållet utlöses.","ty":"v","src":"PPT Transport bild 24","id":"k5c13bxbjr"},{"f":"Vad kan exocytos användas till hos protozoer och hos flercelliga organismer, enligt läraren?","b":"Exocytos utsöndrar stora biomolekyler, t.ex. ämnen från körtelceller. Protozoer kan utsöndra avfallsprodukter. Hos flercelliga organismer har exocytos även signalerande och reglerande funktion.","ty":"b","src":"PPT Transport bild 24","id":"k5c129izpb"},{"f":"Provfälla: gör exocytos eller endocytos cellmembranet större?","b":"Exocytos, eftersom vesikelns fosfolipider blir en del av cellmembranet. Endocytos tar bort fosfolipider.","ty":"f","t":["membran"],"src":"s. 37","id":"k5c1h023pa"},{"f":"Bokens bild s. 37: vad visar a) och b)?","b":"a) Exocytos: vesikeln smälter ihop med membranet och töms, och membranet får fosfolipider. b) Endocytos: membranet buktar in och snörs av till en vesikel, och membranet tappar fosfolipider.","ty":"i","src":"s. 37","id":"k5cgm6bxp"}],"quiz":{"f":[{"q":"Vad släpper en akvaporin igenom?","o":["Bara vattenmolekyler","Vatten och alla joner","Vatten och protoner","Glukos och vatten"],"why":"Filmen betonar att akvaporinen bara släpper igenom vatten. Positiva laddningar stoppar protonerna.","src":"Film Osmos","t":["osmos"],"id":"k5q1740acc"},{"q":"Vad stoppar protonerna (H⁺) i akvaporinen?","o":["Positivt laddade sidogrupper i kanalen","Kanalens storlek","Kolesterol i membranet","ATP"],"why":"Positiva laddningar stöter bort H⁺, och därför bevaras cellens elektriska balans.","src":"Film Osmos","t":["osmos"],"id":"k5qly6gya"},{"q":"Vad mäter osmolalitet?","o":["Antalet osmotiskt aktiva partiklar per kilogram lösningsmedel","Antalet vattenmolekyler per liter","Trycket mot cellväggen","Antalet akvaporiner per cell"],"why":"Osmolalitet räknar osmotiskt aktiva partiklar per kg. Per liter heter det osmolaritet.","src":"Film Osmos","t":["osmos"],"id":"k5qu5dbug"},{"q":"Vilken osmolalitet är isoton med blodplasman?","o":["Ca 280–295 mOsm/kg","Ca 150 mOsm/kg","Ca 1 000 mOsm/kg","Ca 2–3 mOsm/kg"],"why":"Filmen anger 280–295 mOsmol/kg. 1 000 är havsvatten.","src":"Film Osmos","t":["osmos"],"id":"k5q6aptnx"},{"q":"Vad kallas det när röda blodkroppar spricker i en hypoton lösning?","o":["Hemolys","Plasmolys","Turgor","Fagocytos"],"why":"Hemolys gäller blodkroppar. Plasmolys gäller växtceller i hyperton lösning.","src":"Film Osmos","t":["osmos"],"id":"k5q17ptnfg"},{"q":"Vilket engelskt bildord beskriver en växtcell i hypoton lösning?","o":["Turgid","Flaccid","Plasmolyzed","Crenated"],"why":"Turgid betyder spänd. Flaccid (slapp) är isoton, plasmolyzed är hyperton.","src":"Film Osmos","t":["osmos"],"id":"k5qu1brf1"},{"q":"Vad är hyponatremi?","o":["Låg natriumkoncentration i blodplasman","Hög natriumkoncentration i blodplasman","Lågt blodsocker","För lite vatten i cellerna"],"why":"Hypo = under, natremi = natrium i blodet.","src":"Lektion","t":["osmos"],"id":"k5q90xyil"},{"q":"Hur mycket salt och hur hög osmolalitet har havsvatten enligt lektionen?","o":["3,5 % och ca 1 000 mOsm/kg","0,9 % och ca 290 mOsm/kg","10 % och ca 3 000 mOsm/kg","0,1 % och ca 30 mOsm/kg"],"why":"Blodplasman har 0,9 % och 280–295. Havsvatten har ungefär fyra gånger så mycket salt.","src":"Lektion","t":["osmos"],"id":"k5q1u4ipqu"},{"q":"Hur många mmol Na⁺ per liter finns i fysiologisk koksaltlösning?","o":["154","308","9","290"],"why":"9 g/L NaCl = 154 mmol/L. 308 är mOsmol/L, eftersom varje NaCl ger två partiklar.","src":"Lektion","t":["osmos"],"id":"k5qscgpdc"},{"q":"Vad har Ringer-Acetat som vanlig koksaltlösning saknar?","o":["Buffrande ämnen som stabiliserar pH","Glukos","Rent vatten","Albumin"],"why":"Bufferten gör Ringer-Acetat bättre vid stora vätskeförluster och långa infusioner.","src":"Lektion","id":"k5q19tsgfc"},{"q":"Vilka jonkanaler öppnas när nervimpulsen når nervänden?","o":["Ca²⁺-kanaler","K⁺-kanaler","Cl⁻-kanaler","Akvaporiner"],"why":"Ca²⁺ strömmar in och utlöser exocytosen av vesiklarna med signalämne.","src":"Film Aktiv transport","id":"k5q1cif85x"},{"q":"Vilken receptor binder coronaviruset (SARS-CoV-2) till?","o":["ACE2","LDL-receptorn","Insulinreceptorn","Akvaporin"],"why":"Viruset binder till ACE2 och tas in med endocytos.","src":"Film Aktiv transport","t":["nyckel"],"id":"k5qu5as3e"},{"q":"Vilka fyra faktorer avgör enligt boken hur lätt ett ämne tar sig genom cellmembranet?","o":["Laddning, storlek, form och fettlöslighet","Laddning, temperatur, pH och storlek","Storlek, färg, form och vikt","Fettlöslighet, energi, ATP och storlek"],"why":"Boken s. 31 och arbetsbladet: laddning, storlek, form och fettlöslighet.","src":"s. 31 · Arbetsblad","t":["membran"],"id":"k5q1tjn4jw"},{"q":"Vilket ämne passerar fosfolipidskiktet fritt?","o":["Koldioxid","Natriumjoner","Glukos","Vätejoner"],"why":"Koldioxid är liten, oladdad och hydrofob. Joner kommer inte igenom, och glukos mycket dåligt.","src":"s. 31","id":"k5q18tyheh"},{"q":"Varför kan vätejonen inte passera fosfolipidskiktet?","o":["Den omges av ett skal av vattenmolekyler","Den är för stor","Den är fettlöslig","Den bryts ner av membranet"],"why":"Joner attraherar vattenmolekyler och omges av ett vattenskal. Vätejonen är den minsta jonen, så storleken är inte problemet.","src":"s. 31","id":"k5qcln1qv"},{"q":"Vad kallas diffusion som sker genom ett cellmembran?","o":["Passiv transport","Aktiv transport","Exocytos","Kopplad transport"],"why":"Den kallas passiv eftersom den inte kostar cellen energi.","src":"s. 31 · PPT Transport bild 7","id":"k5qv8itil"},{"q":"Åt vilket håll sker diffusion?","o":["Från hög till låg koncentration","Från låg till hög koncentration","Alltid in i cellen","Alltid ut ur cellen"],"why":"Ämnet följer sin koncentrationsgradient, och därför krävs ingen energi.","src":"s. 31 · Arbetsblad","id":"k5q1q2zkeb"},{"q":"Vilket exempel på diffusion använder boken?","o":["En sockerbit i en kopp te","Grädde i kaffe","Bläck i vatten","Parfym i ett rum"],"why":"Boken använder sockerbiten i teet. Grädden i kaffet är lärarens exempel.","src":"s. 31 · PPT Transport bild 5","id":"k5q1de9z8c"},{"q":"Vad kallas proteinerna som bildar vattenfyllda kanaler i membranet?","o":["Kanalproteiner","Bärarproteiner","Proteinpumpar","Receptorer"],"why":"Kanalproteiner bildar vattenfyllda kanaler som vatten och joner kan ta sig igenom.","src":"s. 32","id":"k5qram5q7"},{"q":"Vilka sorters stimuli kan öppna och stänga kanalproteinerna?","o":["Kemiska, elektriska och mekaniska","Bara ATP","Ljus och värme","Bara att glukos binder"],"why":"Boken s. 32 och lärarens bild 9.","src":"s. 32 · PPT Transport bild 9","id":"k5q16rz1oo"},{"q":"Vad heter cellmembranets vattenkanaler?","o":["Aquaporiner","Jonkanaler","Bärarproteiner","Vesiklar"],"why":"Aquaporiner är vattenkanaler. Jonkanaler släpper igenom joner.","src":"s. 33 · Arbetsblad","t":["osmos"],"id":"k5q1g9mfal"},{"q":"Hur definierar boken osmos?","o":["Vattnets diffusion över ett semipermeabelt membran","Saltets diffusion över ett semipermeabelt membran","Vattnets aktiva transport genom membranet","Upptag av vätska med vesiklar"],"why":"Bokens definition på s. 33, samma i arbetsbladet.","src":"s. 33 · Arbetsblad","t":["osmos"],"id":"k5q5vqmd0"},{"q":"Vad betyder att en lösning är hyperton?","o":["Den har hög halt av lösta ämnen","Den har låg halt av lösta ämnen","Den har samma halt som cellen","Den är rent vatten"],"why":"Hyperton = hög halt av lösta ämnen, t.ex. stark saltlösning.","src":"s. 33","t":["osmos"],"id":"k5q1yq6n3y"},{"q":"Vad händer med en röd blodkropp i en stark saltlösning?","o":["Den krymper","Den sväller och spricker","Den påverkas inte","Den tar upp saltet och växer"],"why":"Vatten går från den högre vattenkoncentrationen inuti cellen till den lägre i saltlösningen.","src":"s. 33","t":["osmos"],"id":"k5q2rv1xo"},{"q":"Vad kräver aktiv transport enligt boken?","o":["Energi och ett membrantransportprotein som binder specifikt till ämnet","Bara energi","Bara en koncentrationsgradient","Vesiklar och receptorer"],"why":"Boken s. 34: både energi och ett specifikt membrantransportprotein.","src":"s. 34 · PPT Transport bild 15","t":["atp"],"id":"k5qs94uub"},{"q":"Vilka har proteinpumpar som drivs av solenergi?","o":["Vissa bakterier och arkéer","Alla djurceller","Röda blodkroppar","Svampar"],"why":"Boken s. 34. Läraren nämner inte solenergipumparna.","src":"s. 34","id":"k5q1vrpx9k"},{"q":"Hur många natriumjoner transporteras per glukosmolekyl i tarmen?","o":["Två","En","Tre","Fyra"],"why":"Bokens faktaruta: två natriumjoner per glukosmolekyl.","src":"s. 35","id":"k5qdlg1ui"},{"q":"Vem upptäckte den kopplade transporten av natrium och glukos i tarmceller?","o":["Robert K. Crane","Alexander Fleming","Louis Pasteur","Robert Koch"],"why":"Robert K. Crane (1919–2010).","src":"s. 35","id":"k5q1i1mk01"},{"q":"Vad ska vätskeersättningen vid diarré innehålla enligt boken?","o":["Salt (NaCl) och glukos","Bara rent vatten","Bara salt","Bara glukos"],"why":"Natrium tas upp kopplat till glukos, så båda måste finnas.","src":"s. 35","id":"k5q1wfwrv6"},{"q":"Vad bildas när ATP hydrolyseras och driver en proteinpump?","o":["ADP och ett fosfat","AMP och glukos","Glukos och syre","Kreatinfosfat"],"why":"ATP \"tappar\" ett fosfat och blir ADP, och energin överförs till pumpen.","src":"s. 35 · PPT Transport bild 16","t":["atp"],"id":"k5qdlr0su"},{"q":"Ungefär hur stor del av cellens ATP går till natrium-kaliumpumpen enligt boken?","o":["40 %","4 %","75 %","90 %"],"why":"Boken: ungefär 40 %. Läraren: 10–40 %.","src":"s. 35","t":["atp"],"id":"k5q1t6bkjd"},{"q":"Hur många joner flyttar natrium-kaliumpumpen per varv enligt läraren?","o":["3 Na⁺ ut och 2 K⁺ in","3 K⁺ ut och 2 Na⁺ in","2 Na⁺ ut och 3 K⁺ in","1 Na⁺ ut och 1 K⁺ in"],"why":"Lärarens bild 19: tre natriumjoner ut och två kaliumjoner in.","src":"PPT Transport bild 19","t":["atp"],"id":"k5q2h0adp"},{"q":"Vad betyder fagocytos?","o":["Cellätande","Celldrickande","Cellandning","Celldelning"],"why":"Pinocytos betyder celldrickande.","src":"s. 36 · Arbetsblad","id":"k5q1y4z9l7"},{"q":"Vad tas upp vid pinocytos enligt boken?","o":["Vattenlösliga makromolekyler","Hela bakterier","Syre och koldioxid","Joner genom kanaler"],"why":"Pinocytos (celldrickande) gäller vattenlösliga makromolekyler och kräver receptorer.","src":"s. 36","id":"k5q1vx6mfn"},{"q":"Vilken del av cellskelettet gör endocytos möjlig?","o":["Mikrofilamenten (aktin)","Mikrotubuli","Cellväggen","Intermediära filament"],"why":"Boken s. 36: mikrofilamenten i cytoskelettet (aktin).","src":"s. 36","id":"k5q4sk9o6"},{"q":"Vad står LDL för?","o":["Low density lipoprotein","Lipid dense lysosome","Low density lipid","Liver delivery lipoprotein"],"why":"LDL = low density lipoprotein, HDL = high density lipoprotein.","src":"s. 36","id":"k5q1l9j73v"},{"q":"Vart transporterar HDL överskottet av kolesterol?","o":["Till levern, där det bryts ner","Till kärlväggarna","Till tarmen","Till cellmembranen"],"why":"Boken s. 36. Därför kallas HDL lite slarvigt för det goda kolesterolet.","src":"s. 36","id":"k5q2zgya4"},{"q":"Hur vanligt är det att bära en felaktig LDL-receptorgen på sin ena kromosom?","o":["Mer än en person av tusen","En person av en miljon","Ungefär varannan person","Ungefär var tionde person"],"why":"Boken s. 36: mer än en person av tusen.","src":"s. 36","id":"k5qvbo1vo"},{"q":"Vad producerar membranblåsorna vid exocytos enligt boken?","o":["Golgiapparaten","Lysosomerna","Cellkärnan","Mitokondrierna"],"why":"Golgiapparaten producerar blåsorna, som sedan transporteras till cellmembranet.","src":"s. 37","id":"k5qraq1zz"},{"q":"Vilka tre typer av endocytos nämner läraren?","o":["Fagocytos, pinocytos och receptormedierad endocytos","Fagocytos, exocytos och osmos","Pinocytos, diffusion och osmos","Fagocytos, pinocytos och symport"],"why":"Lärarens bild 21. Boken nämner fagocytos och pinocytos.","src":"PPT Transport bild 21","id":"k5q13kld8b"},{"q":"Hur är cellmembranet laddat på lärarens bild 16?","o":["Positivt på utsidan och negativt på insidan","Negativt på utsidan och positivt på insidan","Oladdat på båda sidor","Positivt på båda sidor"],"why":"Bilden har + + + på utsidan och – – – på insidan.","src":"PPT Transport bild 16","id":"k5q1j6t8r4"},{"q":"Ungefär vilken spänning har hjärtmuskelcellen i vila på lärarens bild 20?","o":["−96 mV","+52 mV","0 mV","−200 mV"],"why":"Vila ca −96 mV, topp ca +52 mV.","src":"PPT Transport bild 20","id":"k5qa6lnjo"}],"u":[{"q":"En lösning har 400 mOsm/kg. Åt vilket håll går vattnet för en röd blodkropp i lösningen?","o":["Ut ur cellen, eftersom osmolaliteten är högre utanför","In i cellen, eftersom det finns mer vatten utanför","Inget, eftersom 400 är isotont","Ut, eftersom saltet tränger in"],"why":"Vatten går från låg till hög osmolalitet. Cellen har ca 280–295, och därför går vattnet ut.","src":"Film Osmos","t":["osmos"],"id":"k5q1c2l9h4"},{"q":"Varför spricker en växtcell inte i destillerat vatten, fast den röda blodkroppen gör det?","o":["Cellväggen håller emot turgortrycket","Växtcellen saknar akvaporiner","Vatten kan inte ta sig in i växtceller","Vakuolen pumpar ut vattnet med ATP"],"why":"Cellväggen tar emot trycket, och cellen blir turgid. Blodkroppen saknar vägg.","src":"Film Osmos","t":["osmos","vagg"],"id":"k5qkxms0b"},{"q":"Varför torkar bakterier ut i sylt?","o":["Sockret ger hög osmolalitet utanför bakterierna, och vatten lämnar dem","Sockret är giftigt för bakteriernas ribosomer","Sockret tränger in och spränger bakterierna","Sylten är för kall för bakterier"],"why":"Det är osmos. Vatten går mot hög osmolalitet, och bakteriernas celler krymper.","src":"Film Osmos","t":["osmos"],"id":"k5q1qgjta5"},{"q":"En person dricker 6 liter vatten på en timme. Vad är den största risken?","o":["Hypoton hyponatremi med hjärnödem","Hyperton hyponatremi med plasmolys","Uttorkning av hjärncellerna","Att blodkropparna krymper"],"why":"Plasman späds ut, osmolaliteten sjunker, vatten går in i cellerna och hjärnan sväller.","src":"Lektion","t":["osmos"],"id":"k5qx9ikr1"},{"q":"Varför blir man mer uttorkad av att dricka havsvatten?","o":["Blodets osmolalitet ökar och drar vatten ur cellerna, och njurarna behöver vatten för att få ut saltet","Havsvatten innehåller för lite salt","Havsvattnet tas inte upp alls i tarmen","Saltet förstör akvaporinerna"],"why":"Havsvatten (ca 1 000 mOsm/kg) är hypertont mot kroppen.","src":"Lektion","t":["osmos"],"id":"k5qa8qjnw"},{"q":"Varför är 0,9 % NaCl tekniskt svagt hyperton?","o":["154 mmol/L × 2 partiklar = 308 mOsmol/L, som är över 280–295","Den innehåller glukos","NaCl ger bara en partikel","Den har lägre osmolalitet än plasman"],"why":"Varje NaCl blir Na⁺ och Cl⁻. 308 ligger strax över normalzonen, men lösningen fungerar som isoton.","src":"Lektion","t":["osmos"],"id":"k5q1qfrioq"},{"q":"Vad har natrium-kaliumpumpen och vesikeltransport gemensamt enligt filmen?","o":["Båda kräver ATP","Båda går alltid mot gradienten","Båda flyttar bara joner","Båda sker genom öppna kanaler"],"why":"Pumpen använder ATP för att ändra form, och vesiklar kräver ATP för att bildas och flyttas.","src":"Film Aktiv transport","t":["atp"],"id":"k5q6q6bt6"},{"q":"Hur hittar en vesikel från golgi rätt mål?","o":["Dess markör passar i en receptor på målmembranet, som nyckel i lås","Den flyter slumpmässigt tills den spricker","Den dras dit av osmos","Kärnan skickar en elektrisk signal till den"],"why":"Adresslappen, protein eller kolhydratkedja, passar bara i rätt receptor.","src":"Film Aktiv transport","t":["nyckel"],"id":"k5q7od1o0"},{"q":"Steroidhormoner är stora molekyler. Varför tar de sig ändå lätt genom membranet?","o":["De är fettlösliga, och fosfolipidskiktet är fettlösligt","De är laddade","De använder aquaporiner","De pumpas in med ATP"],"why":"Fettlösligheten väger tyngst. Storlek är inte allt.","src":"s. 31","t":["membran"],"id":"k5qabbqkf"},{"q":"Syrehalten är 30 utanför en cell och 50 inuti. Vad händer med syret?","o":["Det diffunderar ut","Det diffunderar in","Det pumpas in med ATP","Ingenting, syre kan inte passera membranet"],"why":"Syre följer sin gradient, från hög (inuti) till låg (utanför).","src":"s. 32","id":"k5q1t2q2kq"},{"q":"Kaliumjoner strömmar ut genom en öppen kanal, från hög till låg koncentration. Vilken sorts transport är det?","o":["Underlättad diffusion","Aktiv transport","Osmos","Endocytos"],"why":"Ett protein hjälper, men transporten går med gradienten och kräver ingen energi.","src":"s. 32","id":"k5qoskz15"},{"q":"Varför följer inte saltjonerna med lika snabbt som vattnet vid osmos, enligt boken?","o":["Det finns färre jonkanaler än vattenkanaler","Saltjonerna är fettlösliga","Saltjonerna pumpas hela tiden ut","Vattnet blockerar jonkanalerna"],"why":"Boken s. 33. Läraren förklarar i stället att jonerna är för stora för porerna.","src":"s. 33","t":["osmos"],"id":"k5qthhh01"},{"q":"En röd blodkropp har krympt och ser taggig ut. Vilken sorts lösning ligger den i?","o":["Hyperton","Hypoton","Isoton","Destillerat vatten"],"why":"I en hyperton lösning är vattenkoncentrationen lägre utanför, så vatten går ut.","src":"s. 33","t":["osmos"],"id":"k5q67gehz"},{"q":"Varför spricker en röd blodkropp men inte en växtcell i destillerat vatten?","o":["Växtcellen har en cellvägg som håller emot","Växtcellen saknar aquaporiner","Blodkroppen pumpar in vatten med ATP","Växtcellen har ingen vakuol"],"why":"Vatten går in i båda genom osmos. Växtcellens cellvägg hindrar den från att spricka.","src":"s. 33 · s. 245","t":["osmos"],"id":"k5q11m6rxj"},{"q":"I lärarens bägarförsök finns mest löst ämne på högra sidan av membranet. Vad händer?","o":["Vätskenivån stiger på högra sidan","Vätskenivån stiger på vänstra sidan","Saltet flyttar till vänster","Ingenting händer"],"why":"Lösningsmedlet strömmar till den sida där det finns mest löst ämne.","src":"PPT Transport bild 13","t":["osmos"],"id":"k5qxf77xc"},{"q":"Vad skiljer ett bärarprotein från en proteinpump?","o":["Bärarproteinet går med gradienten utan energi, pumpen mot gradienten med ATP","Bärarproteinet använder ATP, pumpen inte","Pumpen ändrar aldrig form","Bärarproteinet transporterar bara vatten"],"why":"Båda binder ämnet, men bara pumpen arbetar mot gradienten.","src":"s. 32, 35","id":"k5qgcoahh"},{"q":"Glukos tas upp i tarmcellen mot sin gradient. Vad driver det?","o":["Natriumjonernas diffusion in i cellen","ATP som binds direkt till glukos","Osmos","Fagocytos"],"why":"Kopplad transport. Natrium går med sin gradient och drar med sig glukos.","src":"s. 34–35 · PPT Transport bild 18","id":"k5qfi00yi"},{"q":"Vad händer med glukosupptaget i tarmcellen om ATP tar slut?","o":["Det stannar när natriumgradienten jämnas ut","Det går snabbare","Det påverkas inte, eftersom kopplad transport inte använder ATP","Glukos börjar pumpas in direkt"],"why":"Utan ATP pumpas inget natrium ut. Utan koncentrationsgradient ingen diffusion.","src":"s. 34–35","t":["atp"],"id":"k5qay29tr"},{"q":"Varför kan natrium-kaliumpumpen arbeta även när det redan finns mycket Na⁺ utanför cellen?","o":["Den får energin direkt från ATP och fungerar oberoende av gradienter","Na⁺ diffunderar alltid ut","Den använder glukosets gradient","Membranet är fettlösligt"],"why":"Den stora fördelen med ATP-drivna pumpar är att de fungerar oberoende av koncentrationsgradienter.","src":"s. 35","t":["atp"],"id":"k5q1t8n0lc"},{"q":"Na⁺ och glukos går in i tarmcellen genom samma transportör. Vad kallar läraren det?","o":["Symport","Antiport","Osmos","Pinocytos"],"why":"Symport = samma håll. Antiport = motsatta håll, som Na⁺ ut och K⁺ in.","src":"PPT Transport bild 18","id":"k5q1v5plks"},{"q":"Hur bidrar natrium-kaliumpumpen till att insidan av cellen blir negativ?","o":["Den flyttar ut tre positiva joner för varje två den tar in","Den pumpar in kloridjoner","Den pumpar ut elektroner","Den tar in tre Na⁺ för varje två K⁺ den pumpar ut"],"why":"3 Na⁺ ut och 2 K⁺ in ger en positiv laddning mer utanför per varv.","src":"PPT Transport bild 16, 19","t":["atp"],"id":"k5q1n5waaj"},{"q":"Varför rusar spänningen upp i aktionspotentialens fas 0?","o":["Na⁺ strömmar in, och insidan får mer positiv laddning","K⁺ strömmar in","Ca²⁺ strömmar ut","Natrium-kaliumpumpen stannar"],"why":"Lärarens bild 20: fas 0 = Na⁺ in. Fas 3 = K⁺ ut, då faller spänningen.","src":"PPT Transport bild 20","id":"k5qy3ctn1"},{"q":"Digoxin hämmar natrium-kaliumpumpen. Vad händer först i cellen?","o":["Natriumhalten inne i cellen ökar","Kaliumhalten inne i cellen ökar","Cellen får mer ATP","Insidan blir positiv i vila"],"why":"Pumpen för inte längre ut Na⁺. Sedan kan Na⁺/Ca²⁺-pumpen inte fungera, och kontraktionskraften ökar.","src":"PPT Transport bild 16","id":"k5q9hj2oz"},{"q":"Vid fagocytos smälter membranarmarna samman runt bakterien. Vilken egenskap hos membranet gör det möjligt?","o":["Det är som en trögflytande vätska","Det är stelt som en vägg","Det består av cellulosa","Det saknar fosfolipider"],"why":"Boken s. 36: cellmembranet går att jämföra med en trögflytande vätska.","src":"s. 36","t":["membran"],"id":"k5qr7f9wr"},{"q":"En person har felaktig LDL-receptorgen på båda homologa kromosomerna. Vad är troligast?","o":["Extremt höga LDL-halter och tidig hjärt-kärlsjukdom","Normala LDL-halter","Låga LDL-halter","Ingen effekt förrän i hög ålder"],"why":"Två felaktiga gener ger extremt höga halter, och man avlider ofta tidigt. En felaktig gen ger mycket höga halter.","src":"s. 36","id":"k5qhnn4ab"},{"q":"Varför stiger LDL i blodet när LDL-receptorn är felaktig?","o":["LDL tas inte upp i cellerna via endocytos","Levern bildar mer LDL","HDL förstör LDL-partiklarna","LDL kan inte lösas i blodet"],"why":"Receptorn behövs för att ta upp LDL via endocytos.","src":"s. 36","t":["nyckel"],"id":"k5qqp02yi"},{"q":"En cell gör mycket exocytos men ingen endocytos. Vad händer med cellmembranet?","o":["Det får fler fosfolipider, och cellen skulle växa","Det krymper","Ingenting","Det förlorar alla sina proteiner"],"why":"Exocytos tillför fosfolipider. Normalt tar endocytos bort lika mycket.","src":"s. 37","t":["membran"],"id":"k5q16jewph"},{"q":"Hur släpps insulin ut från cellerna i bukspottkörteln?","o":["Med exocytos","Med endocytos","Med osmos","Med kopplad transport"],"why":"Insulinet lagras i sekretoriska blåsor och släpps ut med exocytos vid behov.","src":"s. 37","id":"k5q3o5ouo"}],"o":[{"q":"Förklara vad osmolalitet är och använd begreppet för att förklara varför fysiologisk koksaltlösning används i dropp men aldrig rent vatten.","model":"Osmolalitet är antalet osmotiskt aktiva partiklar per kilogram lösningsmedel. Partiklarna binder vatten, och därför går nettoflödet av vatten från låg till hög osmolalitet. Blodplasman och cellerna har ca 280–295 mOsm/kg. Fysiologisk koksaltlösning är 0,9 % NaCl = 9 g/L = 154 mmol/L, och varje NaCl ger två partiklar, alltså 308 mOsmol/L. Den är funktionellt isoton, och därför sväller eller krymper blodkropparna inte. Rent vatten saknar partiklar och är hypotont. Vatten skulle strömma in i blodkropparna, som saknar cellvägg, och de skulle spricka (hemolys). Det kan också ge hjärnödem.","kw":[["partik"],["låg","hög"],["280","295"],["308","154"],["isoton"],["hemolys","spricker","hjärnödem"]],"src":"Film Osmos · Lektion","t":["osmos"],"id":"k5oj7k0nj"},{"q":"Beskriv de två huvudtyperna av aktiv transport enligt filmen och förklara varför båda kräver ATP. Ge ett exempel på varje.","model":"Proteinpumpar är bärarproteiner som flyttar joner och små molekyler mot koncentrationsgradienten, till exempel natrium-kaliumpumpen som tar ut 3 Na⁺ och in 2 K⁺. ATP spjälkas, och fosfatgruppen binds till pumpen så att den ändrar form. Vesikeltransport är endocytos och exocytos, som flyttar stora molekyler och partiklar, till exempel signalämne i synapsen eller coronaviruset som tas in via ACE2. Den kan gå med eller mot gradienten, men ATP krävs för att omforma membranet och för motorproteiner som flyttar vesiklarna längs mikrotubuli.","kw":[["pump"],["vesik"],["gradient"],["atp"],["fosfat","form"],["motorprotein","mikrotubuli","membranet"]],"src":"Film Aktiv transport","t":["atp"],"id":"k5o1hqryue"},{"q":"Förklara vad som händer med en röd blodkropp i destillerat vatten, i en isoton lösning och i en stark saltlösning. Använd begreppen osmos och vattenkoncentration.","model":"Osmos är vattnets diffusion över ett semipermeabelt membran. En lösning med mycket löst ämne har lägre vattenkoncentration, eftersom det lösta ämnet tar vattnets plats. Destillerat vatten är hypotont och har högre vattenkoncentration än cellen, så vatten diffunderar in och blodkroppen sväller och kan spricka. En isoton lösning har samma halt lösta ämnen som cytoplasman, så lika mycket vatten går in som ut och cellen påverkas inte. En stark saltlösning är hyperton och har lägre vattenkoncentration, så vatten går ut och cellen krymper. Saltet följer inte med lika snabbt, eftersom det finns färre jonkanaler än vattenkanaler.","kw":[["osmos"],["vattenkoncentration","vattenpotential"],["sväll","spricker","sprängs"],["krymp"],["isoton","samma"],["hypoton","hyperton"]],"src":"s. 33","t":["osmos"],"id":"k5o1ux9d43"},{"q":"Förklara skillnaden mellan diffusion, underlättad diffusion och aktiv transport.","model":"Vid diffusion rör sig ett ämne från hög till låg koncentration, med sin koncentrationsgradient, och det kräver ingen energi. Små, oladdade, hydrofoba ämnen som syre diffunderar rakt genom fosfolipidskiktet. Vid underlättad diffusion går ämnet också med sin gradient utan energi, men det behöver hjälp av kanalproteiner eller bärarproteiner, eftersom det är laddat eller polärt. Vid aktiv transport flyttas ämnet mot sin gradient, från låg till hög koncentration. Det kräver energi och ett specifikt membrantransportprotein, och det sker med ATP-drivna pumpar eller kopplad transport.","kw":[["hög","låg"],["gradient"],["energi"],["kanal","bärar"],["mot"],["pump","atp"]],"src":"s. 31–35","id":"k5o1u0w4c9"},{"q":"Förklara hur glukos tas upp i tarmen genom kopplad transport och varför vätskeersättning vid diarré innehåller både salt och glukos.","model":"Natrium-kaliumpumpen använder ATP för att pumpa ut natrium ur tarmcellerna, och därför blir natriumhalten låg inne i cellen. Natriumjonerna diffunderar sedan in med sin gradient genom ett transportprotein, och de tar med sig glukos, två Na⁺ per glukos. Glukos går då mot sin egen gradient. Kopplad transport kräver alltså ATP indirekt. Vid diarré hinner natriumjonerna inte reabsorberas, och förlusten stör kroppens jonbalans och kan leda till döden. Eftersom natrium tas upp tillsammans med glukos måste drycken innehålla både salt och glukos. Det upptäckte Robert K. Crane.","kw":[["natrium","na"],["glukos"],["gradient"],["atp"],["två","2"],["diarr","jonbalans","uttork"]],"src":"s. 34–35 · PPT Transport bild 18","t":["atp"],"id":"k5ozztr9y"},{"q":"Beskriv hur en vit blodkropp tar upp en bakterie och vad som händer med bakterien sedan.","model":"Det kallas fagocytos, cellätande, och det är en sorts endocytos som kräver energi. En receptor på den vita blodkroppen binder bakterien. Cellmembranet buktar ut så att två armar bildas, och armarna sluter sig runt bakterien. Eftersom membranet är som en trögflytande vätska smälter armarna samman, och en membranbubbla bildas som förs in i cellen. Mikrofilament (aktin) gör rörelsen möjlig. Vesikeln smälter sedan ihop med lysosomer, och deras enzymer bryter ner bakterien.","kw":[["receptor"],["arm","pseudopod"],["trögflyt","vätska","smälter"],["vesikel","bubbla","fagosom"],["lysosom"],["enzym","bryter ner"]],"src":"s. 36","id":"k5o1sgwyhs"},{"q":"Förklara vad LDL och HDL är och vad som händer när genen för LDL-receptorn är felaktig.","model":"Kolesterol transporteras i blodet i små partiklar där kolesterol och protein bildar en vattenlöslig enhet. LDL (low density lipoprotein) har mer kolesterol i förhållande till protein, kolesterolet släpper lättare, och höga halter ger ökad risk för hjärt-kärlsjukdom. HDL (high density lipoprotein) för överskott av kolesterol från vävnaderna till levern, där det bryts ner. LDL tas upp i cellerna via endocytos med hjälp av LDL-receptorn. Är genen för receptorn felaktig på en kromosom blir LDL-halten mycket hög, och på båda extremt hög. Båda generna påverkar, och därför är sjukdomen kodominant. Mer än en av tusen bär genen, och risken kan minskas med kolesterolfattig mat, motion och medicin.","kw":[["partik"],["protein"],["lever"],["receptor"],["endocytos"],["kodominant"]],"src":"s. 36","t":["nyckel"],"id":"k5omneexx"},{"q":"Förklara hur exocytos går till och varför cellmembranet ändå inte växer hela tiden.","model":"Exocytos betyder ut ur cellen. Golgiapparaten producerar membranblåsor med innehållet, och de transporteras till cellmembranet. När en blåsa får kontakt med cellmembranet blandar sig fosfolipiderna, membranen smälter ihop och innehållet släpps ut. På så sätt får cellmembranet ett tillskott av fosfolipider, och cellen skulle växa. Vid endocytos försvinner i stället fosfolipider från membranet till den nya blåsan. De två processerna tar alltså ut varandra.","kw":[["golgi"],["blåsa","vesikel"],["smälter","blandar"],["fosfolipid"],["endocytos"],["tar ut","varandra","balans"]],"src":"s. 37","t":["membran"],"id":"k5o1ks39tk"}]},"kan":[{"q":"Kan du förklara hur en akvaporin fungerar och varför bara vatten kommer igenom?","a":"En akvaporin är en proteinkanal i cellmembranet. Inuti sitter aminosyror med positivt laddade sidogrupper som drar till sig vattnets partiellt negativa syreatom. Därför vänds vattenmolekylerna rätt och passerar i en enda rad. Laddningen bildar också en barriär mot protoner, och därför bevaras cellens elektriska balans.","kw":[["protein","kanal"],["positiv","laddad"],["syre","negativ"],["rad"],["proton","h+","h⁺"]],"src":"Film Osmos","id":"k5k1algpki"},{"q":"Kan du förklara varför fysiologisk koksaltlösning är 0,9 % och vad det blir i mOsmol/L?","a":"0,9 % NaCl är 9 g per liter, vilket blir 154 mmol/L Na⁺. Varje NaCl ger två partiklar, Na⁺ och Cl⁻, och därför blir det 308 mOsmol/L. Det är funktionellt isotont med blodplasman (280–295), och därför sväller eller krymper blodkropparna inte. Man kom fram till 0,9 % på 1800-talet genom att testa vilken halt som bevarade blodkropparnas form bäst.","kw":[["9 g","9g"],["154"],["308"],["två","2"],["isoton"]],"src":"Lektion","id":"k5kunpw3o"},{"q":"Kan du förklara varför det är farligt att dricka mycket vatten på kort tid?","a":"Kroppen klarar normalt 2–3 liter per dag. Dricker man mer än 3–4 liter på kort tid hinner njurarna inte med, och blodplasman späds ut. Osmolaliteten och natriumhalten blir låga (hypoton hyponatremi), och därför går vatten in i cellerna genom osmos. I hjärnan ger det hjärnödem, trycket i skallen stiger och hjärnstammen kan pressas ner.","kw":[["njur"],["späd"],["hyponatremi","natrium"],["osmos","in i cellerna"],["hjärnödem","ödem"]],"src":"Lektion","id":"k5kjk0ry5"},{"q":"Kan du nämna de fyra faktorer som avgör hur lätt ett ämne tar sig igenom cellmembranet, och förklara varför syre kommer igenom men inte natriumjoner?","a":"Laddning, storlek, form och fettlöslighet avgör. Syre är litet, oladdat och hydrofobt, och fosfolipidskiktet är fettlösligt, och därför passerar syre fritt. Natriumjoner är laddade och hydrofila. De attraherar vattenmolekyler och omges av ett vattenskal, och därför har de inte fri passage. Inte ens vätejonen, den minsta jonen, kommer igenom.","kw":[["laddning"],["storlek"],["form"],["fettlös","hydrofob"],["vattenskal","skal av vatten","hydrofil"]],"src":"s. 31","id":"k5k195nmuo"},{"q":"Kan du förklara diffusion med sockerbiten i teet och backen?","a":"Partiklar är i ständig, slumpmässig rörelse. Trots det har transporten av socker totalt sett en riktning, från hög koncentration i sockerbiten till låg i teet, tills sockret är jämnt fördelat. Sockret följer koncentrationsgradienten. Gradienten är som en nedförsbacke med potentiell energi (lägesenergi), och därför kräver diffusionen ingen energi. Sker diffusionen genom ett cellmembran kallas den passiv transport.","kw":[["slump"],["hög"],["låg"],["koncentrationsgradient","gradient"],["energi"],["passiv"]],"src":"s. 31","id":"k5k1jcdq5f"},{"q":"Kan du förklara hur en cell \"andas\"?","a":"Syre och koldioxid har fri passage genom membranet. Så länge syrehalten är högre utanför cellen än inuti diffunderar syre in, och så länge koldioxidhalten är högre inuti än utanför diffunderar koldioxid ut. Båda följer sin egen koncentrationsgradient, och det kostar ingen energi.","kw":[["syre","o2","o₂"],["koldioxid","co2","co₂"],["högre"],["diffunder"],["egen","gradient"]],"src":"s. 32 · PPT Transport bild 7","id":"k5k17vyv71"},{"q":"Kan du förklara underlättad diffusion och jämföra kanalproteiner med bärarproteiner?","a":"Ämnen som inte kan ta sig genom fosfolipidlagret kan ändå diffundera med sin gradient med hjälp av proteiner i membranet. Kanalproteiner bildar vattenfyllda kanaler som vatten och joner med rätt storlek, form och laddning kan slinka igenom. De öppnas och stängs av kemiska, elektriska eller mekaniska stimuli, och jonkanaler släpper bara igenom en viss jon. Bärarproteiner binder ett visst ämne, t.ex. glukos, och ändrar form. Båda är specifika och kräver ingen energi, eftersom det är diffusion.","kw":[["kanal"],["bärar"],["ändrar form","form"],["stimul","kemisk","elektrisk","mekanisk"],["energi"],["specifik","glukos"]],"src":"s. 32","id":"k5kvu62l0"},{"q":"Kan du definiera osmos och förklara varför vatten behöver aquaporiner?","a":"Osmos är vattnets diffusion över ett semipermeabelt membran. Vattenmolekylen är polär och har därför svårt att ta sig genom fosfolipidskiktet. Aquaporiner är vattenkanaler som vattnet kan diffundera genom. En cell har många fler vattenkanaler än jonkanaler och bärarproteiner, och därför rör sig vatten mycket lättare än andra ämnen.","kw":[["osmos"],["vatten"],["semipermeab","halvgenom"],["aquaporin","akvaporin","vattenkanal"],["polär"]],"src":"s. 33","t":["osmos"],"id":"k5k155psgc"},{"q":"Kan du förklara vad som händer med en röd blodkropp i en hypoton, isoton och hyperton lösning?","a":"I en hypoton lösning, t.ex. destillerat vatten, är vattenkoncentrationen högre utanför, så vatten diffunderar in och cellen sväller och kan spricka. I en isoton lösning är halten lösta ämnen densamma som i cellen, så lika mycket vatten går in som ut och cellen påverkas inte. I en hyperton lösning, t.ex. stark saltlösning, är vattenkoncentrationen lägre utanför, så vatten går ut och cellen krymper. Saltet följer inte med lika snabbt, eftersom det finns färre jonkanaler än vattenkanaler.","kw":[["hypoton"],["isoton"],["hyperton"],["sväll","spricker","sprängs"],["krymp"],["vattenkoncentration","vattenpotential"]],"src":"s. 33","t":["osmos"],"id":"k5kvy4dd2"},{"q":"Kan du definiera aktiv transport och säga vad den kräver och hur den kan ske?","a":"Aktiv transport är transport över ett cellmembran mot koncentrationsgradienten, från lägre till högre koncentration, som att rulla något uppför en backe. Den kräver energi och ett membrantransportprotein som binder specifikt till ämnet. Den sker genom kopplad transport eller ATP-drivna proteinpumpar. Vissa bakterier och arkéer har dessutom pumpar som drivs av solenergi.","kw":[["mot"],["låg","lägre"],["energi"],["protein"],["kopplad"],["pump"]],"src":"s. 34","t":["atp"],"id":"k5k3wxq2o"},{"q":"Kan du förklara kopplad transport med vattenfallet och varför den kräver ATP indirekt?","a":"Vid kopplad transport kopplas transporten av ett ämne mot sin gradient till ett annat ämne som diffunderar med sin gradient. Det är som ett vattenfall där det fallande vattnet driver ett hjul som lyfter något uppför. Gradienten för det diffunderande ämnet, vanligen natrium- eller vätejoner, måste upprätthållas, och därför måste ämnet pumpas tillbaka med ATP. Utan gradient ingen diffusion.","kw":[["vattenfall","hjul"],["gradient"],["diffunder"],["atp"],["indirekt","pumpas tillbaka","upprätthåll"],["natrium","na"]],"src":"s. 34–35","t":["atp"],"id":"k5kze8git"},{"q":"Kan du förklara hur en ATP-driven proteinpump fungerar och vad natrium-kaliumpumpen gör?","a":"ATP hydrolyseras till ADP och tappar ett fosfat. Energin som frigörs överförs till pumpen, så att ämnet som binder kan föras till andra sidan, mot sin gradient. Fördelen är att pumpen fungerar oberoende av gradienter. Natrium-kaliumpumpen upprätthåller jonbalansen och använder ungefär 40 % av cellens ATP. Enligt läraren pumpar den ut tre Na⁺ och in två K⁺ per ATP.","kw":[["atp"],["adp","fosfat","hydrolys"],["energi"],["oberoende"],["40"],["jonbalans","natrium","kalium"]],"src":"s. 35 · PPT Transport bild 19","t":["atp"],"id":"k5k1f3x8ui"},{"q":"Kan du jämföra fagocytos och pinocytos?","a":"Båda är endocytos, där delar av cellmembranet omsluter det som ska tas upp, med hjälp av mikrofilament (aktin), och båda kräver energi och receptorer. Fagocytos betyder cellätande. Stora partiklar, till och med hela celler, tas upp när membranet buktar ut i två armar som sluter sig, t.ex. när vita blodkroppar slukar bakterier. Pinocytos betyder celldrickande. Vattenlösliga makromolekyler binder till receptorer, membranet buktar in och bubblan snörs av.","kw":[["fagocytos"],["pinocytos"],["cellätande","stora partiklar","bakterie"],["celldrickande","makromolekyl"],["receptor"],["arm","bukta"]],"src":"s. 36","id":"k5k1wva6ts"},{"q":"Kan du förklara LDL och HDL och vad som händer när genen för LDL-receptorn är felaktig?","a":"Kolesterol transporteras i blodet i vattenlösliga partiklar av kolesterol och protein. LDL har mer kolesterol i förhållande till protein och släpper kolesterolet lättare, och höga halter ger ökad risk för hjärt-kärlsjukdom. HDL för överskott av kolesterol till levern, där det bryts ner. LDL tas upp i cellerna via endocytos med hjälp av LDL-receptorn. Är genen för receptorn felaktig på en kromosom blir halterna mycket höga, och på båda extremt höga. Därför är sjukdomen kodominant.","kw":[["partik"],["protein"],["lever"],["receptor"],["endocytos"],["kodominant"]],"src":"s. 36","t":["nyckel"],"id":"k5k1l8szog"},{"q":"Kan du förklara exocytos och varför cellmembranet inte växer hela tiden?","a":"Exocytos betyder ut ur cellen. Golgiapparaten producerar membranblåsor, som transporteras till cellmembranet. Där blandas fosfolipiderna, membranen smälter ihop och innehållet släpps ut. Exocytos tillför alltså fosfolipider till membranet, men vid endocytos försvinner fosfolipider, och därför tar processerna ut varandra. Sekretoriska celler, t.ex. insulinceller i bukspottkörteln och nervceller med synapsblåsor, lagrar ämnen i blåsor och släpper ut dem vid behov.","kw":[["golgi"],["blåsa","vesikel"],["smälter","fosfolipid"],["endocytos"],["tar ut","varandra","balans"],["insulin","synaps","sekretor"]],"src":"s. 37","t":["membran"],"id":"k5kkij86d"}],"kompis":[{"q":"Förklara för en kompis hur natrium-kaliumpumpen går ett helt varv enligt filmen.","model":"Pumpen är ett bärarprotein. Först är den öppen inåt, och tre Na⁺ binder. ATP spjälkas, och fosfatgruppen binds till pumpen. Då ändrar pumpen form och öppnas utåt, och Na⁺ släpps ut. Två K⁺ binder från utsidan. Fosfatet släpper, pumpen ändrar form tillbaka och K⁺ släpps in. Båda jonerna flyttas mot sina gradienter, och därför krävs ATP.","kw":[["3","tre"],["2","två"],["atp"],["fosfat"],["form"],["gradient"]],"src":"Film Aktiv transport","id":"k5e1pa4mbb"},{"q":"Förklara för en kompis hur natrium-kaliumpumpen och den kopplade transporten av glukos i tarmen hänger ihop.","model":"Natrium-kaliumpumpen använder ATP för att pumpa ut natriumjoner ur tarmcellen, och därför blir det mycket Na⁺ ute och lite inne. Det är som att pumpa upp vatten till toppen av ett vattenfall. Natriumjonerna vill sedan diffundera tillbaka in, med sin gradient. Ett transportprotein tar in två Na⁺ och en glukos samtidigt, så glukoset dras med in mot sin egen gradient. Utan ATP stannar pumpen, gradienten jämnas ut och glukostransporten stannar. Därför kräver kopplad transport ATP indirekt.","kw":[["atp"],["pump"],["natrium","na"],["glukos"],["gradient"],["indirekt","stannar","vattenfall"]],"src":"s. 34–35 · PPT Transport bild 18","id":"k5e1b8uvfp"},{"q":"Förklara för en kompis varför joner inte kan diffundera rakt genom cellmembranet och hur de ändå tar sig över.","model":"Cellmembranets inre består av fosfolipidernas hydrofoba svansar och är fettlösligt. Joner är laddade och attraherar vattenmolekyler, så de omges av ett vattenskal och är hydrofila. Därför kommer de inte igenom fosfolipidskiktet, inte ens den lilla vätejonen. Med sin gradient tar de sig i stället genom jonkanaler, vattenfyllda kanalproteiner som öppnas av kemiska, elektriska eller mekaniska signaler. Mot sin gradient flyttas de av pumpar som drivs av ATP, som natrium-kaliumpumpen.","kw":[["laddad","hydrofil"],["vattenskal","skal"],["fettlös","hydrofob"],["jonkanal","kanal"],["pump"],["atp"]],"src":"s. 31–35","id":"k5e1p7zl6k"},{"q":"Förklara för en kompis hur receptorer används när celler tar upp ämnen med endocytos, med LDL som exempel.","model":"Vissa ämnen är för stora för transportproteinerna. Då binder de till receptorer på cellmembranet, som en nyckel i ett lås. Membranet buktar in där receptorerna bundit sina molekyler, och ju fler som binder, desto mer buktar det in. Till sist snörs bubblan av och förs in i cellen. Så tas LDL-partiklarna med kolesterol upp från blodet. Om genen för LDL-receptorn är felaktig tas LDL inte upp, och LDL-halten i blodet blir hög.","kw":[["receptor"],["binder","nyckel"],["bukta"],["snörs","vesikel","bubbla"],["ldl"],["gen","felaktig"]],"src":"s. 36","t":["nyckel"],"id":"k5e116pik8"},{"q":"Förklara för en kompis vad lärarens kurva över hjärtmuskelcellens aktionspotential visar.","model":"Kurvan visar spänningen över cellmembranet i millivolt över tid. I vila, fas 4, är insidan negativ, ungefär −96 mV. I fas 0 strömmar Na⁺ in och spänningen rusar upp till ungefär +52 mV. Fas 1 är en kort topp med utåtriktad ström av K⁺ och Cl⁻. I fas 2 håller Ca²⁺ som strömmar in och K⁺ som strömmar ut en platå. I fas 3 strömmar K⁺ ut och spänningen faller tillbaka. Från fas 0 till slutet av fas 3 tar det ungefär 200 ms.","kw":[["mv","spänning"],["vila","-96","−96"],["na"],["ca"],["k"],["200"]],"src":"PPT Transport bild 20","id":"k5e1s61k2f"}],"gloss":[{"w":"Akvaporin","d":"Filmens stavning av aquaporin. Proteinkanal som bara släpper igenom vatten. Positiva laddningar inuti vänder vattnet rätt och stoppar protoner.","src":"Film Osmos","lek":1},{"w":"Osmolalitet","d":"Antalet osmotiskt aktiva partiklar per kilogram lösningsmedel (osmol/kg, mOsm/kg). Isotont med blodplasma: ca 280–295 mOsm/kg.","src":"Film Osmos","lek":1},{"w":"Osmolaritet","d":"Antalet osmotiskt aktiva partiklar per liter lösning (mOsm/L). Används ofta i sjukvården.","src":"Film Osmos","lek":1},{"w":"Osmotiskt aktiva partiklar","d":"Ämnen som drar till sig och binder vatten, t.ex. sockermolekyler och saltjoner. De minskar antalet fria vattenmolekyler.","src":"Film Osmos","lek":1},{"w":"Plasmolys","d":"När en växtcell i en hyperton lösning förlorar vatten och cellmembranet drar sig bort från cellväggen. Växten slokar.","src":"Film Osmos","lek":1},{"w":"Turgid","d":"Spänd. En växtcell i hypoton lösning med högt turgortryck. Spricker inte tack vare cellväggen.","src":"Film Osmos","lek":1},{"w":"Flaccid","d":"Slapp. En växtcell i isoton lösning, i balans.","src":"Film Osmos","lek":1},{"w":"Hemolys","d":"När röda blodkroppar sväller och spricker i en hypoton lösning, eftersom de saknar cellvägg.","src":"Film Osmos","lek":1},{"w":"Konservering","d":"Att bevara livsmedel så att de håller längre, t.ex. genom saltning, sockring, torkning, kylning eller pastörisering.","src":"Film Osmos","lek":1},{"w":"Hyponatremi","d":"Låg natriumkoncentration i blodplasman. Hypoton hyponatremi (låg osmolalitet) är vanligast och kan ge hjärnödem. Hyperton hyponatremi har hög osmolalitet.","src":"Lektion","lek":1},{"w":"Hjärnödem","d":"Svullnad av hjärnan när cellerna tar upp vatten. Trycket i skallen stiger, blodflödet minskar och hjärnstammen kan pressas ner.","src":"Lektion","lek":1},{"w":"Intrakraniellt tryck","d":"Trycket inne i skallen. Stiger vid hjärnödem, eftersom kraniet är hårt och utrymmet begränsat.","src":"Lektion","lek":1},{"w":"Fysiologisk koksaltlösning","d":"0,9 % NaCl = 9 g/L = 154 mmol/L Na⁺ = 308 mOsmol/L. Funktionellt isoton, vanligaste droppet.","src":"Lektion","lek":1},{"w":"Ringer-Acetat","d":"Vätskeersättning med buffrande ämnen som stabiliserar pH. Bättre vid stora vätskeförluster, kirurgi och långa infusioner.","src":"Lektion","lek":1},{"w":"Motorproteiner","d":"Proteiner som drar vesiklar längs cellskelettets filament, t.ex. mikrotubuli, och använder ATP.","src":"Film Aktiv transport","lek":1},{"w":"Adresslapp (vesikel)","d":"Kemisk markör, protein eller kolhydratkedja, som vesikeln får i ER eller golgi. Passar som nyckel i receptorn på rätt målmembran.","src":"Film Aktiv transport","lek":1},{"w":"Synapsklyfta","d":"Mellanrummet mellan nervänden och nästa cell. Signalämnet går över den efter exocytos.","src":"Film Aktiv transport","lek":1},{"w":"Receptorförmedlad endocytos","d":"Filmens namn på receptormedierad endocytos. Specifik: molekylerna binder till receptorer innan membranet veckas in, t.ex. LDL.","src":"Film Aktiv transport","lek":1},{"w":"ACE2","d":"Receptor på cellytan som SARS-CoV-2 binder till innan det tas in med endocytos.","src":"Film Aktiv transport","lek":1},{"w":"SARS-CoV-2","d":"Coronaviruset som orsakar covid-19. Tar sig in i celler främst via endocytos.","src":"Film Aktiv transport","lek":1},{"w":"Aktionspotential","d":"Den snabba ändringen av spänningen över cellmembranet när t.ex. en hjärtmuskelcell aktiveras (lärarens kurva: −96 mV till +52 mV, ca 200 ms).","src":"PPT Transport bild 20","lek":1},{"w":"Aktiv transport","d":"Transport över ett cellmembran mot koncentrationsgradienten, från lägre till högre koncentration. Kräver energi och ett membrantransportprotein.","src":"Bok s. 34"},{"w":"ADP","d":"Adenosindifosfat. Bildas när ATP hydrolyseras och \"tappar\" ett fosfat.","src":"Bok s. 35"},{"w":"Antiport","d":"Två ämnen transporteras åt motsatta håll, t.ex. Na⁺ ut och K⁺ in.","src":"PPT Transport bild 18","lek":1},{"w":"Aquaporin","d":"Vattenkanal i cellmembranet, som vattenmolekyler kan diffundera genom.","src":"Bok s. 33"},{"w":"ATP","d":"Adenosintrifosfat, cellens energivaluta. När ATP hydrolyseras till ADP frigörs energi.","src":"Bok s. 35 · PPT Transport bild 19"},{"w":"ATP-driven proteinpump","d":"Protein som pumpar ämnen mot deras gradient med energi från ATP. Fungerar oberoende av koncentrationsgradienter.","src":"Bok s. 35"},{"w":"Bärarprotein","d":"Transportprotein som binder ett visst ämne, t.ex. glukos, och ändrar form så att ämnet förs genom membranet. Passivt.","src":"Bok s. 32"},{"w":"Co-transport","d":"Annat namn för kopplad transport.","src":"Bok s. 34"},{"w":"Diffusion","d":"Transport från hög till låg koncentration, längs koncentrationsgradienten. Kräver ingen energi.","src":"Bok s. 31"},{"w":"Digoxin","d":"Hjärtläkemedel som hämmar natrium-kaliumpumpen, vilket ökar hjärtmuskelns kontraktionskraft.","src":"PPT Transport bild 16","lek":1},{"w":"Elektrokemisk gradient","d":"Koncentrationsskillnaden och laddningsskillnaden över membranet tillsammans. Styr hur joner rör sig.","src":"PPT Transport bild 16","lek":1},{"w":"Endocytos","d":"Upptag i cellen med membranblåsor. Kräver energi.","src":"Bok s. 35"},{"w":"Exocytos","d":"\"Ut ur cellen\". Utsöndring med membranblåsor som smälter ihop med cellmembranet. Kräver energi.","src":"Bok s. 35, 37"},{"w":"Faciliterad diffusion","d":"Lärarens ord för underlättad diffusion.","src":"PPT Transport bild 8","lek":1},{"w":"Fagocyt","d":"Vit blodkropp i immunsystemet som tar upp t.ex. bakterier genom fagocytos.","src":"Bok s. 36"},{"w":"Fagocytos","d":"\"Cellätande\". Endocytos av stora partiklar, till och med hela celler. Membranet bildar armar som sluter sig.","src":"Bok s. 36"},{"w":"Fagosom","d":"Membranbubblan (näringsvakuolen) som bildas runt partikeln vid fagocytos.","src":"PPT Transport bild 23","lek":1},{"w":"Fettlöslighet","d":"Hur lätt ett ämne löser sig i fett. Fettlösliga (hydrofoba) ämnen tar sig lätt genom fosfolipidskiktet.","src":"Bok s. 31"},{"w":"Fosfolipidskikt","d":"Cellmembranets dubbla lager av fosfolipider. Det är fettlösligt inuti.","src":"Bok s. 31"},{"w":"Glykolipid","d":"Lipid med socker på.","src":"PPT Transport bild 9","lek":1},{"w":"Glykoprotein","d":"Protein med socker på. Förs ut med exocytos för att bygga cellmembran och ECM.","src":"Bok s. 37 · PPT Transport bild 9"},{"w":"HDL","d":"High density lipoprotein. Partikel som för överskott av kolesterol från vävnaderna till levern. Kallas lite slarvigt \"det goda kolesterolet\".","src":"Bok s. 36"},{"w":"Hydrofil","d":"Vattenälskande. Hydrofila ämnen, t.ex. joner, har svårt att passera membranet.","src":"Bok s. 31"},{"w":"Hydrofob","d":"Vattenskyende och fettlöslig. Hydrofoba ämnen, t.ex. O₂ och CO₂, passerar fritt.","src":"Bok s. 31"},{"w":"Hydrolys","d":"Spjälkning med hjälp av vatten. ATP hydrolyseras till ADP och fosfat, och då frigörs energi.","src":"Bok s. 35"},{"w":"Hyperton","d":"Lösning med hög halt av lösta ämnen. En röd blodkropp krymper i den.","src":"Bok s. 33"},{"w":"Hypoton","d":"Lösning med låg halt av lösta ämnen, t.ex. destillerat vatten. En röd blodkropp sväller och spricker i den.","src":"Bok s. 33"},{"w":"Integralt membranprotein","d":"Protein som går genom hela membranet.","src":"PPT Transport bild 9","lek":1},{"w":"Isoton","d":"Lösning med samma halt av lösta ämnen som inuti cellen. Cellen påverkas inte.","src":"Bok s. 33"},{"w":"Jonkanal","d":"Kanalprotein som är specialiserat på joner, t.ex. bara Na⁺ eller bara K⁺.","src":"Bok s. 32"},{"w":"Kanalprotein","d":"Protein som bildar en vattenfylld kanal genom membranet för vatten och joner. Öppnas och stängs av stimuli.","src":"Bok s. 32"},{"w":"Klatrinbelagd grop","d":"Grop i membranet vid receptormedierad endocytos. Snörs av till en klatrinbelagd vesikel.","src":"PPT Transport bild 23","lek":1},{"w":"Kodominant","d":"Här: en felaktig gen för LDL-receptorn ger mycket höga halter och två ger extremt höga. Båda generna påverkar.","src":"Bok s. 36"},{"w":"Kolesterol","d":"Lipid som transporteras i blodet i partiklar tillsammans med protein (LDL och HDL).","src":"Bok s. 36"},{"w":"Koncentrationsgradient","d":"Skillnaden mellan hög och låg koncentration. Läraren: i förhållande till avståndet, och ett mått på hur snabb diffusionen är.","src":"Bok s. 31 · PPT Transport bild 6"},{"w":"Kopplad transport","d":"Transporten av ett ämne mot sin gradient drivs av att ett annat ämne diffunderar med sin. Kräver ATP indirekt.","src":"Bok s. 34–35"},{"w":"LDL","d":"Low density lipoprotein. Partikel med mer kolesterol i förhållande till protein. Höga halter ger ökad risk för hjärt-kärlsjukdom. Kallas ibland \"det onda kolesterolet\".","src":"Bok s. 36"},{"w":"LDL-receptor","d":"Receptor i cellmembranet som behövs för att ta upp LDL från blodet via endocytos.","src":"Bok s. 36"},{"w":"Lösningsmedel","d":"Vätskan som ämnena är lösta i, oftast vatten. Vid osmos är det lösningsmedlet som passerar membranet.","src":"PPT Transport bild 13","lek":1},{"w":"Membranpotential","d":"Spänningen över cellmembranet, mätt i millivolt (mV). I vila är insidan negativ.","src":"PPT Transport bild 16, 20","lek":1},{"w":"Membrantransportprotein","d":"Protein i membranet som binder specifikt till det ämne som ska transporteras. Krävs vid aktiv transport.","src":"Bok s. 34"},{"w":"Mikrofilament","d":"Del av cellskelettet, av aktin, som gör endocytos möjlig.","src":"Bok s. 36"},{"w":"Natrium-kaliumpumpen","d":"ATP-driven pump som upprätthåller jonbalansen. Använder ca 40 % av cellens ATP (boken). Pumpar 3 Na⁺ ut och 2 K⁺ in (läraren).","src":"Bok s. 35 · PPT Transport bild 19"},{"w":"Neurotransmittorer","d":"Signalämnen som nervceller lagrar i synapsblåsor och släpper ut med exocytos.","src":"Bok s. 37"},{"w":"Osmos","d":"Vattnets diffusion över ett semipermeabelt membran.","src":"Bok s. 33"},{"w":"Passiv transport","d":"Diffusion genom ett cellmembran. Kostar ingen energi.","src":"Bok s. 31"},{"w":"Perifert membranprotein","d":"Protein som sitter på membranets yta.","src":"PPT Transport bild 9","lek":1},{"w":"Pinocytos","d":"\"Celldrickande\". Endocytos av vattenlösliga makromolekyler, med receptorer. Membranet buktar in.","src":"Bok s. 36"},{"w":"Potentiell energi","d":"Lägesenergi. Finns i en koncentrationsgradient, som hos ett föremål uppe på en backe.","src":"Bok s. 31"},{"w":"Primär aktiv transport","d":"Aktiv transport där pumpen använder ATP direkt, t.ex. natrium-kaliumpumpen.","src":"PPT Transport bild 16","lek":1},{"w":"Pseudopodier","d":"Utskott av cellmembranet som omsluter partikeln vid fagocytos.","src":"PPT Transport bild 23","lek":1},{"w":"Reabsorption","d":"Återupptag. Normalt reabsorberas en stor mängd natriumjoner i tarmen.","src":"Bok s. 35"},{"w":"Receptor","d":"Protein i cellmembranet som binder ett visst ämne, t.ex. vid pinocytos och fagocytos.","src":"Bok s. 36"},{"w":"Receptormedierad endocytos","d":"Lärarens tredje typ av endocytos. Ämnet binder till receptorer och tas in i en klatrinbelagd vesikel.","src":"PPT Transport bild 21, 23","lek":1},{"w":"Sekretoriska blåsor","d":"Blåsor där sekretoriska celler lagrar ämnen, som släpps ut med exocytos vid behov.","src":"Bok s. 37"},{"w":"Sekretoriska celler","d":"Celler som utsöndrar ämnen, t.ex. insulinproducerande celler i bukspottkörteln och nervceller.","src":"Bok s. 37"},{"w":"Sekundär aktiv transport","d":"Lärarens ord för kopplad transport.","src":"PPT Transport bild 17","lek":1},{"w":"Semipermeabelt","d":"Halvgenomträngligt. Ett semipermeabelt membran släpper igenom vatten men inte lösta ämnen lika lätt.","src":"Bok s. 33 · PPT Transport bild 13"},{"w":"Symport","d":"Två ämnen transporteras åt samma håll, t.ex. Na⁺ och glukos in i tarmcellen.","src":"PPT Transport bild 18","lek":1},{"w":"Synapsblåsor","d":"Blåsor där nervceller lagrar neurotransmittorer.","src":"Bok s. 37"},{"w":"Underlättad diffusion","d":"Diffusion med hjälp av kanalproteiner eller bärarproteiner. Med gradienten, utan energi.","src":"Bok s. 32"},{"w":"Vattenpotential","d":"Bokens ord för vattenkoncentration. Vatten går från högre till lägre vattenpotential.","src":"Bok s. 33"},{"w":"Vesikel","d":"Membranblåsa, omgiven av ett lipidlager, som transporterar ämnen in, ut eller inom cellen.","src":"Bok s. 35 · PPT Transport bild 21"},{"w":"Vesikulär transport","d":"Lärarens ord för transport med vesiklar: endocytos och exocytos.","src":"PPT Transport bild 21","lek":1}],"snabb":{"keys":["Akvaporin :: bara vatten, i en enda rad; positiva laddningar stoppar H⁺","Osmolalitet :: osmotiskt aktiva partiklar per kg; vatten går från låg till hög","Isoton med blodplasma :: ca 280–295 mOsm/kg","Fysiologisk koksaltlösning :: 0,9 % = 9 g/L = 154 mmol/L = 308 mOsmol/L","Hypoton hyponatremi :: låg Na⁺ och låg osmolalitet, vatten in i cellerna, hjärnödem","Synapsen :: impuls → Ca²⁺ in → exocytos → signalämne över synapsklyftan","Coronaviruset :: ACE2 → membranet buktar in → vesikel in → arvsmassan frigörs","Fyra faktorer :: laddning, storlek, form, fettlöslighet","Passerar fritt :: små, oladdade, hydrofoba (O₂, CO₂) och stora fettlösliga, eftersom fosfolipidskiktet är fettlösligt","Joner :: kommer inte igenom, inte ens H⁺, eftersom de har ett vattenskal","Diffusion :: hög → låg koncentration, längs gradienten, ingen energi","Passiv transport :: diffusion genom ett cellmembran","Underlättad diffusion :: kanalprotein (vattenfylld kanal, stimuli) eller bärarprotein (binder, ändrar form)","Osmos :: vattnets diffusion över ett semipermeabelt membran","Hypo / iso / hyper :: sväller och spricker / påverkas inte / krymper","Aktiv transport :: mot gradienten, kräver energi + specifikt membrantransportprotein","Kopplad transport :: ett ämne mot sin gradient, drivet av ett annat ämnes diffusion; ATP indirekt","ATP-pump :: ATP → ADP, energin till pumpen, oberoende av gradienter","Natrium-kaliumpumpen :: jonbalansen, ≈40 % av ATP, 3 Na⁺ ut och 2 K⁺ in","Fagocytos / pinocytos :: cellätande, stora partiklar / celldrickande, vattenlösliga makromolekyler","Exocytos :: golgiblåsor smälter ihop med membranet; ger fosfolipider, endocytos tar bort"],"nums":[["280–295","mOsm/kg, isoton med blodplasman (Film Osmos)"],["0,9 %","salt i blodplasma och fysiologisk koksaltlösning (Lektion)"],["154","mmol/L Na⁺ i 0,9 % NaCl (Lektion)"],["308","mOsmol/L i 0,9 % NaCl, 154 × 2 (Lektion)"],["0,86 %","teoretiskt mer exakt isoton NaCl-halt (Lektion)"],["3,5 %","salt i havsvatten, ca 1 000 mOsm/kg (Lektion)"],["2–3 L","vatten per dag som kroppen normalt klarar (Lektion)"],["3–4 L","på kort tid kan ge hypoton hyponatremi (Lektion)"],["2–2,5 L","vätska per dag för vuxna (Lektion)"],["8","steg i natrium-kaliumpumpen i filmen"],["4","faktorer: laddning, storlek, form, fettlöslighet (s. 31)"],["3","sorters stimuli som öppnar kanaler: kemiska, elektriska, mekaniska (s. 32)"],["2","sorters proteiner vid underlättad diffusion: kanal och bärare (s. 32)"],["2","sätt för aktiv transport: kopplad transport och ATP-pumpar (s. 34)"],["2 Na⁺ per glukos","i tarmens kopplade transport (s. 35)"],["1919–2010","Robert K. Crane (s. 35)"],["≈ 40 %","av cellens ATP till natrium-kaliumpumpen (boken s. 35)"],["10–40 %","av cellens ATP till Na/K-pumpen (läraren, bild 19)"],["3 Na⁺ ut, 2 K⁺ in","per ATP i natrium-kaliumpumpen (bild 19)"],["> 1 av 1000","bär en felaktig LDL-receptorgen på ena kromosomen (s. 36)"],["−96 mV","hjärtmuskelcellens vila (bild 20)"],["+52 mV","aktionspotentialens topp (bild 20)"],["200 ms","aktionspotentialens längd, fas 0–3 (bild 20)"],["3","typer av endocytos enligt läraren (bild 21)"]],"chains":[["För mycket vatten","plasman späds ut","låg osmolalitet och Na⁺","vatten in i cellerna","hjärnödem"],["Mycket salt eller socker","hög osmolalitet utanför mikroberna","vatten lämnar deras celler","tillväxten hämmas"],["Havsvatten","blodets osmolalitet ökar","vatten dras ur cellerna","uttorkning och organsvikt"],["Nervimpuls","Ca²⁺ in","vesiklar smälter ihop med membranet","signalämnet över synapsklyftan"],["Fosfolipidskiktet är fettlösligt","fettlösliga och små oladdade ämnen passerar fritt","joner med vattenskal kommer inte igenom"],["Stark saltlösning","lägre vattenkoncentration utanför","vatten diffunderar ut","blodkroppen krymper"],["Destillerat vatten","högre vattenkoncentration utanför","vatten diffunderar in","blodkroppen sväller och kan spricka"],["ATP driver Na/K-pumpen","natriumgradient byggs upp","Na⁺ diffunderar in","glukos dras med mot sin gradient"],["Diarré","Na⁺ hinner inte reabsorberas","jonbalansen störs","salt + glukos räddar"],["Receptorer binder molekyler","membranet buktar in","bubblan snörs av","ämnet tas in"],["Felaktig LDL-receptor","LDL tas inte upp via endocytos","höga LDL-halter","ökad risk för hjärtinfarkt och stroke"],["Exocytos tillför fosfolipider","endocytos tar bort fosfolipider","cellens storlek står still"]],"traps":["Vatten går mot HÖG osmolalitet, eftersom många partiklar betyder lite fritt vatten.","0,9 % NaCl är funktionellt isoton men tekniskt svagt hyperton (308 mOsmol/L).","En övervattnad växt får syrebrist i rötterna. Cellerna spricker inte.","Vesikeltransport kan gå med eller mot gradienten men kräver alltid ATP.","Hypo och hyper beskriver halten LÖSTA ÄMNEN utanför cellen, inte vattnet.","Underlättad diffusion använder protein men kräver ingen energi.","Kopplad transport kräver ATP indirekt, eftersom natriumgradienten måste hållas uppe.","Natrium-kaliumpumpen: Na⁺ UT och K⁺ IN, tre ut och två in.","Vätejonen är minst men kommer ändå inte igenom fosfolipidskiktet.","Exocytos gör membranet större, endocytos mindre.","LDL och HDL är partiklar av kolesterol + protein enligt boken.","Saltet följer inte med vid osmos, eftersom det finns färre jonkanaler än vattenkanaler (boken)."]}},"k6":{"pre":[{"q":"Hur många fosfatgrupper har ATP?","o":["Tre","En","Två","Fyra"],"why":"ATP = adenosintrifosfat, och tri betyder tre. ADP har två.","src":"PPT Bi2 bild 29","t":["atp"],"id":"k6p1finz83"},{"q":"Var bildas det mesta av cellens ATP?","o":["I mitokondrien","I cellkärnan","I ribosomerna","I lysosomerna"],"why":"Boken s. 27: de flesta ATP-molekyler bildas i mitokondrien, cellens kraftverk.","src":"s. 27","t":["atp"],"id":"k6p1dkosrn"},{"q":"Vad behövs när ATP spjälkas till ADP och energi frigörs?","o":["Vatten","Kreatinfosfat","Syre","Ljus"],"why":"Reaktionen kallas hydrolys och kräver vatten. Kreatinfosfat används åt andra hållet, för att återbilda ATP.","src":"PPT Bi2 bild 29, 31 · s. 35","t":["atp"],"id":"k6pk5w657"},{"q":"Vad gör kreatinfosfat i musklerna?","o":["Återbildar ATP snabbt från ADP","Bryter ner ATP","Bygger upp muskelproteiner","Transporterar syre"],"why":"Kreatinfosfat + ADP → kreatin + ATP. Ett snabbladdat reservbatteri.","src":"PPT Bi2 bild 31","t":["atp"],"id":"k6plnptxe"},{"q":"Vilken cellprocess tar ungefär 40 % av cellens ATP enligt boken?","o":["Natrium-kaliumpumpen","Osmosen","Proteinsyntesen","Diffusion av syre"],"why":"Boken s. 35: ungefär 40 % av det ATP som produceras i en cell går till natrium-kaliumpumpen.","src":"s. 35","t":["atp","membran"],"id":"k6pggf9mp"}],"cards":[{"f":"Vad står ATP för?","b":"Adenosintrifosfat (tri = tre fosfatgrupper).","ty":"b","t":["atp"],"src":"PPT Bi2 bild 29","id":"k6c18kcxti"},{"f":"Vad står ADP för?","b":"Adenosindifosfat (di = två fosfatgrupper).","ty":"b","t":["atp"],"src":"PPT Bi2 bild 29","id":"k6co7esh2"},{"f":"Vilka tre delar består ATP av?","b":"Sockret ribos, kvävebasen adenin och tre fosfatgrupper.","ty":"b","t":["atp"],"src":"PPT Bi2 bild 29","id":"k6c1t4m8hr"},{"f":"Hur många fosfatgrupper har ADP?","b":"Två.","ty":"s","t":["atp"],"src":"PPT Bi2 bild 29","id":"k6c1tpevj7"},{"f":"Vilket socker finns i ATP?","b":"Ribos (en monosackarid).","ty":"b","t":["atp"],"src":"PPT Bi2 bild 29","id":"k6c1pma4r2"},{"f":"Vilken kvävebas finns i ATP?","b":"Adenin.","ty":"b","t":["atp"],"src":"PPT Bi2 bild 29","id":"k6c1v682pp"},{"f":"Vilken bindning i ATP innehåller mycket energi?","b":"Bindningen mellan den andra och den tredje fosfatgruppen. Därför är det den tredje som lossnar när energin frigörs.","ty":"b","t":["atp"],"src":"PPT Bi2 bild 29","id":"k6c1762mph"},{"f":"Vad är hydrolys av ATP?","b":"ATP + vatten → ADP + fosfat + energi. Bindningen bryts med hjälp av vatten.","ty":"b","t":["atp"],"src":"s. 35 · PPT Bi2 bild 29","p":1,"id":"k6cmsrvd1"},{"f":"Hur återbildas ATP från ADP?","b":"ADP tar upp ett fosfat igen med hjälp av energi, som kommer från födan (mest i mitokondrien).","ty":"v","t":["atp"],"src":"PPT Bi2 bild 29–30 · s. 27","p":1,"id":"k6c4q227h"},{"f":"Varför måste ATP hela tiden återbildas?","b":"Eftersom varje användning gör ATP till ADP och cellen arbetar hela tiden. Utan återbildning tar ATP slut och allt som drivs av ATP stannar.","ty":"v","t":["atp"],"src":"PPT Bi2 bild 30 · s. 27","id":"k6c5wpleb"},{"f":"Vad visar ATP–ADP-cykeln?","b":"ATP → ADP + fosfat + energi för cellen. ADP + fosfat + energi från födan → ATP. Samma molekyler går runt.","ty":"i","t":["atp"],"src":"PPT Bi2 bild 30","p":1,"id":"k6cv58q44"},{"f":"Varifrån kommer energin som laddar ADP till ATP enligt lärarens cykelbild?","b":"Från födan.","ty":"i","t":["atp"],"src":"PPT Bi2 bild 30","id":"k6c6k9zxx"},{"f":"Vilka två roller har nukleotider enligt läraren?","b":"De bygger upp nukleinsyror (DNA och RNA) och fungerar som energibärare (t.ex. ATP).","ty":"b","t":["atp"],"src":"PPT Bi2 bild 28","id":"k6c1auf2rm"},{"f":"Vilka tre delar har en nukleotid?","b":"En fosfatgrupp, en monosackarid (ribos eller deoxiribos) och en kvävebas.","ty":"b","src":"PPT Bi2 bild 27","id":"k6cq79od1"},{"f":"Vilken är cellens viktigaste energibärande molekyl?","b":"ATP.","ty":"b","t":["atp"],"src":"PPT Bi2 bild 29 · s. 27","p":1,"id":"k6c1ymbssl"},{"f":"Provfälla: Behövs kreatinfosfat för att ATP ska frigöra energi?","b":"Nej. Hydrolysen behöver bara vatten. Kreatinfosfat återbildar ATP från ADP (bild 31). Bild 29 har fel här.","ty":"f","t":["atp"],"src":"PPT Bi2 bild 29, 31 · s. 35","id":"k6c32qfkd"},{"f":"Provfälla: Hur stavas ATP:s fullständiga namn?","b":"Adenosintrifosfat (inte \"adenosintrisfosfat\" som i lärarens bild 29).","ty":"f","t":["atp"],"src":"PPT Bi2 bild 29","id":"k6c1xm8onw"},{"f":"Vad är kreatin?","b":"Ett kvävehaltigt ämne som kroppen tillverkar själv, främst i lever och njurar.","ty":"b","t":["atp"],"src":"PPT Bi2 bild 31","id":"k6c14v80ft"},{"f":"Var tillverkas kreatin i kroppen?","b":"Främst i levern och njurarna.","ty":"s","t":["atp"],"src":"PPT Bi2 bild 31","id":"k6cvsmu7k"},{"f":"I vilka livsmedel finns kreatin?","b":"Animaliska livsmedel som kött och fisk.","ty":"s","src":"PPT Bi2 bild 31","id":"k6cotnap5"},{"f":"I vilken form säljs kreatin som kosttillskott?","b":"Vanligen som kreatinmonohydrat.","ty":"s","src":"PPT Bi2 bild 31","id":"k6c1hp756o"},{"f":"I vilken form lagras kreatin i musklerna?","b":"Som fosfokreatin, även kallat kreatinfosfat.","ty":"b","t":["atp"],"src":"PPT Bi2 bild 31","id":"k6c5try0x"},{"f":"Skriv reaktionen där kreatinfosfat används.","b":"Kreatinfosfat + ADP → Kreatin + ATP.","ty":"b","t":["atp"],"src":"PPT Bi2 bild 31","id":"k6c1d7by53"},{"f":"Varför kallas kreatinfosfat ett snabbladdat reservbatteri?","b":"Eftersom det snabbt återbildar ATP från ADP när energibehovet är stort, men förrådet räcker bara en kort stund.","ty":"v","t":["atp"],"src":"PPT Bi2 bild 31","id":"k6cah4mjv"},{"f":"Hur länge kan musklerna arbeta maximalt med kreatinfosfat?","b":"Under väldigt kort tid, eftersom förrådet tar slut.","ty":"s","src":"PPT Bi2 bild 31","id":"k6c5ofeli"},{"f":"Jämför hydrolys av ATP med kreatinfosfatreaktionen.","b":"Hydrolys: ATP + vatten → ADP + fosfat + energi (energi ut). Kreatinfosfat + ADP → kreatin + ATP (ATP återbildas).","ty":"j","t":["atp"],"src":"PPT Bi2 bild 29, 31","id":"k6cpjsk15"},{"f":"Var bildas de flesta ATP-molekylerna?","b":"I mitokondrien, cellens kraftverk.","ty":"s","t":["atp"],"src":"s. 27 · PPT Bi2 bild 22","p":1,"id":"k6ca50tkv"},{"f":"Varför kallas mitokondrien cellens kraftverk?","b":"Eftersom energi ur födan fångas in där och används för att bilda de flesta ATP-molekylerna, som driver alla energikrävande processer i cellen.","ty":"v","t":["atp"],"src":"s. 27 · PPT Bi2 bild 22","p":1,"id":"k6c1k41n7y"},{"f":"Hur beskriver läraren mitokondrien?","b":"\"Cellens kraftverk. Energirik näring förbränns (cellandningen).\"","ty":"b","src":"PPT Bi2 bild 22","id":"k6c1pu8pif"},{"f":"Varför är mitokondriens inre membran starkt veckat?","b":"Det ger stor yta för de membranförankrade enzymerna i elektrontransportkedjan, som ger ATP.","ty":"v","t":["atp","membran"],"src":"s. 27","id":"k6c1oclv44"},{"f":"Vad heter kedjan i inre membranet som ger ATP?","b":"Elektrontransportkedjan.","ty":"i","t":["atp","membran"],"src":"s. 27","id":"k6c392dgu"},{"f":"Vad är matrix i mitokondrien?","b":"Vattenlösningen inuti mitokondrien, med enzymer som utvinner energi ur födan.","ty":"i","src":"s. 27","id":"k6c1bmvr1e"},{"f":"Vad händer med den energi som inte blir ATP i mitokondrien?","b":"Den avgår som spillvärme. Mycket energi avgår på det sättet.","ty":"v","src":"s. 27","id":"k6cng6rmu"},{"f":"Varför har muskelceller extra många mitokondrier?","b":"Eftersom de har högt energibehov och behöver mycket ATP.","ty":"v","t":["atp"],"src":"s. 27","p":1,"id":"k6cih2j13"},{"f":"Vilka tre bevis för endosymbios har mitokondrien?","b":"Två membran, eget ringformat DNA och ribosomer av samma typ som hos bakterier.","ty":"b","t":["endo"],"src":"s. 27","id":"k6c1gs1bgp"},{"f":"Jämför mitokondrie och kloroplast.","b":"Mitokondrien bildar ATP med energi från födan (matrix). Kloroplasten fångar solljus i tylakoiderna (stroma). Båda har två membran, eget ringformat DNA och ribosomer och tros komma från endosymbios.","ty":"j","t":["endo"],"src":"s. 27, 247","id":"k6c4nnlhq"},{"f":"Var i kloroplasten fångas ljusenergi in?","b":"I tylakoiderna, där klorofyllet sitter.","ty":"i","src":"s. 247 · PPT Bi2 bild 25","p":1,"id":"k6c1o5psgx"},{"f":"Hur stor del av cellens ATP går till natrium-kaliumpumpen?","b":"Ungefär 40 % enligt boken (läraren: 10–40 %).","ty":"s","t":["atp","membran"],"src":"s. 35 · PPT Transport bild 19","p":1,"id":"k6c1ldov8e"},{"f":"Hur får en ATP-driven pump sin energi?","b":"ATP hydrolyseras till ADP (tappar ett fosfat). Energin överförs till pumpen, så att ämnet kan föras mot sin gradient.","ty":"v","t":["atp","membran"],"src":"s. 35 · PPT Transport bild 16","p":1,"id":"k6crrz285"},{"f":"Vad är den stora fördelen med ATP-drivna pumpar?","b":"De fungerar oberoende av koncentrationsgradienter, eftersom energin kommer från ATP.","ty":"v","t":["atp","membran"],"src":"s. 35","id":"k6c1g95k8m"},{"f":"Varför kräver kopplad transport ATP indirekt?","b":"Gradienten som driver transporten måste upprätthållas. Ämnet måste pumpas tillbaka, och det kostar ATP.","ty":"v","t":["atp","membran"],"src":"s. 34 · PPT Transport bild 17","p":1,"id":"k6cy8x59u"},{"f":"Provfälla: Drivs alla proteinpumpar av ATP?","b":"Nej. Hos vissa bakterier och arkéer finns pumpar som drivs av solenergi.","ty":"f","src":"s. 34","id":"k6c11uj8ze"},{"f":"Provfälla: Kostar diffusion genom ett bärarprotein ATP?","b":"Nej. Underlättad diffusion sker med gradienten och kräver ingen energi.","ty":"f","t":["membran"],"src":"s. 32","id":"k6c1mglmsf"},{"f":"Vilka två vesikeltransporter kräver energi?","b":"Endocytos och exocytos.","ty":"s","src":"s. 35","id":"k6cfgekox"}],"quiz":{"f":[{"q":"Vad består ATP av?","o":["Ribos, adenin och tre fosfatgrupper","Deoxiribos, adenin och tre fosfatgrupper","Ribos, adenin och två fosfatgrupper","Glukos, adenin och tre fosfatgrupper"],"why":"ATP = ribos + adenin + tre fosfatgrupper. Deoxiribos finns i DNA, och två fosfatgrupper är ADP.","src":"PPT Bi2 bild 29","t":["atp"],"id":"k6qv2i45y"},{"q":"Hur många fosfatgrupper har ADP?","o":["Två","En","Tre","Fyra"],"why":"Di betyder två. ADP = adenosindifosfat.","src":"PPT Bi2 bild 29","t":["atp"],"id":"k6q1tpevj7"},{"q":"Mellan vilka fosfatgrupper sitter den energirika bindningen som bryts?","o":["Den andra och den tredje","Den första och den andra","Ribos och den första","Adenin och ribos"],"why":"Lärarens bild 29: bindningen mellan den andra och tredje fosfatgruppen innehåller mycket energi.","src":"PPT Bi2 bild 29","t":["atp"],"id":"k6qyqy8f6"},{"q":"Vad kallas reaktionen när ATP spjälkas med vatten?","o":["Hydrolys","Fotosyntes","Osmos","Diffusion"],"why":"Hydrolys = spjälkning med vatten. ATP hydrolyseras till ADP.","src":"s. 35 · PPT Bi2 bild 29","t":["atp"],"id":"k6qtmf75w"},{"q":"Vilka produkter bildas vid hydrolysen av ATP?","o":["ADP, fosfat och energi","ADP och kreatin","AMP och glukos","ATP och vatten"],"why":"ATP + vatten → ADP + fosfat + energi.","src":"PPT Bi2 bild 29–30 · s. 35","t":["atp"],"id":"k6qjljjka"},{"q":"Varifrån kommer energin som återbildar ATP i ATP–ADP-cykeln?","o":["Från födan","Från hydrolysen","Från natrium-kaliumpumpen","Från spillvärmen"],"why":"Lärarens bild 30: energi tas upp från födan. Boken: matrix-enzymer utvinner energi ur födan.","src":"PPT Bi2 bild 30 · s. 27","t":["atp"],"id":"k6qbeu2dj"},{"q":"Var bildas de flesta ATP-molekylerna?","o":["I mitokondrien","I cellkärnan","I golgiapparaten","I cellmembranet"],"why":"Boken s. 27: de flesta ATP-molekyler bildas i mitokondrien.","src":"s. 27","t":["atp"],"id":"k6qa50tkv"},{"q":"Var sitter elektrontransportkedjan?","o":["I mitokondriens inre membran","I mitokondriens yttre membran","I cellkärnan","I matrix utanför membranen"],"why":"Det starkt veckade inre membranet ger stor yta för enzymerna i elektrontransportkedjan.","src":"s. 27","t":["atp","membran"],"id":"k6q1cs6ve4"},{"q":"Vad innehåller mitokondriens matrix?","o":["Enzymer som utvinner energi ur födan","Klorofyll","Kollagenfibrer","Fosfolipider som bildar membranet"],"why":"Boken s. 27. Tänk på att mitokondriens matrix inte är detsamma som extracellulär matrix.","src":"s. 27","id":"k6q11r8bam"},{"q":"Vad händer med mycket av energin i mitokondriens energiutvinning?","o":["Den avgår som spillvärme","Den lagras i kärnan","Den blir till kreatin","Den används för att bilda DNA"],"why":"Boken: mycket energi avgår som spillvärme, en del fångas in som ATP.","src":"s. 27","id":"k6ql8c04l"},{"q":"Var tillverkar kroppen främst kreatin?","o":["I levern och njurarna","I musklerna","I mitokondrien","I magsäcken"],"why":"Lärarens bild 31. Musklerna lagrar det som kreatinfosfat.","src":"PPT Bi2 bild 31","t":["atp"],"id":"k6q97omi"},{"q":"Vilken reaktion visar hur kreatinfosfat används?","o":["Kreatinfosfat + ADP → kreatin + ATP","Kreatin + ATP → kreatinfosfat + ADP","ATP + kreatinfosfat → ADP + energi","Kreatin + vatten → ATP"],"why":"Lärarens bild 31. Fosfatet flyttas från kreatin till ADP.","src":"PPT Bi2 bild 31","t":["atp"],"id":"k6q1jf0ue7"},{"q":"Vad kallas kreatin i kosttillskott vanligen?","o":["Kreatinmonohydrat","Fosfokreatin","Kreatintrifosfat","Adenosin"],"why":"Lärarens bild 31.","src":"PPT Bi2 bild 31","id":"k6q1imgqnt"},{"q":"Ungefär hur stor del av cellens ATP går till natrium-kaliumpumpen enligt boken?","o":["Ungefär 40 %","Ungefär 4 %","Ungefär 90 %","Ungefär 60 %"],"why":"Boken s. 35. Lärarens bild 19 skriver 10–40 %.","src":"s. 35","t":["atp","membran"],"id":"k6q1t6bkjd"},{"q":"Vilka två roller har nukleotider enligt läraren?","o":["Bygga nukleinsyror och bära energi","Bygga membran och bära syre","Bygga proteiner och lagra fett","Bygga cellväggar och fånga ljus"],"why":"Lärarens bild 28: nukleotider bygger upp nukleinsyror och är energibärare.","src":"PPT Bi2 bild 28","t":["atp"],"id":"k6q1auf2rm"}],"u":[{"q":"Lärarens bild 29 säger att vatten och kreatinfosfat behövs när ATP frigör energi. Vad är korrekt?","o":["Bara vatten behövs; kreatinfosfat återbildar ATP","Bara kreatinfosfat behövs","Båda behövs, som bilden säger","Inget av dem behövs"],"why":"Hydrolys kräver vatten. Bild 31 visar att kreatinfosfat används för att återbilda ATP från ADP.","src":"PPT Bi2 bild 29, 31 · s. 35","t":["atp"],"id":"k6qfmzvfs"},{"q":"Om en cell plötsligt inte får någon energi från födan, vad händer först med ATP?","o":["ATP tar slut, eftersom ADP inte laddas igen","ATP ökar, eftersom inget används","ADP omvandlas till glukos","Ingenting, ATP lagras i stora mängder"],"why":"Cellen fortsätter att göra ATP till ADP, men utan energi från födan återbildas inget ATP.","src":"PPT Bi2 bild 30 · s. 27","t":["atp"],"id":"k6q1lw23r0"},{"q":"Varför har muskelceller många mitokondrier?","o":["De har högt energibehov och behöver mycket ATP","De behöver avgifta alkohol","De tillverkar mycket protein för export","Mitokondrierna bildar kreatin"],"why":"Boken s. 27: celler med högt energibehov, t.ex. muskelceller, har extra många mitokondrier.","src":"s. 27","t":["atp"],"id":"k6q1sa41ip"},{"q":"Varför är det en fördel att mitokondriens inre membran är veckat?","o":["Större yta ger plats för fler enzymer i elektrontransportkedjan","Vecken gör att mitokondrien kan dela sig","Vecken stoppar spillvärme","Vecken släpper in ljus"],"why":"Stor yta = plats för många membranförankrade enzymer som behövs för att bilda ATP.","src":"s. 27","t":["atp","membran"],"id":"k6qw868q1"},{"q":"Under en kort maximal spurt används ATP snabbare än mitokondrien hinner ladda. Vad hjälper då?","o":["Kreatinfosfat ger fosfat till ADP så att ATP bildas snabbt","Hydrolysen går baklänges av sig själv","Natrium-kaliumpumpen stängs av för alltid","Musklerna slutar använda ATP"],"why":"Kreatinfosfat är ett snabbladdat reservbatteri, men det räcker bara väldigt kort tid.","src":"PPT Bi2 bild 31","t":["atp"],"id":"k6qw0lab9"},{"q":"Varför slutar kopplad transport till slut om cellen inte har något ATP?","o":["Gradienten som driver den kan inte hållas uppe","Kopplad transport använder alltid ATP direkt","Transportproteinet bryts ner av ADP","Glukos blir för stort"],"why":"Ämnet vars diffusion driver transporten måste pumpas tillbaka med ATP. Utan gradient ingen diffusion.","src":"s. 34","t":["atp","membran"],"id":"k6q10evjs5"},{"q":"Vilket påstående om ATP-drivna pumpar stämmer?","o":["De fungerar oberoende av koncentrationsgradienter","De kan bara transportera med gradienten","De drivs av spillvärme","De bildar ATP"],"why":"Boken s. 35: den stora fördelen är att transporten fungerar oberoende av koncentrationsgradienter.","src":"s. 35","t":["atp","membran"],"id":"k6qmwvc8z"},{"q":"Vilken process kostar INGEN energi för cellen?","o":["Glukos genom ett bärarprotein från hög till låg koncentration","Natrium-kaliumpumpen","Exocytos","Kopplad transport av glukos mot gradienten"],"why":"Underlättad diffusion sker med gradienten. Pumpen, exocytos och kopplad transport kräver energi.","src":"s. 32–35","t":["atp"],"id":"k6q1w74mq6"},{"q":"Vad har mitokondrien och kloroplasten gemensamt?","o":["Två membran och eget ringformat DNA","Båda fångar solljus","Båda finns bara i växtceller","Båda saknar ribosomer"],"why":"Båda har dubbla membran, ringformat DNA, ribosomer och enzymer, och tros komma från endosymbios.","src":"s. 27, 247","t":["endo"],"id":"k6qg6zzyy"},{"q":"Varför är summan av ATP och ADP i en cell ungefär densamma från stund till stund, även när mycket energi används?","o":["ATP och ADP omvandlas till varandra i en cykel","ATP bildas från glukos och ADP från fett","ADP lämnar cellen och ersätts","Hydrolysen skapar nya adeninmolekyler"],"why":"ATP blir ADP + fosfat när energin används, och ADP blir ATP igen med energi från födan. Samma molekyler går runt.","src":"PPT Bi2 bild 30","t":["atp"],"id":"k6qivgn4a"}],"o":[{"q":"Beskriv ATP:s byggnad och förklara ATP–ADP-cykeln. Var i cellen bildas det mesta av ATP:t?","model":"ATP (adenosintrifosfat) består av ribos, adenin och tre fosfatgrupper. Bindningen mellan andra och tredje fosfatgruppen innehåller mycket energi. Vid hydrolys med vatten lossnar den tredje fosfatgruppen och energi frigörs, och kvar blir ADP (två fosfatgrupper) och fosfat. Med energi från födan kan ADP ta upp fosfatet igen och bli ATP. Det mesta av ATP:t bildas i mitokondrien, där elektrontransportkedjan i det veckade inre membranet fångar in energi.","kw":[["ribos"],["adenin"],["tre","fosfat"],["hydroly","vatten"],["adp"],["mitokondri"]],"src":"PPT Bi2 bild 29–30 · s. 27, 35","t":["atp"],"id":"k6o12jlx4m"},{"q":"Förklara hur kreatinfosfat hjälper musklerna. Lärarens bild 29 påstår att kreatinfosfat behövs när ATP frigör energi. Kommentera.","model":"Kreatin tillverkas främst i lever och njurar och lagras i musklerna som kreatinfosfat (fosfokreatin). När energibehovet är stort ger kreatinfosfat sitt fosfat till ADP: kreatinfosfat + ADP → kreatin + ATP. Det är ett snabbladdat reservbatteri, så muskeln kan arbeta maximalt men bara under väldigt kort tid. Påståendet i bild 29 är fel. Hydrolysen av ATP behöver bara vatten, och kreatinfosfat används för att återbilda ATP, som bild 31 visar.","kw":[["lever","njur"],["adp"],["återbild","bildar atp"],["kort"],["vatten"],["fel","stämmer inte"]],"src":"PPT Bi2 bild 29, 31 · s. 35","t":["atp"],"id":"k6o1fcpa39"},{"q":"Ge exempel på processer i cellen som kostar ATP, och förklara varför natrium-kaliumpumpen gör att cellen hela tiden måste återbilda ATP.","model":"ATP-drivna proteinpumpar använder energin när ATP hydrolyseras till ADP för att pumpa ämnen mot gradienten. Kopplad transport kostar ATP indirekt, eftersom gradienten måste pumpas upp igen. Endocytos och exocytos kräver energi, och muskelarbete kräver mycket ATP. Natrium-kaliumpumpen håller jonbalansen och tar ungefär 40 % av cellens ATP. Eftersom den alltid arbetar blir ATP hela tiden ADP, och därför måste mitokondrien hela tiden återbilda ATP med energi från födan.","kw":[["pump"],["kopplad","indirekt"],["endocytos","exocytos","vesikl"],["40"],["jonbalans"],["återbild","mitokondri"]],"src":"s. 27, 34–35","t":["atp","membran"],"id":"k6o1immgwh"}]},"kan":[{"q":"Kan du beskriva ATP:s byggnad och skillnaden mot ADP?","a":"ATP (adenosintrifosfat) består av sockret ribos, kvävebasen adenin och tre fosfatgrupper. ADP (adenosindifosfat) har bara två fosfatgrupper. ATP är cellens viktigaste energibärande molekyl.","kw":[["ribos"],["adenin"],["tre","tri"],["två","di"],["energi"]],"src":"PPT Bi2 bild 29","t":["atp"],"id":"k6kxg893q"},{"q":"Kan du förklara var energin i ATP sitter och hur den frigörs?","a":"Bindningen mellan den andra och tredje fosfatgruppen innehåller mycket energi. Vid hydrolys, med hjälp av vatten, lossnar den tredje fosfatgruppen och energin frigörs. Kvar blir ADP och ett fosfat. Boken säger att ATP hydrolyseras till ADP och tappar ett fosfat.","kw":[["bindning"],["andra","tredje"],["hydroly"],["vatten"],["adp"]],"src":"PPT Bi2 bild 29 · s. 35","t":["atp"],"id":"k6k1g7eswf"},{"q":"Kan du förklara ATP–ADP-cykeln och varför ATP hela tiden måste återbildas?","a":"När cellen använder energi hydrolyseras ATP till ADP och fosfat. Med energi från födan kan ADP ta upp fosfatet igen och bli ATP, vilket mest sker i mitokondrien. Eftersom cellen hela tiden arbetar blir ATP hela tiden ADP, och därför måste ATP hela tiden återbildas, annars stannar allt som drivs av ATP.","kw":[["adp"],["fosfat"],["födan","föda"],["mitokondri"],["återbild","laddas","igen"]],"src":"PPT Bi2 bild 29–30 · s. 27","t":["atp"],"id":"k6ksredtl"},{"q":"Kan du förklara vad kreatin och kreatinfosfat är och vad de gör?","a":"Kreatin är ett kvävehaltigt ämne som kroppen tillverkar främst i lever och njurar. Det finns i kött och fisk och säljs som kreatinmonohydrat. I musklerna lagras det som kreatinfosfat (fosfokreatin), som ger sitt fosfat till ADP när energibehovet är stort: kreatinfosfat + ADP → kreatin + ATP. Det är ett snabbladdat reservbatteri som låter muskeln arbeta maximalt under väldigt kort tid.","kw":[["lever","njur"],["fosfokreatin","kreatinfosfat"],["adp"],["reservbatteri","snabb"],["kort tid","kort"]],"src":"PPT Bi2 bild 31","t":["atp"],"id":"k6k1ollm5p"},{"q":"Kan du förklara varför mitokondrien kallas cellens kraftverk?","a":"De flesta ATP-molekyler bildas i mitokondrien. Enzymer i matrix utvinner energi ur födan, och elektrontransportkedjan i det starkt veckade inre membranet fångar in en del av energin och bildar ATP. Mycket energi avgår som spillvärme. Veckningen ger stor yta för enzymerna.","kw":[["atp"],["matrix","födan"],["inre membran","veckat","veck"],["elektrontransport"],["spillvärme"]],"src":"s. 27 · PPT Bi2 bild 22","t":["atp","membran"],"id":"k6k1v7noju"},{"q":"Kan du förklara hur en ATP-driven proteinpump får sin energi och ge ett exempel?","a":"Pumpen utnyttjar energin som frigörs när ATP hydrolyseras till ADP. Energin överförs till pumpen, och därför kan ämnet som binder till pumpen föras till andra sidan, mot sin gradient. Pumparna fungerar oberoende av koncentrationsgradienter. Natrium-kaliumpumpen håller jonbalansen och tar ungefär 40 % av cellens ATP.","kw":[["hydroly","adp"],["mot","gradient"],["oberoende"],["natrium","kalium"],["40"]],"src":"s. 35 · PPT Transport bild 16, 19","t":["atp","membran"],"id":"k6k1px2q4h"},{"q":"Kan du förklara varför kopplad transport kräver ATP fast den inte använder ATP direkt?","a":"Vid kopplad transport driver ett ämne som diffunderar med sin gradient ett annat ämne mot dess gradient. Gradienten för det första ämnet måste upprätthållas, eftersom det utan gradient inte blir någon diffusion. Därför måste ämnet pumpas tillbaka, och det kräver ATP. Kopplad transport kräver alltså ATP indirekt.","kw":[["gradient"],["upprätthåll","hålla"],["pump"],["indirekt"],["atp"]],"src":"s. 34 · PPT Transport bild 17","t":["atp","membran"],"id":"k6k1gqwiwx"}],"kompis":[{"q":"Förklara för en kompis hur ATP fungerar som cellens valuta, från födan till pumpen och tillbaka.","model":"I mitokondrien utvinner enzymer energi ur födan, och elektrontransportkedjan i det veckade inre membranet använder en del av energin för att sätta ett tredje fosfat på ADP, så att ATP bildas. Resten blir spillvärme. ATP går till exempelvis natrium-kaliumpumpen. Där hydrolyseras ATP med vatten, den tredje fosfatgruppen lossnar och energin driver pumpen. Kvar blir ADP och fosfat, som går tillbaka och laddas igen. Därför måste ATP hela tiden återbildas.","kw":[["mitokondri"],["födan","föda"],["adp"],["hydroly","vatten"],["pump"],["återbild","igen","cykel"]],"src":"s. 27, 35 · PPT Bi2 bild 29–30","t":["atp"],"id":"k6eyt82nm"},{"q":"Förklara för en kompis vad som händer i musklerna under en kort maximal spurt, och vad som är fel i lärarens bild 29.","model":"Under en spurt används ATP mycket snabbt, och mitokondrien hinner inte ladda ADP tillräckligt fort. Då ger kreatinfosfat sitt fosfat till ADP så att ATP återbildas snabbt (kreatinfosfat + ADP → kreatin + ATP). Det är ett snabbladdat reservbatteri, men det räcker bara väldigt kort tid. Bild 29 säger att kreatinfosfat behövs när ATP frigör energi, men det är fel. Hydrolysen behöver bara vatten. Kreatinfosfat används för att återbilda ATP.","kw":[["kreatinfosfat","fosfokreatin"],["adp"],["snabb","reservbatteri"],["kort"],["vatten"],["återbild"]],"src":"PPT Bi2 bild 29, 31","t":["atp"],"id":"k6enkhok3"}],"gloss":[{"w":"ATP (adenosintrifosfat)","d":"Cellens viktigaste energibärande molekyl: ribos + adenin + tre fosfatgrupper.","src":"PPT Bi2 bild 29 · bok s. 27, 35"},{"w":"ADP (adenosindifosfat)","d":"ATP med bara två fosfatgrupper. Bildas när ATP hydrolyseras.","src":"PPT Bi2 bild 29 · bok s. 35"},{"w":"Nukleotid","d":"Byggsten av fosfatgrupp, monosackarid (ribos/deoxiribos) och kvävebas. Bygger nukleinsyror och fungerar som energibärare.","src":"PPT Bi2 bild 27–28","lek":1},{"w":"Ribos","d":"Sockret (monosackarid) i ATP och RNA.","src":"PPT Bi2 bild 27, 29","lek":1},{"w":"Adenin","d":"Kvävebasen i ATP.","src":"PPT Bi2 bild 29","lek":1},{"w":"Fosfatgrupp","d":"Del av nukleotiden. ATP har tre, ADP två.","src":"PPT Bi2 bild 27, 29","lek":1},{"w":"Energirik bindning","d":"Bindningen mellan andra och tredje fosfatgruppen i ATP. När den bryts frigörs energi.","src":"PPT Bi2 bild 29","lek":1},{"w":"Hydrolys","d":"Spjälkning med vatten. ATP + vatten → ADP + fosfat + energi.","src":"Bok s. 35 · PPT Bi2 bild 29"},{"w":"ATP–ADP-cykeln","d":"ATP blir ADP + fosfat när energi frigörs, och ADP blir ATP igen med energi från födan.","src":"PPT Bi2 bild 30","lek":1},{"w":"Energibärare","d":"Molekyl som för energi till cellens arbete, t.ex. ATP.","src":"PPT Bi2 bild 28","lek":1},{"w":"Kreatin","d":"Kvävehaltigt ämne som kroppen tillverkar främst i lever och njurar; finns i kött och fisk.","src":"PPT Bi2 bild 31","lek":1},{"w":"Kreatinfosfat (fosfokreatin)","d":"Kreatinets lagringsform i musklerna. Återbildar snabbt ATP från ADP: kreatinfosfat + ADP → kreatin + ATP.","src":"PPT Bi2 bild 31","lek":1},{"w":"Kreatinmonohydrat","d":"Den vanliga formen av kreatin i kosttillskott.","src":"PPT Bi2 bild 31","lek":1},{"w":"Mitokondrie","d":"Cellens kraftverk där de flesta ATP-molekyler bildas. Två membran, det inre veckat.","src":"Bok s. 27 · PPT Bi2 bild 22"},{"w":"Matrix (mitokondrien)","d":"Vattenlösningen i mitokondriens inre, med enzymer som utvinner energi ur födan.","src":"Bok s. 27"},{"w":"Elektrontransportkedjan","d":"Membranförankrade enzymer i mitokondriens inre membran som ger ATP.","src":"Bok s. 27"},{"w":"Spillvärme","d":"Energi som avgår som värme i stället för att bli ATP.","src":"Bok s. 27"},{"w":"Cellandning","d":"Lärarens ord för att energirik näring förbränns i mitokondrien.","src":"PPT Bi2 bild 22","lek":1},{"w":"ATP-driven proteinpump","d":"Membranprotein som pumpar ämnen mot gradienten med energi från hydrolys av ATP.","src":"Bok s. 35 · PPT Transport bild 16"},{"w":"Natrium-kaliumpumpen","d":"ATP-driven pump som håller jonbalansen; tar ungefär 40 % av cellens ATP.","src":"Bok s. 35 · PPT Transport bild 19"},{"w":"Aktiv transport","d":"Transport mot koncentrationsgradienten; kräver energi och ett transportprotein.","src":"Bok s. 34"},{"w":"Kopplad transport","d":"Ett ämne som diffunderar driver ett annat mot dess gradient; kräver ATP indirekt.","src":"Bok s. 34"},{"w":"Tylakoid","d":"Platt membranblåsa i kloroplasten där klorofyllet fångar in solljus.","src":"Bok s. 247"}],"snabb":{"keys":["ATP :: ribos + adenin + tre fosfatgrupper","ADP :: ribos + adenin + två fosfatgrupper","Energirik bindning :: mellan andra och tredje fosfatgruppen","Hydrolys :: ATP + vatten → ADP + fosfat + energi","Återbildning :: ADP + fosfat + energi från födan → ATP","Kreatinfosfat :: kreatinfosfat + ADP → kreatin + ATP","Kreatin :: tillverkas främst i lever och njurar","Kraftverket :: mitokondrien, där de flesta ATP bildas","Inre membranet :: veckat, bär elektrontransportkedjan","Matrix :: enzymer som utvinner energi ur födan","Natrium-kaliumpumpen :: ungefär 40 % av cellens ATP","Kopplad transport :: kräver ATP indirekt"],"nums":[["3","fosfatgrupper i ATP"],["2","fosfatgrupper i ADP"],["ca 40 %","av cellens ATP går till Na/K-pumpen (boken s. 35)"],["10–40 %","av cellens ATP går till Na/K-pumparna (lärarens bild 19)"],["3 Na⁺ ut, 2 K⁺ in","per ATP i Na/K-pumpen (lärarens bild 19)"],["2","membran i mitokondrien"]],"chains":[["Födan","matrix-enzymer utvinner energi","elektrontransportkedjan","ADP + fosfat → ATP","resten spillvärme"],["ATP + vatten","tredje fosfatet lossnar","energi frigörs","driver pumpen","ADP + fosfat kvar"],["Maximalt arbete","ATP tar slut snabbt","kreatinfosfat ger P till ADP","ATP snabbt","bara väldigt kort tid"],["Ingen energi från födan","ADP laddas inte","ATP tar slut","pumparna stannar"],["Na/K-pumpen arbetar","natriumgradient","kopplad transport","kräver ATP indirekt"]],"traps":["Hydrolysen behöver vatten, INTE kreatinfosfat (bild 29 har fel).","Rätt stavning: adenosinTRIfosfat och adenosinDIfosfat.","Det är den TREDJE fosfatgruppen som lossnar.","DE FLESTA ATP bildas i mitokondrien, inte allt.","Det INRE membranet är veckat.","Mitokondriens matrix är inte extracellulär matrix.","Kopplad transport använder ingen ATP direkt men stannar utan ATP."]}},"k7":{"pre":[{"q":"Hur stor del av jordens arter är mikroorganismer enligt boken?","o":["Mer än 90 %","Ungefär 10 %","Ungefär hälften","Mindre än 1 %"],"why":"De allra flesta levande varelser är mikroorganismer, mer än 90 % av alla arter, och de utgör huvuddelen av all biomassa.","src":"s. 178","id":"k7p510s05"},{"q":"Vad orsakar malaria?","o":["Encelliga eukaryoter av släktet Plasmodium","Ett virus som myggan bär på","En bakterie i myggans spott","Myggan själv"],"why":"Plasmodium är encelliga eukaryoter. Myggan är bara bäraren.","src":"s. 179 · PPT Mikroorganismer bild 9–10","id":"k7p1q8qq3f"},{"q":"Vad betyder patogen?","o":["Sjukdomsframkallande","Encellig","Fotosyntetiserande","Nedbrytande"],"why":"Mikroorganismer som lever i kroppen på ett sätt som ger obehag eller skada kallas sjukdomsframkallande eller patogena.","src":"s. 178","id":"k7p1cz4tl6"},{"q":"Är alger växter enligt läraren?","o":["Nej, de är eukaryoter som gör fotosyntes men inte är växter","Ja, alla alger är små växter","Nej, de är bakterier","Ja, men bara de som lever i havet"],"why":"Lärarens definition: eukaryota organismer som utvinner energi ur ljus genom fotosyntes, vanligen lever i vatten och inte är växter.","src":"PPT Mikroorganismer bild 12","id":"k7p18xie5h"},{"q":"Var i människan förökar sig malariaparasiterna först?","o":["I levern","I röda blodkroppar","I hjärnan","I spottkörteln"],"why":"Parasiterna vandrar först till levern. Efter några veckor tar de sig till de röda blodkropparna.","src":"s. 179","id":"k7p1d51es6"}],"cards":[{"f":"Vad är en mikroorganism (mikrob)?","b":"En levande varelse som är så liten att vi inte kan se den med blotta ögat, t.ex. amöbor, jästsvampar, bakterier och arkéer.","ty":"b","src":"s. 178","id":"k7c1qwnoaz"},{"f":"Räknas virus som mikroorganismer?","b":"De brukar räknas dit, men man kan diskutera om virus ska räknas som levande, eftersom de inte har egen ämnesomsättning.","ty":"f","src":"s. 178, 184 · Arbetsblad","p":1,"id":"k7c1t99xc2"},{"f":"Var finns mikroorganismer?","b":"I stort sett överallt: i marken, vattnet, luften, i fuktiga sprickor djupt i jordens inre och på och i alla växter och djur.","ty":"b","src":"s. 178","id":"k7c1r68myc"},{"f":"Hur stor del av alla arter är mikroorganismer?","b":"Mer än 90 %. Dessutom utgör mikroorganismer huvuddelen av all biomassa på jorden.","ty":"s","src":"s. 178","id":"k7cmc4khc"},{"f":"Är de flesta mikroorganismer farliga för oss?","b":"Nej. De flesta är varken farliga eller direkt nyttiga för människan, men de är viktiga delar av ekosystemen.","ty":"f","src":"s. 178","id":"k7cacwu2w"},{"f":"Vilka tre roller i ekosystemen ger boken som exempel?","b":"Mikroskopiska svampar bryter ner döda träd. Bakterier i symbios med rötter hjälper växter att fixera kväve. Arkéer i heta djuphavskällor bildar kolhydrater av oorganiska kemikalier.","ty":"s","src":"s. 178","id":"k7c1nafqs0"},{"f":"Hur kan arkéer livnära hela ekosystem runt heta djuphavskällor?","b":"De utvinner energi ur oorganiska kemikalier från källan och bildar kolhydrater. Kolhydraterna blir föda åt resten av ekosystemet.","ty":"v","src":"s. 178","id":"k7c1fetwp"},{"f":"Hur utnyttjar människan mikroorganismer enligt boken?","b":"Öl och vin, jäsa bröd, filmjölk, rena vatten och bryta ner föroreningar.","ty":"s","src":"s. 178","id":"k7cc70ucq"},{"f":"Vad betyder patogen?","b":"Sjukdomsframkallande. Det gäller mikroorganismer som lever i kroppen på ett sätt som ger obehag eller skada.","ty":"b","src":"s. 178","id":"k7c1cz4tl6"},{"f":"Vilka är livets tre huvudgrupper?","b":"Bakterier, arkéer och eukaryoter.","ty":"s","src":"s. 178 · Arbetsblad lucka 1–3","p":1,"id":"k7cuepwza"},{"f":"Vilka av livets huvudgrupper är mikroorganismer?","b":"Alla bakterier och alla arkéer, och huvuddelen av de eukaryota arterna.","ty":"b","src":"s. 178 · Arbetsblad","p":1,"id":"k7cu1u9yh"},{"f":"Provfälla: är alla eukaryoter mikroorganismer?","b":"Nej, bara huvuddelen av de eukaryota arterna. Du själv är eukaryot men ingen mikroorganism.","ty":"f","src":"s. 178","id":"k7c1tyyata"},{"f":"Vilka två domäner är närmast släkt i lärarens träd?","b":"Arkéer och eukaryoter. Bakterierna grenar av först, och arkéer och eukaryoter har en senare gemensam förfader.","ty":"i","src":"PPT Mikroorganismer bild 20, 36","id":"k7c1qkgxsm"},{"f":"Vad vill lärarens bild av en möglig citrusfrukt visa?","b":"Mögel är mikroskopiska svampar, alltså eukaryota mikroorganismer.","ty":"i","src":"PPT Mikroorganismer bild 2 · s. 178","p":1,"id":"k7cctfw3l"},{"f":"Provfälla: är en koloni av eukaryota mikrober en flercellig kropp?","b":"Nej. Cellerna i kolonin är ganska lika varandra och skulle klara sig utan varandra om det behövdes.","ty":"f","src":"s. 178","id":"k7cgx41gg"},{"f":"Vad gör de encelliga eukaryota algerna i hav och sjöar?","b":"De utför betydande delar av världens fotosyntes.","ty":"b","src":"s. 178 · PPT Mikroorganismer bild 12","p":1,"id":"k7c1m6kxf2"},{"f":"Ge exempel på mikroskopiska svampar och var de finns.","b":"Encellig jäst och små osynliga trådar av mögel. De finns i vatten, jord och på de flesta större levande varelser.","ty":"b","src":"s. 178 · PPT Mikroorganismer bild 2","p":1,"id":"k7cpyvc4p"},{"f":"Vad kallades encelliga eukaryoter förr, och vad gör de?","b":"Encelliga djur. De fångar upp, innesluter och bryter ner energirika livsformer i omgivningen.","ty":"b","src":"s. 178 · PPT Mikroorganismer bild 4","p":1,"id":"k7cgl2gj2"},{"f":"Vad orsakar Entamoeba histolytica?","b":"Blodiga diarréer, amöbadysenteri.","ty":"s","src":"s. 178","id":"k7coq5r7r"},{"f":"Vad orsakar Giardia lamblia, och var lever den t.ex.?","b":"Diarréer och magont. Den lever t.ex. i St Petersburgs vattensystem.","ty":"s","src":"s. 178","id":"k7c1bx2mv4"},{"f":"Vilka tre eukaryota mikroorganismer visar bokens mikroskopbilder?","b":"(a) En amöba i rörelse, (b) svampen Candida och (c) en ciliat där man ser många organeller.","ty":"i","src":"s. 178","id":"k7c1efuv9c"},{"f":"Vad kan släktingar till svampen Candida orsaka?","b":"Infektioner i både underliv och fötter.","ty":"i","src":"s. 178","id":"k7c2iyru4"},{"f":"Vad är protister?","b":"I den äldre systematiken mestadels encelliga organismer med cellkärna.","ty":"b","src":"PPT Mikroorganismer bild 3","id":"k7cwg1ozv"},{"f":"I vilka tre grupper delas protisterna traditionellt?","b":"Protozoer (urdjur), djurliknande. Alger, växtliknande. Slemsvampar, svampliknande.","ty":"s","src":"PPT Mikroorganismer bild 3","id":"k7czg8ot"},{"f":"Vad är urdjur (protozoer)?","b":"Ett samlingsnamn för encelliga eukaryoter med egenskaper som vi förknippar med djur, t.ex. rörlighet och att de saknar fotosyntes.","ty":"b","src":"PPT Mikroorganismer bild 4 · s. 178","p":1,"id":"k7cytti0a"},{"f":"Hur många arter urdjur finns det ungefär?","b":"Ungefär 28 500, indelade i flera stammar.","ty":"s","src":"PPT Mikroorganismer bild 4","id":"k7c1ply8bf"},{"f":"Vilka fyra stammar urdjur tar läraren upp?","b":"Flagellater, amöbadjur, ciliater och spordjur (FACS).","ty":"s","src":"PPT Mikroorganismer bild 5","id":"k7c17ou6uq"},{"f":"Vad kännetecknar flagellaterna (gisseldjuren)?","b":"Piskliknande organeller som ofta används för förflyttning. Många är parasiter som ger allvarliga sjukdomar, t.ex. sömnsjuka.","ty":"b","src":"PPT Mikroorganismer bild 6","id":"k7c1ylispv"},{"f":"Vad lever amöbadjuren (Rhizopoda) av?","b":"Bakterier och andra mikroorganismer.","ty":"b","src":"PPT Mikroorganismer bild 7 · s. 178","p":1,"id":"k7c1v8x6pg"},{"f":"Vad är ciliater, och vilken är en känd art?","b":"Flimmerdjur eller infusionsdjur, frilevande i alla typer av vatten, främst näringsrika. De äter främst bakterier och växtplankton. Känd art: toffeldjuret.","ty":"b","src":"PPT Mikroorganismer bild 8 · s. 178","p":1,"id":"k7c1uiy3fy"},{"f":"Vad kännetecknar spordjuren?","b":"De är huvudsakligen parasiter som tar upp flytande föda genom cellmembranen. Släktet Plasmodium hör hit.","ty":"b","src":"PPT Mikroorganismer bild 10","id":"k7c1qc9x3p"},{"f":"Provfälla: är myggan som sprider malaria ett urdjur?","b":"Nej. Myggan är inget urdjur, men den kan bära på ett, Plasmodium.","ty":"f","src":"PPT Mikroorganismer bild 9 · s. 179","p":1,"id":"k7cfx8emx"},{"f":"Flagellat eller bakteriens flagell?","b":"En flagellat är ett eukaryot urdjur med piskliknande organeller. En flagell är ett utskott på en bakterie.","ty":"j","src":"PPT Mikroorganismer bild 6 · s. 181","id":"k7c1aedimd"},{"f":"Hur många insjuknar och dör i malaria varje år?","b":"Över 200 miljoner insjuknar och över två miljoner dör.","ty":"s","src":"s. 179","id":"k7ceke78d"},{"f":"Vad orsakar malaria, och hur smittas man?","b":"Encelliga eukaryoter av släktet Plasmodium. Man smittas genom stick från en mygga.","ty":"b","src":"s. 179 · PPT Mikroorganismer bild 10","p":1,"id":"k7cimeddt"},{"f":"Malaria steg 1: vad händer i myggan?","b":"Myggan suger blod med könsmogna parasiter av båda könen, och de parar sig med varandra i myggan.","ty":"b","src":"s. 179","id":"k7cfijgcx"},{"f":"Malaria steg 2: hur kommer parasiterna in i människan?","b":"De små avkommorna vandrar till myggans spottkörtel och förs in när myggan biter.","ty":"b","src":"s. 179","id":"k7c1gcuidb"},{"f":"Malaria steg 3: vad gör parasiterna i levern?","b":"De delar sig (förökar sig asexuellt), växer och mognar.","ty":"b","src":"s. 179","id":"k7cmsquf2"},{"f":"Malaria steg 4: vad händer i de röda blodkropparna?","b":"Efter några veckor i levern tar sig parasiterna dit, växer och delar sig i några dagar. Blodkropparna sprängs, och parasiterna infekterar nya blodkroppar.","ty":"b","src":"s. 179","id":"k7c2skv2o"},{"f":"Malaria steg 5: hur kommer parasiterna tillbaka till myggan?","b":"I en del blodkroppar blir de könsmogna. Sugs en sådan upp av en mygga och träffar en parasit av motsatt kön kan processen börja om.","ty":"b","src":"s. 179","id":"k7c1vu58pd"},{"f":"Varför får man feber och frossa vid malaria?","b":"Parasiterna förökar sig i de röda blodkropparna, som sprängs. Parasiterna åker ut i blodet och infekterar nya blodkroppar.","ty":"v","src":"s. 179","id":"k7cf76ibq"},{"f":"Vilka symtom kan malaria ge förutom feber och frossa?","b":"Muskelvärk, diarréer, kräkningar och blodbrist.","ty":"s","src":"s. 179","id":"k7cfm5664"},{"f":"Provfälla: var förökar sig malariaparasiterna sexuellt och var asexuellt?","b":"De parar sig i myggan. I människan delar de sig, alltså förökar sig asexuellt.","ty":"f","src":"s. 179","id":"k7cure2pr"},{"f":"Var finns malaria i dag, och hur var det förr?","b":"Främst i tropiska trakter. Senaste smittan i Sverige var i början av 1900-talet, och fram till 1930-talet var malaria vanlig norr om Medelhavet.","ty":"s","src":"s. 179","id":"k7cekkc20"},{"f":"Vilka etiketter har bokens figur över Plasmodiums livscykel?","b":"MYGGA, MÄNNISKA, myggans spottkörtel, myggbett (två gånger), parasit, levercell och röd blodkropp, plus siffrorna 1–5 och symbolerna för hane och hona.","ty":"i","src":"s. 179","id":"k7c1ojhkez"},{"f":"Hur definierar läraren alger?","b":"Eukaryota organismer som utvinner energi ur ljus genom fotosyntes, vanligen lever i vatten och inte är växter.","ty":"b","src":"PPT Mikroorganismer bild 12","id":"k7c1jrr3ll"},{"f":"Varifrån kommer algernas förmåga till fotosyntes enligt läraren?","b":"Den härstammar evolutionärt från cyanobakterierna.","ty":"b","t":["endo"],"src":"PPT Mikroorganismer bild 12","id":"k7c1uwygzp"},{"f":"Hur stor del av den globala syreproduktionen står algerna för enligt läraren?","b":"Omkring 73–87 %. Boken säger i stället att bakterierna står för huvuddelen av fotosyntesen i havet.","ty":"s","src":"PPT Mikroorganismer bild 12 · s. 186","id":"k7c1cn9ov4"},{"f":"Alger eller cyanobakterier: vad är skillnaden?","b":"Alger är eukaryoter med cellkärna. Cyanobakterier är bakterier utan cellkärna, som förr kallades blågröna alger. Båda gör fotosyntes.","ty":"j","src":"s. 178, 181 · PPT Mikroorganismer bild 12, 34","p":1,"id":"k7c1qa3kp8"},{"f":"Vilka är slemsvampens fyra livsstadier?","b":"Spor, gamet, plasmoid och fruktkropp (S-G-P-F).","ty":"s","src":"PPT Mikroorganismer bild 14","id":"k7cx92q07"},{"f":"Vad är en gamet och vad är en zygot?","b":"En gamet är en könscell med enkel kromosomuppsättning. En zygot är cellen som bildas när två gameter förenas vid befruktning.","ty":"b","src":"PPT Mikroorganismer bild 14","id":"k7c14ycnwj"},{"f":"Vad är slemsvampens plasmoid (plasmodium)?","b":"En supercell som lever i förnan, i multnande organiskt material. Den äter genom att innesluta födan och lösa upp den och rör sig ungefär 1 mm per timme.","ty":"b","src":"PPT Mikroorganismer bild 15","id":"k7c19axxbs"},{"f":"När bildas slemsvampens fruktkropp?","b":"Vid näringsbrist. Det är det sista stadiet.","ty":"b","src":"PPT Mikroorganismer bild 15","id":"k7c1se8zjt"},{"f":"Vilken slemsvamp visar läraren med namn?","b":"Vargmjölk, små rosa-orange kulor på murket trä.","ty":"i","src":"PPT Mikroorganismer bild 17","id":"k7cy550ua"},{"f":"Plasmodium, plasmoid, plasmid: vad är vad?","b":"Plasmodium = släktet som ger malaria. Plasmoid (plasmodium) = slemsvampens supercell. Plasmid = bakteriens extra DNA-ring.","ty":"j","src":"s. 179, 182 · PPT Mikroorganismer bild 10, 15","id":"k7co1zx60"}],"quiz":{"f":[{"q":"Vilket av följande nämner boken som exempel på mikroorganismer?","o":["Amöbor och jästsvampar","Myggor och fästingar","Mossor och lavar","Maskar och kvalster"],"why":"Boken: amöbor, jästsvampar och miljontals bakterier och arkéer.","src":"s. 178","id":"k7q18v8u9o"},{"q":"Var finns mikroorganismer enligt boken?","o":["I stort sett överallt, även djupt i jordens inre","Bara i vatten","Bara i och på djur","Bara i varma miljöer"],"why":"I marken, vattnet, luften, fuktiga sprickor djupt i jordens inre och på och i alla växter och djur.","src":"s. 178","id":"k7qsu9nea"},{"q":"Vad utgör huvuddelen av all biomassa på jorden?","o":["Mikroorganismer","Träd","Insekter","Människor och husdjur"],"why":"Boken: huvuddelen av all biomassa utgörs av mikroorganismer.","src":"s. 178","id":"k7q14pvu6t"},{"q":"Vilka mikroorganismer bryter ner döda träd enligt boken?","o":["Mikroskopiska svampar","Arkéer","Ciliater","Virus"],"why":"Mikroskopiska svampar bryter ner döda träd.","src":"s. 178","id":"k7q1y14mja"},{"q":"Vilka mikroorganismer hjälper växter att fixera kväve från luften?","o":["Bakterier i symbios med rötter","Arkéer i djuphavskällor","Alger på bladen","Jästsvampar i jorden"],"why":"Bakterier lever i symbios med rötter och hjälper växter att fixera kväve.","src":"s. 178","id":"k7q18unonb"},{"q":"Vilket nämner boken INTE som ett sätt människan utnyttjar mikroorganismer?","o":["Att göra plast av sand","Att jäsa bröd","Att göra filmjölk","Att bryta ner föroreningar"],"why":"Boken: öl och vin, bröd, filmjölk, rena vatten och bryta ner föroreningar.","src":"s. 178","id":"k7q15yajqk"},{"q":"Vilka tre huvudgrupper delas allt levande in i?","o":["Bakterier, arkéer och eukaryoter","Bakterier, virus och eukaryoter","Djur, växter och svampar","Prokaryoter, virus och alger"],"why":"Boken och arbetsbladet (lucka 1–3): bakterier, arkéer och eukaryoter.","src":"s. 178 · Arbetsblad lucka 1–3","id":"k7qrvnz6e"},{"q":"Vilken organism orsakar blodiga diarréer (amöbadysenteri)?","o":["Entamoeba histolytica","Giardia lamblia","Plasmodium","Candida"],"why":"Entamoeba är en amöba, därav amöbadysenteri. Giardia ger diarréer och magont.","src":"s. 178","id":"k7qg952ht"},{"q":"Vilken encellig eukaryot lever t.ex. i St Petersburgs vattensystem?","o":["Giardia lamblia","Entamoeba histolytica","Plasmodium","Toffeldjuret"],"why":"Giardia lamblia ger diarréer och magont.","src":"s. 178","id":"k7q1jca3g"},{"q":"Vad visar bokens bild (b)?","o":["Svampen Candida","En ciliat","En amöba i rörelse","En malariaparasit"],"why":"(a) amöba, (b) svampen Candida, (c) ciliat.","src":"s. 178","id":"k7q1aqkneu"},{"q":"Hur många arter urdjur finns det ungefär enligt läraren?","o":["28 500","2 850","285 000","2,8 miljoner"],"why":"Lärarens bild 4: ungefär 28 500 arter i flera stammar.","src":"PPT Mikroorganismer bild 4","id":"k7q1v1wgf4"},{"q":"Vilken stam urdjur har piskliknande organeller och ger t.ex. sömnsjuka?","o":["Flagellater","Ciliater","Amöbadjur","Spordjur"],"why":"Flagellater (gisseldjur) rör sig med piskliknande organeller.","src":"PPT Mikroorganismer bild 6","id":"k7qm40pgg"},{"q":"Vilket urdjur är en känd ciliat?","o":["Toffeldjuret","Plasmodium","Giardia","Vargmjölk"],"why":"Ciliater (flimmerdjur) äter bakterier och växtplankton. Toffeldjuret är den kända arten.","src":"PPT Mikroorganismer bild 8","id":"k7q1qkhvpv"},{"q":"Till vilken stam urdjur hör Plasmodium enligt läraren?","o":["Spordjur","Flagellater","Ciliater","Amöbadjur"],"why":"Spordjur är parasiter som tar upp flytande föda genom cellmembranen. Plasmodium sprids med blodsugande myggor.","src":"PPT Mikroorganismer bild 10","id":"k7qbuaxof"},{"q":"Hur många insjuknar i malaria varje år enligt boken?","o":["Över 200 miljoner","Över 2 miljoner","Ungefär 20 000","Över 2 miljarder"],"why":"Över 200 miljoner insjuknar och över två miljoner dör.","src":"s. 179","id":"k7q6gy3nv"},{"q":"Var hamnar malariaparasiterna först när de kommit in i människan?","o":["I levern","I röda blodkroppar","I lungorna","I spottkörteln"],"why":"De vandrar till levern och delar sig, växer och mognar där i några veckor.","src":"s. 179","id":"k7q6x57yx"},{"q":"När smittades den senaste personen i Sverige av malaria genom myggbett?","o":["I början av 1900-talet","I början av 1800-talet","På 1970-talet","Det har aldrig hänt"],"why":"Boken: början av 1900-talet. Norr om Medelhavet var malaria vanlig fram till 1930-talet.","src":"s. 179","id":"k7qz8d1xb"},{"q":"Hur stor del av den globala syreproduktionen står algerna för enligt läraren?","o":["Omkring 73–87 %","Omkring 10 %","Omkring 40 %","Nästan 100 %"],"why":"Lärarens bild 12. Boken säger att bakterierna står för huvuddelen av fotosyntesen i havet, så märk siffran som lärarens.","src":"PPT Mikroorganismer bild 12","id":"k7q1cn9ov4"},{"q":"Vilket är slemsvampens sista livsstadium?","o":["Fruktkropp","Spor","Gamet","Plasmoid"],"why":"Spor → gamet → plasmoid → fruktkropp. Fruktkroppen bildas vid näringsbrist.","src":"PPT Mikroorganismer bild 14–15","id":"k7q1wey4xm"},{"q":"Hur snabbt rör sig slemsvampens plasmoid normalt?","o":["Ungefär 1 mm per timme","Ungefär 1 cm per sekund","Ungefär 1 m per dag","Den rör sig inte"],"why":"Lärarens bild 15: ungefär en millimeter per timme.","src":"PPT Mikroorganismer bild 15","id":"k7q14288r2"}],"u":[{"q":"Varför kan arkéer runt heta djuphavskällor bära ett helt ekosystem utan solljus?","o":["De bildar kolhydrater med energi ur oorganiska kemikalier","De gör fotosyntes med värmen","De äter döda träd som sjunker ner","De lever på virus"],"why":"Arkéerna utvinner energi ur kemikalierna och bildar kolhydrater, som blir föda för resten av ekosystemet.","src":"s. 178","id":"k7qes2hk"},{"q":"Varför kallas Plasmodium, Entamoeba och Giardia för patogena?","o":["De lever i kroppen på ett sätt som ger obehag eller skada","De gör fotosyntes","De är bakterier","De sprids alltid med myggor"],"why":"Patogen betyder sjukdomsframkallande.","src":"s. 178","id":"k7q193ue9a"},{"q":"En patient har fått malaria. Vilken typ av organism orsakar sjukdomen?","o":["En encellig eukaryot","En bakterie","Ett virus","En svamp"],"why":"Plasmodium är en encellig eukaryot. Myggan är bara bäraren.","src":"s. 179","id":"k7q1o9ffwf"},{"q":"Varför ses en koloni av mikroskopiska eukaryoter inte som en flercellig organism?","o":["Cellerna är ganska lika och skulle klara sig utan varandra","Cellerna saknar cellkärna","Cellerna är olika specialiserade","Kolonin har inget cellmembran"],"why":"I en flercellig organism är cellerna specialiserade och beroende av varandra.","src":"s. 178","id":"k7q5twor9"},{"q":"Varför stämmer bilden av urdjur som djurliknande?","o":["De är rörliga och saknar fotosyntes","De är flercelliga","De har skelett","De föder levande ungar"],"why":"Lärarens definition: egenskaper som vi förknippar med djur, t.ex. rörlighet och avsaknad av fotosyntes.","src":"PPT Mikroorganismer bild 4","id":"k7q107z2g"},{"q":"Varför får malariapatienter återkommande feber och frossa?","o":["Parasiterna spränger röda blodkroppar och infekterar nya","Myggan sprutar in gift","Levern slutar fungera","Parasiterna parar sig i blodet"],"why":"Varje gång blodkropparna sprängs åker parasiterna ut i blodet och infekterar nya blodkroppar.","src":"s. 179","id":"k7qlw2z9"},{"q":"Varför kan en mygga som biter en malariasjuk människa bli smittbärare?","o":["Den suger upp könsmogna parasiter som parar sig i den","Den suger upp leverceller med parasiter","Viruset i blodet förökar sig i myggan","Myggan blir själv ett urdjur"],"why":"I en del blodkroppar blir parasiterna könsmogna. I myggan parar de sig, och avkommorna går till spottkörteln.","src":"s. 179","id":"k7qvsrvdy"},{"q":"Varför kan malaria ge blodbrist?","o":["Många röda blodkroppar sprängs av parasiterna","Myggan suger för mycket blod","Levern bildar inga blodkroppar","Parasiterna äter järn i maten"],"why":"Parasiterna förökar sig i de röda blodkropparna, som sprängs och förstörs.","src":"s. 179","id":"k7qot91o9"},{"q":"Varför är namnet blågröna alger missvisande för cyanobakterier?","o":["De är bakterier utan cellkärna, inte eukaryota alger","De är växter","De gör inte fotosyntes","De är virus"],"why":"Alger är eukaryoter. Cyanobakterier är prokaryoter, även om båda gör fotosyntes.","src":"s. 181 · PPT Mikroorganismer bild 12, 34","id":"k7qu32scx"},{"q":"Varför räknas alger inte som växter fast de gör fotosyntes?","o":["Läraren definierar alger som eukaryoter som gör fotosyntes men inte är växter","De saknar cellkärna","De lever bara på land","De gör fotosyntes utan ljus"],"why":"Lärarens definition skiljer alger från växter. De är protister, den växtliknande gruppen.","src":"PPT Mikroorganismer bild 3, 12","id":"k7q150sa65"},{"q":"Vad utlöser att slemsvampen bildar en fruktkropp?","o":["Näringsbrist","Att gameterna smälter samman","Att sporen gror","Att det blir varmt"],"why":"Fruktkroppen är det sista stadiet och bildas vid näringsbrist.","src":"PPT Mikroorganismer bild 15","id":"k7qf53rln"},{"q":"Vilket påstående om virus och mikroorganismer stämmer med boken?","o":["Virus räknas ofta dit, men det är omdiskuterat om de lever","Virus är en av livets tre huvudgrupper","Virus är eukaryoter","Virus har egen ämnesomsättning"],"why":"Livets tre huvudgrupper är bakterier, arkéer och eukaryoter. Virus saknar egen ämnesomsättning.","src":"s. 178, 184","id":"k7q15qvrm5"},{"q":"Hur hänger lärarens urdjur ihop med bokens text?","o":["Bokens encelliga eukaryoter (förr encelliga djur) är samma grupp","Urdjur är bakterier i boken","Boken kallar dem alger","Urdjur nämns inte alls i boken"],"why":"Boken: encelliga eukaryoter, tidigare kallade encelliga djur, som fångar upp och bryter ner andra livsformer.","src":"s. 178 · PPT Mikroorganismer bild 4","id":"k7q8v1glj"}],"o":[{"q":"Beskriv Plasmodiums livscykel och förklara varför man får feber och frossa.","model":"1. En mygga suger blod med könsmogna parasiter av båda könen, som parar sig i myggan. 2. De små avkommorna vandrar till myggans spottkörtel och förs in i människan vid ett bett. 3. I levern delar de sig asexuellt, växer och mognar. 4. Efter några veckor tar de sig till röda blodkroppar, växer och delar sig, och blodkropparna sprängs. Parasiterna infekterar nya blodkroppar. 5. Vissa blir könsmogna och kan sugas upp av en ny mygga. Feber och frossa kommer av att blodkropparna sprängs och parasiterna åker ut i blodet och infekterar nya.","kw":[["mygga"],["spottkörtel"],["lever"],["blodkropp"],["spräng"],["könsmogn","para"],["feber","frossa"]],"src":"s. 179","id":"k7o1hhm6p0"},{"q":"Vad är mikroorganismer? Beskriv var de finns, hur vanliga de är och ge exempel på deras betydelse för ekosystemen och för människan.","model":"Mikroorganismer är levande varelser som är för små för att ses med blotta ögat, t.ex. amöbor, jästsvampar, bakterier och arkéer. Virus räknas ofta dit, men det är omdiskuterat om de lever. De finns nästan överallt och utgör mer än 90 % av alla arter och huvuddelen av all biomassa. Svampar bryter ner döda träd, bakterier i symbios med rötter hjälper växter att fixera kväve och arkéer i heta djuphavskällor bildar kolhydrater som föder hela ekosystem. Människan använder dem till öl, vin, bröd, filmjölk, vattenrening och nedbrytning av föroreningar. Några är patogena.","kw":[["blotta ögat","små"],["90"],["biomassa"],["kväve","träd","djuphav"],["bröd","öl","filmjölk"],["patogen","sjukdom"]],"src":"s. 178","id":"k7o8dyhf7"},{"q":"Beskriv de eukaryota mikroorganismerna. Använd både bokens och lärarens indelning och ge exempel på sjukdomar de orsakar.","model":"Boken nämner encelliga alger som gör betydande delar av världens fotosyntes, mikroskopiska svampar som jäst och mögel, och encelliga eukaryoter (förr encelliga djur) som fångar upp och bryter ner andra livsformer. Läraren kallar dem protister och delar in dem i urdjur, alger och slemsvampar. Urdjuren har fyra stammar: flagellater, amöbadjur, ciliater och spordjur. Plasmodium (spordjur) ger malaria, Entamoeba histolytica ger blodiga diarréer och Giardia lamblia ger diarréer och magont.","kw":[["alger"],["svamp","jäst","mögel"],["urdjur","protozo"],["slemsvamp"],["plasmodium","malaria"],["entamoeba","giardia"]],"src":"s. 178 · PPT Mikroorganismer bild 3–10","id":"k7o1uhg9y6"},{"q":"Beskriv slemsvampens livscykel och förklara skillnaden mellan Plasmodium, plasmoid och plasmid.","model":"Slemsvampen har fyra livsstadier. Sporen är en överlevare som sprids lätt. Ur en mogen spor föds gameter med enkel kromosomuppsättning, som smälter samman parvis till zygoter. Zygoterna förenas till plasmodier, en supercell som lever i förnan, äter genom att innesluta och lösa upp födan och rör sig ungefär en millimeter i timmen. Vid näringsbrist bildas en fruktkropp. Plasmodium är också namnet på släktet som ger malaria, plasmoid är slemsvampens supercell och plasmid är bakteriens extra DNA-ring.","kw":[["spor"],["gamet"],["zygot"],["förna"],["fruktkropp","näringsbrist"],["malaria"],["plasmid","bakterie"]],"src":"PPT Mikroorganismer bild 14–15 · s. 179, 182","id":"k7oher9go"}]},"kan":[{"q":"Kan du förklara vad mikroorganismer är, var de finns och hur många de är?","a":"Mikroorganismer, eller mikrober, är levande varelser som är för små för att ses med blotta ögat, t.ex. amöbor, jästsvampar, bakterier och arkéer. Virus räknas ofta dit, men det är omdiskuterat om de lever. Mikroorganismer finns i stort sett överallt: i marken, vattnet, luften, i fuktiga sprickor djupt i jordens inre och på och i alla växter och djur. Mer än 90 % av alla arter är mikroorganismer, och de utgör huvuddelen av jordens biomassa.","kw":[["blotta ögat","för små","små"],["virus"],["överallt","mark","luft"],["90"],["biomassa"]],"src":"s. 178","id":"k7kur4dt2"},{"q":"Kan du ge tre exempel på mikroorganismers roller i ekosystemen och några exempel på hur människan använder dem?","a":"Mikroskopiska svampar bryter ner döda träd. Bakterier lever i symbios med rötter och hjälper växter att fixera kväve från luften. Arkéer i heta djuphavskällor utvinner energi ur oorganiska kemikalier och bildar kolhydrater, och därför kan de livnära hela ekosystem runt källorna. Människan använder mikroorganismer för öl och vin, för att jäsa bröd, göra filmjölk, rena vatten och bryta ner föroreningar.","kw":[["svamp","träd"],["kväve"],["arkéer","djuphav"],["kolhydrat"],["öl","vin","bröd","filmjölk"],["rena vatten","förorening"]],"src":"s. 178","id":"k7ktfms45"},{"q":"Kan du förklara hur mikroorganismerna fördelar sig på livets tre huvudgrupper?","a":"Allt levande delas in i bakterier, arkéer och eukaryoter. Alla bakterier och alla arkéer är mikroorganismer, liksom huvuddelen av de eukaryota arterna. Virus hör inte till någon av huvudgrupperna, eftersom det är omdiskuterat om de alls lever. Lärarens träd visar att bakterierna grenar av först och att arkéer och eukaryoter är närmast släkt.","kw":[["bakterier"],["arkéer"],["eukaryot"],["alla"],["huvuddel","de flesta"],["virus"]],"src":"s. 178 · Arbetsblad lucka 1–3 · PPT bild 20","id":"k7k1g7q2z0"},{"q":"Kan du beskriva vilka sorters eukaryota mikroorganismer boken nämner?","a":"Mikroskopiska eukaryoter lever ensamma eller i små kolonier eller trådar, där cellerna är ganska lika varandra och skulle klara sig utan varandra. I hav och sjöar finns stora mängder encelliga eukaryota alger som gör betydande delar av världens fotosyntes. Mikroskopiska svampar, t.ex. encellig jäst och mögeltrådar, finns i vatten, jord och på de flesta större levande varelser. Encelliga eukaryoter, tidigare kallade encelliga djur, fångar upp, innesluter och bryter ner energirika livsformer.","kw":[["koloni","trådar"],["alger"],["fotosyntes"],["svamp","jäst","mögel"],["encelliga djur"],["innesluter","fångar"]],"src":"s. 178","id":"k7k118rzls"},{"q":"Kan du nämna tre sjukdomsframkallande encelliga eukaryoter och vad de orsakar?","a":"Olika arter av släktet Plasmodium orsakar malaria och sprids med myggor. Entamoeba histolytica orsakar blodiga diarréer, amöbadysenteri. Giardia lamblia, som t.ex. lever i St Petersburgs vattensystem, ger diarréer och magont.","kw":[["plasmodium"],["malaria"],["entamoeba"],["blodig","amöbadysenteri"],["giardia"],["magont"]],"src":"s. 178","id":"k7keap94"},{"q":"Kan du beskriva lärarens indelning av protisterna?","a":"Protister är i den äldre systematiken mestadels encelliga organismer med cellkärna. De delas traditionellt i tre grupper: protozoer (urdjur), som är djurliknande, alger, som är växtliknande, och slemsvampar, som är svampliknande. Urdjur är rörliga och saknar fotosyntes, och det finns ungefär 28 500 arter i flera stammar.","kw":[["cellkärna","encellig"],["urdjur","protozo"],["alger"],["slemsvamp"],["djurlik","växtlik","svamplik"],["28 500","28500"]],"src":"PPT Mikroorganismer bild 3–4","id":"k7krne08b"},{"q":"Kan du nämna urdjurens fyra stammar som läraren tar upp, med ett kännetecken för varje?","a":"Flagellater (gisseldjur) har piskliknande organeller för förflyttning, och många är parasiter som ger t.ex. sömnsjuka. Amöbadjur (Rhizopoda) lever av bakterier och andra mikroorganismer. Ciliater (flimmerdjur, infusionsdjur) lever fritt i vatten och äter bakterier och växtplankton, t.ex. toffeldjuret. Spordjur är parasiter som tar upp flytande föda genom cellmembranen, t.ex. Plasmodium som ger malaria.","kw":[["flagellat","gissel"],["sömnsjuka"],["amöba"],["ciliat","flimmer"],["toffeldjur"],["spordjur"]],"src":"PPT Mikroorganismer bild 5–10","id":"k7k1wn1beq"},{"q":"Kan du beskriva malariaparasitens livscykel i fem steg?","a":"1. En mygga suger blod med könsmogna parasiter av båda könen, och de parar sig i myggan. 2. De små avkommorna vandrar till myggans spottkörtel och förs in i en människa vid ett bett. 3. Parasiterna vandrar till levern, där de delar sig asexuellt, växer och mognar. 4. Efter några veckor tar de sig till röda blodkroppar, växer, delar sig, och blodkropparna sprängs. Parasiterna infekterar nya blodkroppar. 5. I en del blodkroppar blir parasiterna könsmogna, och om en mygga suger upp dem kan cykeln börja om.","kw":[["para","könsmogn"],["spottkörtel"],["lever"],["röda blodkropp"],["spräng"],["mygga"]],"src":"s. 179","id":"k7kqruz0d"},{"q":"Kan du jämföra alger och cyanobakterier?","a":"Alger är eukaryoter med cellkärna som gör fotosyntes, vanligen lever i vatten och inte är växter. Cyanobakterier är bakterier utan cellkärna som också gör fotosyntes. De kallades förr blågröna alger, men de är inte alls alger. Enligt läraren härstammar algernas förmåga till fotosyntes från cyanobakterierna, och algerna står för omkring 73–87 % av den globala syreproduktionen.","kw":[["eukaryot"],["bakterie"],["cellkärna"],["fotosyntes"],["blågröna"],["73","87"]],"src":"s. 178, 181 · PPT Mikroorganismer bild 12, 34","id":"k7kx4tyzz"},{"q":"Kan du beskriva slemsvampens fyra livsstadier?","a":"Sporen är en överlevare som sprids lätt. Ur en mogen spor föds gameter, könsceller med enkel kromosomuppsättning. De smälter samman parvis till zygoter, som förenar sig med andra zygoter till plasmodier. Plasmoiden är en supercell som lever i förnan, äter genom att innesluta födan och lösa upp den och rör sig ungefär en millimeter per timme. Vid näringsbrist bildas det sista stadiet, fruktkroppen.","kw":[["spor"],["gamet"],["zygot"],["plasmoid","plasmodi"],["förna"],["fruktkropp"],["näringsbrist"]],"src":"PPT Mikroorganismer bild 14–15","id":"k7k56ytbw"}],"kompis":[{"q":"Förklara för en kompis hur malariaparasiten tar sig från mygga till människa och tillbaka.","model":"I myggan parar sig könsmogna parasiter av båda könen. Avkommorna är mycket små och vandrar till myggans spottkörtel. När myggan biter en människa förs de in i blodet och vandrar till levern. Där delar de sig asexuellt, växer och mognar. Efter några veckor tar de sig till de röda blodkropparna, växer och delar sig, och blodkropparna sprängs. Parasiterna åker ut i blodet och infekterar nya blodkroppar. I en del blodkroppar blir de könsmogna, och när en ny mygga suger blod tar den upp dem. Träffar de en parasit av motsatt kön börjar cykeln om.","kw":[["para","könsmogn"],["spottkörtel"],["bett","biter","stick"],["lever"],["blodkropp"],["spräng"],["mygga"]],"src":"s. 179","id":"k7eplepbj"},{"q":"Förklara för en kompis varför man får feber och frossa vid malaria och varför man kan få blodbrist.","model":"Parasiterna växer och delar sig inne i de röda blodkropparna. Efter några dagar sprängs blodkropparna, och parasiterna åker ut i blodet och infekterar nya blodkroppar. Det leder till feber och frossa, och ibland muskelvärk, diarréer och kräkningar. Eftersom många röda blodkroppar förstörs när de sprängs kan man också få blodbrist.","kw":[["blodkropp"],["spräng"],["nya"],["feber"],["frossa"],["blodbrist"]],"src":"s. 179","id":"k7e1dm1vs3"},{"q":"Förklara för en kompis varför cyanobakterier inte är alger fast de kallades blågröna alger.","model":"Cyanobakterier är bakterier, alltså prokaryoter utan cellkärna. Alger är eukaryoter med cellkärna som gör fotosyntes och inte är växter. Båda gör fotosyntes, och därför trodde man förr att cyanobakterierna var alger. Läraren säger att algernas förmåga till fotosyntes härstammar evolutionärt från cyanobakterierna, och boken säger att kloroplasten troligen uppkommit genom endosymbios, precis som mitokondrien.","kw":[["bakterie","prokaryot"],["eukaryot"],["cellkärna"],["fotosyntes"],["härstamma","endosymbios"]],"src":"s. 178, 181 · PPT Mikroorganismer bild 12, 34","t":["endo"],"id":"k7e1tcwtkb"}],"gloss":[{"w":"Alger","d":"Eukaryota organismer som utvinner energi ur ljus genom fotosyntes, vanligen lever i vatten och inte är växter.","src":"PPT Mikroorganismer bild 12 · Bok s. 178"},{"w":"Amöbadjur (Rhizopoda)","d":"Stam urdjur som lever av bakterier och andra mikroorganismer.","src":"PPT Mikroorganismer bild 7","lek":1},{"w":"Amöbadysenteri","d":"Blodiga diarréer som orsakas av Entamoeba histolytica.","src":"Bok s. 178"},{"w":"Arkéer","d":"En av livets tre huvudgrupper. Alla arkéer är mikroorganismer.","src":"Bok s. 178"},{"w":"Asexuell förökning","d":"Förökning genom delning, utan parning. Malariaparasiten förökar sig så i levern.","src":"Bok s. 179"},{"w":"Bakterier","d":"En av livets tre huvudgrupper. Alla bakterier är mikroorganismer.","src":"Bok s. 178"},{"w":"Biomassa","d":"Mängden levande material. Huvuddelen av jordens biomassa är mikroorganismer.","src":"Bok s. 178"},{"w":"Candida","d":"Svamp vars släktingar kan ge infektioner i underliv och fötter.","src":"Bok s. 178"},{"w":"Ciliater","d":"Flimmerdjur eller infusionsdjur. Frilevande urdjur i vatten som äter bakterier och växtplankton, t.ex. toffeldjuret.","src":"PPT Mikroorganismer bild 8 · Bok s. 178"},{"w":"Cyanobakterier","d":"Fotosyntetiserande bakterier, förr kallade blågröna alger.","src":"Bok s. 181 · PPT Mikroorganismer bild 12, 34"},{"w":"Domän","d":"Livets största grupper i lärarens träd: bakterier, arkéer och eukaryoter.","src":"PPT Mikroorganismer bild 20","lek":1},{"w":"Encelliga djur","d":"Gammalt namn på encelliga eukaryoter som fångar upp och bryter ner andra livsformer.","src":"Bok s. 178"},{"w":"Entamoeba histolytica","d":"Encellig eukaryot (amöba) som orsakar blodiga diarréer, amöbadysenteri.","src":"Bok s. 178"},{"w":"Eukaryoter","d":"Organismer med cellkärna. Huvuddelen av de eukaryota arterna är mikroorganismer.","src":"Bok s. 178"},{"w":"Flagellater (gisseldjur)","d":"Stam urdjur med piskliknande organeller för förflyttning. Många är parasiter, t.ex. vid sömnsjuka.","src":"PPT Mikroorganismer bild 6","lek":1},{"w":"Förna","d":"Multnande organiskt material där slemsvampens plasmoid lever.","src":"PPT Mikroorganismer bild 15","lek":1},{"w":"Fruktkropp","d":"Slemsvampens sista stadium, bildas vid näringsbrist.","src":"PPT Mikroorganismer bild 15","lek":1},{"w":"Gamet","d":"Könscell med enkel kromosomuppsättning.","src":"PPT Mikroorganismer bild 14","lek":1},{"w":"Giardia lamblia","d":"Encellig eukaryot som ger diarréer och magont, lever t.ex. i St Petersburgs vattensystem.","src":"Bok s. 178"},{"w":"Jäst","d":"Encellig mikroskopisk svamp.","src":"Bok s. 178"},{"w":"Koloni","d":"Celler som sitter ihop men är ganska lika och skulle klara sig utan varandra.","src":"Bok s. 178"},{"w":"Malaria","d":"Sjukdom som orsakas av Plasmodium och sprids med myggor. Över 200 miljoner insjuknar varje år.","src":"Bok s. 179"},{"w":"Mikroorganism (mikrob)","d":"Levande varelse som är för liten för att ses med blotta ögat.","src":"Bok s. 178"},{"w":"Mögel","d":"Små osynliga trådar av mikroskopiska svampar.","src":"Bok s. 178"},{"w":"Patogen","d":"Sjukdomsframkallande.","src":"Bok s. 178"},{"w":"Plasmodium (släkte)","d":"Släkte encelliga eukaryoter (spordjur) som orsakar malaria.","src":"Bok s. 178–179 · PPT Mikroorganismer bild 10"},{"w":"Plasmoid (plasmodium)","d":"Slemsvampens supercell i förnan som äter genom att innesluta födan. Rör sig ca 1 mm per timme.","src":"PPT Mikroorganismer bild 15","lek":1},{"w":"Protister (Protista)","d":"I äldre systematik mestadels encelliga organismer med cellkärna: urdjur, alger och slemsvampar.","src":"PPT Mikroorganismer bild 3","lek":1},{"w":"Slemsvampar","d":"Svampliknande protister med fyra livsstadier: spor, gamet, plasmoid och fruktkropp.","src":"PPT Mikroorganismer bild 13–15","lek":1},{"w":"Spor (slemsvamp)","d":"Slemsvampens överlevnadsstadium, som sprids lätt.","src":"PPT Mikroorganismer bild 14","lek":1},{"w":"Spordjur","d":"Stam urdjur, huvudsakligen parasiter som tar upp flytande föda genom cellmembranen, t.ex. Plasmodium.","src":"PPT Mikroorganismer bild 10","lek":1},{"w":"Spottkörtel","d":"Myggans körtel dit malariaparasitens avkommor vandrar innan de förs in i människan.","src":"Bok s. 179"},{"w":"Toffeldjur","d":"Känd art av ciliater.","src":"PPT Mikroorganismer bild 8","lek":1},{"w":"Urdjur (protozoer)","d":"Encelliga eukaryoter med djurliknande egenskaper, t.ex. rörlighet och ingen fotosyntes. Ca 28 500 arter.","src":"PPT Mikroorganismer bild 4","lek":1},{"w":"Vargmjölk","d":"Slemsvamp, små rosa-orange kulor på murket trä.","src":"PPT Mikroorganismer bild 17","lek":1},{"w":"Virus","d":"Räknas ofta till mikroorganismerna, men det är omdiskuterat om de lever, eftersom de saknar egen ämnesomsättning.","src":"Bok s. 178"},{"w":"Zygot","d":"Cellen som bildas när två gameter förenas vid befruktning.","src":"PPT Mikroorganismer bild 14","lek":1}],"snabb":{"keys":["Mikroorganism :: för liten för blotta ögat; > 90 % av arterna, huvuddelen av biomassan","Virus :: räknas ofta dit, men lever de? (ingen egen ämnesomsättning)","Tre huvudgrupper :: bakterier (alla mikrober), arkéer (alla), eukaryoter (huvuddelen)","Roller i ekosystem :: svampar bryter ner träd, bakterier fixerar kväve, arkéer bildar kolhydrater vid djuphavskällor","Patogen :: sjukdomsframkallande","Eukaryota mikrober :: alger, mikroskopiska svampar (jäst, mögel), encelliga eukaryoter (förr encelliga djur)","Plasmodium / Entamoeba / Giardia :: malaria / blodig diarré (amöbadysenteri) / diarré och magont","Protister :: urdjur (djurliknande), alger (växtliknande), slemsvampar (svampliknande)","Urdjurens stammar :: flagellater, amöbadjur, ciliater, spordjur (FACS)","Malaria :: mygga (parning) → spottkörtel → lever (asexuell delning) → röda blodkroppar sprängs → könsmogna → mygga","Alger :: eukaryoter med fotosyntes, inte växter; fotosyntesen kommer från cyanobakterier","Slemsvamp :: spor → gamet → plasmoid → fruktkropp (vid näringsbrist)"],"nums":[["> 90 %","av alla arter är mikroorganismer (s. 178)"],["3","huvudgrupper: bakterier, arkéer, eukaryoter (s. 178)"],["> 200 miljoner","insjuknar i malaria varje år (s. 179)"],["> 2 miljoner","dör i malaria varje år (s. 179)"],["5","steg i Plasmodiums livscykel (s. 179)"],["några veckor","i levern innan parasiterna går till blodet (s. 179)"],["början av 1900-talet","senaste malariasmittan i Sverige (s. 179)"],["1930-talet","malaria vanlig norr om Medelhavet fram till dess (s. 179)"],["≈ 28 500","arter urdjur (PPT bild 4)"],["4","stammar urdjur som läraren tar upp (PPT bild 5)"],["73–87 %","av den globala syreproduktionen från alger (PPT bild 12)"],["4","livsstadier hos slemsvampar (PPT bild 14)"],["≈ 1 mm/timme","plasmoidens hastighet (PPT bild 15)"]],"chains":[["Oorganiska kemikalier i djuphavskälla","arkéer utvinner energi","bildar kolhydrater","föda för hela ekosystemet"],["Myggbett","parasiter till levern","delar sig asexuellt","till röda blodkroppar","blodkroppar sprängs","feber och frossa"],["Könsmogna parasiter i blodet","sugs upp av mygga","parar sig i myggan","avkommor till spottkörteln","nytt bett"],["Mogen spor","gameter","zygoter","plasmoid i förnan","näringsbrist","fruktkropp"],["Cyanobakterier gör fotosyntes","algernas fotosyntes härstammar därifrån","alger ger 73–87 % av syret (läraren)"]],"traps":["Alla eukaryoter är inte mikroorganismer, bara huvuddelen av arterna.","Malaria orsakas av en encellig eukaryot, inte av bakterie eller virus, och myggan är inget urdjur.","Parasiterna parar sig i myggan och delar sig asexuellt i människan.","Parasiterna går först till levern, inte direkt till blodet.","Cyanobakterier (blågröna alger) är bakterier, inte alger. Alger är inte växter.","Plasmodium (malaria), plasmoid (slemsvamp) och plasmid (bakterie) är olika saker.","Flagellat (urdjur) är inte samma sak som bakteriens flagell.","Boken: bakterier gör huvuddelen av fotosyntesen i havet. Läraren: alger ger 73–87 % av syret."]}},"k8":{"pre":[{"q":"Vad saknar en bakterie som våra celler har?","o":["Cellkärna","Ribosomer","Cellmembran","DNA"],"why":"Bakterier saknar cellkärna och andra organeller med membran. Ribosomer, cellmembran och DNA har de.","src":"s. 180","id":"k8px2rdum"},{"q":"Vad kallas en rund bakterie?","o":["Kock","Stav","Spirill","Bacill"],"why":"Kock = klot. Stav (bacill) är avlång och spirill spiralformad.","src":"s. 180","id":"k8pne550m"},{"q":"Vilka bakterier behåller den blå färgen i Grams test?","o":["Grampositiva","Gramnegativa","Båda","Ingen av dem"],"why":"Bara grampositiva behåller den blå färgen, eftersom deras tjocka peptidoglykanlager håller kvar den.","src":"s. 180","t":["vagg"],"id":"k8pkk1rcu"},{"q":"Vad kallades cyanobakterier förr?","o":["Blågröna alger","Grönalger","Kiselalger","Slemsvampar"],"why":"Cyanobakterier kallades blågröna alger, men de är bakterier.","src":"s. 181 · PPT Mikroorganismer bild 34","id":"k8pbny5bd"},{"q":"Hur många bakterier finns i tarmen jämfört med antalet människoceller i kroppen?","o":["Ungefär tio gånger fler","Ungefär lika många","Ungefär en tiondel","Ungefär tusen gånger fler"],"why":"Boken: omkring tio gånger så många bakterier i tarmarna som människoceller i en kropp.","src":"s. 182 · PPT Mikroorganismer bild 22","id":"k8ptybbb0"}],"cards":[{"f":"Vad saknar bakterier, som eukaryota celler har?","b":"Cellkärna och andra organeller som avgränsas av membran.","ty":"b","src":"s. 180 · PPT Mikroorganismer bild 22","p":1,"id":"k8cpv6uj8"},{"f":"Hur skiljer sig bakteriers cellmembran från arkéers?","b":"Bakteriers cellmembran har ungefär samma kemiska uppbyggnad som eukaryoternas. Arkéernas skiljer sig kemiskt.","ty":"j","src":"s. 180","t":["membran"],"id":"k8c103otwa"},{"f":"Vad kallas en rund bakterie?","b":"Kock (läraren: kocker).","ty":"b","src":"s. 180 · PPT Mikroorganismer bild 24","p":1,"id":"k8cne550m"},{"f":"Vad kallas en avlång bakterie?","b":"Stav. Läraren kallar stavformade bakterier baciller.","ty":"b","src":"s. 180 · PPT Mikroorganismer bild 25","p":1,"id":"k8c9mioxu"},{"f":"Vad kallas en spiral- eller makaronliknande bakterie?","b":"Spirill eller spiroket.","ty":"b","src":"s. 180 · PPT Mikroorganismer bild 26","p":1,"id":"k8cx1aefo"},{"f":"Hur stora är bakterier?","b":"Från några tiondels till något tiotal mikrometer.","ty":"s","src":"s. 180","p":1,"id":"k8c1x70n2r"},{"f":"Hur stor är en typisk stav?","b":"Någon mikrometer lång och en halv mikrometer tjock.","ty":"s","src":"s. 180","id":"k8c63qa3i"},{"f":"Hur stor är en typisk kock?","b":"En knapp mikrometer i diameter.","ty":"s","src":"s. 180","id":"k8coe19lq"},{"f":"Hur många bakterier får plats på en punkt som knappt syns?","b":"Tiotusentals, ihopträngda i ett enda lager, eftersom de bara är runt en mikrometer stora.","ty":"s","src":"s. 180","id":"k8cjr16bh"},{"f":"Vad betyder ordet baciller i vardagligt tal?","b":"Bakterier eller alla smittämnen i stort, t.ex. när man pratar med barn.","ty":"b","src":"PPT Mikroorganismer bild 25","id":"k8c1i98pcr"},{"f":"När utvecklades de första bakterierna enligt läraren?","b":"För 3,5–4 miljarder år sedan.","ty":"s","src":"PPT Mikroorganismer bild 21","id":"k8c27mjxt"},{"f":"Är dagens bakterier primitiva?","b":"Nej. De härstammar från de mest ursprungliga livsformerna, men har utvecklats under miljarder år och är väl anpassade till dagens miljöer.","ty":"f","src":"PPT Mikroorganismer bild 20","id":"k8cr11juw"},{"f":"Vilken större grupp räknas bakterier till enligt läraren?","b":"Prokaryoterna, som även inkluderar domänen arkéer.","ty":"b","src":"PPT Mikroorganismer bild 22","id":"k8cc61ilx"},{"f":"Vad är diplokocker?","b":"Två kockar som sitter ihop i par.","ty":"i","src":"PPT Mikroorganismer bild 24, 27","id":"k8cqsdhkq"},{"f":"Vad är streptokocker?","b":"Kockar som sitter i en kedja. Många streptokockarter är sjukdomsalstrare.","ty":"i","src":"PPT Mikroorganismer bild 24, 27","id":"k8c1jeu0z3"},{"f":"Vad är stafylokocker?","b":"Kockar i en klump som liknar en druvklase.","ty":"i","src":"PPT Mikroorganismer bild 24, 27","id":"k8csa84j0"},{"f":"Vad är sarcina?","b":"Åtta kockar i en kub, 2 × 2 × 2.","ty":"i","src":"PPT Mikroorganismer bild 24","id":"k8c2bay06"},{"f":"Vad är en tetrad?","b":"Fyra kockar i en kvadrat, 2 × 2.","ty":"i","src":"PPT Mikroorganismer bild 24","id":"k8c1lz8lk8"},{"f":"Vad är en solitär kock?","b":"En ensamlevande kock.","ty":"i","src":"PPT Mikroorganismer bild 27","id":"k8c1j3xppl"},{"f":"Bildar bakterier flercelliga organismer?","b":"Nej, de är encelliga, men vissa arter bildar sammansatta kedjor eller klasar.","ty":"f","src":"PPT Mikroorganismer bild 21","id":"k8c1lal7k4"},{"f":"Vad har bakterier utanför cellmembranet?","b":"En cellvägg (arbetsbladet: nästan alla bakterier).","ty":"b","src":"s. 180 · Arbetsblad","p":1,"t":["vagg"],"id":"k8cs3qff8"},{"f":"Vilka två grupper delas bakterier in i efter cellväggen?","b":"Grampositiva (Gr⁺) och gramnegativa (Gr⁻).","ty":"b","src":"s. 180 · Arbetsblad","p":1,"t":["vagg"],"id":"k8c1yytcfa"},{"f":"Vad består peptidoglykan av?","b":"Långa kedjor av kolhydrater som är korsbundna till varandra med peptider (korta aminosyrekedjor).","ty":"b","src":"s. 180","p":1,"t":["vagg"],"id":"k8c1em78le"},{"f":"Hur ser cellväggen ut hos grampositiva bakterier?","b":"Ett tjockt lager peptidoglykan utanför cellmembranet.","ty":"b","src":"s. 180 · Arbetsblad","p":1,"t":["vagg"],"id":"k8cfntah0"},{"f":"Hur ser cellväggen ut hos gramnegativa bakterier?","b":"Ett mycket tunt lager peptidoglykan och utanför det ett yttre membran.","ty":"b","src":"s. 180 · Arbetsblad","p":1,"t":["vagg","membran"],"id":"k8c1euja30"},{"f":"Vad är LPS?","b":"Lipopolysackarider: i det yttre membranet hos gramnegativa är en del fosfolipider utbytta mot LPS, som kan vara mycket skadliga för människor.","ty":"b","src":"s. 180","t":["membran"],"id":"k8c1xjtpio"},{"f":"Vilka två delar består en lipopolysackarid av enligt bokens figur?","b":"En lipid (sitter i membranet) och en polysackarid (sticker ut).","ty":"i","src":"s. 180","id":"k8c1o9wrxl"},{"f":"Vem utvecklade testet som skiljer grampositiva från gramnegativa?","b":"Dansken Hans Christian Gram.","ty":"s","src":"s. 180","id":"k8c1m5b343"},{"f":"Vilka bakterier behåller den blå färgen i Grams test, och varför?","b":"Bara de grampositiva, eftersom deras tjocka peptidoglykanlager håller kvar färgen.","ty":"v","src":"s. 180","t":["vagg"],"id":"k8c1kboa7j"},{"f":"Vilken färg får grampositiva och gramnegativa vid gramfärgning enligt läraren?","b":"G+ blåa/lila, G− rosa/röda.","ty":"j","src":"Antibiotika bild 16","id":"k8ckntd8j"},{"f":"Har gramnegativa bakterier peptidoglykan?","b":"Ja, men bara ett mycket tunt lager. Båda grupperna har peptidoglykan.","ty":"f","src":"s. 180","t":["vagg"],"id":"k8cmisrn9"},{"f":"Vilket tryckfel finns i bokens figur på s. 180?","b":"\"Pepdidoglykan\". Rätt: peptidoglykan. Längre fram och i antibiotikabilderna står \"peptidoglukan\", samma ämne.","ty":"f","src":"s. 180","id":"k8c1l27nyc"},{"f":"Varför verkar penicillin framför allt mot grampositiva bakterier?","b":"Penicillin slår mot bildandet av peptidoglykan, och grampositiva har ett tjockt lager av det.","ty":"v","src":"s. 213 · Antibiotika bild 15–16","t":["vagg"],"id":"k8c1rimfh3"},{"f":"Hur beskriver läraren en gramnegativ bakterie?","b":"Ett plasmamembran, en tunn cellvägg och ett yttre cellmembran. Färgas rosa/röd.","ty":"b","src":"Antibiotika bild 16","id":"k8ch86mut"},{"f":"Vilken uppgift har yttermembranet?","b":"Skyddar bakterien.","ty":"i","src":"s. 181","p":1,"t":["membran"],"id":"k8c1aoemk0"},{"f":"Vilken uppgift har peptidoglykanet?","b":"Ger bakterien struktur och skyddar den.","ty":"i","src":"s. 181","p":1,"t":["vagg"],"id":"k8cly3npj"},{"f":"Vilken uppgift har innermembranet?","b":"Separerar cellens innehåll från omgivningen.","ty":"i","src":"s. 181","t":["membran"],"id":"k8c1rwidiw"},{"f":"Vilken uppgift har ribosomerna?","b":"Utför proteinsyntes.","ty":"i","src":"s. 181 · PPT Mikroorganismer bild 35","p":1,"t":["ribosom"],"id":"k8c1p3zw6a"},{"f":"Vad är bakteriens DNA enligt bokens lista?","b":"Bakteriens kromosom (en cirkulär DNA-molekyl).","ty":"i","src":"s. 181 · PPT Mikroorganismer bild 35","p":1,"id":"k8c1dwdtme"},{"f":"Vad är en flagell och vad gör den?","b":"Ett tjockt utskott av proteiner. Genom att rotera sätter den bakterien i rörelse.","ty":"i","src":"s. 181 · Arbetsblad","p":1,"id":"k8c1056n3g"},{"f":"Vad är fimbrier och vad gör de?","b":"Tunna utskott av proteiner med ett protein på spetsen som griper tag, så att bakterien kan hålla sig fast.","ty":"i","src":"s. 181 · Arbetsblad","p":1,"id":"k8co8asc6"},{"f":"Flagell eller fimbrier: vilken är tjock och vilken är tunn?","b":"Flagellen är tjock och roterar (fart). Fimbrierna är tunna och griper (fästa).","ty":"j","src":"s. 181","p":1,"id":"k8c5n5r7n"},{"f":"Vad heter innermembranet i lärarens figur?","b":"Plasmamembran. Det är bakteriens cellmembran.","ty":"j","src":"PPT Mikroorganismer bild 35","t":["membran"],"id":"k8c1xjkd5t"},{"f":"Vilka delar har lärarens figur som inte finns i boken?","b":"Kapsel (yttersta lagret), mesosom (veckad struktur vid membranet) och cytoplasma som etikett.","ty":"j","src":"PPT Mikroorganismer bild 35","id":"k8cfz6jjj"},{"f":"Vad är en kapsel enligt lärarens figur?","b":"Det yttersta lagret utanför cellväggen. Finns inte i boken.","ty":"i","src":"PPT Mikroorganismer bild 35","id":"k8c1a68681"},{"f":"Vad är en mesosom?","b":"En veckad struktur vid membranet i lärarens figur. Inte samma som ribosom.","ty":"f","src":"PPT Mikroorganismer bild 35","id":"k8cbjvwbt"},{"f":"Vad är de röda ringarna i lärarens bild av en bakterie?","b":"Plasmider, små extra DNA-ringar (Antibiotika bild 16: \"DNA (plasmid)\").","ty":"i","src":"PPT Mikroorganismer bild 18 · Antibiotika bild 16","t":["plasmid"],"id":"k8ctpmgld"},{"f":"Vad är skillnaden mellan bakteriens flagell och flagellater?","b":"Flagellen är ett proteinutskott på en bakterie. Flagellater (gisseldjur) är eukaryota urdjur.","ty":"f","src":"s. 181 · PPT Mikroorganismer bild 6","id":"k8c18hj64v"},{"f":"Var ligger bakteriens DNA?","b":"Fritt i cytoplasman, eftersom bakterien saknar cellkärna.","ty":"v","src":"s. 180–181","id":"k8cfe2x3y"},{"f":"Vad är en endospor?","b":"En vilande cell med avstannad ämnesomsättning, där DNA-kopian omges av en mycket motståndskraftig vägg.","ty":"b","src":"PPT Mikroorganismer bild 29","id":"k8ch6vcq4"},{"f":"Varför bildar bakterier endosporer?","b":"För att klara extrema förhållanden som torka, värme och näringsbrist, inte för att föröka sig.","ty":"v","src":"PPT Mikroorganismer bild 29","id":"k8c14q2ks1"},{"f":"Hur länge kan en endospor vara livskraftig?","b":"I hundratals år.","ty":"s","src":"PPT Mikroorganismer bild 29","id":"k8cq8tari"},{"f":"Är endosporer och spordjur samma sak?","b":"Nej. Endosporer är vilande bakterieceller. Spordjur är en stam urdjur, t.ex. Plasmodium.","ty":"f","src":"PPT Mikroorganismer bild 10, 29","id":"k8c1x07tmk"},{"f":"Vad är fotoautotrofa bakterier?","b":"Autotrofa bakterier som använder solljus som energikälla, t.ex. cyanobakterier.","ty":"b","src":"PPT Mikroorganismer bild 33–34","id":"k8cj5cpgd"},{"f":"Vad är kemoautotrofa bakterier?","b":"Bakterier som använder oorganiska föreningar som energikälla. Boken: bildar kolhydrater med hjälp av energirika oorganiska kemikalier.","ty":"b","src":"s. 181 · PPT Mikroorganismer bild 33","p":1,"id":"k8c1r63jlz"},{"f":"Vad är cyanobakterier?","b":"Bakterier som utför fotosyntes, många lever i havet. Förr kallade blågröna alger.","ty":"b","src":"s. 181 · PPT Mikroorganismer bild 34 · Arbetsblad","p":1,"id":"k8c1q6v40q"},{"f":"Varför är \"blågröna alger\" ett missvisande namn?","b":"Cyanobakterier är bakterier, inte alger, och alla arter är inte blågröna.","ty":"f","src":"s. 181 · PPT Mikroorganismer bild 34","p":1,"id":"k8c1l8ieuq"},{"f":"När var cyanobakterier viktiga för jordens atmosfär enligt läraren?","b":"Vid syresättningen av atmosfären för cirka 3 miljarder år sedan.","ty":"s","src":"PPT Mikroorganismer bild 34","id":"k8c1xm2g73"},{"f":"Varifrån härstammar algernas förmåga till fotosyntes enligt läraren?","b":"Från cyanobakterierna.","ty":"s","src":"PPT Mikroorganismer bild 12","id":"k8c3yfw0r"},{"f":"Hur många bakterier finns i havsvatten?","b":"I storleksordningen hundra miljoner per deciliter.","ty":"s","src":"s. 181","id":"k8cq19cj5"},{"f":"Hur många bakteriearter hittade man i Sargassohavet?","b":"Bortåt 2 000 olika arter.","ty":"s","src":"s. 181","id":"k8c1gjjs4p"},{"f":"Hur många bakterier finns i jord?","b":"Över en miljard i ett enda gram.","ty":"s","src":"s. 181","id":"k8cnwoz50"},{"f":"Hur många bakteriearter finns i jord?","b":"Fler än 10 000 olika arter på varje undersökt ställe.","ty":"s","src":"s. 181","id":"k8c1290cn4"},{"f":"Vilka är de viktigaste primärproducenterna i haven?","b":"Fotosyntetiserande bakterier. De bildar huvuddelen av den kemiska energi (kolhydrater) som andra livsformer utnyttjar.","ty":"b","src":"s. 181 · Arbetsblad","p":1,"id":"k8c1h6ds1k"},{"f":"Vad gör bakterier med kväve och fosfater?","b":"De fixerar och omvandlar kväve i vatten och mark, och löser upp fosfater ur mineraler så att andra livsformer kan använda dem.","ty":"b","src":"s. 181","id":"k8c4jstt1"},{"f":"Vad är normalflora?","b":"Bakterierna på och i kroppen som inte gör oss sjuka. De finns på huden, i tarmarna och i andra inbuktningar som munhålan och vagina.","ty":"b","src":"s. 182 · Arbetsblad","p":1,"id":"k8c17ck476"},{"f":"Hur många bakteriearter finns i tarmarna och på huden?","b":"Tarmarna: 500–1 000 arter. Huden: hundratals olika bakterier.","ty":"s","src":"s. 182","id":"k8c1sxmqva"},{"f":"Hur många bakterier finns i tarmen jämfört med människoceller?","b":"Omkring tio gånger fler än antalet människoceller i en kropp. Läraren: 10 gånger fler i en människa, mest i tarm och hud.","ty":"s","src":"s. 182 · PPT Mikroorganismer bild 22","p":1,"id":"k8c19ioenr"},{"f":"Är normalfloran likadan hos alla?","b":"Nej, den varierar kraftigt från person till person och över tiden i samma person.","ty":"f","src":"s. 182 · Arbetsblad","p":1,"id":"k8c1jvi61h"},{"f":"Varför är normalfloran viktig?","b":"Den hjälper oss att bryta ner maten och sitter i vägen för sjukdomsframkallande bakterier.","ty":"v","src":"s. 182","id":"k8c14y6ewq"},{"f":"Vad händer om tarmfloran störs hos en nyfödd?","b":"Immunförsvaret utvecklas i samspel med floran, så störningar ökar risken för allergier och sjukdomar där immunförsvaret angriper den egna kroppen.","ty":"v","src":"s. 182","id":"k8c1gc17te"},{"f":"Vilka sjukdomar orsakas av kocker enligt läraren?","b":"Halsfluss, bihåleinflammation, öroninflammation, lunginflammation, hjärnhinneinflammation, gonorré och karies.","ty":"s","src":"PPT Mikroorganismer bild 24, 27","id":"k8ca0qgve"},{"f":"Vilka sjukdomar orsakas av baciller enligt läraren?","b":"Mjältbrand, kikhosta, tuberkulos, stelkramp och spetälska.","ty":"s","src":"PPT Mikroorganismer bild 25, 27","id":"k8cmyw06j"},{"f":"Vilka sjukdomar orsakas av spiriller enligt läraren?","b":"Syfilis och kolera (bild 26). Magsår och kolera (bild 27).","ty":"s","src":"PPT Mikroorganismer bild 26–27","id":"k8c6f4asn"},{"f":"Hur lång är en generation för bakterier enligt läraren?","b":"1–3 timmar under gynnsamma förhållanden. Vissa arter delar sig var tjugonde minut.","ty":"s","src":"PPT Mikroorganismer bild 28","id":"k8c1ac6dem"},{"f":"Vad skiljer bakterier från virus enligt läraren?","b":"Bakterier har egen ämnesomsättning. De kan ta upp syre och näring och avge avfallsprodukter.","ty":"j","src":"PPT Mikroorganismer bild 28","id":"k8cagiiat"},{"f":"Var trivs bakterier enligt läraren?","b":"Där det är varmt och fuktigt (t.ex. i svettiga skor).","ty":"b","src":"PPT Mikroorganismer bild 30","id":"k8ch3f5kl"},{"f":"\"Om mat står länge i hög temperatur så bildas bakterier.\" Vad är fel?","b":"Bakterierna bildas inte ur maten. De som redan finns förökar sig genom delning.","ty":"f","src":"PPT Mikroorganismer bild 32","id":"k8c1kxb4jt"},{"f":"Vilka tio knep skyddar maten mot bakterier?","b":"Torka, konservera, värma, salta, sockra, syra, röka, kyla, frysa och stråla.","ty":"s","src":"PPT Mikroorganismer bild 32","id":"k8c7hxglh"},{"f":"Varför blir det så många bakterier så snabbt i varm mat?","b":"Varje bakterie delar sig i två, så antalet fördubblas varje generation. Med 20 minuter per generation blir det 2, 4, 8 … på en timme.","ty":"v","src":"PPT Mikroorganismer bild 28","id":"k8cvp1syn"}],"quiz":{"f":[{"q":"Vad saknar bakterier?","o":["Cellkärna och organeller med membran","Cellmembran","Ribosomer","DNA"],"why":"Bakterier saknar cellkärna och andra organeller som avgränsas av membran (s. 180). Cellmembran, ribosomer och DNA har de.","src":"s. 180","id":"k8qn021m"},{"q":"Vad heter en avlång bakterie i boken?","o":["Stav","Kock","Spirill","Tetrad"],"why":"Boken: avlång = stav. Läraren kallar stavarna baciller.","src":"s. 180","id":"k8q1jtwpec"},{"q":"Hur stor är en typisk kock?","o":["En knapp mikrometer i diameter","En knapp millimeter","Tio nanometer","Hundra mikrometer"],"why":"Boken s. 180. Bakterier varierar från några tiondels till något tiotal mikrometer.","src":"s. 180","id":"k8qoe19lq"},{"q":"Vad kallas kockar som sitter i en kedja?","o":["Streptokocker","Stafylokocker","Diplokocker","Sarcina"],"why":"Strepto = kedja. Stafylokocker sitter i druvklase, diplokocker i par, sarcina i kub.","src":"PPT Mikroorganismer bild 24","id":"k8qneanh9"},{"q":"Hur många kockar sitter i en sarcina?","o":["Åtta","Fyra","Två","Tolv"],"why":"Sarcina är en kub av 2 × 2 × 2 = 8 kockar. Tetrad har fyra.","src":"PPT Mikroorganismer bild 24","id":"k8q8fn710"},{"q":"Vad består peptidoglykan av?","o":["Kolhydratkedjor korsbundna med peptider","Fosfolipider och kolesterol","Cellulosa","Proteiner korsbundna med DNA"],"why":"Långa kedjor av kolhydrater korsbundna med peptider, korta aminosyrekedjor (s. 180). Cellulosa finns i växtens cellvägg.","src":"s. 180","t":["vagg"],"id":"k8q1em78le"},{"q":"Vad har gramnegativa bakterier som grampositiva saknar?","o":["Ett yttre membran","Peptidoglykan","Cellmembran","Ribosomer"],"why":"Gramnegativa har ett yttre membran utanför sitt tunna peptidoglykan. Båda har peptidoglykan.","src":"s. 180","t":["membran"],"id":"k8q1xkz546"},{"q":"Var finns lipopolysackarider (LPS)?","o":["I yttermembranet hos gramnegativa","I cellväggen hos grampositiva","I ribosomerna","I flagellen"],"why":"En del av fosfolipiderna i det yttre membranet är utbytta mot LPS (s. 180).","src":"s. 180","t":["membran"],"id":"k8q10gko08"},{"q":"Vem utvecklade färgningstestet för bakterier?","o":["Hans Christian Gram","Alexander Fleming","Louis Pasteur","Robert Koch"],"why":"Dansken Hans Christian Gram (s. 180). Fleming upptäckte penicillinet (K11).","src":"s. 180","id":"k8q1lpjob8"},{"q":"Vilken färg får gramnegativa bakterier enligt läraren?","o":["Rosa/röd","Blå/lila","Grön","Ingen färg alls"],"why":"Antibiotika bild 16: G− färgas rosa/röda, G+ blåa/lila.","src":"Antibiotika bild 16","id":"k8q1ge4lub"},{"q":"Vilken del utför proteinsyntes?","o":["Ribosomerna","Mesosomen","Fimbrierna","Peptidoglykanet"],"why":"Bokens lista s. 181: ribosomer utför proteinsyntes.","src":"s. 181","t":["ribosom"],"id":"k8qe7sjxk"},{"q":"Vilken del separerar cellens innehåll från omgivningen?","o":["Innermembranet","Yttermembranet","Fimbrierna","Kapseln"],"why":"Innermembranet är cellmembranet (s. 181). Yttermembranet skyddar.","src":"s. 181","t":["membran"],"id":"k8q8aqun4"},{"q":"Vad gör flagellen?","o":["Roterar och sätter bakterien i rörelse","Griper tag i ytor","Utför proteinsyntes","Lagrar gener"],"why":"Flagellen är ett tjockt proteinutskott som roterar (s. 181). Fimbrierna griper tag.","src":"s. 181","id":"k8q1pjb0eg"},{"q":"Vad finns ofta på fimbriernas spets?","o":["Ett protein som kan gripa tag","En ribosom","En liten plasmid","Ett lager LPS"],"why":"Boken s. 181: på deras spets sitter ofta ett protein som kan gripa tag i något bakterien ska hålla sig fast vid.","src":"s. 181","id":"k8q9ceu9f"},{"q":"Vilken del finns i lärarens figur men inte i boken?","o":["Mesosom","Ribosomer","Flagell","DNA"],"why":"Kapsel och mesosom finns bara i lärarens figur (bild 35).","src":"PPT Mikroorganismer bild 35","id":"k8qsu3n8p"},{"q":"Vad är en endospor?","o":["En vilande cell med avstannad ämnesomsättning","Ett sätt för bakterier att föröka sig snabbt","Ett urdjur som sprider malaria","En liten DNA-ring"],"why":"Endosporer är vilande celler med mycket motståndskraftig vägg (bild 29). Plasmid är DNA-ringen.","src":"PPT Mikroorganismer bild 29","id":"k8qh6vcq4"},{"q":"Vad använder kemoautotrofa bakterier som energikälla?","o":["Oorganiska föreningar","Solljus","Döda organismer","Andra bakterier"],"why":"Läraren bild 33. Boken: bildar kolhydrater med energirika oorganiska kemikalier.","src":"s. 181 · PPT Mikroorganismer bild 33","id":"k8qrviux0"},{"q":"Hur många bakterier kan ett gram jord innehålla?","o":["Över en miljard","Omkring hundra","Omkring en miljon","Över en biljon per milligram"],"why":"Boken s. 181. Havsvatten har ungefär 100 miljoner per deciliter.","src":"s. 181","id":"k8qj465uv"},{"q":"Hur många bakteriearter finns i tarmarna?","o":["500–1 000","Omkring 10","Omkring 50","Över 100 000"],"why":"Boken s. 182: mellan 500 och 1 000 olika bakteriearter.","src":"s. 182","id":"k8q1458d1z"},{"q":"Vilken sjukdom orsakas av en bacill enligt läraren?","o":["Tuberkulos","Halsfluss","Karies","Kolera"],"why":"Baciller: mjältbrand, kikhosta, tuberkulos, stelkramp, spetälska. Halsfluss och karies = kocker, kolera = spiriller.","src":"PPT Mikroorganismer bild 25","id":"k8q1szjido"},{"q":"Vilken sjukdom nämns för spiriller på båda lärarens bilder?","o":["Kolera","Syfilis","Magsår","Lunginflammation"],"why":"Bild 26: syfilis och kolera. Bild 27: magsår och kolera. Kolera finns på båda.","src":"PPT Mikroorganismer bild 26–27","id":"k8qugsh4m"},{"q":"Hur lång tid tar en generation för bakterier under gynnsamma förhållanden enligt läraren?","o":["1–3 timmar","1–3 dagar","1–3 sekunder","1–3 veckor"],"why":"Bild 28. Vissa arter kan dela sig var tjugonde minut.","src":"PPT Mikroorganismer bild 28","id":"k8q10jh61u"},{"q":"Vilket av följande är INTE ett av lärarens tio knep mot bakterier i maten?","o":["Vattna","Röka","Syra","Stråla"],"why":"De tio knepen: torka, konservera, värma, salta, sockra, syra, röka, kyla, frysa, stråla. Vatten gynnar bakterierna, som trivs fuktigt.","src":"PPT Mikroorganismer bild 32","id":"k8q1q8m6m"}],"u":[{"q":"En bakterie behåller den blå färgen i Grams test. Vad vet du om dess cellvägg?","o":["Den har ett tjockt lager peptidoglykan","Den har ett yttre membran med LPS","Den saknar peptidoglykan","Den har en cellvägg av cellulosa"],"why":"Bara grampositiva behåller den blå färgen, eftersom det tjocka peptidoglykanlagret håller kvar den.","src":"s. 180","t":["vagg"],"id":"k8qme1aci"},{"q":"Varför är gramnegativa bakterier extra farliga för människor när det gäller cellväggen?","o":["Deras yttre membran innehåller LPS, som kan vara mycket skadliga","De har tjockare peptidoglykan","De saknar cellmembran","De har kapsel men inte grampositiva"],"why":"Boken s. 180: LPS i det yttre membranet kan vara mycket skadliga för människor.","src":"s. 180","t":["membran"],"id":"k8qd8pbof"},{"q":"Penicillin hindrar bildandet av peptidoglykan. Vilken bakterie drabbas mest?","o":["En grampositiv","En gramnegativ","Båda lika mycket","Ingen, peptidoglykan finns bara hos växter"],"why":"Grampositiva har ett tjockt lager peptidoglykan och inget yttre membran, och därför verkar penicillin framför allt mot dem (s. 213).","src":"s. 180 · s. 213","t":["vagg"],"id":"k8q1tcloqm"},{"q":"En bakterie saknar fimbrier. Vad blir svårare för den?","o":["Att fästa sig på ett lämpligt ställe","Att röra sig framåt","Att göra proteiner","Att dela sig"],"why":"Fimbrierna griper tag med ett protein på spetsen. Flagellen sköter rörelsen.","src":"s. 181","id":"k8q470irp"},{"q":"Varför ligger bakteriens DNA fritt i cytoplasman?","o":["Bakterien har ingen cellkärna","DNA:t är för stort för en kärna","Ribosomerna har brutit ner kärnan","DNA:t sitter i mesosomen"],"why":"Bakterier saknar cellkärna och andra organeller med membran (s. 180).","src":"s. 180–181","id":"k8q1bhfikd"},{"q":"Varför är det fel att säga att bakterier bildar endosporer för att föröka sig?","o":["En bakterie blir en vilande endospor för att överleva, inte flera nya","Endosporer bildas bara av virus","Endosporer är könsceller","Endosporer bildas i värme för att dela sig snabbare"],"why":"Endosporer bildas för att klara torka, värme och näringsbrist (bild 29).","src":"PPT Mikroorganismer bild 29","id":"k8q7r2ei0"},{"q":"Varför räcker det inte alltid att värma mat för att få bort alla bakterier?","o":["Endosporer kan klara värme","Bakterier har ingen ämnesomsättning","Värme gör bakterierna gramnegativa","Värmen ökar antalet fimbrier"],"why":"Endosporer bildas just för att klara extrema förhållanden, bland annat värme (bild 29).","src":"PPT Mikroorganismer bild 29","id":"k8q1e5xwoo"},{"q":"Vad har cyanobakterier och kemoautotrofa bakterier gemensamt?","o":["Båda bildar själva kolhydrater","Båda använder solljus","Båda är eukaryota alger","Båda lever bara i tarmen"],"why":"Båda är autotrofa. Energikällan skiljer: solljus respektive oorganiska kemikalier.","src":"s. 181 · PPT Mikroorganismer bild 33","id":"k8q1uiqusq"},{"q":"Var finns flest bakterier per mängd enligt boken?","o":["I jord (över en miljard per gram)","I havet (100 miljoner per deciliter)","Lika många överallt","I luften"],"why":"Boken: \"ännu mer bakterietät är marken\". Jorden har också fler arter per ställe.","src":"s. 181","id":"k8qgki53x"},{"q":"Hur hjälper bakterier andra livsformer med fosfor?","o":["De löser upp fosfater ur mineraler","De bildar fosfater ur kväve","De tar bort fosfater ur vattnet","De bildar fosfater genom fotosyntes"],"why":"Boken s. 181: bakterier löser upp fosfater ur mineraler så att de kan användas av andra livsformer.","src":"s. 181","id":"k8q1v1em29"},{"q":"Varför kan en bakteriell tarminfektion vara svårare att få för någon med en frisk normalflora?","o":["Normalfloran sitter i vägen för sjukdomsframkallande bakterier","Normalfloran bildar antibiotika","Normalfloran gör tarmen steril","Normalfloran består av virus"],"why":"Boken s. 182: normalfloran kan sitta i vägen för sjukdomsframkallande bakterier.","src":"s. 182","id":"k8qk05ecu"},{"q":"En bakterie delar sig var 20:e minut. Hur många har den blivit efter en timme?","o":["8","3","6","20"],"why":"Tre generationer: 1 → 2 → 4 → 8. Antalet fördubblas varje generation (bild 28).","src":"PPT Mikroorganismer bild 28","id":"k8qql8bjq"},{"q":"Varför ställer man maten i kylskåpet?","o":["Bakterierna delar sig mycket långsammare i kyla","Kylan dödar alla bakterier","Kylan gör bakterierna grampositiva","Kylan bildar endosporer som skyddar maten"],"why":"Bakterier trivs varmt. Kyla bromsar delningen men dödar inte alla (extra).","src":"PPT Mikroorganismer bild 30, 32","id":"k8qlw5znj"},{"q":"Vilket påstående om lärarens bild och bokens bild av bakteriecellen stämmer?","o":["Plasmamembran i lärarens bild = innermembran i boken","Kapsel i lärarens bild = yttermembran i boken","Mesosom = ribosom","Boken har kapsel men inte flagell"],"why":"Plasmamembran är bakteriens cellmembran, som boken kallar innermembran. Kapsel och mesosom finns inte i boken.","src":"s. 181 · PPT Mikroorganismer bild 35","t":["membran"],"id":"k8q14rqecg"}],"o":[{"q":"Förklara skillnaden mellan grampositiva och gramnegativa bakterier. Ta med peptidoglykan, yttre membran, LPS och Grams test.","model":"Bakterier har en cellvägg utanför cellmembranet. Hos grampositiva består den av ett tjockt lager peptidoglykan, långa kolhydratkedjor korsbundna med peptider. Hos gramnegativa är peptidoglykanlagret mycket tunt, och utanför det finns ett yttre membran där en del av fosfolipiderna är utbytta mot lipopolysackarider (LPS), som kan vara mycket skadliga för människor. I det test som dansken Hans Christian Gram utvecklade behåller bara de grampositiva den blå färgen, eftersom det tjocka peptidoglykanet håller kvar den. Enligt läraren blir grampositiva blå/lila och gramnegativa rosa/röda.","kw":[["tjock"],["tunt","tunn"],["peptidoglykan"],["yttre membran","yttermembran"],["lps","lipopolysackarid"],["blå"]],"src":"s. 180 · Antibiotika bild 16","t":["vagg","membran"],"id":"k8o4ybyr0"},{"q":"Rita en typisk gramnegativ bakterie och sätt ut sju delar. Skriv vad varje del gör.","model":"Fimbrier: tunna proteinutskott med ett gripande protein på spetsen, fäster bakterien. Yttermembran: skyddar. Peptidoglykan: ger struktur och skyddar. Innermembran: separerar cellens innehåll från omgivningen. Ribosomer: utför proteinsyntes. DNA: bakteriens kromosom. Flagell: tjockt proteinutskott som roterar och sätter bakterien i rörelse.","kw":[["fimbri"],["yttermembran"],["peptidoglykan"],["innermembran"],["ribosom"],["flagell"]],"src":"s. 181","t":["membran","ribosom"],"id":"k8orpho04"},{"q":"Beskriv bakteriernas betydelse i ekosystemen och i människokroppen. Använd gärna siffror.","model":"Bakterier finns på de flesta platser. Havsvatten har ungefär 100 miljoner bakterier per deciliter och bortåt 2 000 arter. Ett gram jord har över en miljard bakterier och fler än 10 000 arter. Fotosyntetiserande bakterier (cyanobakterier) är de viktigaste primärproducenterna i haven och bildar huvuddelen av kolhydraterna som andra livsformer utnyttjar. Kemoautotrofer bildar kolhydrater med energirika oorganiska kemikalier. Bakterier fixerar och omvandlar kväve och löser upp fosfater ur mineraler. I kroppen har vi en normalflora som inte gör oss sjuka: hundratals arter på huden och 500–1 000 i tarmen, där de är ca tio gånger fler än kroppens celler. Den hjälper till att bryta ner maten, sitter i vägen för sjukdomsframkallande bakterier och behövs för att nyföddas immunförsvar ska utvecklas. Floran varierar mellan personer och över tid.","kw":[["primärproducent"],["kväve"],["fosfat"],["normalflora"],["tio gånger","10 gånger"],["miljard","miljoner"]],"src":"s. 181–182","id":"k8o18lli76"},{"q":"Förklara varför mat inte ska stå varmt länge. Ta med hur bakterier förökar sig, endosporer och några av lärarens knep.","model":"Bakterier har egen ämnesomsättning och förökar sig genom delning. En generation tar 1–3 timmar under gynnsamma förhållanden, och vissa arter delar sig var tjugonde minut. Eftersom antalet fördubblas varje generation blir några få bakterier snabbt väldigt många när maten står varmt och fuktigt, där bakterier trivs. Bakterierna bildas alltså inte ur maten, de förökar sig. Vissa bakterier kan bilda endosporer, vilande celler med tålig vägg som klarar torka, värme och näringsbrist, och därför räcker värme inte alltid. Läraren listar tio knep: torka, konservera, värma, salta, sockra, syra, röka, kyla, frysa och stråla.","kw":[["delning","delar sig"],["generation"],["varmt","fukt"],["endospor"],["kyla","frysa"],["salta","sockra","torka"]],"src":"PPT Mikroorganismer bild 28–32","id":"k8o1o9kac2"}]},"kan":[{"q":"Kan du beskriva bakteriernas tre former och hur stora de är?","a":"En bakterie kan vara rund och kallas då kock, avlång och kallas då stav, eller spiral- eller makaronliknande och kallas då spirill eller spiroket. Storleken varierar från några tiondels till något tiotal mikrometer. En typisk stav är någon mikrometer lång och en halv mikrometer tjock, och en typisk kock en knapp mikrometer i diameter. Därför får tiotusentals bakterier plats på en punkt som knappt syns.","kw":[["kock"],["stav","bacill"],["spirill","spiroket"],["mikrometer","µm"],["tiotusen"]],"src":"s. 180","id":"k8k1uywwu8"},{"q":"Kan du förklara skillnaden mellan grampositiva och gramnegativa bakterier?","a":"Båda har en cellvägg utanför cellmembranet. Grampositiva har ett tjockt lager peptidoglykan. Gramnegativa har ett mycket tunt peptidoglykanlager och utanför det ett yttre membran, där en del av fosfolipiderna är utbytta mot lipopolysackarider (LPS), som kan vara mycket skadliga för människor. Bara grampositiva behåller den blå färgen i Hans Christian Grams test, eftersom det tjocka peptidoglykanet håller kvar färgen.","kw":[["tjock"],["tunt","tunn"],["peptidoglykan"],["yttre membran","yttermembran"],["lps","lipopolysackarid"],["blå"]],"src":"s. 180","t":["vagg","membran"],"id":"k8kdbn8ax"},{"q":"Kan du förklara vad peptidoglykan är och vad det gör?","a":"Peptidoglykan består av långa kedjor av kolhydrater som är korsbundna till varandra med peptider, alltså korta aminosyrekedjor. Det bildar cellväggen utanför cellmembranet och ger bakterien struktur och skyddar den. Grampositiva har ett tjockt lager och gramnegativa ett tunt.","kw":[["kolhydrat"],["peptid","aminosyr"],["korsbund"],["struktur"],["skydd"]],"src":"s. 180–181","t":["vagg"],"id":"k8kna7dy1"},{"q":"Kan du namnge sju delar i en typisk gramnegativ bakterie och deras uppgift?","a":"Yttermembranet skyddar bakterien. Peptidoglykanet ger struktur och skyddar. Innermembranet separerar cellens innehåll från omgivningen. Ribosomerna utför proteinsyntes. DNA är bakteriens kromosom. Flagellen är ett tjockt proteinutskott som roterar och sätter bakterien i rörelse. Fimbrierna är tunna proteinutskott med ett protein på spetsen som griper tag, så att bakterien kan hålla sig fast.","kw":[["yttermembran"],["peptidoglykan"],["innermembran"],["ribosom"],["flagell"],["fimbri"]],"src":"s. 181","t":["ribosom","membran"],"id":"k8kenhtup"},{"q":"Kan du förklara vad endosporer är och varför de bildas?","a":"En del bakterier kan kopiera sitt DNA och omge kopiorna med mycket motståndskraftiga väggar. Då bildas endosporer, vilande celler med avstannad ämnesomsättning. De bildas inte för att föröka sig utan för att klara extrema förhållanden som torka, värme och näringsbrist, och de kan vara livskraftiga i hundratals år.","kw":[["vilande"],["ämnesomsättning"],["vägg"],["torka","värme","näringsbrist"],["hundratals"],["inte","föröka"]],"src":"PPT Mikroorganismer bild 29","id":"k8k2nxzrp"},{"q":"Kan du förklara skillnaden mellan fotoautotrofa och kemoautotrofa bakterier?","a":"Båda är autotrofa och bildar själva sina kolhydrater. Fotoautotrofa använder solljus som energikälla, t.ex. cyanobakterierna. Kemoautotrofa använder oorganiska föreningar som energikälla. Boken säger att kemoautotrofer bildar kolhydrater med hjälp av energirika oorganiska kemikalier.","kw":[["solljus","ljus"],["oorganisk"],["kolhydrat"],["cyanobakteri"],["autotrof"]],"src":"s. 181 · PPT Mikroorganismer bild 33","id":"k8kwi7ey3"},{"q":"Kan du förklara vilka roller bakterier har i ekosystemen?","a":"Fotosyntetiserande bakterier, cyanobakterierna, är de viktigaste primärproducenterna i haven och bildar huvuddelen av den kemiska energin (kolhydrater) som andra livsformer utnyttjar. Kemoautotrofer bildar kolhydrater med energirika oorganiska kemikalier. Bakterier fixerar och omvandlar kväve i vatten och mark och löser upp fosfater ur mineraler så att andra livsformer kan använda dem.","kw":[["primärproducent"],["fotosyntes","cyanobakteri"],["kväve"],["fosfat"],["kemoautotrof","oorganisk"]],"src":"s. 181","id":"k8k1k4ge5v"},{"q":"Kan du förklara vad normalfloran är och varför den är viktig?","a":"Normalfloran är de bakterier som finns på och i vår kropp utan att göra oss sjuka. På huden finns hundratals olika bakterier och i tarmarna 500–1 000 arter, och där är bakterierna omkring tio gånger fler än människocellerna i kroppen. Floran varierar mellan personer och över tid. Den hjälper oss att bryta ner maten och sitter i vägen för sjukdomsframkallande bakterier. En nyfödds immunförsvar utvecklas i samspel med tarmfloran, och störningar ökar risken för allergier och autoimmuna sjukdomar.","kw":[["inte","sjuka"],["tarm"],["tio gånger","10 gånger"],["bryta ner","maten"],["sjukdomsframkallande","i vägen"],["allergi","immunförsvar"]],"src":"s. 181–182 · PPT Mikroorganismer bild 22","id":"k8k1tvogzw"},{"q":"Kan du ge exempel på sjukdomar för varje bakterieform enligt läraren?","a":"Kocker: halsfluss, bihåleinflammation, öroninflammation, lunginflammation, hjärnhinneinflammation, gonorré och karies. Många streptokockarter är sjukdomsalstrare. Baciller (stavar): mjältbrand, kikhosta, tuberkulos, stelkramp och spetälska. Spiriller: kolera, och syfilis (bild 26) eller magsår (bild 27).","kw":[["kock"],["bacill","stav"],["spirill"],["halsfluss","lunginflammation"],["tuberkulos","stelkramp","kikhosta"],["kolera"]],"src":"PPT Mikroorganismer bild 24–27","id":"k8kfltkms"},{"q":"Kan du förklara varför mat inte ska stå varmt länge, och nämna lärarens tio knep?","a":"Bakterier trivs där det är varmt och fuktigt. De bakterier som finns i maten förökar sig då genom delning, en generation tar 1–3 timmar och vissa arter delar sig var tjugonde minut, och eftersom antalet fördubblas varje generation blir de snabbt väldigt många. Knepen är torka, konservera, värma, salta, sockra, syra, röka, kyla, frysa och stråla.","kw":[["varmt"],["fukt"],["delning","delar sig","förökar"],["kyla","frysa"],["salta","sockra","torka"]],"src":"PPT Mikroorganismer bild 28, 30–32","id":"k8k17ue2p"}],"kompis":[{"q":"Förklara för en kompis hur Grams test skiljer bakterier åt och varför det fungerar.","model":"Bakterier har en cellvägg utanför cellmembranet, och den finns i två typer. Grampositiva har ett tjockt lager peptidoglykan, långa kolhydratkedjor korsbundna med peptider. Gramnegativa har bara ett tunt lager och utanför det ett yttre membran med LPS. När man färgar bakterierna blå och sedan tvättar, behåller bara de grampositiva den blå färgen, eftersom det tjocka peptidoglykanlagret håller kvar den. Läraren säger att grampositiva blir blå/lila och gramnegativa rosa/röda. Testet utvecklades av dansken Hans Christian Gram.","kw":[["tjock"],["tunt","tunn"],["peptidoglykan"],["yttre membran","yttermembran"],["blå"],["gram"]],"src":"s. 180 · Antibiotika bild 16","t":["vagg"],"id":"k8e1cvwjrz"},{"q":"Förklara för en kompis hur en bakterie är byggd, utifrån och in.","model":"En gramnegativ bakterie har ytterst fimbrier, tunna proteinutskott som griper tag, och en flagell, ett tjockt proteinutskott som roterar så att bakterien rör sig. Sedan kommer yttermembranet som skyddar, peptidoglykanet som ger struktur och skydd, och innermembranet, cellmembranet, som separerar innehållet från omgivningen. Inne i cytoplasman finns ribosomer som gör proteiner och DNA, bakteriens kromosom. Det finns ingen cellkärna, så DNA ligger fritt. Läraren lägger till en kapsel ytterst, en mesosom vid membranet och plasmider.","kw":[["fimbri"],["flagell"],["yttermembran"],["peptidoglykan"],["innermembran","cellmembran","plasmamembran"],["ribosom"]],"src":"s. 181 · PPT Mikroorganismer bild 35","t":["membran","ribosom"],"id":"k8emdggt6"},{"q":"Förklara för en kompis varför bakterier är så viktiga i naturen och i kroppen.","model":"I haven är fotosyntetiserande bakterier, cyanobakterierna, de viktigaste primärproducenterna och bildar huvuddelen av kolhydraterna som andra lever av. Kemoautotrofer bildar kolhydrater med energi från oorganiska kemikalier. Bakterier fixerar och omvandlar kväve och löser upp fosfater ur mineraler så att andra kan använda dem. I kroppen har vi en normalflora, i tarmen tio gånger fler bakterier än människoceller, som hjälper oss att bryta ner maten, sitter i vägen för sjukdomsframkallande bakterier och hjälper den nyföddas immunförsvar att utvecklas.","kw":[["primärproducent"],["kväve"],["fosfat"],["normalflora"],["immunförsvar","allergi"]],"src":"s. 181–182","id":"k8e1t97aap"}],"gloss":[{"w":"Bacill","d":"Lärarens ord för en avlång, stavformad bakterie. I vardagligt tal även bakterier eller smittämnen i allmänhet.","src":"PPT Mikroorganismer bild 25","lek":1},{"w":"Cellvägg (bakterie)","d":"Lager utanför cellmembranet. Av peptidoglykan, hos gramnegativa även ett yttre membran.","src":"Bok s. 180"},{"w":"Cyanobakterier","d":"Bakterier som utför fotosyntes, de viktigaste primärproducenterna i haven. Förr kallade blågröna alger.","src":"Bok s. 181 · PPT Mikroorganismer bild 34"},{"w":"Cytoplasma","d":"Vätskan i bakteriens enda rum, där DNA och ribosomer finns.","src":"PPT Mikroorganismer bild 35","lek":1},{"w":"Diplokocker","d":"Två kockar i par.","src":"PPT Mikroorganismer bild 24, 27","lek":1},{"w":"DNA (bakteriens kromosom)","d":"Bakteriens arvsmassa, en cirkulär DNA-molekyl som ligger fritt i cytoplasman.","src":"Bok s. 181–182"},{"w":"Endospor","d":"Vilande bakteriecell med avstannad ämnesomsättning och mycket motståndskraftig vägg. Klarar torka, värme och näringsbrist i hundratals år.","src":"PPT Mikroorganismer bild 29","lek":1},{"w":"Fimbrier","d":"Tunna utskott av proteiner med ett gripande protein på spetsen, så att bakterien kan hålla sig fast.","src":"Bok s. 181"},{"w":"Flagell","d":"Tjockt utskott av proteiner som roterar och sätter bakterien i rörelse.","src":"Bok s. 181"},{"w":"Fotoautotrof","d":"Autotrof organism som använder solljus som energikälla, t.ex. cyanobakterier.","src":"PPT Mikroorganismer bild 33","lek":1},{"w":"Generation","d":"En celldelning. Hos bakterier 1–3 timmar under gynnsamma förhållanden, för vissa arter 20 minuter.","src":"PPT Mikroorganismer bild 28","lek":1},{"w":"Gramnegativ (Gr⁻)","d":"Bakterie med tunt peptidoglykanlager och ett yttre membran med LPS. Behåller inte den blå färgen i Grams test (läraren: rosa/röd).","src":"Bok s. 180 · Antibiotika bild 16"},{"w":"Grampositiv (Gr⁺)","d":"Bakterie med tjockt peptidoglykanlager utanför cellmembranet. Behåller den blå färgen i Grams test (läraren: blå/lila).","src":"Bok s. 180 · Antibiotika bild 16"},{"w":"Grams test","d":"Färgningstest utvecklat av dansken Hans Christian Gram. Bara grampositiva behåller den blå färgen.","src":"Bok s. 180"},{"w":"Heterotrof","d":"Står bara i lärarens rubrik. Allmänt: organism som tar energi och kol från organiska ämnen.","src":"Extra"},{"w":"Innermembran","d":"Bakteriens cellmembran. Separerar cellens innehåll från omgivningen. Läraren: plasmamembran.","src":"Bok s. 181"},{"w":"Kapsel","d":"Yttersta lagret i lärarens figur av bakteriecellen. Finns inte i boken.","src":"PPT Mikroorganismer bild 35","lek":1},{"w":"Kemoautotrof","d":"Bakterie som bildar kolhydrater med hjälp av energirika oorganiska kemikalier (läraren: oorganiska föreningar som energikälla).","src":"Bok s. 181 · PPT Mikroorganismer bild 33"},{"w":"Kock","d":"Rund bakterie, en knapp mikrometer i diameter.","src":"Bok s. 180"},{"w":"Lipopolysackarid (LPS)","d":"Molekyl av lipid + polysackarid som ersätter en del fosfolipider i gramnegativa bakteriers yttre membran. Kan vara mycket skadlig för människor.","src":"Bok s. 180"},{"w":"Mesosom","d":"Veckad struktur vid membranet i lärarens figur. Finns inte i boken.","src":"PPT Mikroorganismer bild 35","lek":1},{"w":"Normalflora","d":"Bakterierna på och i kroppen som inte gör oss sjuka. Varierar mellan personer och över tid.","src":"Bok s. 182"},{"w":"Peptidoglykan","d":"Långa kolhydratkedjor korsbundna med peptider. Bildar bakteriens cellvägg och ger struktur och skydd. Boken stavar fel i figuren s. 180 (\"pepdidoglykan\"), och s. 213 skriver peptidoglukan.","src":"Bok s. 180–181"},{"w":"Plasmamembran","d":"Lärarens ord för cellmembranet, bokens innermembran.","src":"PPT Mikroorganismer bild 35","lek":1},{"w":"Primärproducent","d":"Organism som bildar kemisk energi (kolhydrater) som andra livsformer utnyttjar. I haven främst fotosyntetiserande bakterier.","src":"Bok s. 181"},{"w":"Prokaryot","d":"Encellig organism utan cellkärna. Bakterier och arkéer.","src":"PPT Mikroorganismer bild 22","lek":1},{"w":"Ribosom","d":"Utför proteinsyntes.","src":"Bok s. 181"},{"w":"Sarcina","d":"Åtta kockar i en kub (2 × 2 × 2).","src":"PPT Mikroorganismer bild 24","lek":1},{"w":"Spirill","d":"Spiral- eller makaronliknande bakterie.","src":"Bok s. 180"},{"w":"Spiroket","d":"Spiral- eller makaronliknande bakterie. Boken nämner spirill och spiroket tillsammans. Extra: spiroketen är tunnare och tätare vriden än en spirill.","src":"Bok s. 180 · Extra"},{"w":"Stafylokocker","d":"Kockar i en druvklase.","src":"PPT Mikroorganismer bild 24, 27","lek":1},{"w":"Stav","d":"Avlång bakterie, någon mikrometer lång och en halv mikrometer tjock.","src":"Bok s. 180"},{"w":"Streptokocker","d":"Kockar i en kedja. Många arter är sjukdomsalstrare.","src":"PPT Mikroorganismer bild 24, 27","lek":1},{"w":"Tetrad","d":"Fyra kockar i en kvadrat.","src":"PPT Mikroorganismer bild 24","lek":1},{"w":"Yttermembran","d":"Membran utanför det tunna peptidoglykanet hos gramnegativa. Skyddar bakterien och innehåller LPS.","src":"Bok s. 180–181"}],"snabb":{"keys":["Kock :: rund bakterie","Stav (bacill) :: avlång bakterie","Spirill/spiroket :: spiral- eller makaronliknande bakterie","Grampositiv :: tjockt peptidoglykan, behåller blå färg","Gramnegativ :: tunt peptidoglykan + yttre membran med LPS","Peptidoglykan :: kolhydratkedjor korsbundna med peptider","Flagell :: tjock, roterar, rörelse","Fimbrier :: tunna, griper tag, fäster","Innermembran :: separerar cellens innehåll från omgivningen","Endospor :: vilande cell som klarar torka, värme, näringsbrist","Fotoautotrof :: energi från solljus","Kemoautotrof :: energi från oorganiska föreningar","Normalflora :: bakterier på och i kroppen som inte gör oss sjuka","Cyanobakterier :: fotosyntetiserande bakterier, förr blågröna alger"],"nums":[["några tiondels – något tiotal µm","bakteriers storlek"],["~1 µm × ½ µm","typisk stav (längd × tjocklek)"],["< 1 µm","typisk kock (diameter)"],["tiotusentals","bakterier på en punkt som knappt syns"],["3,5–4 miljarder år","sedan de första bakterierna (läraren)"],["100 miljoner / dl","bakterier i havsvatten"],["~2 000","bakteriearter i Sargassohavet"],["> 1 miljard / g","bakterier i jord"],["> 10 000","bakteriearter per ställe i jord"],["500–1 000","bakteriearter i tarmarna"],["hundratals","bakteriearter på huden"],["10 ×","fler bakterier i tarmen än människoceller i kroppen"],["3 miljarder år","sedan cyanobakterier syresatte atmosfären (läraren)"],["1–3 h","en generation (läraren)"],["20 min","snabbaste generationstid (läraren)"],["hundratals år","endosporers livslängd (läraren)"],["10","knep mot bakterier i maten (läraren)"],["8 / 4","kockar i sarcina / tetrad"]],"chains":[["Tjockt peptidoglykan","håller kvar färgen","blå i Grams test","grampositiv"],["Torka, värme eller näringsbrist","DNA kopieras och får tålig vägg","ämnesomsättningen stannar","endospor överlever i hundratals år"],["Varm och fuktig mat","bakterierna delar sig","antalet fördubblas varje generation","väldigt många bakterier"],["Tarmfloran störs hos nyfödd","immunförsvaret utvecklas sämre","ökad risk för allergier och autoimmuna sjukdomar"],["Cyanobakterier gör fotosyntes","bildar kolhydrater","andra livsformer i havet får energi"]],"traps":["Både Gr⁺ och Gr⁻ har peptidoglykan. Skillnaden är tjockleken och yttermembranet.","Det är de GRAMPOSITIVA som behåller den blå färgen.","Cyanobakterier är bakterier, inte alger.","Endosporer bildas för att överleva, inte för att föröka sig.","Bakterier bildas inte ur maten. De som finns förökar sig.","Flagell = tjock och roterar. Fimbrier = tunna och griper.","Plasmamembran (läraren) = innermembran (boken) = cellmembran.","Boken stavar \"pepdidoglykan\" i figuren s. 180, ett tryckfel."]}},"k9":{"pre":[{"q":"Hur förökar sig bakterier?","o":["Genom delning","Genom parning mellan två bakterier","Genom sporer som befruktas","Genom att virus kopierar dem"],"why":"Bakterier delar sig, en könlös förökning. De två nya bakterierna har nästan alltid identisk arvsmassa.","src":"s. 182 · PPT Mikroorganismer bild 28 · Arbetsblad","id":"k9p1ao2l4x"},{"q":"Vad är en plasmid?","o":["En extra, mindre, cirkulär DNA-molekyl hos bakterier","Bakteriens huvudkromosom","Ett bakterievirus","En sorts ribosom"],"why":"Plasmider bär ett litet antal gener som bakterien har nytta av ibland, t.ex. resistensgener.","src":"s. 182","t":["plasmid"],"id":"k9p1ebj614"},{"q":"Vad kallas det när ett bakterievirus för över gener mellan bakterier?","o":["Transduktion","Transformation","Konjugation","Mutation"],"why":"Transduktion: ett virus är budbärare. Transformation är upptag av naket DNA, konjugation sker via kontakt.","src":"s. 183 · PPT Antibiotika bild 10","id":"k9p5d67h1"},{"q":"Kan bakterier byta gener med varandra fast de saknar könlig förökning?","o":["Ja, på flera sätt, t.ex. konjugation","Nej, aldrig","Bara om de är av samma art och tvillingar","Bara när de dör"],"why":"Gener kan föras över genom transformation, konjugation och transduktion, ibland även över artgränser.","src":"s. 182–183, 214 · Arbetsblad","id":"k9p44chku"},{"q":"Hur ofta ändras en DNA-bokstav när en bakterie delar sig?","o":["Vid ungefär en delning på tio, hundra eller tusen","Vid varje delning","Aldrig","Vid en delning på en miljard"],"why":"Bakterier har så liten arvsmassa att mutationer är ovanliga per delning.","src":"s. 182","id":"k9p15g2yl1"}],"cards":[{"f":"Hur förökar sig bakterier?","b":"Genom delning (celldelning), en könlös förökning.","ty":"b","src":"s. 182 · PPT Mikroorganismer bild 28 · Arbetsblad lucka 17","p":1,"id":"k9c1ao2l4x"},{"f":"Varför får de två bakterierna efter en delning nästan alltid identisk arvsmassa?","b":"Bakterien kopierar hela sin arvsmassa före delningen och ger en kopia till var och en.","ty":"v","src":"s. 182","id":"k9c1f09p4c"},{"f":"Vad bildas när bakterier växer och delar sig?","b":"Kloner, bakterier med i stort sett samma arvsanlag.","ty":"b","src":"s. 182","id":"k9c1ypwzfj"},{"f":"Varför är mutationer ovanliga vid bakteriers delning?","b":"Bakterier har så liten arvsmassa att bara vid en delning på tio, hundra eller tusen förändras någon enstaka DNA-bokstav.","ty":"v","src":"s. 182","id":"k9coewd4"},{"f":"Provfälla: har kloner alltid identisk arvsmassa?","b":"I de allra flesta fall, men ibland sker mutationer när arvsmassan kopieras.","ty":"f","src":"s. 182","id":"k9c76xl7u"},{"f":"Hur lång tid tar en bakteriegeneration enligt läraren?","b":"1–3 timmar under gynnsamma förhållanden. Vissa arter kan dela sig var tjugonde minut.","ty":"s","src":"PPT Mikroorganismer bild 28","id":"k9cv7v4b8"},{"f":"Vad har bakterier som virus saknar enligt läraren?","b":"Egen ämnesomsättning. De kan ta upp syre och näring och avge avfallsprodukter.","ty":"j","src":"PPT Mikroorganismer bild 28","id":"k9cayte6s"},{"f":"Provfälla: betyder könlös förökning att bakterier aldrig byter gener?","b":"Nej. Trots att de saknar könlig förökning byter de gener, t.ex. genom transformation, konjugation och transduktion.","ty":"f","src":"s. 182–183 · Arbetsblad","p":1,"id":"k9c19nmrpe"},{"f":"Hur lagrar en bakterie sin arvsmassa?","b":"I en cirkulär DNA-molekyl som kallas kromosom.","ty":"b","src":"s. 182 · Arbetsblad lucka 18–20","p":1,"id":"k9c10gh6kn"},{"f":"Hur många gener har en typisk bakteriekromosom?","b":"Några tusen.","ty":"s","src":"s. 182","id":"k9clpn0yk"},{"f":"Vad är plasmider?","b":"Extra, mindre, cirkulära DNA-molekyler med ett litet antal gener som bakterien har nytta av under speciella omständigheter men inte ständigt behöver.","ty":"b","t":["plasmid"],"src":"s. 182 · Arbetsblad lucka 21","p":1,"id":"k9c18kquf4"},{"f":"Ge exempel på gener som ofta sitter på plasmider.","b":"Gener som ger resistens mot ett antibiotikum. Arbetsbladet: extra-gener som är bra i extrema miljöer, t.ex. hög metallhalt eller antibiotika.","ty":"b","t":["plasmid"],"src":"s. 182 · Arbetsblad","p":1,"id":"k9c7c6cq1"},{"f":"Kromosom eller plasmid: vad är skillnaden?","b":"Kromosomen har några tusen gener som alltid behövs. Plasmiden är mindre och extra, med få gener för speciella omständigheter.","ty":"j","t":["plasmid"],"src":"s. 182","id":"k9cvz2wzl"},{"f":"Vad kan hända med en plasmid vid en celldelning?","b":"Den ena dotterbakterien kan bli utan den plasmid som moderbakterien hade.","ty":"b","t":["plasmid"],"src":"s. 182","id":"k9c1dybx6s"},{"f":"Varför kan en dotterbakterie bli utan plasmid?","b":"Plasmiderna kopieras inför delningen, men det finns inget maskineri som ser till att det hamnar plasmider i båda bakterierna.","ty":"v","t":["plasmid"],"src":"s. 214","id":"k9criz3t6"},{"f":"När försvinner plasmider långsamt ur en bakteriepopulation?","b":"När de inte ger bakterien någon överlevnadsfördel i den miljö den lever i.","ty":"v","t":["plasmid"],"src":"s. 182","id":"k9c18l2ckt"},{"f":"Varför blir en resistensplasmid kvar när det finns antibiotika?","b":"Bakterierna som saknar plasmiden dör, medan de med resistensgenen överlever och delar sig.","ty":"v","t":["plasmid"],"src":"s. 182, 214","id":"k9c1mgtz5p"},{"f":"Kan en bakterie förlora delar av sin kromosom?","b":"Ja, då och då förlorar en bakterie stora avsnitt av kromosomen. Det verkar kunna ske på många olika sätt.","ty":"b","src":"s. 182","id":"k9cmdt1wk"},{"f":"Vilka två DNA-etiketter har lärarens bakteriebild?","b":"DNA (kromosom) och DNA (plasmid). Avsnittsbilden visar plasmiderna som röda ringar i en stavbakterie.","ty":"i","t":["plasmid"],"src":"PPT Antibiotika bild 16 · Mikroorganismer bild 18","id":"k9cebbc7j"},{"f":"Provfälla: vilken DNA-molekyl har några tusen gener?","b":"Kromosomen. Plasmiden har bara några få gener och kan saknas utan att bakterien dör.","ty":"f","t":["plasmid"],"src":"s. 182","id":"k9c1102foa"},{"f":"Vad har bakteriekromosomen gemensamt med mitokondriens DNA?","b":"Båda är ringformade (cirkulära). Det är ett av bevisen för endosymbiosteorin.","ty":"j","t":["endo"],"src":"s. 27, 182","id":"k9c12r867z"},{"f":"Vilka tre sätt kan bakterier få nya gener från andra bakterier?","b":"Transformation, konjugation och transduktion.","ty":"s","src":"s. 182–183 · PPT Antibiotika bild 8–10 · Arbetsblad lucka 22–24","p":1,"id":"k9c10x8y2u"},{"f":"Vad är transformation?","b":"Bakterien fiskar upp plasmider eller andra bitar naket DNA från omgivningen. Alla bakterier kan göra det då och då.","ty":"b","src":"s. 182 · PPT Antibiotika bild 9 · Arbetsblad lucka 22","p":1,"id":"k9coqxcfo"},{"f":"Var kommer DNA:t vid transformation ifrån?","b":"Från döda organismer som bryts ned. Läraren: från bakterier som dött och lyserat (spruckit).","ty":"b","src":"Arbetsblad · PPT Antibiotika bild 9","id":"k9c1nbriwb"},{"f":"Vad betyder att en bakterie är naturligt kompetent?","b":"Den kan ta upp DNA. Den binder DNA:t med proteiner på cellytan och tar in det i cellen.","ty":"b","src":"PPT Antibiotika bild 9","id":"k9c1x7u8lu"},{"f":"Vad händer med DNA:t som tas upp vid transformation?","b":"Ett DNA-fragment fogas in i kromosomen. En hel plasmid blir i stället en egen, separat del av bakterien.","ty":"b","t":["plasmid"],"src":"PPT Antibiotika bild 9","id":"k9c1hg7ew3"},{"f":"Vad är konjugation enligt boken?","b":"En bakterie fäster vid en närbesläktad bakterie bredvid, bildar en kanal och för över delar av sin arvsmassa.","ty":"b","src":"s. 182 · Arbetsblad lucka 24","p":1,"id":"k9cxcptu4"},{"f":"Vad är konjugation enligt läraren?","b":"Utbyte av DNA i form av plasmider mellan bakterier via kontakt med hjälp av sexpili.","ty":"b","t":["plasmid"],"src":"PPT Antibiotika bild 8","id":"k9c1krqniv"},{"f":"Vilken bakterie kan vara givarcell vid konjugation?","b":"Bara en bakterie med en plasmid som har gener för sexpili.","ty":"b","t":["plasmid"],"src":"PPT Antibiotika bild 8","id":"k9chzupvl"},{"f":"Varför kan konjugation snabbt göra om en hel population?","b":"Mottagarcellen får plasmiden med generna för sexpili och blir själv givarcell. Varje ny bärare sprider vidare.","ty":"v","t":["plasmid"],"src":"PPT Antibiotika bild 8","id":"k9c1u1h8gf"},{"f":"Vad förs över vid konjugation, boken eller läraren?","b":"Boken: delar av arvsmassan (figuren visar kromosom-DNA). Läraren och arbetsbladet: plasmider. Skriv: delar av arvsmassan, ofta plasmider.","ty":"f","t":["plasmid"],"src":"s. 182–183 · PPT Antibiotika bild 8","id":"k9c1dmw06w"},{"f":"Vad är transduktion?","b":"Gener eller stora paket av gener förs över mellan bakterier av ett bakterievirus.","ty":"b","src":"s. 183 · PPT Antibiotika bild 10 · Arbetsblad lucka 23","p":1,"id":"k9cmodzw3"},{"f":"Vad är en bakteriofag?","b":"Ett virus som kan infektera bakterier, ofta kallat fag.","ty":"b","src":"s. 185 · PPT Antibiotika bild 10","p":1,"id":"k9cfyjctp"},{"f":"Hur går transduktion till enligt lärarens bild?","b":"Fagen för in sitt DNA, som fogas in i kromosomen. En bit bakterie-DNA följer med in i en ny viruspartikel, som infekterar nästa bakterie och för in genen där.","ty":"i","src":"PPT Antibiotika bild 10","id":"k9c664w6p"},{"f":"Provfälla: transformation eller transduktion, vilket kräver virus?","b":"Transduktion. Vid transformation tas naket DNA upp utan budbärare.","ty":"f","src":"s. 182–183","id":"k9c3a109j"},{"f":"Vilket av de tre sätten kräver kontakt mellan två levande bakterier?","b":"Konjugation.","ty":"f","src":"s. 182","id":"k9chx67ri"},{"f":"Vilka etiketter har bokens figur på s. 183?","b":"Rekombination och transposoner (inom bakterien), konjugation, genöverföring via virus och transformation (mellan bakterier).","ty":"i","src":"s. 183","id":"k9cxygihs"},{"f":"Vart kan gener flytta inom en bakterie?","b":"Från en plasmid till kromosomen, eller från kromosomen till en plasmid.","ty":"b","t":["plasmid"],"src":"s. 183","id":"k9c6d8ngl"},{"f":"Vad är homolog rekombination (homolog omlagring)?","b":"En naturlig process där gener byter plats mellan olika delar av bakteriens arvsmassa, t.ex. mellan plasmid och kromosom.","ty":"b","src":"s. 183 · Arbetsblad","p":1,"id":"k9c1dxodlu"},{"f":"Vad är transposoner?","b":"Mobila genetiska element. Avsnitt av DNA som lätt kan flyttas eller kopieras, varpå kopian placeras på ett annat ställe i arvsmassan.","ty":"b","src":"s. 183 · Arbetsblad","p":1,"id":"k9csm8smh"},{"f":"Provfälla: flyttar transposoner gener mellan bakterier?","b":"Nej, inom bakteriens arvsmassa. För att hamna i en annan bakterie måste genen följa med, t.ex. på en plasmid.","ty":"f","t":["plasmid"],"src":"s. 183","id":"k9cy7mt7f"},{"f":"Vilken resistent bakterie bär ett hoppande genpaket (en transposon)?","b":"MRSA, meticillinresistenta gula stafylokocker. Transposonen ger resistens mot de flesta antibiotika som slår mot cellväggssyntesen.","ty":"s","src":"s. 215","id":"k9ccn101h"},{"f":"Hur vanliga är förluster, upptag och omflyttningar av gener för en enskild bakterie?","b":"Mycket ovanliga. Men över långa tidsperioder ger de stora förändringar i arvsmassan.","ty":"b","src":"s. 183","id":"k9c1s5g929"},{"f":"Vad leder genbytena till över lång tid?","b":"Arvsmassan förändras mycket och gener av olika ursprung kombineras på nya sätt.","ty":"b","src":"s. 183","id":"k9cpka6k7"},{"f":"Hur många gener delar en bakterie med alla sina artfränder?","b":"Många bakterier har inte ens hälften av sina gener gemensamt med alla artfränder. Huvuddelen av generna finns bara hos en del av arten.","ty":"s","src":"s. 183","id":"k9c18c6upv"},{"f":"Varför är det svårt att definiera en bakterieart?","b":"Bakterier av samma art kan ha mindre än hälften av generna gemensamt, eftersom gener tappas, tas upp och flyttas.","ty":"v","src":"s. 183","id":"k9cam5txh"},{"f":"Vad är vertikal spridning?","b":"Från en modercell till två dotterceller.","ty":"b","src":"PPT Antibiotika bild 7 · s. 186","id":"k9c1bf03bp"},{"f":"Vad är horisontell spridning?","b":"Från en bakterie till en annan, genom konjugation, transduktion eller transformation.","ty":"b","src":"PPT Antibiotika bild 7 · s. 186","id":"k9c1mnwga6"},{"f":"Hur använder boken vertikal och horisontell om evolutionen?","b":"Gener har förts vertikalt från anfader till avkomma, men också horisontellt mellan individer och arter, ofta med virus som transportörer.","ty":"b","src":"s. 186","id":"k9c1kwv1ix"},{"f":"Hur förklarar läraren att resistens blir vanligare?","b":"En bakterie i en antibiotikamiljö får en mutation som ger tålighet. Alla avkommor ärver den och får genom naturligt urval en överlevnadsfördel. Ju mer antibiotika, desto fler resistenta.","ty":"v","src":"PPT Antibiotika bild 7","id":"k9cvpmvl"},{"f":"Sitter resistensgener alltid på plasmider?","b":"Boken: i många fall på plasmider, men MRSA har sin i en transposon. Läraren skriver att de sitter på plasmider.","ty":"f","t":["plasmid"],"src":"s. 214–215 · PPT Antibiotika bild 7","id":"k9c1o1pjr8"},{"f":"Kan resistensgener flyttas mellan olika bakteriearter?","b":"Ja, enligt boken kan de flyttas från en bakterie till en annan, även över artgränser.","ty":"b","src":"s. 213–214","id":"k9cbip7h0"},{"f":"Provfälla: blir människan resistent mot antibiotika?","b":"Nej, det är bakterierna som blir resistenta. Antibiotikan skapar inte heller resistensgenen. Den dödar de känsliga så att de resistenta får plats.","ty":"f","src":"PPT Antibiotika bild 2, 7","id":"k9ce8t9zc"}],"quiz":{"f":[{"q":"Vad kallas bakterier som bildats genom delning och har i stort sett samma arvsanlag?","o":["Kloner","Plasmider","Transposoner","Kolonier av mutanter"],"why":"Delning ger kloner, eftersom arvsmassan kopieras och delas lika.","src":"s. 182","id":"k9qjhr1in"},{"q":"Varför är mutationer ovanliga när bakterier delar sig?","o":["Arvsmassan är så liten","Bakterier har inget DNA","Bakterier saknar enzymer","Plasmiderna rättar alla fel"],"why":"Med liten arvsmassa ändras en DNA-bokstav bara vid var tionde, hundrade eller tusende delning.","src":"s. 182","id":"k9q85gsn0"},{"q":"Hur lång är en bakteriegeneration under gynnsamma förhållanden enligt läraren?","o":["1–3 timmar","1–3 dygn","1–3 sekunder","1–3 veckor"],"why":"1–3 timmar, och vissa arter kan dela sig var tjugonde minut.","src":"PPT Mikroorganismer bild 28","id":"k9qkk7n4g"},{"q":"Hur ser bakteriens kromosom ut?","o":["En cirkulär DNA-molekyl","Flera raka DNA-molekyler i en kärna","En RNA-ring","Ett proteinnät"],"why":"Boken och arbetsbladet: en cirkulär DNA-molekyl.","src":"s. 182 · Arbetsblad lucka 18–20","id":"k9qw672j"},{"q":"Hur många gener har en typisk bakteriekromosom?","o":["Några tusen","Några få","Några miljoner","Exakt hundra"],"why":"Kromosomen har några tusen gener. Plasmiden har ett litet antal.","src":"s. 182","id":"k9qlpn0yk"},{"q":"Vilket exempel på plasmidgener ger boken?","o":["Gener för resistens mot ett antibiotikum","Gener för ribosomernas rRNA","Gener för cellväggen","Gener för celldelning"],"why":"Plasmidgener behövs under speciella omständigheter, t.ex. när antibiotika finns.","src":"s. 182","t":["plasmid"],"id":"k9q4xl4n0"},{"q":"Vilket arbetsbladsexempel på extrem miljö där plasmidgener hjälper stämmer?","o":["Hög metallhalt","Brist på ljus","Hög syrehalt","Låg salthalt"],"why":"Arbetsbladet: t.ex. hög metallhalt eller antibiotika.","src":"Arbetsblad","t":["plasmid"],"id":"k9q15nqaxo"},{"q":"Vad kallas processen när en bakterie tar upp naket DNA från omgivningen?","o":["Transformation","Transduktion","Konjugation","Transposition"],"why":"Transformation. Transduktion kräver virus och konjugation kontakt.","src":"s. 182 · Arbetsblad lucka 22","id":"k9q1gicohf"},{"q":"Vad kallas bakterier som kan ta upp DNA vid transformation enligt läraren?","o":["Naturligt kompetenta","Givarceller","Lyserade","Kloner"],"why":"Kompetenta bakterier binder DNA med proteiner på cellytan.","src":"PPT Antibiotika bild 9","id":"k9q1airdcx"},{"q":"Vad använder bakterierna för kontakten vid konjugation enligt läraren?","o":["Sexpili","Flageller","Kärnporer","Bakteriofager"],"why":"Konjugation sker via kontakt med hjälp av sexpili.","src":"PPT Antibiotika bild 8","id":"k9qq0p27d"},{"q":"Vilka bakterier kan konjugera enligt boken?","o":["Närbesläktade bakterier bredvid varandra","Bara bakterier av olika domäner","Bara döda bakterier","Bakterier långt ifrån varandra via vatten"],"why":"Boken: överföring till närbesläktade bakterier bredvid, via en kanal.","src":"s. 182","id":"k9q147b754"},{"q":"Vad för över gener vid transduktion?","o":["Ett bakterievirus (bakteriofag)","En sexpilus","Naket DNA i vattnet","En transposon"],"why":"Transduktion: gener förs över av bakterievirus.","src":"s. 183 · PPT Antibiotika bild 10","id":"k9qg5t0ty"},{"q":"Vad kallas avsnitt av DNA som lätt kan flyttas eller kopieras till ett annat ställe i arvsmassan?","o":["Transposoner","Plasmider","Ribosomer","Kloner"],"why":"Transposoner är mobila genetiska element.","src":"s. 183","id":"k9q1y4wd5a"},{"q":"Vad är ett annat namn för homolog rekombination?","o":["Homolog omlagring","Transduktion","Konjugation","Mutation"],"why":"Boken: homolog omlagring (homolog rekombination).","src":"s. 183","id":"k9q21mzmh"},{"q":"Hur stor del av sina gener delar många bakterier med alla sina artfränder?","o":["Mindre än hälften","Alla","Exakt 90 %","Ingen alls"],"why":"Många bakterier har inte ens hälften av generna gemensamt med alla artfränder.","src":"s. 183","id":"k9q65n9up"},{"q":"Vad är vertikal spridning?","o":["Från modercell till två dotterceller","Från en bakterie till en annan via virus","Upptag av DNA från omgivningen","Från plasmid till kromosom"],"why":"Lärarens definition. Horisontell spridning är mellan bakterier.","src":"PPT Antibiotika bild 7","id":"k9q1bf03bp"},{"q":"Vilken av följande är INTE horisontell spridning?","o":["Delning","Konjugation","Transduktion","Transformation"],"why":"Delning är vertikal spridning, från modercell till dotterceller.","src":"PPT Antibiotika bild 7","id":"k9q16vc25p"},{"q":"Var sitter MRSA:s resistens mot cellväggsantibiotika enligt boken?","o":["I en transposon, ett hoppande genpaket","I cellkärnan","I ribosomerna","I en sexpilus"],"why":"Boken s. 215: MRSA bär ett hoppande genpaket, en transposon.","src":"s. 215","id":"k9qeqe7qk"},{"q":"Vad har bakterier som virus saknar enligt läraren?","o":["Egen ämnesomsättning","DNA","Proteiner","Förmåga att mutera"],"why":"Bakterierna kan ta upp syre och näring och avge avfall. Virus har ingen egen ämnesomsättning.","src":"PPT Mikroorganismer bild 28","id":"k9qayte6s"}],"u":[{"q":"Varför kan en plasmid utan nytta långsamt försvinna ur en population?","o":["Ibland blir en dotterbakterie utan, och plasmiden ger ingen överlevnadsfördel","Plasmiden bryts ner av lysosomer","Plasmiden muterar till kromosom","Antibiotika förstör plasmiden"],"why":"Inget maskineri fördelar plasmiderna. Utan fördel klarar sig plasmidlösa bakterier lika bra och blir fler.","src":"s. 182, 214","t":["plasmid"],"id":"k9qgddv9b"},{"q":"En population bakterier lever länge i en miljö med antibiotika. Vad händer med resistensplasmiderna?","o":["De blir kvar, eftersom bakterier utan plasmid dör","De försvinner snabbt","De flyttar till virus","De blir till ribosomer"],"why":"Med antibiotika ger plasmiden en överlevnadsfördel.","src":"s. 182, 214","t":["plasmid"],"id":"k9q1sne1ro"},{"q":"En bakterie spricker och dör. En granne tar upp en plasmid som flöt ut. Vad kallas det?","o":["Transformation","Konjugation","Transduktion","Vertikal spridning"],"why":"Upptag av naket DNA från omgivningen är transformation.","src":"s. 182 · PPT Antibiotika bild 9","id":"k9q1q0qj2e"},{"q":"Två bakterier har aldrig träffats, men en gen har gått från den ena till den andra via ett virus. Vad kallas det?","o":["Transduktion","Transformation","Konjugation","Homolog rekombination"],"why":"Vid transduktion är bakterieviruset budbäraren.","src":"s. 183 · PPT Antibiotika bild 10","id":"k9q1hop2hq"},{"q":"Varför kan bara vissa bakterier vara givarceller vid konjugation?","o":["Bara de har en plasmid med gener för sexpili","Bara de är naturligt kompetenta","Bara de har en cellkärna","Bara de är döda"],"why":"Generna för sexpili sitter på plasmiden.","src":"PPT Antibiotika bild 8","t":["plasmid"],"id":"k9q1mtf3to"},{"q":"Varför sprids resistens snabbare genom konjugation än genom nya mutationer?","o":["Varje mottagare blir själv givare, och genen behöver inte uppstå på nytt","Konjugation skapar nya mutationer","Konjugation dödar känsliga bakterier","Mutationer sker aldrig hos bakterier"],"why":"Mutationer är ovanliga. En resistensplasmid kan i stället lånas ut och sprids vidare av varje ny bärare.","src":"s. 182 · PPT Antibiotika bild 7–8","t":["plasmid"],"id":"k9q41160d"},{"q":"En resistensgen sitter på kromosomen. Hur kan den hamna i en annan bakterie via konjugation med plasmid?","o":["En transposon kopierar den till en plasmid som sedan förs över","Kromosomen förs över hel genom kärnporen","Genen lämnar cellen som ett virus","Det går inte"],"why":"Transposoner flyttar gener mellan kromosom och plasmid, och plasmiden kan föras över.","src":"s. 183, 213–214","t":["plasmid"],"id":"k9ql8tlfe"},{"q":"Vilket påstående skiljer homolog rekombination från konjugation?","o":["Homolog rekombination flyttar gener inom en bakterie, konjugation mellan bakterier","Båda kräver virus","Båda sker bara vid delning","Konjugation sker inom en bakterie"],"why":"Rekombination och transposoner verkar inom bakteriens arvsmassa. De tre överföringssätten går mellan bakterier.","src":"s. 182–183","id":"k9q1c94clr"},{"q":"Varför är det svårt att definiera vad en bakterieart är?","o":["Bakterier av samma art kan ha mindre än hälften av generna gemensamt","Bakterier saknar DNA","Alla bakterier är kloner av varandra","Bakterier förökar sig sexuellt"],"why":"Gener tappas, tas upp och flyttas, så arvsmassan varierar mycket inom en art.","src":"s. 183","id":"k9q10386a6"},{"q":"Vad är rätt enligt lärarens förklaring av hur resistens blir vanlig?","o":["Antibiotika selekterar bakterier som redan fått en resistensmutation","Antibiotika får bakterierna att skapa resistensgener","Människan blir resistent","Resistens sprids bara vertikalt"],"why":"Mutationen uppstår slumpvis. Naturligt urval ger de resistenta en överlevnadsfördel.","src":"PPT Antibiotika bild 7","id":"k9qwr9tnf"},{"q":"Varför ses bakteriens delning som ärftlighet utan sex?","o":["En bakterie blir två utan att två föräldrar blandar gener","Bakterien har två kön","Generna blandas med en annan bakterie vid delningen","Bakterien saknar DNA"],"why":"Delning är könlös: arvsmassan kopieras och delas mellan dottercellerna.","src":"s. 182 · PPT Mikroorganismer bild 28","id":"k9qqvvrhp"},{"q":"Varför kan horisontell genöverföring göra att resistens dyker upp var och när som helst?","o":["Resistensgener kan hoppa i arvsmassan och flyttas mellan bakterier, även över artgränser","Resistensgener bildas av antibiotikan","Alla bakterier har redan alla resistensgener","Virus gör människan resistent"],"why":"Boken s. 213–214: mekanismer gör att resistensgener kan hoppa och flyttas, även mellan arter.","src":"s. 213–214","id":"k9q1ir0v0w"}],"o":[{"q":"Beskriv de tre sätt på vilka bakterier kan få nya gener från andra bakterier.","model":"Transformation: bakterien fiskar upp plasmider eller bitar naket DNA från omgivningen, t.ex. från döda bakterier som spruckit. Naturligt kompetenta bakterier binder DNA:t med proteiner på cellytan och fogar in det i kromosomen, och en hel plasmid blir en egen del. Konjugation: bakterien fäster vid en närbesläktad granne och för över delar av sin arvsmassa, ofta plasmider, genom en kanal via sexpili. Mottagaren kan sedan själv bli givare. Transduktion: ett bakterievirus för över gener eller paket av gener från en bakterie till en annan.","kw":[["transformation"],["naket dna","omgivning"],["konjugation"],["sexpil","kanal","kontakt"],["transduktion"],["virus","fag"]],"src":"s. 182–183 · PPT Antibiotika bild 8–10","id":"k9o1j5jdsj"},{"q":"Jämför kromosom och plasmid och förklara varför plasmider ibland försvinner och ibland blir kvar i en bakteriepopulation.","model":"Kromosomen är en cirkulär DNA-molekyl med några tusen gener som bakterien ständigt behöver. Plasmider är extra, mindre, cirkulära DNA-molekyler med få gener för speciella omständigheter, t.ex. antibiotikaresistens. Plasmiderna kopieras inför delningen, men inget maskineri fördelar dem, så ibland blir en dotterbakterie utan. Ger plasmiden ingen överlevnadsfördel försvinner den långsamt ur populationen. Finns antibiotika i miljön dör de bakterier som saknar resistensplasmiden, och därför blir den kvar.","kw":[["cirkulär"],["tusen"],["få gener","litet antal"],["resistens"],["maskineri","utan"],["överlevnadsfördel","fördel"]],"src":"s. 182, 214","t":["plasmid"],"id":"k9o1f3qq76"},{"q":"Förklara vertikal och horisontell spridning och varför antibiotikaresistens kan spridas så snabbt bland bakterier.","model":"Vertikal spridning är från en modercell till två dotterceller. Horisontell spridning är från en bakterie till en annan genom konjugation, transduktion eller transformation. Om en bakterie i en antibiotikamiljö får en mutation som gör den resistent ärver alla avkommor egenskapen, och genom naturligt urval får de en överlevnadsfördel. Resistensgener ligger ofta på plasmider och kan lånas ut horisontellt, t.ex. genom konjugation där varje mottagare blir ny givare, även över artgränser. Transposoner kan flytta resistensgener mellan kromosom och plasmid. Ju mer antibiotika används, desto vanligare blir resistenta bakterier.","kw":[["vertikal"],["horisontell"],["mutation"],["urval","överlevnadsfördel"],["plasmid"],["konjugation"],["artgräns","transposon"]],"src":"PPT Antibiotika bild 7 · s. 213–214","t":["plasmid"],"id":"k9ora6yun"},{"q":"Beskriv hur gener kan flytta inom en bakterie och vad förluster, upptag och omflyttningar av gener leder till över lång tid.","model":"Gener och paket av gener kan flytta från en plasmid till kromosomen eller tvärtom. Det sker bland annat genom homolog omlagring (homolog rekombination) och med transposoner, mobila genetiska element som lätt kan flyttas eller kopieras till ett annat ställe i arvsmassan. För en enskild bakterie är det mycket ovanligt, men över lång tid kan arvsmassan förändras mycket och gener av olika ursprung kombineras på nya sätt. Många bakterier har inte ens hälften av generna gemensamt med alla artfränder, och därför är det svårt att definiera en bakterieart.","kw":[["plasmid"],["kromosom"],["homolog"],["transposon"],["lång tid"],["hälften"],["art"]],"src":"s. 183","id":"k9oqxtdho"}]},"kan":[{"q":"Kan du förklara varför bakterier som delar sig bildar kloner, och hur ofta mutationer sker?","a":"Bakterier förökar sig genom delning, en könlös förökning. Bakterien kopierar sin arvsmassa före delningen, och de två bakterierna får därför i de allra flesta fall identisk arvsmassa. Så bildas kloner med i stort sett samma arvsanlag. Ibland blir det fel vid kopieringen, en mutation, men bakteriens arvsmassa är så liten att någon enstaka DNA-bokstav ändras bara vid en delning på tio, hundra eller tusen.","kw":[["delning","delar"],["könlös"],["identisk"],["klon"],["mutation"],["tio","hundra","tusen"]],"src":"s. 182 · PPT Mikroorganismer bild 28","id":"k9kvqmsy5"},{"q":"Kan du jämföra bakteriens kromosom och plasmider?","a":"Kromosomen är en cirkulär DNA-molekyl med några tusen gener som bakterien ständigt behöver. Plasmider är extra, mindre, cirkulära DNA-molekyler med ett litet antal gener som bakterien har nytta av under speciella omständigheter, t.ex. resistens mot ett antibiotikum. Båda kan förändras: bakterien kan förlora stora avsnitt av kromosomen, och en dotterbakterie kan bli helt utan plasmid vid en delning.","kw":[["cirkulär"],["tusen"],["mindre","extra"],["få gener","litet antal"],["resistens","antibiotik"],["förlor","utan"]],"src":"s. 182","t":["plasmid"],"id":"k9k173w7ph"},{"q":"Kan du förklara varför plasmider långsamt kan försvinna ur en bakteriepopulation?","a":"Plasmiderna kopieras inför varje delning, men inget maskineri ser till att båda dotterbakterierna får en plasmid. Därför blir ibland en bakterie utan. Om plasmiden inte ger någon överlevnadsfördel i miljön klarar sig bakterierna utan plasmid lika bra, och plasmiden kan långsamt försvinna. Finns antibiotika i miljön dör i stället de bakterier som saknar resistensplasmiden, och plasmiden blir kvar.","kw":[["delning"],["maskineri"],["utan"],["överlevnadsfördel","fördel"],["antibiotik"]],"src":"s. 182, 214","t":["plasmid"],"id":"k9k6ba3ec"},{"q":"Kan du förklara transformation?","a":"Vid transformation fiskar en bakterie upp plasmider eller andra bitar naket DNA från omgivningen. Boken säger att alla bakterier kan göra det då och då. DNA:t kommer från döda organismer som bryts ned, enligt läraren bakterier som dött och lyserat. Naturligt kompetenta bakterier binder DNA:t med proteiner på cellytan, tar in det och fogar in det i kromosomen. En hel plasmid blir i stället en egen, separat del av bakterien.","kw":[["naket dna","dna"],["omgivning"],["död","lyser"],["kompetent"],["kromosom"],["plasmid"]],"src":"s. 182 · PPT Antibiotika bild 9 · Arbetsblad","t":["plasmid"],"id":"k9k1jscc3r"},{"q":"Kan du förklara konjugation?","a":"Vid konjugation fäster en bakterie vid en närbesläktad bakterie bredvid, bildar en kanal och för över delar av sin arvsmassa, enligt läraren plasmider, via kontakt med sexpili. Plasmiden innehåller gener för sexpili, och därför kan bara en bakterie med en sådan plasmid vara givarcell. Mottagarcellen kan sedan själv bilda sexpili och bli givare. Därför kan några få bakterier snabbt göra om en hel population, och resistens kan spridas mycket snabbt.","kw":[["närbesläkt","granne","bredvid"],["kanal","kontakt"],["sexpil"],["plasmid"],["givar"],["mottagar"]],"src":"s. 182 · PPT Antibiotika bild 8 · Arbetsblad","t":["plasmid"],"id":"k9k1lw44v7"},{"q":"Kan du förklara transduktion?","a":"Vid transduktion förs gener eller stora paket av gener över mellan bakterier av ett bakterievirus, en bakteriofag. Fagen för in sitt DNA i en bakterie, och virus-DNA:t fogas in i kromosomen. När nya virus byggs följer en bit av bakteriens DNA med. När det viruset infekterar nästa bakterie för det in genen där, utan att bakterierna har träffats.","kw":[["virus","bakteriofag","fag"],["infekter"],["gen"],["kromosom"],["träff","kontakt"]],"src":"s. 183 · PPT Antibiotika bild 10 · Arbetsblad","id":"k9k19el3dg"},{"q":"Kan du förklara hur gener kan flytta inom en bakteries egen arvsmassa?","a":"Gener och paket av gener kan flytta från en plasmid till kromosomen eller tvärtom. Det sker bland annat genom homolog omlagring, eller homolog rekombination, en naturlig process. Det kan också ske med transposoner, mobila genetiska element. Det är avsnitt av DNA som lätt kan flyttas eller kopieras, varpå kopian placeras någon annanstans i arvsmassan.","kw":[["plasmid"],["kromosom"],["homolog"],["rekombination","omlagring"],["transposon"],["kopier","flytt"]],"src":"s. 183 · Arbetsblad","id":"k9k6l3h7s"},{"q":"Kan du förklara vad genbytena leder till över lång tid?","a":"För en enskild bakterie är förluster, upptag och omflyttningar av gener mycket ovanliga. Men över långa tidsperioder kan bakteriers arvsmassa förändras mycket, och gener av olika ursprung kombineras på nya sätt. Många bakterier har inte ens hälften av sina gener gemensamt med alla sina artfränder, och huvuddelen av generna hos en art finns bara hos en del medlemmar. Därför är det svårt att definiera en bakterieart.","kw":[["ovanlig"],["lång tid","längre tid"],["kombiner"],["hälften"],["art"]],"src":"s. 183","id":"k9kkad481"},{"q":"Kan du förklara skillnaden mellan vertikal och horisontell spridning av gener?","a":"Vertikal spridning är från en modercell till två dotterceller, vid delning. Horisontell spridning är från en bakterie till en annan, genom konjugation, transduktion eller transformation. Boken använder orden också om evolutionen: gener förs vertikalt från anfader till avkomma, men också horisontellt mellan individer och arter, ofta med virus som transportörer.","kw":[["vertikal"],["modercell","dotterc"],["horisontell"],["konjugation","transduktion","transformation"],["virus"]],"src":"PPT Antibiotika bild 7 · s. 186","t":["plasmid"],"id":"k9kegu0ez"},{"q":"Kan du förklara varför antibiotikaresistens kan spridas så snabbt bland bakterier?","a":"Om det finns antibiotika i miljön och en bakterie får en mutation som gör att den tål antibiotikan ärver alla dess avkommor egenskapen. Genom naturligt urval får de en överlevnadsfördel, och ju mer antibiotika som används, desto vanligare blir resistenta bakterier. Resistensgener ligger dessutom i många fall på plasmider, och de kan spridas horisontellt, t.ex. genom konjugation, även över artgränser. Transposoner kan flytta resistensgener mellan kromosom och plasmid.","kw":[["mutation"],["ärv","avkomm"],["urval","överlevnadsfördel"],["plasmid"],["horisontell","konjugation"],["artgräns","transposon"]],"src":"PPT Antibiotika bild 7 · s. 213–214","t":["plasmid"],"id":"k9k1x02cas"}],"kompis":[{"q":"Förklara för en kompis hur en resistensplasmid kan sprida sig genom en hel bakteriepopulation med konjugation.","model":"En bakterie har en plasmid med en resistensgen och gener för sexpili. Därför kan den vara givarcell. Den fäster vid en närbesläktad mottagarcell med sexpilus, och en kopia av plasmiden förs över genom kanalen. Nu har båda bakterierna plasmiden, och mottagaren kan själv bilda sexpili och bli givare. Varje ny bärare blir alltså en ny givare, och därför kan några få bakterier snabbt göra om hela populationen. Finns antibiotika i miljön dör de som saknar plasmiden, och de resistenta tar över.","kw":[["plasmid"],["sexpil"],["givar"],["mottagar"],["kopia","för över"],["population"],["antibiotik"]],"src":"s. 182 · PPT Antibiotika bild 8","t":["plasmid"],"id":"k9eiu8cx"},{"q":"Förklara för en kompis skillnaden mellan transformation, konjugation och transduktion.","model":"Alla tre flyttar gener mellan bakterier. Vid transformation fiskar bakterien upp naket DNA, plasmider eller DNA-bitar, från omgivningen, t.ex. från döda bakterier som spruckit. Vid konjugation fäster bakterien vid en levande, närbesläktad granne och för över delar av arvsmassan, ofta plasmider, genom en kanal. Det är det enda sättet där två levande bakterier måste ha kontakt. Vid transduktion är ett bakterievirus budbärare. Det tar med sig gener från en bakterie och för in dem i nästa.","kw":[["naket dna","omgivning"],["död","lyser"],["granne","kontakt"],["kanal","sexpil"],["virus","fag"],["budbärar","för in"]],"src":"s. 182–183 · PPT Antibiotika bild 8–10","id":"k9e1nnw27g"},{"q":"Förklara för en kompis varför plasmider med resistensgener blir kvar när det finns antibiotika men kan försvinna annars.","model":"Plasmider kopieras inför delningen, men inget maskineri fördelar kopiorna, så ibland blir en dotterbakterie utan plasmid. Utan antibiotika ger plasmiden ingen överlevnadsfördel. Bakterier utan plasmid klarar sig lika bra, och plasmiden kan långsamt försvinna ur populationen. Med antibiotika i miljön dör bakterierna utan resistensplasmid, medan de med plasmiden överlever och delar sig. Därför blir plasmiden kvar, och därför ska antibiotikaanvändningen hållas nere.","kw":[["kopier"],["maskineri","fördela"],["utan"],["överlevnadsfördel","fördel"],["antibiotik"],["dör","överlev"]],"src":"s. 182, 214","t":["plasmid"],"id":"k9e14h8gd8"}],"gloss":[{"w":"Bakteriofag (fag)","d":"Virus som kan infektera bakterier.","src":"Bok s. 185 · PPT Antibiotika bild 10"},{"w":"Delning","d":"Bakteriers könlösa förökning. En bakterie blir två med nästan alltid identisk arvsmassa.","src":"Bok s. 182"},{"w":"Generation","d":"En celldelning. Hos bakterier 1–3 timmar under gynnsamma förhållanden, ibland 20 minuter.","src":"PPT Mikroorganismer bild 28","lek":1},{"w":"Givarcell","d":"Bakterien som för över en plasmid vid konjugation. Måste ha plasmiden med gener för sexpili.","src":"PPT Antibiotika bild 8","lek":1},{"w":"Homolog rekombination (homolog omlagring)","d":"Naturlig process där gener byter plats inom bakteriens arvsmassa, t.ex. mellan plasmid och kromosom.","src":"Bok s. 183"},{"w":"Horisontell spridning","d":"Gener förs från en bakterie till en annan genom konjugation, transduktion eller transformation.","src":"PPT Antibiotika bild 7 · Bok s. 186"},{"w":"Klon","d":"Bakterier med i stort sett samma arvsanlag, bildade genom delning.","src":"Bok s. 182"},{"w":"Kompetent bakterie","d":"Bakterie som naturligt kan binda och ta upp DNA från omgivningen.","src":"PPT Antibiotika bild 9","lek":1},{"w":"Konjugation","d":"En bakterie fäster vid en närbesläktad granne, bildar en kanal och för över delar av arvsmassan, ofta plasmider via sexpili.","src":"Bok s. 182 · PPT Antibiotika bild 8"},{"w":"Kromosom (bakterie)","d":"Bakteriens cirkulära DNA-molekyl med några tusen gener.","src":"Bok s. 182"},{"w":"Könlös förökning","d":"Förökning utan att två föräldrar blandar gener, t.ex. bakteriens delning.","src":"PPT Mikroorganismer bild 28 · Bok s. 182"},{"w":"Lysera","d":"Spricka. DNA från bakterier som dött och lyserat kan tas upp vid transformation.","src":"PPT Antibiotika bild 9","lek":1},{"w":"Mobila genetiska element","d":"DNA-avsnitt som kan flytta i arvsmassan, t.ex. transposoner.","src":"Bok s. 183"},{"w":"Mottagarcell","d":"Bakterien som tar emot plasmiden vid konjugation. Kan sedan bli givarcell.","src":"PPT Antibiotika bild 8","lek":1},{"w":"MRSA","d":"Meticillinresistenta gula stafylokocker. Bär ett hoppande genpaket (transposon) med resistens.","src":"Bok s. 215"},{"w":"Mutation","d":"Förändring i arvsmassan när den kopieras. Hos bakterier en ändrad DNA-bokstav på var tionde till tusende delning.","src":"Bok s. 182"},{"w":"Naket DNA","d":"DNA fritt i omgivningen, utan cell runt sig. Tas upp vid transformation.","src":"Bok s. 182"},{"w":"Naturligt urval","d":"Bakterier med en fördelaktig egenskap, t.ex. resistens, överlever och förökar sig mer.","src":"PPT Antibiotika bild 7","lek":1},{"w":"Plasmid","d":"Extra, mindre, cirkulär DNA-molekyl med få gener för speciella omständigheter, t.ex. resistens.","src":"Bok s. 182"},{"w":"Resistensgen","d":"Gen som gör bakterien okänslig för ett antibiotikum. Sitter i många fall på plasmider.","src":"Bok s. 182, 214"},{"w":"Sexpili","d":"Utskott som bakterier använder för kontakten vid konjugation. Generna sitter på plasmiden.","src":"PPT Antibiotika bild 8","lek":1},{"w":"Transduktion","d":"Gener eller paket av gener förs över mellan bakterier av ett bakterievirus.","src":"Bok s. 183"},{"w":"Transformation","d":"En bakterie fiskar upp plasmider eller bitar naket DNA från omgivningen.","src":"Bok s. 182"},{"w":"Transposon","d":"Mobilt genetiskt element. DNA-avsnitt som lätt flyttas eller kopieras till ett annat ställe i arvsmassan.","src":"Bok s. 183"},{"w":"Vertikal spridning","d":"Gener förs från en modercell till två dotterceller.","src":"PPT Antibiotika bild 7 · Bok s. 186"}],"snabb":{"keys":["Delning :: könlös förökning, kloner med nästan identisk arvsmassa","Mutation hos bakterier :: ovanlig, en DNA-bokstav per 10, 100 eller 1000 delningar, eftersom arvsmassan är liten","Kromosom :: cirkulär DNA-molekyl, några tusen gener","Plasmid :: extra, mindre, cirkulär DNA; få gener, t.ex. resistens","Plasmid försvinner :: ingen fördelning vid delning + ingen överlevnadsfördel","Transformation :: naket DNA från omgivningen (döda, lyserade bakterier), kompetenta bakterier","Konjugation :: kontakt och kanal till närbesläktad granne, sexpili, ofta plasmider","Transduktion :: bakterievirus (fag) bär gener mellan bakterier","Homolog rekombination :: gener byter plats mellan plasmid och kromosom","Transposon :: DNA-avsnitt som flyttas eller kopieras i arvsmassan","Vertikal / horisontell :: modercell → dotterceller / bakterie → bakterie","Över lång tid :: mindre än hälften av generna gemensamt inom en art"],"nums":[["1 på 10–1000","delningar ger en ändrad DNA-bokstav (s. 182)"],["några tusen","gener på bakteriekromosomen (s. 182)"],["1–3 h","en bakteriegeneration (PPT Mikroorganismer bild 28)"],["20 min","snabbaste generationstiden hos vissa arter (PPT bild 28)"],["3","sätt att få gener från andra bakterier (s. 182–183)"],["2","sätt att flytta gener inom bakterien: homolog rekombination och transposoner (s. 183)"],["< 1/2","av generna gemensamma med alla artfränder hos många bakterier (s. 183)"]],"chains":[["Arvsmassan kopieras","bakterien delar sig","två kloner med samma arvsmassa"],["Plasmid kopieras","ingen fördelning vid delning","dotterbakterie utan plasmid","ingen fördel → plasmiden försvinner"],["Givare med plasmid (sexpiligener)","kontakt via sexpilus","plasmidkopia till mottagaren","mottagaren blir givare","hela populationen får genen"],["Fag infekterar bakterie 1","bakterie-DNA hamnar i ny fag","fagen infekterar bakterie 2","genen fogas in"],["Antibiotika i miljön","mutation ger resistens","avkommorna ärver","naturligt urval","resistenta blir vanliga"],["Transposon kopierar resistensgen till plasmid","plasmiden förs över","ny bakterie blir resistent"]],"traps":["Kloner har identisk arvsmassa i de allra flesta fall, inte alltid.","Könlös förökning betyder inte att bakterier aldrig byter gener.","Kromosomen har några tusen gener, plasmiden bara få.","Transformation = naket DNA, transduktion = virus. Bara konjugation kräver kontakt.","Rekombination och transposoner flyttar gener inom en bakterie, de tre överföringssätten mellan bakterier.","Boken: resistensgener ligger i många fall på plasmider (MRSA: transposon). Läraren: på plasmider.","Det är bakterierna som blir resistenta, och antibiotikan skapar inte resistensgenen."]}},"k10":{"pre":[{"q":"Vilka två av livets tre domäner är närmast släkt?","o":["Arkéer och eukaryoter","Bakterier och arkéer","Bakterier och eukaryoter","Bakterier och virus"],"why":"Bakterierna grenade av först i livets träd. Arkéer och eukaryoter har en senare gemensam förfader.","src":"PPT Mikroorganismer bild 20, 36","id":"k10p3evccd"},{"q":"Vilken av organismerna kan leva vid +122 °C?","o":["Termofila arkéer","Herpesviruset","Plasmodium","Mjölksyrabakterier"],"why":"Värmeälskande (termofila) arkéer klarar att växa och dela sig vid +122 °C.","src":"s. 184","id":"k10psnvaeq"},{"q":"Hur många arkéer som orsakar sjukdom hos människa eller djur känner man till?","o":["Ingen","Ungefär tio","Ungefär hälften av alla arter","Bara de som bildar metan"],"why":"Boken: hittills har man inte hittat en enda arké som orsakar sjukdom hos vare sig människa eller djur.","src":"s. 184 · PPT Mikroorganismer bild 37","p":1,"id":"k10pvl7ekt"},{"q":"Varför kan ett virus inte föröka sig på egen hand?","o":["Det saknar egen ämnesomsättning och måste använda en cells energi och näring","Det har inget DNA eller RNA","Det är för stort för att dela sig","Det dör direkt utanför kroppen"],"why":"Viruset får en levande cell att använda sin energi och sina näringsämnen till att göra nya viruspartiklar.","src":"s. 184 · Arbetsblad","id":"k10p6t51ad"},{"q":"Var gömmer sig herpesviruset när det ligger latent?","o":["I nervceller","I röda blodkroppar","I levern","I tarmens bakterier"],"why":"Ofta i nervceller som startar eller slutar i de läppar som har infekterats.","src":"s. 186","id":"k10p8t1hr2"}],"cards":[{"f":"Vilka är livets tre huvudgrupper (domäner)?","b":"Bakterier, arkéer och eukaryoter.","ty":"b","src":"s. 178 · PPT Mikroorganismer bild 20","p":1,"id":"k10c1scnote"},{"f":"Vilka grupper är helt och hållet mikroorganismer?","b":"Alla bakterier och alla arkéer, liksom huvuddelen av alla eukaryota arter.","ty":"s","src":"s. 178","id":"k10c1qul1cu"},{"f":"Vad kallas bakterier och arkéer tillsammans?","b":"Prokaryoter, eftersom de saknar cellkärna.","ty":"b","src":"PPT Mikroorganismer bild 22","p":1,"id":"k10c1v93htt"},{"f":"Vilken domän grenade av först i livets träd?","b":"Bakterierna. Arkéer och eukaryoter har en senare gemensam förfader.","ty":"i","src":"PPT Mikroorganismer bild 20, 36","id":"k10cj7w719"},{"f":"Varför är arkéer och eukaryoter närmast släkt?","b":"Eftersom de har en senare gemensam förfader. Trädets andra förgrening delar dem först efter att bakterierna redan grenat av.","ty":"v","src":"PPT Mikroorganismer bild 20, 36","id":"k10c1glm2mt"},{"f":"Är bakterier och arkéer närmast släkt eftersom båda är prokaryoter?","b":"Nej. Prokaryot beskriver cellens byggnad (ingen kärna). I livets träd är arkéerna närmare släkt med eukaryoterna.","ty":"f","src":"PPT Mikroorganismer bild 20, 22","id":"k10c1sbw73n"},{"f":"När utvecklades de första bakterierna enligt läraren?","b":"För 3,5–4 miljarder år sedan.","ty":"s","src":"PPT Mikroorganismer bild 21","id":"k10c27mjxt"},{"f":"Är dagens bakterier primitiva?","b":"Nej. De härstammar från jordens mest ursprungliga livsformer, men de har utvecklats under miljarder år och är ytterst väl anpassade till dagens miljöer.","ty":"f","src":"PPT Mikroorganismer bild 20","id":"k10cr11juw"},{"f":"Varför är det svårt att definiera en art hos bakterier?","b":"Eftersom individerna skiljer sig mycket. De tappar, tar upp och flyttar gener, och många har inte ens hälften av generna gemensamma med alla artfränder.","ty":"v","src":"s. 183","id":"k10c1tspcql"},{"f":"Vad har man enats om att 16S rRNA-genen ska avgöra?","b":"Vilken släkt och familj en bakterie hör till.","ty":"s","t":["ribosom"],"src":"s. 183","id":"k10c12l33pp"},{"f":"Vad innebär förslaget till artbestämning med 16S rRNA?","b":"Bakterier med samma gen för 16S rRNA räknas som en art, oavsett hur lika eller olika de är i övrigt.","ty":"b","src":"s. 183","id":"k10c1n8h2z3"},{"f":"Vilka två fördelar har artbestämning med 16S rRNA?","b":"Systematiken grundas enhetligt på släktskap, och man kan artbestämma snabbt och enkelt utan att ha sett bakterierna.","ty":"s","src":"s. 183","id":"k10c1b2upx2"},{"f":"Vilket är det mindre problemet med 16S-förslaget?","b":"Bakterier som setts som olika arter, ibland olika släkten eller familjer, måste föras ihop, och en art kan behöva delas i flera.","ty":"s","src":"s. 183","id":"k10c9oij8e"},{"f":"Vilket är det stora problemet med 16S-förslaget?","b":"En del bakterier har flera kopior av genen med olika sekvens. Ska de då höra till flera arter samtidigt?","ty":"s","src":"s. 183","id":"k10caqvl1o"},{"f":"Vad visar arvsmassan om arkéerna?","b":"Att de utgör en separat huvudgren av livets träd, trots att de liknar bakterier till det yttre.","ty":"b","src":"s. 184 · PPT Mikroorganismer bild 36","p":1,"id":"k10c17lc8ey"},{"f":"Vad skiljer arkéernas cellmembran från andras (boken)?","b":"Fosfolipiderna skiljer sig rent kemiskt kraftigt från fosfolipiderna hos bakterier och eukaryoter.","ty":"j","t":["membran"],"src":"s. 184 · Arbetsblad","p":1,"id":"k10c1nx5wi3"},{"f":"Vad säger läraren skiljer arkéer från bakterier?","b":"De har inte samma material i sin cellvägg. Boken säger i stället cellmembranets fosfolipider. Svara med boken.","ty":"f","src":"PPT Mikroorganismer bild 37 · s. 184","id":"k10c1x60qti"},{"f":"Vad kallades arkéerna förr?","b":"De räknades till bakterierna. Bokens bildtext säger fortfarande arkebakterier.","ty":"b","src":"Arbetsblad · s. 184","id":"k10c1bo6lon"},{"f":"Vilka former kan arkéer ha?","b":"Fler än bakterier: platta och fyrkantiga, tunna nålformade, skrynkliga eller nästan perfekt rektangulära.","ty":"s","src":"s. 184","id":"k10cw68jg9"},{"f":"Var finns arkéer?","b":"I stort sett överallt: i luft, vatten, jord, djurs tarmar och på deras hud. Läraren: där bakterier lever.","ty":"s","src":"s. 184 · PPT Mikroorganismer bild 37","p":1,"id":"k10cvvyj5t"},{"f":"Varför finns arkéer på fler ställen än bakterier?","b":"Eftersom en del arkéer klarar miljöer som är för tuffa för alla andra livsformer (extremofiler).","ty":"v","src":"s. 184","id":"k10c14tvfay"},{"f":"Vad är en extremofil?","b":"En organism som lever i en miljö som är för tuff för alla andra livsformer.","ty":"b","src":"s. 184 · PPT Mikroorganismer bild 37","p":1,"id":"k10c1kz9iuj"},{"f":"Vad klarar halofila (saltälskande) arkéer?","b":"Höga salthalter. De färgar saltdammar röda och gröna. Arbetsbladet: Döda havet.","ty":"s","src":"s. 184 · Arbetsblad","p":1,"id":"k10cuh206v"},{"f":"Vilken temperatur klarar termofila arkéer?","b":"De växer och delar sig vid +122 °C. Arbetsbladet: de lever i heta källor.","ty":"s","src":"s. 184 · Arbetsblad","p":1,"id":"k10c1c544cg"},{"f":"Vilket pH klarar acidofila arkéer?","b":"pH 0, vilket motsvarar 1,2 M svavelsyra.","ty":"s","src":"s. 184 · Arbetsblad","p":1,"id":"k10c1kbsv3e"},{"f":"Var lever Sulfolobus?","b":"I vulkaniska källor med pH 2 och +85 °C.","ty":"s","src":"s. 184","id":"k10czci04n"},{"f":"Vad är speciellt med Deinococcus radiodurans?","b":"Hittades i Saharas öken. Den har system för att reparera sitt DNA mot solens UV-strålning, och därför tål den stark radioaktivitet.","ty":"s","src":"s. 184","id":"k10ccc1ywl"},{"f":"Varför är arkéer intressanta för frågan om livets uppkomst?","b":"Liv i så extrema miljöer ger perspektiv på livets uppkomst och på liv på andra planeter. Arkéer kanske mest liknar det första livet.","ty":"v","src":"s. 184","id":"k10c2grg7a"},{"f":"Vad gör arkéer i heta djuphavskällor?","b":"De utvinner energi ur oorganiska kemikalier och bildar kolhydrater, som livnär hela ekosystem runt källorna.","ty":"s","src":"s. 178","id":"k10c1mix6ki"},{"f":"Varför bidrar kött- och mjölkproduktion till global uppvärmning?","b":"Eftersom arkéer i idisslares matspjälkning bildar metan, och metan är en växthusgas.","ty":"v","src":"s. 184 · PPT Mikroorganismer bild 38","p":1,"id":"k10ccp801w"},{"f":"Var lever metanproducerande arkéer enligt läraren?","b":"I sumpmarker, i syrefattiga sjöbottnar och i tarmarna hos olika djur, eftersom de är anaeroba.","ty":"s","src":"PPT Mikroorganismer bild 38","id":"k10c1cqe01h"},{"f":"Hur kan människan använda arkéernas metan?","b":"Som biogas, som används som bränsle.","ty":"s","src":"Arbetsblad","id":"k10c1fuyz6r"},{"f":"Orsakar arkéer sjukdomar?","b":"Nej. Man har inte hittat en enda arké som orsakar sjukdom hos människa eller djur.","ty":"s","src":"s. 184 · PPT Mikroorganismer bild 37","p":1,"id":"k10cqua9pj"},{"f":"Hur påverkas arkéer av antibiotika enligt läraren?","b":"De tycks vara resistenta mot de flesta formerna av antibiotika.","ty":"s","src":"PPT Mikroorganismer bild 37","id":"k10cdf02rx"},{"f":"Är Deinococcus radiodurans en arké?","b":"Boken placerar den i arké-bildtexten, men i dag räknas den som en bakterie. Lär dig bildtexten som den står.","ty":"f","src":"Extra","id":"k10c1m71863"},{"f":"Vad är ett virus (bokens definition)?","b":"En bit arvsanlag, inslaget i ett paket med proteiner och ibland ett membran, som kan ta sig in i en levande cell och få den att använda sin energi och sina näringsämnen till att göra nya viruspartiklar.","ty":"b","src":"s. 184 · PPT Mikroorganismer bild 39","p":1,"id":"k10c1oa388d"},{"f":"Är virus levande?","b":"Det beror på vad man tycker är livets viktigaste egenskap. Egen ämnesomsättning och energihantering: döda. Informationsöverföring och evolution: levande.","ty":"v","src":"s. 184 · Arbetsblad","p":1,"id":"k10c1sho9yi"},{"f":"Varför kallar arbetsbladet virus för parasiter?","b":"Eftersom de inte har någon egen ämnesomsättning och måste invadera en cell för att kunna föröka sig.","ty":"v","src":"Arbetsblad","id":"k10c1rm2t23"},{"f":"Hur många virus är beskrivna, och hur många finns det?","b":"Över 5 000 är beskrivna i detalj. Man räknar med minst en miljon olika virus.","ty":"s","src":"s. 184 · PPT Mikroorganismer bild 39","p":1,"id":"k10c32771z"},{"f":"Vilka slags arvsanlag kan virus ha?","b":"DNA eller RNA, enkelsträngat eller dubbelsträngat.","ty":"s","src":"s. 185 · PPT Mikroorganismer bild 39","p":1,"id":"k10c68ukri"},{"f":"Hur stora är virus?","b":"Från 20 nm till en mikrometer.","ty":"s","src":"s. 185","id":"k10ck0vw7h"},{"f":"Har alla virus ett membranhölje?","b":"Nej. Virus kan ha eller sakna membranhölje.","ty":"f","src":"s. 185","id":"k10cqyng2u"},{"f":"Vilka livsformer kan infekteras av virus?","b":"Alla: växter, svampar, djur, encelliga eukaryoter, bakterier och arkéer.","ty":"s","src":"s. 185 · PPT Mikroorganismer bild 39","p":1,"id":"k10c1em456o"},{"f":"Vad är en bakteriofag?","b":"Ett virus som infekterar bakterier (boken: bakterier eller arkéer). Kallas också fag.","ty":"b","src":"s. 185 · PPT Mikroorganismer bild 39 · Arbetsblad","p":1,"id":"k10cfyjctp"},{"f":"Vilka två livsstilar kan virus ha i en cell?","b":"Ta över cellen med en gång och döda den, eller lägga sig som en tyst fripassagerare. Herpesviruset kan båda.","ty":"j","src":"s. 185","id":"k10ct5c4l7"},{"f":"Varför passar ett virus bara vissa celler?","b":"Eftersom virusets ytproteiner måste passa cellens membranproteiner, som nyckel i lås (boken: hand i handske).","ty":"v","t":["nyckel"],"src":"s. 185 · Extra","id":"k10cnn0n6m"},{"f":"Är virus alltid mindre än bakterier?","b":"Nej. De största virusen (1 µm) är lika stora som små bakterier.","ty":"f","src":"s. 180, 185","id":"k10c18vitbd"},{"f":"Hur är herpesviruset uppbyggt?","b":"En DNA-molekyl omgiven av ett proteinhölje, inslaget i ett membran med några proteiner.","ty":"i","src":"s. 185","id":"k10c1et96e4"},{"f":"Hur smittar herpesviruset?","b":"Genom kontakt mellan slemhinnor, t.ex. vid kyssar och sex.","ty":"s","src":"s. 185","id":"k10c1u9a8eo"},{"f":"Vilka två sorters herpesvirus nämner boken?","b":"Ett som orsakar munsår och ett som orsakar sår på könsorganen. Båda kan ibland ta sig in i den andra sortens slemhinna.","ty":"s","src":"s. 185","id":"k10cr20fd9"},{"f":"Herpes steg 1?","b":"Virusets membranproteiner binder som hand i handske till proteiner i slemhinnecellens membran. Membranen smälter ihop, och DNA och proteinhölje hamnar i cellen.","ty":"i","t":["nyckel","membran"],"src":"s. 185","id":"k10cvdlt45"},{"f":"Herpes steg 2 och 3?","b":"2: DNA-molekylen och proteinhöljet säras. 3: DNA:t förs in i kärnan och kopieras många gånger.","ty":"i","src":"s. 185","id":"k10czetx07"},{"f":"Herpes steg 4: vad gör de nya virusproteinerna?","b":"(a) Stänger av cellens förmåga att använda sina egna arvsanlag, (b) bryter ner cellens proteiner och arvsmassa till byggstenar, (c) bygger virusets membran och hölje.","ty":"i","src":"s. 185","id":"k10cccjac7"},{"f":"Herpes steg 5?","b":"DNA och proteiner ordnar sig till nya viruspartiklar, som slås in i en bit av cellens membran och knoppas av. Efter en tid dör cellen.","ty":"i","t":["membran"],"src":"s. 185","id":"k10c1uwjjwh"},{"f":"Varför dör slemhinnecellen?","b":"Eftersom virusproteinerna stänger av cellens förmåga att använda sina egna arvsanlag och bryter ner dess proteiner och arvsmassa.","ty":"v","src":"s. 185","id":"k10c1pwgl4b"},{"f":"Vad är lytiskt beteende?","b":"Att viruset snabbt förökar sig och dödar sin värd.","ty":"b","src":"s. 186","id":"k10c11xw6sr"},{"f":"Hur många nya virus hinner en slemhinnecell bilda?","b":"Hundratals.","ty":"s","src":"s. 186","id":"k10chn5o5s"},{"f":"Varför blir herpessåren hårda och svullna?","b":"Av de reaktioner som kroppens försvar sätter igång.","ty":"v","src":"s. 186","id":"k10c1x1q9fd"},{"f":"Vad är lysogent beteende?","b":"Viruset drar ner sin aktivitet och ligger nästan tyst, ibland med sitt DNA insatt i värdcellens DNA. Det prioriterar långsiktig överlevnad framför snabb förökning.","ty":"b","src":"s. 186","id":"k10c1ome0pq"},{"f":"Varför kopieras virusets DNA garanterat vid lysogent beteende?","b":"Eftersom det sitter insatt i värdcellens DNA, som kopieras varje gång cellen delar sig.","ty":"v","t":["plasmid"],"src":"s. 186","id":"k10c1628y98"},{"f":"Vad betyder latent?","b":"Att viruset ligger gömt, ofta i många år, i några av kroppens celler.","ty":"b","src":"s. 186","id":"k10c1pazcta"},{"f":"Var ligger herpesviruset latent?","b":"Ofta i nervceller som startar eller slutar i de läppar som infekterats.","ty":"s","src":"s. 186","id":"k10c1r4w7zg"},{"f":"Vad är skillnaden mellan vertikal och horisontell genöverföring?","b":"Vertikal: från anfader till avkomma. Horisontell: mellan olika individer och arter, t.ex. med virus.","ty":"j","t":["plasmid"],"src":"s. 186","id":"k10ccyvnyz"},{"f":"Vilket exempel på horisontell genöverföring ger boken?","b":"Genen för hemoglobin har hittats i vissa växter.","ty":"s","src":"s. 186","id":"k10c1xc6c5j"},{"f":"Varför är virus viktiga för det naturliga urvalet?","b":"Eftersom de flyttar gener horisontellt och därmed skapar genetisk variation, som är grunden för det naturliga urvalet.","ty":"v","src":"s. 186","id":"k10czujham"},{"f":"Hur många bakterievirus finns i havsvatten?","b":"I varje milliliter minst tio gånger fler bakterievirus än bakterier.","ty":"s","src":"s. 186","id":"k10cupruau"},{"f":"Hur stor del av havets biomassa dödas av bakterievirus per dag?","b":"Ungefär en femtedel.","ty":"s","src":"s. 186","id":"k10ch5nkct"},{"f":"Varför blir havets ekosystem mer dynamiska av bakterievirus?","b":"Eftersom molekylerna i de döda bakterierna släpps ut i vattnet och kan tas upp av andra organismer. Arbetsbladet: mycket DNA frigörs.","ty":"v","src":"s. 186 · Arbetsblad","p":1,"id":"k10c1ru0syd"},{"f":"Vad vet man om bakterievirusen i människans tarm?","b":"Det finns tusentals olika, men man har ännu ingen aning om vilken roll de spelar.","ty":"s","src":"s. 186","id":"k10c2z3jha"},{"f":"Två olika \"tio gånger\": vilka?","b":"Tarmen: ca tio gånger fler bakterier än människoceller. Havet: minst tio gånger fler bakterievirus än bakterier per ml.","ty":"f","src":"s. 182, 186","id":"k10cxt5r3u"}],"quiz":{"f":[{"q":"Vilken RNA-molekyl används för att avgöra en bakteries släkt och familj?","o":["16S rRNA","mRNA","tRNA","Plasmid-RNA"],"why":"Genen för 16S rRNA, en av ribosomernas RNA-molekyler.","src":"s. 183","t":["ribosom"],"id":"k10q1pp46pw"},{"q":"Vad säger boken skiljer arkéernas cellmembran från bakteriernas?","o":["Fosfolipiderna är kemiskt annorlunda","De saknar cellmembran","De har kolesterol i membranet","Membranet är dubbelt så tjockt"],"why":"Fosfolipiderna skiljer sig rent kemiskt kraftigt. Läraren nämner cellväggen, men boken säger membranet.","src":"s. 184","t":["membran"],"id":"k10q7gbt5j"},{"q":"Vid vilken temperatur kan termofila arkéer växa och dela sig?","o":["+122 °C","+85 °C","+60 °C","+200 °C"],"why":"+122 °C. +85 °C är Sulfolobus i vulkaniska källor.","src":"s. 184","id":"k10q1gexkb4"},{"q":"Vilket pH klarar acidofila arkéer?","o":["pH 0","pH 2","pH 5","pH 14"],"why":"pH 0, motsvarande 1,2 M svavelsyra. pH 2 är Sulfolobus.","src":"s. 184","id":"k10q1kbsv3e"},{"q":"Vad motsvarar pH 0 enligt boken?","o":["1,2 M svavelsyra","Rent vatten","Magsaft","1,2 M saltlösning"],"why":"Boken: pH-värdet 0, vilket motsvarar 1,2 M svavelsyra.","src":"s. 184","id":"k10q1jsdk2y"},{"q":"Vad kallas saltälskande arkéer?","o":["Halofiler","Termofiler","Acidofiler","Anaerober"],"why":"Halo = salt. De färgar saltdammar röda och gröna.","src":"s. 184","id":"k10qorlewv"},{"q":"Var lever Sulfolobus?","o":["I vulkaniska källor med pH 2 och +85 °C","I Saharas öken","I kons mage","I Döda havet"],"why":"Bokens bildtext s. 184.","src":"s. 184","id":"k10qzci04n"},{"q":"Vilken gas bildar arkéer i idisslares matspjälkning?","o":["Metan","Koldioxid","Syrgas","Kvävgas"],"why":"Metan, CH₄, är en växthusgas.","src":"s. 184 · PPT Mikroorganismer bild 38","id":"k10qk5zge8"},{"q":"Vad betyder att metanbildande arkéer är anaeroba?","o":["De klarar sig utan syrgas","De behöver ljus","De lever bara i salt vatten","De orsakar sjukdom"],"why":"Därför lever de i sumpmarker, syrefattiga sjöbottnar och tarmar.","src":"PPT Mikroorganismer bild 38","id":"k10qihru14"},{"q":"Hur många sjukdomsframkallande arkéer känner man till?","o":["Ingen","En","Ett tiotal","Över hundra"],"why":"Inte en enda, varken hos människa eller djur.","src":"s. 184 · PPT Mikroorganismer bild 37","id":"k10qpm233u"},{"q":"Hur många virus är beskrivna i detalj enligt boken?","o":["Över 5 000","Ungefär 500","Över en miljon","Ungefär 50 000"],"why":"Över 5 000 beskrivna, men minst en miljon antas finnas.","src":"s. 184 · PPT Mikroorganismer bild 39","id":"k10qpq1vim"},{"q":"Hur stora är virus?","o":["20 nm till 1 µm","1 till 10 µm","1 till 5 nm","0,1 till 1 mm"],"why":"Boken s. 185.","src":"s. 185","id":"k10qk0vw7h"},{"q":"Vad kallas virus som infekterar bakterier?","o":["Bakteriofager","Plasmider","Transposoner","Prioner"],"why":"Bakteriofager eller fager. Boken: även virus som infekterar arkéer.","src":"s. 185 · PPT Mikroorganismer bild 39","id":"k10q1127ueb"},{"q":"Hur smittar herpesviruset?","o":["Genom kontakt mellan slemhinnor","Via myggbett","Via förorenat vatten","Via luften i hosta"],"why":"T.ex. vid kyssar och sex.","src":"s. 185","id":"k10q1u9a8eo"},{"q":"Vad består herpesviruset av?","o":["En DNA-molekyl i ett proteinhölje, inslaget i ett membran med proteiner","En RNA-molekyl utan hölje","En liten cell med cellvägg","En plasmid i en fosfolipidblåsa"],"why":"Boken s. 185.","src":"s. 185","id":"k10q1w2f7va"},{"q":"Var kopieras herpesvirusets DNA?","o":["I cellkärnan","I mitokondrien","I lysosomen","Utanför cellen"],"why":"Steg 3: DNA-molekylen förs in i kärnan och kopieras många gånger.","src":"s. 185","id":"k10qktc86y"},{"q":"Vad kallas beteendet när ett virus snabbt förökar sig och dödar värden?","o":["Lytiskt","Lysogent","Latent","Symbiotiskt"],"why":"Lytiskt. Lysogent och latent är det tysta läget.","src":"s. 186","id":"k10qkwyze0"},{"q":"Var ligger herpesviruset ofta latent?","o":["I nervceller till de infekterade läpparna","I röda blodkroppar","I hudens fettceller","I lymfkörtlarna"],"why":"Boken s. 186.","src":"s. 186","id":"k10q1ndkz9g"},{"q":"Vilken gen har hittats i vissa växter som exempel på horisontell genöverföring?","o":["Hemoglobingenen","Insulingenen","Klorofyllgenen","16S rRNA-genen"],"why":"Virus har flyttat gener mellan arter.","src":"s. 186","id":"k10qy4b3qv"},{"q":"Hur många fler bakterievirus än bakterier finns per milliliter havsvatten?","o":["Minst tio gånger fler","Lika många","Hälften så många","Hundra gånger färre"],"why":"Minst tio gånger fler.","src":"s. 186","id":"k10qpzgvj7"},{"q":"Hur stor del av havets biomassa motsvarar bakterierna som dödas av virus under en dag?","o":["Ungefär en femtedel","Ungefär hälften","Ungefär en hundradel","Nästan allt"],"why":"Ungefär en femtedel.","src":"s. 186","id":"k10q13ymqia"},{"q":"När utvecklades de första bakterierna enligt läraren?","o":["För 3,5–4 miljarder år sedan","För 3,5–4 miljoner år sedan","För 500 miljoner år sedan","För 10 miljarder år sedan"],"why":"PPT bild 21. Jorden är ca 4,6 miljarder år, så 10 miljarder är omöjligt.","src":"PPT Mikroorganismer bild 21","id":"k10q27mjxt"}],"u":[{"q":"En elev säger: \"Arkéer och bakterier är närmast släkt, eftersom båda saknar cellkärna.\" Vad är fel?","o":["I livets träd är arkéerna närmare släkt med eukaryoterna","Arkéer har cellkärna","Bakterier har cellkärna","Inget, påståendet stämmer"],"why":"Prokaryot beskriver byggnaden, inte släktskapen. Arkéer och eukaryoter har en senare gemensam förfader.","src":"PPT Mikroorganismer bild 20, 36 · s. 184","id":"k10q1fi7jy5"},{"q":"En bakterie har två kopior av 16S-genen med olika sekvens. Vilket problem uppstår med förslaget att 16S avgör art?","o":["Bakterien skulle höra till två arter samtidigt","Bakterien kan inte sekvensbestämmas","Bakterien måste vara en arké","Inget problem uppstår"],"why":"Det är det stora problemet som boken lyfter.","src":"s. 183","id":"k10qfcpvnp"},{"q":"Varför kan man artbestämma bakterier i ett jordprov utan att odla dem?","o":["Man kan sekvensbestämma DNA:t och jämföra 16S-genen","Alla jordbakterier har samma form","Man ser arten med blotta ögat","Bakterierna lyser i olika färger"],"why":"Prov, slå sönder celler, sekvensbestäm DNA.","src":"s. 183","id":"k10q13yc3q7"},{"q":"Varför ger kött- och mjölkproduktion mycket växthusgas?","o":["Arkéer i idisslares matspjälkning bildar metan","Korna andas ut syre","Bakterier i gräset bildar koldioxid","Mjölken innehåller metan från början"],"why":"Metan är en växthusgas och bildas av arkéer i matspjälkningen.","src":"s. 184","id":"k10q95qwaa"},{"q":"Varför finns metanbildande arkéer i syrefattiga sjöbottnar?","o":["De är anaeroba och klarar sig utan syrgas","De behöver mycket ljus","De är halofiler","De lever av fisk"],"why":"Anaeroba organismer trivs där det saknas syrgas.","src":"PPT Mikroorganismer bild 38","id":"k10q1n5jame"},{"q":"Varför har arkéer föreslagits likna det första livet på jorden?","o":["De kan leva i extrema miljöer, liknande dem som kan ha funnits tidigt","De har cellkärna","De är virus","De är de största cellerna"],"why":"Upptäckten av liv i extrema miljöer ger perspektiv på livets uppkomst.","src":"s. 184","id":"k10q9tm1yn"},{"q":"Varför räknas virus som döda om ämnesomsättning är livets viktigaste egenskap?","o":["De har ingen egen ämnesomsättning utan använder cellens","De har inga gener","De kan inte förändras","De är för små"],"why":"Viruset får cellen att använda sin energi och sina näringsämnen.","src":"s. 184","id":"k10q1hc73u5"},{"q":"Varför kan de flesta virus bara infektera någon eller några arter?","o":["Virusets ytproteiner måste passa cellens membranproteiner","Virus kan bara överleva i en temperatur","Virus har ingen arvsmassa","Alla arter har samma celler"],"why":"Som hand i handske eller nyckel i lås. Bara celler med rätt lås kan infekteras.","src":"s. 185 · Extra","t":["nyckel"],"id":"k10q1u7hr5r"},{"q":"Varför dör en slemhinnecell som infekterats lytiskt av herpes?","o":["Virusproteiner stänger av dess gener och bryter ner dess proteiner och arvsmassa","Viruset äter upp cellmembranet","Cellen svälter för att viruset tar allt syre","Immunförsvaret dödar alltid cellen först"],"why":"Steg 4 dömer cellen till döden.","src":"s. 185","id":"k10q1i05jqy"},{"q":"Varför kopieras virusets DNA vid lysogent beteende varje gång cellen delar sig?","o":["Det sitter insatt i värdcellens DNA","Viruset har en egen kopieringsmaskin","Viruset knoppas av vid delningen","Det sitter i cellmembranet"],"why":"När värdens DNA kopieras följer virus-DNA:t med.","src":"s. 186","t":["plasmid"],"id":"k10qto6m8g"},{"q":"En person har munsår. Vad gör herpesviruset just då i läppens slemhinna?","o":["Beter sig lytiskt","Ligger latent","Beter sig lysogent","Sover i nervcellerna"],"why":"Såren bildas när viruset uppför sig lytiskt i slemhinnan.","src":"s. 186","id":"k10q1wean7v"},{"q":"Varför gör bakterievirus havets ekosystem mer dynamiska?","o":["De dödar bakterier, och molekylerna tas upp av andra organismer","De gör fotosyntes","De bildar syre","De skyddar bakterierna"],"why":"De döda bakteriernas molekyler släpps ut och återanvänds.","src":"s. 186","id":"k10q1e98epu"},{"q":"Varför är horisontell genöverföring med virus viktig för evolutionen?","o":["Den skapar genetisk variation som det naturliga urvalet verkar på","Den gör att alla individer blir lika","Den stoppar mutationer","Den gör att virus blir levande"],"why":"Variationen är grunden för det naturliga urvalet.","src":"s. 186","id":"k10qu5fm9q"}],"o":[{"q":"Vad skiljer arkéer från bakterier? Ge minst fyra skillnader och nämn var läraren och boken säger olika.","model":"Arkéer liknar bakterier till det yttre och saknar också cellkärna. Men arvsmassan visar att de är en separat huvudgren av livets träd, närmare släkt med eukaryoterna. Fosfolipiderna i cellmembranet skiljer sig kemiskt kraftigt från bakteriernas och eukaryoternas (boken). Läraren skriver i stället att de har ett annat material i cellväggen. Arkéer kan ha fler former, t.ex. platta och fyrkantiga. Många är extremofiler och klarar salt, +122 °C och pH 0. Ingen känd arké orsakar sjukdom hos människa eller djur, och läraren lägger till att de tycks vara resistenta mot de flesta antibiotika. Arkéer bildar metan i idisslares matspjälkning.","kw":[["huvudgren","arvsmassa"],["fosfolipid"],["cellvägg"],["form"],["extremofil","122","ph 0"],["sjukdom"]],"src":"s. 184 · PPT Mikroorganismer bild 36–38","t":["membran"],"id":"k10o73zyd"},{"q":"Definiera virus och beskriv på vilka sätt virus kan skilja sig från varandra. Är virus levande?","model":"Ett virus är en bit arvsanlag i ett paket med proteiner och ibland ett membran, som kan ta sig in i en levande cell och få den att använda sin energi och sina näringsämnen till att göra nya viruspartiklar. Arvsanlagen kan vara DNA eller RNA, enkel- eller dubbelsträngade. Virus kan ha eller sakna membranhölje och är 20 nm till 1 µm stora. De flesta infekterar bara en eller några arter, men alla livsformer kan infekteras. Om virus lever beror på definitionen: med egen ämnesomsättning som krav är de döda, med informationsöverföring och evolution är de levande.","kw":[["arvsanlag"],["protein"],["dna"],["rna"],["membran"],["ämnesomsättning"],["evolution"]],"src":"s. 184–185","id":"k10o1v23bsn"},{"q":"Beskriv hur herpesviruset förökar sig i en slemhinnecell, och förklara skillnaden mellan lytiskt och lysogent beteende.","model":"1. Virusets membranproteiner binder som hand i handske till proteiner i slemhinnecellens membran, och membranen smälter ihop. 2. DNA och proteinhölje säras. 3. DNA:t förs in i kärnan och kopieras många gånger. 4. DNA:t avläses, och proteiner stänger av cellens egna gener, bryter ner cellen till byggstenar och bygger virusets hölje. 5. Nya virus slås in i cellmembran och knoppas av, och cellen dör. Det är lytiskt beteende: snabb förökning som dödar värden och ger herpessår. Lysogent beteende: viruset drar ner aktiviteten, kan sätta in sitt DNA i värdcellens DNA och kopieras vid varje delning. Det ligger latent i många år, ofta i nervceller till läpparna.","kw":[["handske","binder"],["smälter"],["kärna"],["kopier"],["knopp"],["lytisk"],["lysogen","latent"]],"src":"s. 185–186","t":["nyckel","membran"],"id":"k10ocev7wr"},{"q":"Vilken betydelse har virus för evolutionen och för havets ekosystem?","model":"Virus transporterar gener horisontellt mellan individer och arter, inte bara vertikalt från anfader till avkomma. Genen för hemoglobin har till exempel hittats i vissa växter. Det skapar genetisk variation, som är grunden för det naturliga urvalet. I havet, där bakterier står för huvuddelen av fotosyntesen, finns minst tio gånger fler bakterievirus än bakterier per milliliter. De dödar så många bakterier att det motsvarar en femtedel av havets biomassa per dag. Molekylerna släpps ut och tas upp av andra organismer, och därför blir ekosystemen mer dynamiska och flexibla.","kw":[["horisontell"],["vertikal"],["hemoglobin"],["variation","urval"],["tio gånger","10"],["femtedel"],["dynamisk","flexib"]],"src":"s. 186 · Arbetsblad","t":["plasmid"],"id":"k10ong731j"}]},"kan":[{"q":"Kan du förklara varför det är svårt att definiera en bakterieart, och vad man har enats om?","a":"Bakterier tappar, tar upp och flyttar gener, och därför kan individer av samma art vara mycket olika. Många har inte ens hälften av sina gener gemensamma med alla artfränder. Man har enats om att genen för 16S rRNA, en av ribosomernas RNA-molekyler, avgör vilken släkt och familj en bakterie hör till. Att samma gen också ska avgöra art är bara ett förslag.","kw":[["16s"],["ribosom"],["släkt"],["familj"],["förslag"],["gener","genbyte","olika"]],"src":"s. 183","t":["ribosom"],"id":"k10k6pkx4o"},{"q":"Kan du ge fördelarna och problemen med att låta 16S rRNA avgöra art?","a":"Fördelar: systematiken grundar sig på ett enhetligt sätt på släktskap, och man kan artbestämma bakterier snabbt utan att ha sett dem, genom att ta ett prov, slå sönder cellerna och sekvensbestämma DNA:t. Mindre problem: tidigare arter, ibland från olika släkten eller familjer, måste slås ihop eller delas upp. Stora problemet: en del bakterier har flera kopior av genen med olika sekvens.","kw":[["släktskap","enhetlig"],["snabb","sekvens"],["prov"],["slå ihop","dela upp"],["flera kopior","kopior"]],"src":"s. 183","id":"k10k16b665w"},{"q":"Kan du rita och förklara livets träd?","a":"Livet delas i tre domäner: bakterier, arkéer och eukaryoter. Stammen delar sig först så att bakterierna grenar av. Den andra grenen delar sig sedan i arkéer och eukaryoter, och därför har de en senare gemensam förfader och är närmast släkt. Bakterier och arkéer saknar cellkärna och kallas prokaryoter, men det är ingen släktgren.","kw":[["bakterie"],["arké"],["eukaryot"],["först","grenar av"],["närmast","gemensam förfader"],["prokaryot","kärna"]],"src":"PPT Mikroorganismer bild 20, 22, 36 · s. 178, 184","id":"k10k1bdbsyj"},{"q":"Kan du förklara vad som skiljer arkéer från bakterier?","a":"Arkéer påminner till det yttre om bakterier, men arvsmassan visar att de är en separat huvudgren av livets träd. Fosfolipiderna i deras cellmembran skiljer sig kemiskt kraftigt från bakteriernas och eukaryoternas. De kan anta fler former, många är extremofiler, och ingen känd arké orsakar sjukdom. Läraren säger att de har ett annat material i cellväggen och tycks vara resistenta mot de flesta antibiotika.","kw":[["fosfolipid"],["membran"],["huvudgren","arvsmassa"],["form"],["extremofil"],["sjukdom"]],"src":"s. 184 · PPT Mikroorganismer bild 37","t":["membran"],"id":"k10kdw2qp0"},{"q":"Kan du förklara vad extremofiler är och ge tre exempel med siffror?","a":"Extremofiler är organismer som lever i miljöer som är för tuffa för alla andra livsformer. Halofiler lever vid höga salthalter och färgar saltdammar röda och gröna. Termofila arkéer växer och delar sig vid +122 °C. Acidofila arkéer lever vid pH 0, vilket motsvarar 1,2 M svavelsyra. Därför finns arkéer på fler ställen i naturen än bakterier.","kw":[["extremofil"],["salt","halofil"],["122"],["ph 0","ph0"],["svavelsyra","1,2"]],"src":"s. 184","id":"k10kz213nl"},{"q":"Kan du förklara varför arkéer är viktiga i diskussionen om global uppvärmning?","a":"Det är arkéer som bildar metan i matspjälkningssystemet hos idisslande djur. Metan är en växthusgas, och därför ger kött- och mjölkproduktion mycket växthusgas. Läraren lägger till att metanbildarna är anaeroba och också finns i sumpmarker och syrefattiga sjöbottnar, och arbetsbladet att metanet kan tas till vara som biogas.","kw":[["metan","ch4","ch₄"],["idissl","ko","kor"],["växthusgas"],["kött","mjölk"],["anaerob"]],"src":"s. 184 · PPT Mikroorganismer bild 38 · Arbetsblad","id":"k10k1nnmzqt"},{"q":"Kan du definiera virus och resonera om virus är levande?","a":"Ett virus är en bit arvsanlag, inslaget i ett paket med proteiner och ibland ett membran, som kan ta sig in i en levande cell och få den att använda sin energi och sina näringsämnen till att göra nya viruspartiklar. Om virus lever beror på vad man tycker är livets viktigaste egenskap. Är det egen ämnesomsättning och energihantering är virus döda. Är det informationsöverföring och evolution hör de till det levande.","kw":[["arvsanlag"],["protein"],["membran"],["energi","näring"],["ämnesomsättning"],["evolution","informationsöverföring"]],"src":"s. 184","id":"k10ktxt5me"},{"q":"Kan du beskriva på vilka sätt virus kan skilja sig från varandra?","a":"Arvsanlagen kan vara DNA eller RNA, och molekylerna kan vara enkelsträngade eller dubbelsträngade. Virus kan ha eller sakna membranhölje. De varierar i storlek från 20 nm till en mikrometer. De flesta kan bara infektera någon eller några arter, men alla livsformer kan infekteras av något virus.","kw":[["dna"],["rna"],["enkel","dubbel"],["membranhölje","membran"],["20 nm","mikrometer","µm"]],"src":"s. 185","id":"k10k16gi2ah"},{"q":"Kan du jämföra lytiskt och lysogent beteende hos herpesviruset?","a":"Lytiskt: viruset förökar sig snabbt och dödar sin värd. Slemhinnecellen dör relativt snabbt men hinner bilda hundratals nya virus, och då bildas herpessåren. Lysogent: viruset drar ner sin aktivitet och ligger nästan tyst, ibland med sitt DNA insatt i värdcellens DNA så att det kopieras vid varje delning. Det prioriterar långsiktig överlevnad, och kan ligga latent i nervceller i många år.","kw":[["lytisk"],["lysogen"],["dödar","dör"],["värdcellens dna","värdens dna","insatt"],["latent"],["nerv"]],"src":"s. 186","id":"k10k1aj735j"},{"q":"Kan du förklara virusens betydelse för evolutionen och för havet?","a":"Virus transporterar gener horisontellt mellan individer och arter, inte bara vertikalt från anfader till avkomma. Man har till exempel hittat hemoglobingenen i vissa växter. Det skapar genetisk variation, som är grunden för det naturliga urvalet. I havet finns minst tio gånger fler bakterievirus än bakterier. De dödar så många bakterier att det motsvarar en femtedel av havets biomassa per dag, och molekylerna tas upp av andra organismer, så ekosystemen blir mer dynamiska.","kw":[["horisontell"],["hemoglobin"],["variation","naturliga urvalet","urval"],["tio gånger","10"],["femtedel"],["dynamisk","flexib"]],"src":"s. 186","t":["plasmid"],"id":"k10k1cux5d2"}],"kompis":[{"q":"Förklara för en kompis hur herpesviruset tar över en slemhinnecell, steg för steg.","model":"Viruset smittar vid kontakt mellan slemhinnor. Proteiner i virusets membran passar som hand i handske till proteiner i cellens membran, och membranen smälter ihop så att DNA och proteinhölje kommer in. Sedan säras DNA:t och höljet. DNA:t förs in i kärnan och kopieras många gånger. Det avläses, och proteiner bildas som stänger av cellens egna gener, bryter ner cellen till byggstenar och bygger virusets hölje. Till sist slås nya virus in i en bit cellmembran och knoppas av, och cellen dör.","kw":[["hand i handske","nyckel","binder"],["smälter"],["säras","isär"],["kärna"],["kopier"],["stänger av"],["knopp"]],"src":"s. 185","t":["nyckel","membran"],"id":"k10e16caoym"},{"q":"Förklara för en kompis varför man kan få munsår igen och igen på samma ställe.","model":"Herpesviruset kan bete sig på två sätt. I slemhinnan är det lytiskt: det förökar sig snabbt, cellerna dör och sår bildas, som blir hårda och svullna av kroppens försvar. Men viruset kan också bete sig lysogent. Det drar ner aktiviteten och kan sätta in sitt DNA i värdcellens DNA, så att det kopieras vid varje delning. Då ligger det latent i många år i nervceller som går till läppen. Boken säger inte mer, men viruset kan senare vakna och bli lytiskt igen, och då kommer ett nytt sår.","kw":[["lytisk"],["lysogen"],["latent"],["nerv"],["dna"],["vakna","igen","reaktiv"]],"src":"s. 186 · Extra","id":"k10ez361u2"},{"q":"Förklara för en kompis varför arkéerna inte bara är konstiga bakterier.","model":"Arkéer liknar bakterier till det yttre, och båda saknar cellkärna. Men när man analyserar arvsmassan ser man att arkéerna är en egen huvudgren av livets träd, och i trädet är de närmare släkt med eukaryoterna än med bakterierna. Fosfolipiderna i deras cellmembran är kemiskt helt annorlunda. Många är extremofiler som klarar salt, +122 °C och pH 0, de bildar metan, och ingen orsakar sjukdom.","kw":[["arvsmassa","huvudgren"],["eukaryot"],["fosfolipid"],["extremofil"],["metan"],["sjukdom"]],"src":"s. 184 · PPT Mikroorganismer bild 36–38","t":["membran"],"id":"k10e171roo1"}],"gloss":[{"w":"Domän","d":"Högsta indelningen av livet. Det finns tre: bakterier, arkéer och eukaryoter.","src":"PPT Mikroorganismer bild 20, 36","lek":1},{"w":"Prokaryot","d":"Cell utan cellkärna. Bakterier och arkéer.","src":"PPT Mikroorganismer bild 22","lek":1},{"w":"Eukaryot","d":"Organism vars celler har cellkärna. Livets tredje domän.","src":"s. 178"},{"w":"Livets träd","d":"Släktträd över livets tre domäner. Bakterierna grenade av först.","src":"s. 184 · PPT Mikroorganismer bild 20"},{"w":"16S rRNA","d":"En av ribosomernas RNA-molekyler. Genen för den avgör vilken släkt och familj en bakterie hör till.","src":"Bok s. 183"},{"w":"Sekvensbestämma","d":"Ta reda på ordningen av byggstenarna i ett DNA. Används för att artbestämma bakterier utan att se dem.","src":"Bok s. 183"},{"w":"Arkéer","d":"Prokaryoter som liknar bakterier men är en egen huvudgren av livets träd, med kemiskt annorlunda fosfolipider i cellmembranet.","src":"Bok s. 184"},{"w":"Arkebakterier","d":"Äldre namn på arkéer, från tiden då de räknades till bakterierna.","src":"Bok s. 184 · Arbetsblad"},{"w":"Fosfolipider","d":"Huvudkomponenterna i cellmembranet. Hos arkéer skiljer de sig kemiskt kraftigt från bakteriers och eukaryoters.","src":"Bok s. 184"},{"w":"Extremofil","d":"Organism som lever i en miljö som är för tuff för alla andra livsformer.","src":"Bok s. 184"},{"w":"Halofil","d":"Saltälskande organism som lever vid höga salthalter.","src":"Bok s. 184"},{"w":"Termofil","d":"Värmeälskande organism. Termofila arkéer klarar +122 °C.","src":"Bok s. 184"},{"w":"Acidofil","d":"Syraälskande organism. Acidofila arkéer klarar pH 0.","src":"Bok s. 184"},{"w":"Sulfolobus","d":"Arké som lever i vulkaniska källor med pH 2 och +85 °C.","src":"Bok s. 184"},{"w":"Deinococcus radiodurans","d":"Mikroorganism från Saharas öken som reparerar sitt DNA och tål stark radioaktivitet.","src":"Bok s. 184"},{"w":"Metan","d":"Växthusgasen CH₄. Bildas av arkéer, t.ex. i idisslares matspjälkning.","src":"Bok s. 184 · PPT Mikroorganismer bild 38"},{"w":"Idisslare","d":"Djur som kor, där arkéer i matspjälkningen bildar metan.","src":"Bok s. 184"},{"w":"Växthusgas","d":"Gas som bidrar till global uppvärmning, t.ex. metan.","src":"Bok s. 184"},{"w":"Anaerob","d":"Klarar sig utan syrgas.","src":"PPT Mikroorganismer bild 38","lek":1},{"w":"Biogas","d":"Metan från arkéer som tas till vara och används som bränsle.","src":"Arbetsblad","lek":1},{"w":"Virus","d":"En bit arvsanlag i ett paket med proteiner och ibland ett membran, som tar sig in i en levande cell och får den att göra nya viruspartiklar.","src":"Bok s. 184"},{"w":"Viruspartikel","d":"Ett enskilt, färdigt virus.","src":"Bok s. 184"},{"w":"Proteinhölje","d":"Paketet av proteiner som virusets arvsanlag ligger i.","src":"Bok s. 185"},{"w":"Membranhölje","d":"Membran utanför proteinhöljet hos vissa virus.","src":"Bok s. 185"},{"w":"Enkelsträngad / dubbelsträngad","d":"Arvsmassa med en eller två strängar. Virus kan ha båda sorterna.","src":"Bok s. 185"},{"w":"Parasit","d":"Lever på en värd. Virus kallas parasiter eftersom de saknar egen ämnesomsättning.","src":"Arbetsblad","lek":1},{"w":"Värdcell","d":"Cellen som ett virus infekterar och använder.","src":"Bok s. 184–186"},{"w":"Bakteriofag (fag)","d":"Virus som infekterar bakterier eller arkéer.","src":"Bok s. 185 · PPT Mikroorganismer bild 39"},{"w":"Herpesvirus","d":"DNA-virus med membranhölje som ger munsår eller sår på könsorganen och kan ligga latent i nervceller.","src":"Bok s. 185–186"},{"w":"Slemhinna","d":"Fuktig vävnad, t.ex. i läppar och könsorgan, där herpesviruset smittar och förökar sig.","src":"Bok s. 185"},{"w":"Avknoppning","d":"Nya virus slås in i en bit av cellens membran och lämnar cellen.","src":"Bok s. 185"},{"w":"Lytiskt","d":"Viruset förökar sig snabbt och dödar sin värd.","src":"Bok s. 186"},{"w":"Lysogent","d":"Viruset ligger nästan tyst, ibland med sitt DNA i värdcellens DNA, och prioriterar långsiktig överlevnad.","src":"Bok s. 186"},{"w":"Latent","d":"Gömt och vilande, ofta i många år.","src":"Bok s. 186"},{"w":"Vertikal genöverföring","d":"Gener förs från anfader till avkomma.","src":"Bok s. 186"},{"w":"Horisontell genöverföring","d":"Gener förs mellan olika individer och arter, t.ex. med virus.","src":"Bok s. 186"},{"w":"Naturligt urval","d":"Processen där de bäst anpassade överlever. Genetisk variation är grunden.","src":"Bok s. 186"},{"w":"Biomassa","d":"Den totala mängden levande material.","src":"Bok s. 186"}],"snabb":{"keys":["Tre domäner :: bakterier, arkéer, eukaryoter","Närmast släkt :: arkéer och eukaryoter (bakterierna grenade av först)","16S rRNA :: avgör släkt och familj (art = bara förslag)","Arkéer skiljer sig (boken) :: fosfolipiderna i cellmembranet","Arkéer skiljer sig (läraren) :: materialet i cellväggen","Extremofil :: lever där inget annat liv klarar sig","Metan :: arkéer i idisslare, växthusgas, anaeroba","Arkéer och sjukdom :: ingen känd hos människa eller djur","Virus :: arvsanlag i proteinpaket (ibland membran), använder cellens energi och näring","Lever virus? :: ämnesomsättning = nej, evolution = ja","Fag :: virus som infekterar bakterier (eller arkéer)","Herpes 5 steg :: binder, säras, kopieras i kärnan, avläses, knoppas av","Lytiskt :: snabb förökning, värden dör, sår","Lysogent / latent :: tyst, DNA i värdens DNA, nervceller i många år"],"nums":[["3,5–4 miljarder år","sedan de första bakterierna (läraren)"],["16S","rRNA-genen som avgör släkt och familj"],["+122 °C","termofila arkéer växer och delar sig"],["pH 0","acidofila arkéer (= 1,2 M svavelsyra)"],["1,2 M","svavelsyra motsvarar pH 0"],["pH 2 och +85 °C","Sulfolobus i vulkaniska källor"],["> 5 000","virus beskrivna i detalj"],["≥ 1 miljon","olika virus antas finnas"],["20 nm – 1 µm","virusens storlek"],["5 steg","herpesviruset tar över en slemhinnecell"],["hundratals","nya virus per slemhinnecell"],["≥ 10 ×","fler bakterievirus än bakterier per ml havsvatten"],["1/5","av havets biomassa dödas av bakterievirus per dag"],["tusentals","olika bakterievirus i människans tarm"]],"chains":[["Idisslare äter","arkéer bildar metan","växthusgas","global uppvärmning"],["Herpes binder (hand i handske)","membranen smälter ihop","DNA kopieras i kärnan","cellen tas över","nya virus knoppas av","cellen dör"],["Lysogent","virus-DNA i värdens DNA","kopieras vid varje delning","latent i nervceller i många år"],["Virus flyttar gener horisontellt","genetisk variation","naturligt urval"],["Bakterievirus dödar bakterier","molekyler släpps ut","tas upp av andra","dynamiskt ekosystem"],["Prov","slå sönder cellerna","sekvensbestäm DNA","16S-genen ger art (förslag)"]],"traps":["Prokaryot är ingen släktgren: arkéer är närmare släkt med eukaryoter än med bakterier.","16S rRNA: enats om släkt och familj, art är bara ett förslag.","Boken: arkéernas FOSFOLIPIDER i membranet skiljer sig. Läraren: cellväggen. Svara med boken.","Lytiskt = cellen dör (sår). Lysogent = tyst, cellen lever. Blanda inte ihop dem.","Alla virus har inte membranhölje, och virus är inte alltid mindre än bakterier.","+85 °C och pH 2 är Sulfolobus. +122 °C och pH 0 är rekorden.","Två olika \"tio gånger\": bakterier/människoceller i tarmen, bakterievirus/bakterier i havet."]}},"k11":{"pre":[{"q":"Vilket antibiotikum används mest i Sverige?","o":["Penicillin","Rifampicin","Tetracyklin","Isoniazid"],"why":"Penicillin är både det mest använda och det första som upptäcktes (s. 212).","id":"k11p49y6rs"},{"q":"Vad tillverkar penicillin i naturen?","o":["Mögelsvampar","Bakterier i tarmen","Människans vita blodkroppar","Virus"],"why":"Penicillin tillverkas av mögelsvampar. Fleming såg att bakterierna invid möglet hade dött.","id":"k11p1co9af0"},{"q":"Hur dödar penicillin en bakterie?","o":["Det blockerar ett enzym som behövs för att bygga cellväggen","Det löser upp bakteriens DNA","Det gör att bakterien sväller av vatten","Det stänger bakteriens flageller"],"why":"Bakterien kan då inte bilda och reparera sin cellvägg, kan inte dela sig och dör (s. 212).","id":"k11pu6gci5"},{"q":"Varför kan ett antibiotikum som stoppar ribosomen döda bakterier men inte våra celler?","o":["Bakteriens ribosom skiljer sig från människans","Våra celler saknar ribosomer","Antibiotikan kommer aldrig in i kroppen","Bakterier har fler ribosomer än vi"],"why":"Molekylerna för proteinsyntes skiljer sig kraftigt mellan bakterier och eukaryoter (s. 213, PPT bild 19).","id":"k11p8xmzmp"},{"q":"Vad händer om man sätter till en aminogrupp på penicillin?","o":["Man får ampicillin, som även verkar mot gramnegativa","Man får ett vaccin","Läkemedlet slutar fungera","Det verkar mot virus"],"why":"Lärarens bild 17. En hydroxylgrupp gör i stället att läkemedlet tas upp lättare i mag-tarmkanalen.","id":"k11p90pl1g"}],"cards":[{"f":"Vad är antibiotika enligt boken?","b":"Ämnen som kan döda bakterier, men som lämnar människans celler relativt oskadda.","ty":"b","src":"s. 212 · PPT bild 3","p":1,"id":"k11c13we1v2"},{"f":"Varför kan antibiotika användas för att behandla bakterieinfektioner?","b":"Eftersom de dödar bakterier men lämnar människans celler relativt oskadda.","ty":"v","src":"s. 212","p":1,"id":"k11cfx6ccy"},{"f":"Hur beskriver läraren antibiotika på bild 3?","b":"Ett samlingsbegrepp för de läkemedel som används för att behandla infektioner som orsakas av bakterier.","ty":"b","src":"PPT bild 3","id":"k11cftfbqm"},{"f":"Används antibiotika mot infektioner som beror på virus eller svampar?","b":"Nej. Antibiotika används mot bakterieinfektioner (lärarens bild 2–3).","ty":"f","src":"PPT bild 2–3","id":"k11c699co0"},{"f":"Vad kallas antibiotika ofta i dagligt tal?","b":"Penicillin. Men penicillin är bara ett av många antibiotika.","ty":"f","src":"PPT bild 3","id":"k11ccr20wk"},{"f":"På vilka två sätt kan antibiotika verka enligt läraren?","b":"De dödar bakterierna eller hindrar dem från att föröka sig. Boken säger bara att de dödar bakterier.","ty":"j","src":"PPT bild 2 · s. 212","id":"k11cdjg0bv"},{"f":"När dök de första antibiotika upp?","b":"På 1940- och 50-talen.","ty":"s","src":"s. 212","p":1,"id":"k11c1l41zhc"},{"f":"Varför kallas antibiotikan en revolution för sjukvården?","b":"Eftersom en lång rad bakteriesjukdomar gick från att vara dödliga hot till lättbehandlade åkommor.","ty":"v","src":"s. 212 · PPT bild 2","p":1,"id":"k11c13ivskr"},{"f":"Ge bokens två exempel på sjukdomar som blev lättbehandlade tack vare antibiotika.","b":"Lunginflammationer efter förkylningar och infekterade sår vid operationer.","ty":"s","src":"s. 212","id":"k11cawdyml"},{"f":"Vad säger läraren att antibiotika har gjort för modern medicin?","b":"Revolutionerat den och räddat otaliga liv. Men effekten hotas nu av antibiotikaresistens.","ty":"b","src":"PPT bild 2","id":"k11c1whku6t"},{"f":"Varför infekteras människor allt oftare av resistenta bakterier?","b":"Eftersom människan använt mer och mer antibiotika och därmed selekterat för bakterier som är resistenta.","ty":"v","src":"s. 212","p":1,"id":"k11c1l9jys6"},{"f":"Betyder \"relativt oskadda\" att antibiotika är helt ofarliga för oss?","b":"Nej. Våra celler klarar sig mycket bättre än bakterierna, men antibiotika är inte helt ofarliga.","ty":"f","src":"s. 212","id":"k11cd5jghy"},{"f":"Vilket antibiotikum används mest i Sverige?","b":"Penicillin.","ty":"s","src":"s. 212 · PPT bild 15","p":1,"id":"k11c49y6rs"},{"f":"Vilket var det första antibiotikum som upptäcktes?","b":"Penicillin.","ty":"s","src":"s. 212","id":"k11cjxdmal"},{"f":"Vad tillverkar penicillin?","b":"Mögelsvampar. (Läraren: tillverkades först av mögelsvampar.)","ty":"b","src":"s. 212 · PPT bild 15","p":1,"id":"k11c19d3fe8"},{"f":"Vem upptäckte penicillinet, och när levde han?","b":"Den brittiske forskaren Alexander Fleming, 1881–1955.","ty":"s","src":"s. 212 · PPT bild 15","p":1,"id":"k11c1eteti9"},{"f":"Hur stavar boken och läraren Flemings namn?","b":"Flemming, med två m. Han hette Fleming.","ty":"f","src":"s. 212 · PPT bild 15","id":"k11c1ygi6ei"},{"f":"Hur länge var Fleming borta innan han upptäckte möglet?","b":"En månad, på semester.","ty":"s","src":"s. 212","id":"k11c16p68xg"},{"f":"Vad såg Fleming i näringsskålen när han kom tillbaka?","b":"Mögelsvampar hade börjat växa i en av skålarna, och invid möglet hade bakterierna dött.","ty":"b","src":"s. 212","id":"k11c1e20956"},{"f":"Vilken slutsats drog Fleming?","b":"Att mögelsvampen måste bilda något ämne som dödar bakterierna.","ty":"v","src":"s. 212","id":"k11c8mibrk"},{"f":"Varför fick ämnet namnet penicillin?","b":"Det fick namn efter den typ av mögelsvampar som tillverkade det.","ty":"v","src":"s. 212","id":"k11c1a3kr8y"},{"f":"Vad visar lärarens bild 14?","b":"Ett foto av Alexander Fleming i laboratoriet bland provrör och näringsskålar.","ty":"i","src":"PPT bild 14","id":"k11chyj5xf"},{"f":"Vilket år upptäcktes penicillinet, och vad heter mögelsläktet?","b":"1928, Penicillium. Står inte i boken.","ty":"s","src":"Extra","id":"k11c5ird6k"},{"f":"Vilka fick Nobelpriset 1945 för penicillinet?","b":"Fleming, Howard Florey och Ernst Chain. Florey och Chain tog fram penicillin i större mängder på 1940-talet. Står inte i boken.","ty":"s","src":"Extra","id":"k11c1uz47k"},{"f":"Hur verkar penicillin?","b":"Det binder till och blockerar ett enzym som behövs för att bakterier ska kunna bygga sin cellvägg.","ty":"b","src":"s. 212 · PPT bild 15","p":1,"t":["vagg","nyckel"],"id":"k11cg6tkub"},{"f":"Varför dör en bakterie som behandlas med penicillin?","b":"Den kan inte bilda och reparera sin cellvägg, och därför kan den inte dela sig och dör.","ty":"v","src":"s. 212 · PPT bild 15","p":1,"t":["vagg"],"id":"k11c1aakquz"},{"f":"Penicillin slår mot bildandet av vilket ämne i cellväggen?","b":"Peptidoglukan (i K8 stavat peptidoglykan, samma ämne).","ty":"b","src":"s. 213 · PPT bild 15","p":1,"t":["vagg"],"id":"k11c1hscfd4"},{"f":"Varför verkar penicillin framför allt mot grampositiva bakterier?","b":"Eftersom det slår mot bildandet av peptidoglukan, och grampositiva har ett tjockt lager peptidoglukan.","ty":"v","src":"s. 213 · PPT bild 15","p":1,"t":["vagg"],"id":"k11c1rimfh3"},{"f":"Kan penicillin slå mot gramnegativa bakterier?","b":"Vissa varianter kan slå mot vissa gramnegativa, t.ex. ampicillin.","ty":"b","src":"s. 213 · PPT bild 15, 17","p":1,"id":"k11c1qepxrs"},{"f":"Vilka tre grundläggande mekanismer skiljer sig kraftigt mellan bakterier och eukaryoter enligt boken?","b":"DNA-syntes, replikation och proteinsyntes.","ty":"s","src":"s. 213 · PPT bild 18","p":1,"id":"k11c14gnayi"},{"f":"Hur kan andra antibiotika än penicillin döda bakterier utan att skada oss?","b":"De binder till och blockerar bakteriens variant av molekylerna för DNA-syntes, replikation eller proteinsyntes. Våra varianter skiljer sig kraftigt.","ty":"v","src":"s. 213","p":1,"id":"k11cg32dbb"},{"f":"Vad slår penicilliner, cefalosporiner och karbapenemer mot i bokens figur?","b":"Bygget av cellväggen (pilen från proteiner till cellväggen).","ty":"i","src":"s. 213","p":1,"t":["vagg"],"id":"k11c9f35ag"},{"f":"Vad slår kinoloner mot i bokens figur?","b":"Kopieringen av DNA, cirkelpilen vid DNA. Läraren: hämmare av DNA-replikation.","ty":"i","src":"s. 213 · PPT bild 13","p":1,"id":"k11chw891e"},{"f":"Vad slår rifampicin mot i bokens figur?","b":"Steget DNA → RNA. Läraren kallar den nukleinsyrasynteshämmare.","ty":"i","src":"s. 213 · PPT bild 13","p":1,"id":"k11c1ar0fc7"},{"f":"Vad slår tetracykliner, makrolider och linkosamider mot?","b":"Steget RNA → proteiner, alltså proteinsyntesen.","ty":"i","src":"s. 213 · PPT bild 13","p":1,"t":["ribosom"],"id":"k11c5f1pvw"},{"f":"Vilka fyra verkningsmekanismer visar läraren på bild 13?","b":"Hämmare av cellväggssyntes, proteinsynteshämmare, nukleinsyrasynteshämmare och hämmare av DNA-replikation.","ty":"s","src":"PPT bild 13","id":"k11c8dic0f"},{"f":"Vilka preparat står under hämmare av cellväggssyntes på lärarens bild 13?","b":"Betalaktamer och glykopeptider.","ty":"s","src":"PPT bild 13","id":"k11c108pjl3"},{"f":"Vilka preparat står under proteinsynteshämmare på lärarens bild 13?","b":"Aminoglykosider, tetracykliner, makrolider, linkosamider och kloramfenikol.","ty":"s","src":"PPT bild 13","id":"k11c1utxexy"},{"f":"Vilka preparat står under nukleinsyrasynteshämmare på lärarens bild 13?","b":"Trimetoprim, sulfonamid och rifampicin.","ty":"s","src":"PPT bild 13","id":"k11c1uvbmc6"},{"f":"Vilka preparat står under hämmare av DNA-replikation på lärarens bild 13?","b":"Kinoloner och metronidazol.","ty":"s","src":"PPT bild 13","id":"k11cswgx64"},{"f":"Boken säger penicilliner, cefalosporiner och karbapenemer. Läraren säger betalaktamer. Hur hänger det ihop?","b":"Båda slår mot cellväggen. Penicilliner, cefalosporiner och karbapenemer hör till betalaktamerna (extra, står inte i materialet).","ty":"j","src":"s. 213 · PPT bild 13","id":"k11c2fvq35"},{"f":"Varför stämmer både \"DNA → RNA\" (boken) och \"nukleinsyrasyntes\" (läraren) för rifampicin?","b":"Eftersom RNA är en nukleinsyra. Att stoppa bygget av RNA är att stoppa nukleinsyrasyntes.","ty":"j","src":"s. 213 · PPT bild 13","id":"k11ckwmwdx"},{"f":"Vad betyder replikation?","b":"Att DNA kopieras. Kinoloner och metronidazol hämmar den.","ty":"b","src":"s. 213 · PPT bild 13","id":"k11cxb4gik"},{"f":"Vad heter stegen DNA → RNA och RNA → protein?","b":"Transkription och translation. Orden står inte i boken.","ty":"b","src":"Extra","id":"k11c8ds9uj"},{"f":"Minnesknep: PCK och TML?","b":"PCK på väggen: penicilliner, cefalosporiner, karbapenemer. TML på arbetsbänken (ribosomen): tetracykliner, makrolider, linkosamider.","ty":"s","src":"s. 213","id":"k11c2leikz"},{"f":"Vad händer till slut med bakterien oavsett vilken av bokens angreppspunkter antibiotikan träffar?","b":"Den kan inte dela sig och dör.","ty":"v","src":"s. 212–213","id":"k11cgbp1m5"},{"f":"Vad binder antibiotika som hindrar proteinsyntesen till?","b":"Bakteriens ribosom eller något av hjälparproteinerna.","ty":"b","src":"PPT bild 19","t":["ribosom","nyckel"],"id":"k11c1cjg3sg"},{"f":"Varför överlever människocellerna när bakterier behandlas med proteinsynteshämmare?","b":"Antibiotikan binder bakteriens ribosom men gör inte samma sak hos människor, eftersom våra ribosomer skiljer sig från bakteriens.","ty":"v","src":"PPT bild 19 · s. 213","p":1,"t":["ribosom"],"id":"k11c17t3ceb"},{"f":"Vilken organell i våra celler har ribosomer av samma typ som bakterier?","b":"Mitokondrien. Det är ett av bevisen för endosymbiosteorin (K4).","ty":"j","src":"s. 27 (K4)","t":["endo","ribosom"],"id":"k11c1ql8c8f"},{"f":"Är rifampicin en proteinsynteshämmare?","b":"Nej. Rifampicin slår mot steget DNA → RNA (nukleinsyrasyntes).","ty":"f","src":"s. 213 · PPT bild 13","id":"k11c1hr2jke"},{"f":"Vad får man om man sätter till en aminogrupp på penicillin?","b":"Ampicillin, som även verkar mot gramnegativa bakterier.","ty":"b","src":"PPT bild 17","id":"k11c78ck78"},{"f":"Vad händer om man sätter till en hydroxylgrupp på penicillinmolekylen?","b":"Läkemedlet tas lättare upp av mag-tarmkanalen.","ty":"b","src":"PPT bild 17","id":"k11ckruv4t"},{"f":"Vad heter molekylen med både aminogrupp och hydroxylgrupp?","b":"Amoxicillin. Namnet står inte i lärarens bild eller i boken.","ty":"s","src":"Extra","id":"k11c1yg2dsq"},{"f":"Vad visar lärarens bild 17?","b":"Att små ändringar av strukturen hos penicillin vidgar användningsområdet: aminogrupp (ampicillin) och hydroxylgrupp.","ty":"i","src":"PPT bild 17","id":"k11chyg0fg"},{"f":"Vilken kemisk grupp i penicillinmolekylen känner du igen från fettsyrorna i K1?","b":"Karboxylgruppen, COOH.","ty":"i","src":"PPT bild 17 · Bi2 bild 11","id":"k11c1orei8q"},{"f":"Aminogrupp eller hydroxylgrupp: vilken ger effekt mot gramnegativa?","b":"Aminogruppen. Hydroxylgruppen ger lättare upptag i mag-tarmkanalen.","ty":"f","src":"PPT bild 17","id":"k11c1ra7r37"},{"f":"Vad är det viktigaste när läkaren väljer antibiotika?","b":"Att det har effekt mot just den bakterie som orsakar infektionen.","ty":"b","src":"PPT bild 11","id":"k11c163qz2u"},{"f":"Vilket spektrum väljer läkaren i första hand?","b":"Smalt spektrum.","ty":"b","src":"PPT bild 11","id":"k11c1uled1u"},{"f":"När behövs antibiotika med brett spektrum?","b":"När patienten är mycket sjuk eller när det inte är helt klart vilka bakterier som orsakar infektionen.","ty":"v","src":"PPT bild 11","id":"k11c1jpsoyt"},{"f":"Varför kan inte alla antibiotika användas mot hjärnhinneinflammation?","b":"Eftersom alla antibiotika inte passerar till hjärnan.","ty":"v","src":"PPT bild 11","id":"k11cniom9g"},{"f":"Kan man behöva flera antibiotika samtidigt?","b":"Ja, enligt lärarens bild 11.","ty":"b","src":"PPT bild 11","id":"k11c4vu81l"},{"f":"Hur ser en grampositiv bakterie ut och vilken färg får den vid gramfärgning?","b":"Plasmamembran och en mycket tjock yttre cellvägg. Den färgas blå/lila.","ty":"j","src":"PPT bild 16 · s. 180","id":"k11cvdly6m"},{"f":"Hur ser en gramnegativ bakterie ut och vilken färg får den vid gramfärgning?","b":"Plasmamembran, tunn cellvägg och ett yttre cellmembran. Den färgas rosa/röd.","ty":"j","src":"PPT bild 16 · s. 180","id":"k11c1hg9e9u"},{"f":"Vilken webbplats tipsar läraren om för en överblick?","b":"Antibiotikasmart (antibiotikasmart.se/fakta.html).","ty":"s","src":"PPT bild 20","id":"k11c147itwx"}],"quiz":{"f":[{"q":"Vad är antibiotika enligt boken?","o":["Ämnen som kan döda bakterier men lämnar människans celler relativt oskadda","Ämnen som dödar alla celler","Vaccin mot bakterier","Ämnen som dödar virus"],"why":"Därför kan de användas mot bakterieinfektioner. Antibiotika hjälper inte mot virus.","src":"s. 212 · PPT bild 3","id":"k11q13we1v2"},{"q":"När dök de första antibiotika upp?","o":["På 1940- och 50-talen","På 1880-talet","På 1920-talet","På 1970-talet"],"why":"Det innebar en revolution för sjukvården (s. 212). Fleming levde 1881–1955.","src":"s. 212","id":"k11q1l41zhc"},{"q":"Vilket exempel ger boken på sjukdomar som blev lättbehandlade tack vare antibiotika?","o":["Lunginflammationer efter förkylningar och infekterade sår vid operationer","Influensa och förkylning","Malaria och herpes","Polio och mässling"],"why":"De gick från dödliga hot till lättbehandlade åkommor. Influensa, polio och mässling är virus.","src":"s. 212","id":"k11q1kjqbah"},{"q":"Mot vilka infektioner används INTE antibiotika enligt läraren?","o":["Infektioner som beror på virus eller svampar","Lunginflammation orsakad av bakterier","Infekterade operationssår","Urinvägsinfektion orsakad av bakterier"],"why":"Antibiotika är läkemedel mot bakterieinfektioner (bild 3).","src":"PPT bild 3","id":"k11qpp6vql"},{"q":"Vilket antibiotikum upptäcktes först?","o":["Penicillin","Rifampicin","Isoniazid","Meticillin"],"why":"Penicillin är både först upptäckt och mest använt i Sverige.","src":"s. 212","id":"k11q10b6kgf"},{"q":"Vem upptäckte penicillinet?","o":["Alexander Fleming","Hans Christian Gram","Louis Pasteur","Charles Darwin"],"why":"Den brittiske forskaren Alexander Fleming (1881–1955). Boken stavar Flemming. Gram utvecklade gramfärgningen.","src":"s. 212 · PPT bild 15","id":"k11q713uj4"},{"q":"Vad hade hänt i näringsskålen när Fleming kom tillbaka?","o":["Mögel hade börjat växa, och invid möglet hade bakterierna dött","Bakterierna hade ätit upp möglet","Alla bakterier i alla skålar hade dött","Ett virus hade infekterat bakterierna"],"why":"Slutsatsen blev att möglet bildar ett ämne som dödar bakterier.","src":"s. 212","id":"k11qc67yvu"},{"q":"Varför heter ämnet penicillin?","o":["Efter den typ av mögelsvampar som tillverkade det","Efter Flemings hemstad","Efter bakterien det dödade","Efter enzymet det blockerar"],"why":"Fleming döpte ämnet efter mögelsvampen (s. 212).","src":"s. 212","id":"k11q1o5yqju"},{"q":"Vad blockerar penicillin?","o":["Ett enzym som behövs för att bygga cellväggen","Bakteriens ribosomer","Steget DNA → RNA","Bakteriens flageller"],"why":"Bakterien kan då inte bilda och reparera sin cellvägg och kan inte dela sig.","src":"s. 212 · PPT bild 15","t":["vagg"],"id":"k11qhvm6u3"},{"q":"Mot vilka bakterier är penicillin framför allt verksamt?","o":["Grampositiva","Gramnegativa","Bakterier utan cellvägg","Alla lika bra"],"why":"Eftersom det slår mot bildandet av peptidoglukan, som grampositiva har ett tjockt lager av.","src":"s. 213 · PPT bild 15","t":["vagg"],"id":"k11q1aiztzx"},{"q":"Vad slår rifampicin mot i bokens figur?","o":["Steget DNA → RNA","Cellväggen","Steget RNA → proteiner","Kopieringen av DNA"],"why":"Rifampicin pekar på pilen mellan DNA och RNA. Läraren: nukleinsyrasynteshämmare.","src":"s. 213 · PPT bild 13","id":"k11q1ar0fc7"},{"q":"Vad slår kinoloner mot i bokens figur?","o":["Kopieringen av DNA","Cellväggen","Steget RNA → proteiner","Plasmiderna"],"why":"Kinoloner pekar på cirkelpilen vid DNA. Läraren: hämmare av DNA-replikation.","src":"s. 213 · PPT bild 13","id":"k11qhw891e"},{"q":"Vilken grupp slår mot cellväggen i bokens figur?","o":["Penicilliner, cefalosporiner och karbapenemer","Tetracykliner, makrolider och linkosamider","Kinoloner","Rifampicin"],"why":"PCK på väggen.","src":"s. 213","t":["vagg"],"id":"k11q1urd87s"},{"q":"Vilken grupp slår mot proteinsyntesen i bokens figur?","o":["Tetracykliner, makrolider och linkosamider","Penicilliner, cefalosporiner och karbapenemer","Kinoloner","Rifampicin"],"why":"TML på arbetsbänken: steget RNA → proteiner.","src":"s. 213 · PPT bild 13","t":["ribosom"],"id":"k11q14ib6p"},{"q":"Vilka mekanismer skiljer sig kraftigt mellan bakterier och eukaryoter enligt boken?","o":["DNA-syntes, replikation och proteinsyntes","Andning och matsmältning","Fotosyntes och osmos","Diffusion och osmos"],"why":"Därför kan antibiotika blockera bakteriens variant.","src":"s. 213 · PPT bild 18","id":"k11q5w5puz"},{"q":"Under vilken av lärarens verkningsmekanismer står glykopeptider?","o":["Hämmare av cellväggssyntes","Proteinsynteshämmare","Nukleinsyrasynteshämmare","Hämmare av DNA-replikation"],"why":"Tillsammans med betalaktamer (bild 13).","src":"PPT bild 13","id":"k11q1iq27qh"},{"q":"Under vilken av lärarens verkningsmekanismer står kloramfenikol och aminoglykosider?","o":["Proteinsynteshämmare","Hämmare av cellväggssyntes","Nukleinsyrasynteshämmare","Hämmare av DNA-replikation"],"why":"Tillsammans med tetracykliner, makrolider och linkosamider (bild 13).","src":"PPT bild 13","id":"k11q3gvprt"},{"q":"Vilka preparat står under nukleinsyrasynteshämmare på lärarens bild 13?","o":["Trimetoprim, sulfonamid och rifampicin","Kinoloner och metronidazol","Betalaktamer och glykopeptider","Makrolider och linkosamider"],"why":"Kinoloner och metronidazol är hämmare av DNA-replikation.","src":"PPT bild 13","id":"k11q1uvbmc6"},{"q":"Var under lärarens fyra verkningsmekanismer står metronidazol?","o":["Hämmare av DNA-replikation","Hämmare av cellväggssyntes","Proteinsynteshämmare","Nukleinsyrasynteshämmare"],"why":"Tillsammans med kinoloner (bild 13).","src":"PPT bild 13","id":"k11q1lgs2b5"},{"q":"Vad binder proteinsynteshämmande antibiotika till enligt läraren?","o":["Ribosomen eller något av hjälparproteinerna hos bakterier","Människans ribosomer","Bakteriens cellvägg","Bakteriens plasmider"],"why":"Samma sak händer inte hos människor, och därför överlever människocellerna (bild 19).","src":"PPT bild 19","t":["ribosom"],"id":"k11q1xfuppj"},{"q":"Vad får man om man sätter till en aminogrupp på penicillin?","o":["Ampicillin, som även verkar mot gramnegativa","Ett läkemedel som tas upp lättare i tarmen","Rifampicin","Ett vaccin"],"why":"Hydroxylgruppen ger lättare upptag i mag-tarmkanalen (bild 17).","src":"PPT bild 17","id":"k11q78ck78"},{"q":"Vad gör en hydroxylgrupp på penicillinmolekylen?","o":["Läkemedlet tas lättare upp av mag-tarmkanalen","Läkemedlet verkar mot virus","Läkemedlet slår mot ribosomen","Läkemedlet blir ett vaccin"],"why":"Lärarens bild 17.","src":"PPT bild 17","id":"k11q14dz8ia"},{"q":"Vilket spektrum väljer läkaren i första hand?","o":["Smalt spektrum","Brett spektrum","Alltid två antibiotika","Det som är billigast"],"why":"Brett spektrum när patienten är mycket sjuk eller bakterien är okänd (bild 11).","src":"PPT bild 11","id":"k11q1uled1u"},{"q":"Vilken sjukdom ger läraren som exempel på att antibiotikan måste nå fram dit infektionen sitter?","o":["Hjärnhinneinflammation","Öroninflammation","Urinvägsinfektion","Lunginflammation"],"why":"Alla antibiotika passerar inte till hjärnan (bild 11).","src":"PPT bild 11","id":"k11q96yxwb"},{"q":"Vilken färg får grampositiva bakterier vid gramfärgning enligt läraren?","o":["Blå/lila","Rosa/röd","Grön","Gul"],"why":"Gramnegativa blir rosa/röda (bild 16).","src":"PPT bild 16","id":"k11qwvxz1k"}],"u":[{"q":"Vad hade Fleming troligen sett om möglet inte bildat något ämne alls?","o":["Bakterierna hade vuxit ända fram till möglet","Alla bakterier i skålen hade dött","Möglet hade dött","Bakterierna hade blivit gröna"],"why":"Det var de döda bakterierna invid möglet som avslöjade att möglet bildar ett ämne.","src":"s. 212","id":"k11qnq20wx"},{"q":"Varför kan antibiotika användas som medicin, men inte vilket bakteriedödande ämne som helst?","o":["Antibiotika dödar bakterier men lämnar människans celler relativt oskadda","Antibiotika dödar även virus","Antibiotika är billiga","Antibiotika stärker immunförsvaret"],"why":"Det är själva definitionen (s. 212).","src":"s. 212","id":"k11q1p1bkeq"},{"q":"En bakterie behandlas med penicillin. Vad är det första som går fel för bakterien?","o":["Den kan inte bilda och reparera sin cellvägg","Dess DNA kopieras fel","Dess ribosomer stannar","Den tappar sina plasmider"],"why":"Sedan kan den inte dela sig och dör.","src":"s. 212","t":["vagg"],"id":"k11q17tfsai"},{"q":"Varför fungerar vanligt penicillin sämre mot gramnegativa än mot grampositiva bakterier?","o":["Det slår mot peptidoglukan, och gramnegativa har bara ett tunt lager","Gramnegativa saknar cellvägg helt","Gramnegativa har tjockare peptidoglukan","Gramnegativa saknar ribosomer"],"why":"Grampositiva har ett tjockt lager peptidoglukan (s. 180, 213).","src":"s. 213","t":["vagg"],"id":"k11q4sz3s1"},{"q":"Vad händer om en bakterie behandlas med tetracyklin?","o":["Steget RNA → proteiner blockeras, så den kan inte dela sig och dör","Cellväggen löses upp direkt","Bakterien blir grampositiv","Bakteriens DNA kopieras dubbelt"],"why":"Tetracykliner slår mot proteinsyntesen, bakteriens ribosom.","src":"s. 213 · PPT bild 19","t":["ribosom"],"id":"k11q1v7hir8"},{"q":"Varför skadar rifampicin inte våra celler lika mycket som bakteriernas?","o":["Molekylerna som gör RNA skiljer sig kraftigt mellan bakterier och eukaryoter","Våra celler har cellvägg","Våra celler saknar DNA","Rifampicin kan inte komma in i kroppen"],"why":"Rifampicin blockerar bakteriens variant av molekylen (s. 213).","src":"s. 213","id":"k11qufomk4"},{"q":"Vad har penicillin och kinoloner gemensamt enligt boken?","o":["Båda leder till att bakterien inte kan dela sig och dör","Båda slår mot cellväggen","Båda slår mot ribosomerna","Båda är proteinsynteshämmare"],"why":"Penicillin slår mot cellväggen, kinoloner mot DNA-kopieringen, men slutresultatet är detsamma.","src":"s. 212–213","id":"k11q1oqaa9l"},{"q":"Varför kan proteinsynteshämmare döda bakterier men inte människoceller?","o":["Bakteriens ribosom skiljer sig från människans, så antibiotikan binder bara till bakteriens","Människoceller gör inga proteiner","Människocellerna har en cellvägg som skyddar ribosomerna","Antibiotikan bryts ner i blodet innan den når människocellerna"],"why":"Lärarens bild 19 och bokens s. 213.","src":"PPT bild 19 · s. 213","t":["ribosom"],"id":"k11qt99egu"},{"q":"Läraren skriver \"betalaktamer\" där boken skriver penicilliner, cefalosporiner och karbapenemer. Vad är gemensamt för dem?","o":["De slår alla mot cellväggssyntesen","De slår alla mot ribosomen","De verkar alla bara mot virus","De tillverkas alla av människan"],"why":"Hämmare av cellväggssyntes (bild 13). Att de tre grupperna är betalaktamer är extra.","src":"s. 213 · PPT bild 13","t":["vagg"],"id":"k11q1vbul1z"},{"q":"En patient har en infektion med gramnegativa bakterier. Vilket av alternativen passar bäst enligt lärarens bilder?","o":["Ampicillin","Vanligt penicillin, eftersom det verkar bäst mot gramnegativa","Ett vaccin","Ett läkemedel mot virus"],"why":"Aminogruppen gör att ampicillin även verkar mot gramnegativa (bild 17).","src":"PPT bild 17","id":"k11q1nvk0dw"},{"q":"Varför vill man ha en hydroxylgrupp på ett penicillin som ska tas som tablett?","o":["Läkemedlet tas lättare upp av mag-tarmkanalen","Läkemedlet verkar mot virus","Läkemedlet passerar lättare till hjärnan","Läkemedlet blir smalare i spektrum"],"why":"Lärarens bild 17.","src":"PPT bild 17","id":"k11q1j3iffr"},{"q":"En patient är mycket sjuk och det är oklart vilken bakterie som orsakar infektionen. Vad gör läkaren enligt läraren?","o":["Ger antibiotika med brett spektrum, eventuellt flera samtidigt","Väntar tills infektionen läker av sig själv","Ger alltid ett smalt spektrum","Ger ett vaccin"],"why":"Bild 11.","src":"PPT bild 11","id":"k11qxzvkrm"},{"q":"Ett antibiotikum dödar en bakterie bra i ett provrör, men hjälper inte patienten med hjärnhinneinflammation. Vad är en trolig förklaring enligt läraren?","o":["Antibiotikan passerar inte till hjärnan","Bakterien blev en virus","Hjärnan saknar ribosomer","Antibiotikan är för smal i spektrum för provröret"],"why":"Läkaren måste ta hänsyn till var infektionen sitter (bild 11).","src":"PPT bild 11","id":"k11q1n6peca"},{"q":"Vilket påstående om bokens och lärarens beskrivning av rifampicin stämmer?","o":["Båda stämmer, eftersom RNA är en nukleinsyra","Bara boken har rätt","Bara läraren har rätt","De beskriver två olika läkemedel"],"why":"Boken: DNA → RNA. Läraren: nukleinsyrasyntes.","src":"s. 213 · PPT bild 13","id":"k11q1fn0iya"},{"q":"Varför är mitokondriens ribosomer intressanta när man pratar om antibiotika mot ribosomen?","o":["De är av samma typ som bakteriers, vilket visar att bakteriens ribosom skiljer sig från cellens egna","De saknar RNA","De bygger cellväggen","De är målet för penicillin"],"why":"Bevis för endosymbios (K4). Bakteriens ribosom skiljer sig från eukaryotens vanliga ribosomer.","src":"s. 27 (K4) · PPT bild 19","t":["endo","ribosom"],"id":"k11qrgaa0"}],"o":[{"q":"Förklara hur penicillin och andra antibiotika kan döda bakterier men lämna människans celler relativt oskadda. Ge exempel från bokens figur och förklara varför penicillin framför allt verkar mot grampositiva bakterier.","model":"Penicillin binder till och blockerar ett enzym som behövs för att bakterier ska bygga sin cellvägg. Utan att kunna bilda och reparera cellväggen kan bakterien inte dela sig och dör. Eftersom penicillin slår mot bildandet av peptidoglukan verkar det framför allt mot grampositiva bakterier, som har ett tjockt peptidoglukanlager. Andra antibiotika utnyttjar att molekylerna för DNA-syntes, replikation och proteinsyntes skiljer sig kraftigt mellan bakterier och eukaryoter, och blockerar bakteriens variant. I bokens figur slår kinoloner mot kopieringen av DNA, rifampicin mot DNA → RNA och tetracykliner, makrolider och linkosamider mot RNA → proteiner. Penicilliner, cefalosporiner och karbapenemer slår mot cellväggen.","kw":[["enzym"],["cellvägg"],["dela"],["peptidogl"],["grampositiv"],["skiljer"],["variant"],["kinolon","rifampicin","tetracyklin"]],"src":"s. 212–213","t":["vagg"],"id":"k11o1k2rysm"},{"q":"Berätta hur penicillinet upptäcktes och förklara varför antibiotika blev en revolution för sjukvården. Varför har resistenta bakterier blivit vanligare?","model":"Alexander Fleming (1881–1955) kom tillbaka till laboratoriet efter en månads semester. Mögelsvampar hade börjat växa i en av näringsskålarna där han odlat bakterier, och invid möglet hade bakterierna dött. Slutsatsen var att mögelsvampen bildar ett ämne som dödar bakterier. Han isolerade det och kallade det penicillin. Antibiotika dödar bakterier men lämnar våra celler relativt oskadda. När de kom på 1940- och 50-talen blev bakteriesjukdomar som lunginflammation efter förkylning och infekterade operationssår lättbehandlade i stället för dödliga. Men människan har använt mer och mer antibiotika och därmed selekterat för resistenta bakterier.","kw":[["fleming","flemming"],["semester"],["mögel"],["dött","döda"],["ämne","penicillin"],["1940","50-tal"],["lunginflammation","sår"],["selekt"]],"src":"s. 212","id":"k11o1yx0jtf"},{"q":"Beskriv lärarens fyra verkningsmekanismer för antibiotika med exempel på preparat. Förklara varför proteinsynteshämmare inte skadar människans celler.","model":"Hämmare av cellväggssyntes, till exempel betalaktamer och glykopeptider. Proteinsynteshämmare, till exempel aminoglykosider, tetracykliner, makrolider, linkosamider och kloramfenikol. Nukleinsyrasynteshämmare, till exempel trimetoprim, sulfonamid och rifampicin. Hämmare av DNA-replikation, till exempel kinoloner och metronidazol. Proteinsynteshämmarna binder till och blockerar bakteriens ribosom eller något av hjälparproteinerna. Människans ribosomer skiljer sig från bakteriens, och därför händer inte samma sak i våra celler. Bakterierna dör medan människocellerna överlever.","kw":[["cellväggssyntes","cellvägg"],["proteinsyntes"],["nukleinsyra"],["replikation"],["ribosom"],["hjälparprotein"],["skiljer","människ"]],"src":"PPT bild 13, 19 · s. 213","t":["ribosom"],"id":"k11o117zl7i"},{"q":"Förklara hur man kan ändra penicillin för att vidga användningsområdet, och vad läkaren måste tänka på när hen väljer antibiotikum.","model":"Små ändringar av strukturen hos penicillin vidgar användningsområdet. Med en aminogrupp får man ampicillin, som även verkar mot gramnegativa bakterier. Vanligt penicillin verkar framför allt mot grampositiva, eftersom det slår mot peptidoglukan. Med en hydroxylgrupp tas läkemedlet lättare upp av mag-tarmkanalen. Läkaren väljer ett antibiotikum som har effekt mot just den bakterie som orsakar infektionen, i första hand med smalt spektrum. Brett spektrum används om patienten är mycket sjuk eller om bakterien är okänd. Läkaren måste också tänka på var infektionen sitter, eftersom alla antibiotika inte passerar till hjärnan och därför inte kan användas mot hjärnhinneinflammation.","kw":[["aminogrupp"],["ampicillin"],["gramnegativ"],["hydroxyl"],["tarm"],["smalt"],["brett"],["hjärn"]],"src":"PPT bild 11, 15–17","id":"k11o15arrly"}]},"kan":[{"q":"Kan du ge bokens definition av antibiotika och säga vad de används till?","a":"Antibiotika är ämnen som kan döda bakterier, men som lämnar människans celler relativt oskadda. Därför kan de användas för att behandla bakterieinfektioner. Läraren lägger till att de verkar genom att döda bakterierna eller hindra dem från att föröka sig, och att de inte används mot virus eller svampar.","kw":[["döda bakterier","dödar bakterier","döda"],["människans celler","våra celler"],["oskadd"],["bakterieinfektion","infektion"]],"src":"s. 212 · PPT bild 2–3","id":"k11k17c6vj8"},{"q":"Kan du förklara varför antibiotika var en revolution för sjukvården, med årtal och exempel?","a":"De första antibiotika dök upp på 1940- och 50-talen. En lång rad bakteriesjukdomar gick då från att vara dödliga hot till lättbehandlade åkommor, eftersom man kunde döda bakterierna i kroppen. Bokens exempel är lunginflammationer efter förkylningar och infekterade sår vid operationer.","kw":[["1940","40-tal"],["50-tal"],["dödlig"],["lättbehandl"],["lunginflammation"],["sår","operation"]],"src":"s. 212","id":"k11k1sp8lpu"},{"q":"Kan du berätta hur Fleming upptäckte penicillinet och vilken slutsats han drog?","a":"Den brittiske forskaren Alexander Fleming (1881–1955) hade odlat bakterier i näringsskålar. När han kom tillbaka efter en månads semester hade det börjat växa mögelsvampar i en av skålarna, och invid möglet hade bakterierna dött. Slutsatsen: mögelsvampen måste bilda något ämne som dödar bakterierna. Han isolerade ämnet och kallade det penicillin, efter den typ av mögelsvampar som tillverkade det.","kw":[["fleming","flemming"],["semester"],["näringsskål","skål"],["mögel"],["dött","döda","dog"],["ämne"],["penicillin"]],"src":"s. 212","id":"k11k2sbsmr"},{"q":"Kan du förklara steg för steg hur penicillin dödar en bakterie?","a":"Penicillin binder till och blockerar ett enzym som behövs för att bakterien ska kunna bygga sin cellvägg. Bakterien kan då inte bilda och reparera sin cellvägg. Därför kan den inte dela sig, och den dör.","kw":[["enzym"],["blocker"],["cellvägg"],["reparera","bilda"],["dela"],["dör","död"]],"src":"s. 212 · PPT bild 15","id":"k11kn313s1"},{"q":"Kan du förklara varför penicillin framför allt verkar mot grampositiva bakterier?","a":"Penicillin slår mot bildandet av peptidoglukan. Grampositiva bakterier har ett tjockt lager peptidoglukan i cellväggen, medan gramnegativa har ett tunt lager och ett yttre membran. Därför verkar penicillin framför allt mot grampositiva. Vissa varianter, som ampicillin, kan även slå mot vissa gramnegativa.","kw":[["peptidogl"],["grampositiv"],["tjock"],["gramnegativ"],["variant","ampicillin"]],"src":"s. 213 · PPT bild 15–17","id":"k11k16hfa51"},{"q":"Kan du förklara hur andra antibiotika kan döda bakterier men skona människans celler?","a":"De molekyler som utför DNA-syntes, replikation och proteinsyntes skiljer sig kraftigt mellan bakterier och eukaryoter. Antibiotikan binder därför till och blockerar bakteriens variant av en sådan molekyl, men inte vår. Bakterien kan då inte dela sig och dör, medan våra celler klarar sig.","kw":[["dna-syntes","replikation"],["proteinsyntes"],["skiljer"],["eukaryot","människ"],["variant"],["dela"]],"src":"s. 213 · PPT bild 18","id":"k11k1dbje13"},{"q":"Kan du para ihop antibiotikagrupperna i bokens figur med det de slår mot?","a":"Penicilliner, cefalosporiner och karbapenemer slår mot bygget av cellväggen. Kinoloner slår mot kopieringen av DNA. Rifampicin slår mot steget DNA → RNA. Tetracykliner, makrolider och linkosamider slår mot steget RNA → proteiner, alltså proteinsyntesen.","kw":[["penicillin"],["cellvägg"],["kinolon"],["kopier","replikation"],["rifampicin"],["tetracyklin","makrolid","linkosamid"],["protein"]],"src":"s. 213","id":"k11k1qgo2cq"},{"q":"Kan du nämna lärarens fyra verkningsmekanismer med minst ett preparat i varje?","a":"Hämmare av cellväggssyntes: betalaktamer och glykopeptider. Proteinsynteshämmare: aminoglykosider, tetracykliner, makrolider, linkosamider och kloramfenikol. Nukleinsyrasynteshämmare: trimetoprim, sulfonamid och rifampicin. Hämmare av DNA-replikation: kinoloner och metronidazol.","kw":[["cellväggssyntes","cellvägg"],["proteinsyntes"],["nukleinsyra"],["replikation"],["betalaktam","glykopeptid"],["kinolon","metronidazol"]],"src":"PPT bild 13","id":"k11k1h5h2r9"},{"q":"Kan du förklara hur antibiotika som hindrar proteinsyntesen fungerar och varför människocellerna överlever?","a":"De binder till och blockerar ribosomen eller något av hjälparproteinerna hos bakterier. Bakterien kan då inte bygga proteiner och dör. Samma sak händer inte hos människor, eftersom våra ribosomer skiljer sig från bakteriens. Därför överlever de omgivande människocellerna.","kw":[["ribosom"],["hjälparprotein"],["blocker","binder"],["människ"],["överlev","skiljer"]],"src":"PPT bild 19 · s. 213","id":"k11k13q0cxq"},{"q":"Kan du förklara vad ampicillin är och vad en hydroxylgrupp gör?","a":"Små ändringar av strukturen hos penicillin vidgar användningsområdet. Sätter man till en aminogrupp får man ampicillin, som även verkar mot gramnegativa bakterier. Sätter man till en hydroxylgrupp tas läkemedlet lättare upp av mag-tarmkanalen.","kw":[["aminogrupp","nh2","nh₂"],["ampicillin"],["gramnegativ"],["hydroxyl","oh"],["mag-tarm","tarm"]],"src":"PPT bild 17","id":"k11ka3cezv"},{"q":"Kan du förklara smalt och brett spektrum och varför det spelar roll var infektionen sitter?","a":"Det viktigaste är att antibiotikan har effekt mot just den bakterie som orsakar infektionen. Läkaren väljer i första hand smalt spektrum. Brett spektrum används om patienten är mycket sjuk eller om det är oklart vilka bakterier det är, och ibland behövs flera antibiotika samtidigt. Läkaren måste också tänka på var infektionen sitter, eftersom alla antibiotika inte passerar till hjärnan och därför inte kan användas mot hjärnhinneinflammation.","kw":[["smalt"],["brett"],["första hand"],["mycket sjuk","oklart"],["hjärn"]],"src":"PPT bild 11","id":"k11k104qnzj"}],"kompis":[{"q":"Förklara för en kompis, som en detektivhistoria, hur Fleming kom fram till att mögel kan döda bakterier. Ta med varför antibiotika blev en revolution.","model":"Fleming odlade bakterier i näringsskålar och åkte på en månads semester. När han kom tillbaka växte det mögelsvampar i en av skålarna, och invid möglet hade bakterierna dött. Längre bort levde de. Slutsatsen var att möglet måste bilda ett ämne som dödar bakterier. Han isolerade ämnet och kallade det penicillin. Antibiotika dödar bakterier men lämnar våra celler relativt oskadda. När de kom på 1940- och 50-talen blev det en revolution, eftersom dödliga sjukdomar som lunginflammation efter förkylning och infekterade operationssår blev lättbehandlade.","kw":[["näringsskål","skål"],["semester"],["mögel"],["dött","döda","dog"],["ämne"],["penicillin"],["1940","50-tal"],["revolution"]],"src":"s. 212","id":"k11e197efoq"},{"q":"Förklara för en kompis varför ett antibiotikum kan döda bakterier i kroppen utan att döda kroppens egna celler. Ta med penicillin och minst ett annat exempel.","model":"Penicillin blockerar ett enzym som bakterien behöver för att bygga sin cellvägg. Utan en cellvägg som kan byggas och lagas kan bakterien inte dela sig och dör. Våra celler har ingen cellvägg. Andra antibiotika utnyttjar att molekylerna för DNA-syntes, replikation och proteinsyntes skiljer sig kraftigt mellan bakterier och eukaryoter. De blockerar bakteriens variant. Tetracykliner binder till exempel bakteriens ribosom men inte människans, och rifampicin stoppar bakteriens steg DNA → RNA. Därför överlever våra celler.","kw":[["enzym"],["cellvägg"],["dela"],["skiljer"],["variant"],["ribosom","rifampicin","kinolon","tetracyklin"],["överlev","klarar"]],"src":"s. 212–213 · PPT bild 19","t":["vagg","ribosom"],"id":"k11edgt0vq"},{"q":"Förklara för en kompis vad ampicillin är och varför man inte alltid kan använda vanligt penicillin.","model":"Penicillin slår mot bildandet av peptidoglukan och verkar därför framför allt mot grampositiva bakterier, som har ett tjockt lager peptidoglukan. Gramnegativa har en tunn cellvägg och ett yttre cellmembran. Sätter man till en aminogrupp på penicillinet får man ampicillin, som även verkar mot gramnegativa. Med en hydroxylgrupp tas läkemedlet dessutom lättare upp i mag-tarmkanalen. Läkaren väljer antibiotikum efter vilken bakterie det är, och i första hand ett med smalt spektrum.","kw":[["peptidogl"],["grampositiv"],["gramnegativ"],["aminogrupp"],["ampicillin"],["hydroxyl"],["spektrum"]],"src":"s. 213 · PPT bild 11, 15–17","id":"k11ezwja52"}],"gloss":[{"w":"Antibiotika","d":"Ämnen som kan döda bakterier men lämnar människans celler relativt oskadda. Används mot bakterieinfektioner.","src":"Bok s. 212"},{"w":"Bakterieinfektion","d":"Infektion som orsakas av bakterier. Kan behandlas med antibiotika.","src":"Bok s. 212"},{"w":"Samlingsbegrepp","d":"Ett ord för en hel grupp. Antibiotika är ett samlingsbegrepp för läkemedel mot bakterieinfektioner.","src":"PPT Antibiotika bild 3","lek":1},{"w":"Penicillin","d":"Det mest använda antibiotikumet i Sverige och det första som upptäcktes. Tillverkas av mögelsvampar. Blockerar ett enzym som bygger cellväggen.","src":"Bok s. 212"},{"w":"Mögelsvampar","d":"Mikroskopiska svampar (eukaryoter). En sorts mögelsvamp tillverkar penicillin.","src":"Bok s. 212"},{"w":"Alexander Fleming","d":"Brittisk forskare (1881–1955) som upptäckte penicillinet. Boken och läraren stavar Flemming.","src":"Bok s. 212"},{"w":"Näringsskål","d":"Skål där man odlar bakterier. Där växte möglet som ledde till Flemings upptäckt.","src":"Bok s. 212"},{"w":"Selektera","d":"Gynna vissa varianter så att de blir fler. Användningen av antibiotika har selekterat för resistenta bakterier.","src":"Bok s. 212"},{"w":"Resistent","d":"Motståndskraftig. En resistent bakterie tål ett antibiotikum.","src":"Bok s. 212"},{"w":"Enzym","d":"Protein som får en kemisk reaktion att gå. Penicillin blockerar enzymet som behövs för att bygga cellväggen.","src":"Bok s. 212"},{"w":"Cellvägg (bakterie)","d":"Väggen utanför bakteriens cellmembran, byggd av peptidoglukan. Mål för penicilliner, cefalosporiner och karbapenemer.","src":"Bok s. 212–213"},{"w":"Peptidoglukan (peptidoglykan)","d":"Ämnet i bakteriers cellvägg: kolhydratkedjor korsbundna med peptider. Penicillin slår mot bildandet av det.","src":"Bok s. 180, 213"},{"w":"Grampositiva bakterier","d":"Bakterier med plasmamembran och en mycket tjock cellvägg av peptidoglukan. Färgas blå/lila. Penicillin verkar framför allt mot dem.","src":"Bok s. 213 · PPT bild 16"},{"w":"Gramnegativa bakterier","d":"Bakterier med plasmamembran, tunn cellvägg och ett yttre cellmembran. Färgas rosa/röda. Vissa penicillinvarianter, t.ex. ampicillin, verkar mot dem.","src":"Bok s. 213 · PPT bild 16–17"},{"w":"DNA-syntes","d":"Bygget av nytt DNA. En av de grundläggande mekanismer som skiljer sig mellan bakterier och eukaryoter.","src":"Bok s. 213"},{"w":"Replikation","d":"Kopiering av DNA. Kinoloner och metronidazol hämmar den.","src":"Bok s. 213 · PPT bild 13"},{"w":"Proteinsyntes","d":"Tillverkning av proteiner (RNA → proteiner) på ribosomerna. Tetracykliner, makrolider, linkosamider, aminoglykosider och kloramfenikol hämmar den.","src":"Bok s. 213 · PPT bild 13"},{"w":"Nukleinsyrasyntes","d":"Bygget av nukleinsyror (DNA och RNA). Trimetoprim, sulfonamid och rifampicin hämmar den enligt läraren.","src":"PPT Antibiotika bild 13","lek":1},{"w":"Penicilliner, cefalosporiner, karbapenemer","d":"Antibiotikagrupper som slår mot bygget av cellväggen (bokens figur).","src":"Bok s. 213"},{"w":"Betalaktamer","d":"Lärarens gruppnamn för cellväggshämmare (bild 13). Penicilliner, cefalosporiner och karbapenemer är betalaktamer (extra).","src":"PPT Antibiotika bild 13","lek":1},{"w":"Glykopeptider","d":"Hämmare av cellväggssyntes enligt lärarens bild 13.","src":"PPT Antibiotika bild 13","lek":1},{"w":"Kinoloner","d":"Antibiotika som slår mot kopieringen av DNA (DNA-replikation).","src":"Bok s. 213 · PPT bild 13"},{"w":"Metronidazol","d":"Hämmare av DNA-replikation enligt lärarens bild 13.","src":"PPT Antibiotika bild 13","lek":1},{"w":"Rifampicin","d":"Antibiotikum som slår mot steget DNA → RNA (nukleinsyrasyntes). Förstahandsval mot tuberkulos.","src":"Bok s. 213, 215 · PPT bild 13"},{"w":"Trimetoprim och sulfonamid","d":"Nukleinsyrasynteshämmare enligt lärarens bild 13.","src":"PPT Antibiotika bild 13","lek":1},{"w":"Tetracykliner, makrolider, linkosamider","d":"Antibiotikagrupper som slår mot steget RNA → proteiner, alltså proteinsyntesen.","src":"Bok s. 213 · PPT bild 13"},{"w":"Aminoglykosider och kloramfenikol","d":"Proteinsynteshämmare enligt lärarens bild 13.","src":"PPT Antibiotika bild 13","lek":1},{"w":"Ribosom","d":"Cellens arbetsbänk där proteiner byggs. Bakteriens ribosom skiljer sig från människans, och vissa antibiotika blockerar bara bakteriens.","src":"PPT Antibiotika bild 19"},{"w":"Hjälparproteiner","d":"Proteiner som hjälper ribosomen. Vissa antibiotika blockerar bakteriens hjälparproteiner.","src":"PPT Antibiotika bild 19","lek":1},{"w":"Verkningsmekanism","d":"Det sätt ett läkemedel verkar på. Läraren delar in antibiotika i fyra verkningsmekanismer.","src":"PPT Antibiotika bild 13","lek":1},{"w":"Ampicillin","d":"Penicillin med en aminogrupp. Verkar även mot gramnegativa bakterier.","src":"PPT Antibiotika bild 17","lek":1},{"w":"Aminogrupp","d":"Kemisk grupp, NH₂. Ger ampicillin när den sätts på penicillin.","src":"PPT Antibiotika bild 17","lek":1},{"w":"Hydroxylgrupp","d":"Kemisk grupp, OH. Gör att penicillinvarianten tas lättare upp av mag-tarmkanalen.","src":"PPT Antibiotika bild 17","lek":1},{"w":"Smalt spektrum","d":"Antibiotika som läkaren väljer i första hand. Verkar mot färre sorters bakterier (extra).","src":"PPT Antibiotika bild 11","lek":1},{"w":"Brett spektrum","d":"Antibiotika som behövs om patienten är mycket sjuk eller om det är oklart vilka bakterier det är.","src":"PPT Antibiotika bild 11","lek":1},{"w":"Hjärnhinneinflammation","d":"Infektion där antibiotikan måste nå hjärnan. Alla antibiotika passerar inte dit.","src":"PPT Antibiotika bild 11","lek":1},{"w":"Gramfärgning","d":"Färgningstest: grampositiva blir blå/lila, gramnegativa rosa/röda.","src":"PPT Antibiotika bild 16 · Bok s. 180"}],"snabb":{"keys":["Antibiotika :: ämnen som dödar bakterier men lämnar människans celler relativt oskadda","Läraren :: dödar bakterier eller hindrar dem från att föröka sig, inte mot virus eller svampar","Penicillin :: mest använt i Sverige, först upptäckt, tillverkas av mögelsvampar","Fleming (1881–1955) :: en månads semester, mögel i skålen, döda bakterier invid möglet","Penicillin verkar :: blockerar enzymet som bygger cellväggen → ingen delning → död","Peptidoglukan :: penicillinets mål → framför allt grampositiva","PCK :: penicilliner, cefalosporiner, karbapenemer → cellväggen","Kinoloner :: kopieringen av DNA (DNA-replikation)","Rifampicin :: DNA → RNA (nukleinsyrasyntes)","TML :: tetracykliner, makrolider, linkosamider → RNA → proteiner","Proteinsynteshämmare :: blockerar bakteriens ribosom eller hjälparproteiner, inte människans","Ampicillin :: penicillin + aminogrupp → även gramnegativa","Hydroxylgrupp :: lättare upptag i mag-tarmkanalen","Spektrum :: smalt i första hand, brett vid svår sjukdom eller okänd bakterie"],"nums":[["1940- och 50-talen","de första antibiotika, en revolution för sjukvården (s. 212)"],["1881–1955","Alexander Flemings livstid (s. 212)"],["1 månad","Flemings semester (s. 212)"],["4","angreppspunkter i bokens figur och fyra verkningsmekanismer hos läraren"],["3","grundläggande mekanismer som skiljer sig: DNA-syntes, replikation, proteinsyntes (s. 213)"],["1928","upptäckten av penicillin (extra)"],["1945","Nobelpriset till Fleming, Florey och Chain (extra)"]],"chains":[["Mögel i Flemings skål","bakterierna invid möglet döda","möglet bildar ett ämne","penicillin"],["Penicillin blockerar enzymet","ingen ny eller lagad cellvägg","ingen delning","bakterien dör"],["Penicillin slår mot peptidoglukan","grampositiva har tjockt lager","verkar främst mot grampositiva"],["Bakteriens ribosom skiljer sig från vår","antibiotikan binder bara bakteriens","bakterien dör, människocellen överlever"],["Penicillin + aminogrupp","ampicillin","verkar även mot gramnegativa"],["Mer och mer antibiotika","selektion för resistenta","fler resistenta infektioner"]],"traps":["Antibiotika hjälper mot bakterier. Mot virus och svampar används inte antibiotika.","Boken och läraren stavar Flemming. Han hette Fleming.","Peptidoglukan (s. 213) och peptidoglykan (s. 180) är samma ämne.","Rifampicin = DNA → RNA. Kinoloner = kopieringen av DNA. Blanda inte ihop dem.","Aminogrupp → ampicillin, gramnegativa. Hydroxylgrupp → upptag i tarmen.","Läkaren väljer i första hand smalt spektrum, inte brett.","\"Relativt oskadda\" betyder inte helt ofarliga."]}},"k12":{"pre":[{"q":"Vad är Haemophilus influenzae, som alla barn vaccineras mot?","o":["En bakterie som kan orsaka lunginflammation","Influensaviruset","En svamp","Ett vaccin"],"why":"Trots namnet är det en bakterie. Influensa är ett virus.","src":"s. 212","id":"k12p114322w"},{"q":"Vad gör antibiotikan när en resistent bakterie finns i en patient som behandlas?","o":["Den dödar konkurrenterna, så att den resistenta får plats att dela sig","Den gör de känsliga bakterierna resistenta","Den gör patienten resistent","Ingenting alls"],"why":"Antibiotikan selekterar. Den skapar inte resistensen (s. 214).","src":"s. 214","id":"k12pfcghpk"},{"q":"Varför fanns det resistensgener i naturen redan innan människan började använda antibiotika?","o":["De flesta antibiotika tillverkas naturligt av bakterier och svampar som vapen mot konkurrenter","Människan har spridit dem med vaccin","Alla bakterier är födda resistenta","Det fanns inga resistensgener före 1940"],"why":"Bakterier har skyddat sig mot \"kemisk krigsföring\" under hela evolutionen (s. 213).","src":"s. 213","id":"k12p1n9ztml"},{"q":"Vad betyder MRSA?","o":["Meticillinresistenta gula stafylokocker","Multiresistent salmonella","Mycket resistenta streptokocker A","Mördarbakterie med resistent sax"],"why":"Faktarutan Mördarbakterier (s. 215).","src":"s. 215","id":"k12p6jcn0t"},{"q":"Vad är den vanligaste orsaken till att man inte blir frisk trots antibiotika?","o":["Infektionen beror på virus","Bakterien är resistent","Dosen är för hög","Man har ätit fel mat"],"why":"Lärarens bild 12. Antibiotika verkar bara mot bakterier.","src":"PPT Antibiotika bild 12","id":"k12p6luoei"}],"cards":[{"f":"Vilka tre bakteriesjukdomar erbjuds alla barn vaccin mot enligt boken?","b":"Difteri, stelkramp och halsfluss. Minnesknep: DiSH.","ty":"s","src":"s. 212","id":"k12c10vt2jd"},{"f":"Vilka tre virussjukdomar (plus en fjärde) erbjuds alla barn vaccin mot enligt boken?","b":"Mässling, röda hund och påssjuka (MRP), och dessutom virussjukdomen polio.","ty":"s","src":"s. 212","id":"k12cbhhe1c"},{"f":"Vad kan papillomavirus orsaka enligt boken?","b":"Vårtor och kondylom, och det kan öka risken för livmoderhalscancer. Alla barn erbjuds vaccin.","ty":"b","src":"s. 212","id":"k12cj4ku26"},{"f":"Vilka två bakterier som kan orsaka lunginflammation vaccineras alla barn mot?","b":"Pneumokocker och Haemophilus influenzae.","ty":"s","src":"s. 212","id":"k12cdyg82g"},{"f":"Provfälla: är Haemophilus influenzae ett virus?","b":"Nej, en bakterie, trots namnet. Influensa är ett virus. Boken stavar Haemophilius, men rätt är Haemophilus.","ty":"f","src":"s. 212","id":"k12cwxavug"},{"f":"Vilka vaccin erbjuds barn med ökad risk att smittas?","b":"Tuberkulos (en bakterie) och gulsotsviruset hepatit B.","ty":"s","src":"s. 212","id":"k12c4wmioo"},{"f":"Vilka uppmanas att vaccinera sig mot influensa, och hur ofta?","b":"Äldre, personer med nedsatt immunförsvar och personer med lungsjukdomar. Varje år.","ty":"s","src":"s. 212","id":"k12c1lukmzw"},{"f":"Varför ska riskgrupperna vaccinera sig mot influensa?","b":"Influensa ökar risken för allvarlig lunginflammation, som varje år kostar tusentals personer i riskgrupperna livet.","ty":"v","src":"s. 212","id":"k12c2rosmf"},{"f":"Vilka vaccin nämner boken inför resor?","b":"Vaccin mot smittämnen man riskerar att möta på resmålet, som gula febern och kolera.","ty":"s","src":"s. 212","id":"k12c1iysl8y"},{"f":"Vaccin eller antibiotika: vad är skillnaden?","b":"Vaccin ges förebyggande, före smittan, och finns mot både bakterie- och virussjukdomar. Antibiotika behandlar en bakterieinfektion man redan har och hjälper inte mot virus.","ty":"j","src":"s. 212 · PPT Antibiotika bild 2–3","id":"k12c11vzpr9"},{"f":"Hur skiljer sig dagens svenska vaccinationsprogram från bokens lista? (extra)","b":"Kikhosta i stället för halsfluss, rotavirus har tillkommit, HPV till alla barn sedan 2020 och hepatit B till alla spädbarn. På provet gäller bokens lista.","ty":"s","src":"Extra","id":"k12cwj4o7k"},{"f":"Vad har hänt när människan använt mer och mer antibiotika?","b":"Man har selekterat för resistenta bakterier. Därför infekteras människor allt oftare av bakterier som är resistenta mot en eller flera av de vanliga antibiotikan.","ty":"v","src":"s. 212 · PPT Antibiotika bild 5, 7","p":1,"id":"k12c1wrmzbn"},{"f":"Vem blir resistent, bakterien eller människan?","b":"Bakterien. Det är bakterierna som blir resistenta, inte människor eller djur.","ty":"f","src":"PPT Antibiotika bild 2","id":"k12c1818pbg"},{"f":"Vad kallar läraren antibiotikaresistens?","b":"Ett naturligt fenomen där bakterier utvecklar motståndskraft mot antibiotika.","ty":"b","src":"PPT Antibiotika bild 2","id":"k12c1hao6qj"},{"f":"Var kommer de flesta antibiotika ifrån ursprungligen?","b":"De produceras naturligt i bakterier eller svampar i naturen.","ty":"b","src":"s. 213","id":"k12c1qgp8a6"},{"f":"Varför tillverkar bakterier och svampar antibiotika?","b":"Som redskap i konkurrensen mellan arter om resurserna i ekologiska nischer. Den som dödar konkurrenter får bättre möjlighet att föröka sig.","ty":"v","src":"s. 213","id":"k12c1fduvt9"},{"f":"Varför bär många bakterier i naturen resistensgener?","b":"För att skydda sig mot den \"kemiska krigsföringen\" från andra bakterier och svampar. Därför finns mängder av resistensgener i ekosystemen.","ty":"v","src":"s. 213","id":"k12c1yr7xz3"},{"f":"Vad har behandling med antibiotika skapat enligt boken s. 213?","b":"Ett selektivt tryck för nya mutationer som ger resistens.","ty":"b","src":"s. 213 · PPT Antibiotika bild 7","p":1,"id":"k12c1x4kzxg"},{"f":"Hur förklarar läraren resistens med mutation och naturligt urval?","b":"Om antibiotika finns i miljön och en bakterie får en mutation som gör att den tål antibiotika ärver alla dess avkommor egenskapen och får genom naturligt urval en överlevnadsfördel. Ju mer antibiotika, desto vanligare resistens.","ty":"v","src":"PPT Antibiotika bild 7 · s. 213","p":1,"id":"k12c691tfv"},{"f":"Resistensmekanism 1 (sax)?","b":"Resistensgenen beskriver ett protein som klipper sönder antibiotikan. Exempel: ESBL.","ty":"b","t":["nyckel"],"src":"s. 213","id":"k12ciym42j"},{"f":"Resistensmekanism 2 (utkastare)?","b":"Resistensgenen beskriver ett protein som transporterar ut antibiotikan ur bakterien.","ty":"b","t":["membran"],"src":"s. 213","id":"k12cn7eqqc"},{"f":"Resistensmekanism 3 (nytt lås)?","b":"En förändrad gen för det protein som antibiotikumet normalt binder, så att antibiotikan inte längre kan fästa vid det. Exempel: MRSA.","ty":"b","t":["nyckel"],"src":"s. 213","id":"k12c1k8fksy"},{"f":"Minnesknep för de tre resistensmekanismerna?","b":"SUN: Sax, Utkastare, Nytt lås.","ty":"s","src":"s. 213","id":"k12cniwvsf"},{"f":"Provfälla: vid nytt lås, vad är det som har ändrats?","b":"Bakteriens målprotein (genen för det). Antibiotikan är densamma men passar inte längre, som en nyckel i ett bytt lås.","ty":"f","t":["nyckel"],"src":"s. 213","id":"k12cr031do"},{"f":"Var finns resistensgener enligt boken?","b":"I en rad bakterier, både i kroppen och i naturen omkring oss. Nya kan dessutom uppkomma slumpmässigt.","ty":"b","src":"s. 213","id":"k12ctx2piu"},{"f":"Varför kan resistenta bakterier dyka upp var och när som helst?","b":"Resistensgener kan hoppa mellan ställen i arvsmassan och flyttas från en bakterie till en annan, även över artgränser.","ty":"v","src":"s. 213–214 · PPT Antibiotika bild 7–10","p":1,"id":"k12cyi3pmq"},{"f":"Vertikal och horisontell spridning av resistensgener?","b":"Vertikal: från en modercell till två dotterceller. Horisontell: från en bakterie till en annan genom konjugation, transduktion eller transformation.","ty":"j","t":["plasmid"],"src":"PPT Antibiotika bild 7","id":"k12cvg28c5"},{"f":"Varför kan några få plasmidbärare snabbt göra en hel population resistent?","b":"Vid konjugation blir mottagaren själv givarcell och kan föra plasmiden vidare.","ty":"v","t":["plasmid"],"src":"PPT Antibiotika bild 8","id":"k12ccwv4st"},{"f":"Gör det en sjuk att bära på resistenta bakterier?","b":"Inte nödvändigtvis, men det ökar risken för spridning till andra och för framtida, svårbehandlade infektioner.","ty":"b","src":"PPT Antibiotika bild 4","id":"k12cie5dh4"},{"f":"Vilka tre spridningsvägar i samhället nämner läraren?","b":"Mellan människor (nära kontakt, bristande handhygien), via djur och livsmedel (djurhållning) och i miljön (antibiotikarester från avloppsvatten och jordbruk).","ty":"s","src":"PPT Antibiotika bild 6","p":1,"id":"k12cjioqga"},{"f":"Vad menar läraren med \"Bakterier känner inga gränser\"?","b":"Resistens som uppstår i ett land kan snabbt spridas globalt genom resor och handel. Därför krävs internationellt samarbete.","ty":"b","src":"PPT Antibiotika bild 6","id":"k12css1zh3"},{"f":"Vilka delar av sjukvården är beroende av effektiva antibiotika enligt läraren?","b":"Cancerbehandlingar, transplantationer och operationer, eftersom de innebär en ökad infektionsrisk. Även enklare tillstånd, t.ex. urinvägsinfektion.","ty":"s","src":"PPT Antibiotika bild 5","p":1,"id":"k12c1ch8iov"},{"f":"Vad händer med lättbehandlade infektioner när bakterierna blir resistenta?","b":"De kan bli svåra eller omöjliga att bota. Läraren kallar det ett allvarligt och växande folkhälsoproblem.","ty":"v","src":"PPT Antibiotika bild 5","id":"k12c1gngnrh"},{"f":"Hur ska antibiotika användas enligt läraren?","b":"Ansvarsfullt, endast när det behövs och på rätt sätt.","ty":"b","src":"PPT Antibiotika bild 5 · s. 214","p":1,"id":"k12c1ba6nkp"},{"f":"Selektion i patienten: vad händer steg för steg?","b":"En resistent bakterie finns i en patient som får dess antibiotikum → konkurrenterna dödas → den resistenta delar sig och fyller upp den lediga platsen.","ty":"v","src":"s. 214 · PPT Antibiotika bild 7","p":1,"id":"k12cv7t9o3"},{"f":"Vad skapar användning av antibiotika enligt boken?","b":"Ett starkt selektivt tryck för bakterier som bär på resistensgener.","ty":"b","src":"s. 214","p":1,"id":"k12c13b5c1w"},{"f":"Provfälla: gör antibiotikan bakterierna resistenta?","b":"Nej. Den dödar de känsliga, och de som redan var resistenta får plats. Det är urval.","ty":"f","src":"s. 214","id":"k12cctb6g6"},{"f":"Var är resistenta bakterier särskilt besvärliga att bli av med, och varför?","b":"I miljöer där man använder mycket antibiotika, t.ex. sjukhusens operationsavdelningar, eftersom antibiotikan hela tiden dödar deras konkurrenter.","ty":"v","src":"s. 214","p":1,"id":"k12c90ifkx"},{"f":"Till vad används antibiotika i boskapsskötsel enligt boken?","b":"Att behandla djur med infektioner, att förebygga smitta om en infektion kommit in i besättningen och i många länder att snabba på djurens tillväxt.","ty":"s","src":"s. 214 · PPT Antibiotika bild 6","p":1,"id":"k12c57vtiv"},{"f":"Varför ökar antibiotika djurens tillväxt enligt boken?","b":"Det är oklart, skriver boken.","ty":"f","src":"s. 214","id":"k12c1eh47ny"},{"f":"Vilka djur runt stora djurbesättningar bär bakterier med resistensgener?","b":"Fåglar och smågnagare. Generna ger resistens mot de antibiotika som getts till boskapen.","ty":"s","src":"s. 214","id":"k12c12kz7a4"},{"f":"När förbjöds antibiotika enbart för tillväxt i Sverige och EU? (extra)","b":"Sverige 1986, EU 2006.","ty":"s","src":"Extra","id":"k12c1azf0hc"},{"f":"Var ligger gener för antibiotikaresistens i många fall?","b":"På plasmider, små extra DNA-molekyler i bakterierna.","ty":"b","t":["plasmid"],"src":"s. 214 · PPT Antibiotika bild 7","p":1,"id":"k12czerad5"},{"f":"Boken och läraren om plasmider och resistensgener: vad skiljer?","b":"Boken: \"i många fall\" på plasmider (MRSA har en transposon). Läraren: \"Resistensgener sitter på plasmider.\" Skriv bokens version.","ty":"j","t":["plasmid"],"src":"s. 214–215 · PPT Antibiotika bild 7","id":"k12ckzdaag"},{"f":"Varför blir ibland en dotterbakterie utan plasmid?","b":"Plasmiderna kopieras inför delningen, men det finns inget maskineri som ser till att det hamnar plasmider i båda bakterierna.","ty":"v","t":["plasmid"],"src":"s. 214","id":"k12czm8q50"},{"f":"Varför minskar resistenta bakterier om vi slutar använda antibiotika?","b":"Utan antibiotika ger plasmiden ingen fördel, och eftersom den ibland tappas vid delningen förloras den i det långa loppet. Det gäller så länge vi inte selekterar för dem.","ty":"v","t":["plasmid"],"src":"s. 214","id":"k12c1s9zby8"},{"f":"Bokens råd 1 om sjukvården?","b":"Håll tillbaka antibiotika: använd det inte vid infektioner som normalt läker av sig själva, t.ex. öroninflammation, även om det kan ge lite längre sjukdomsperiod och lite mer obehag.","ty":"b","src":"s. 214 · PPT Antibiotika bild 5","p":1,"id":"k12cr0r3j9"},{"f":"Bokens råd 2 om dosen?","b":"Relativt höga doser, behandlingen tiden ut och inte sluta när symptomen försvinner.","ty":"b","src":"s. 214 · PPT Antibiotika bild 12","p":1,"id":"k12c5rcxea"},{"f":"Varför ska dosen vara relativt hög?","b":"Genvarianter med svag motståndskraft uppstår och cirkulerar relativt ofta. De dödas av höga doser, men överlever låga doser eller oregelbundet intag och kan bli allt mer resistenta.","ty":"v","src":"s. 214–215","id":"k12c1trs2c1"},{"f":"Vad kan svagt motståndskraftiga bakterier göra om de överlever en låg dos?","b":"Föröka sig, sprida sig och sedan mutera vidare eller kombinera sina gener med varandra, så att allt mer resistenta bakterier uppkommer.","ty":"v","src":"s. 215","id":"k12c1lmu7mu"},{"f":"Bokens råd 3 om djurhållning?","b":"Begränsa antibiotika: inte för att öka vikten och inte för att förebygga, bara för att behandla infektioner som verkligen bryter ut.","ty":"b","src":"s. 215 · PPT Antibiotika bild 6","p":1,"id":"k12c1tn39zs"},{"f":"Bokens råd 4 om sällskapsdjur, och varför?","b":"Var försiktig med antibiotika till sällskapsdjur. Etablerar sig resistenta bakterier hos en katt eller hund kan bakterier eller resistensgener föras över till husse eller matte och deras umgänge.","ty":"v","src":"s. 215","id":"k12cdyww3i"},{"f":"Bokens råd 5, och varför?","b":"Undvik att sprida bakterier. Ju färre som smittas, desto färre behöver antibiotika, och ju mindre smittspridning, desto mindre spridning av resistenta bakterier.","ty":"v","src":"s. 215 · PPT Antibiotika bild 6","p":1,"id":"k12cosi83n"},{"f":"Vad är det viktigaste och samtidigt enklaste man kan göra mot resistenta bakterier?","b":"Att överallt följa de hygienråd som redan finns, i hem, sjukhus, slakterier, livsmedelsaffärer, restauranger och så vidare.","ty":"b","src":"s. 215 · PPT Antibiotika bild 6","p":1,"id":"k12c1kuyt3b"},{"f":"Minnesknep för bokens fem råd?","b":"Sju Duktiga Djur Sover Hemma: Sjukvården håller tillbaka, Dosen hög hela tiden, Djurhållning begränsas, Sällskapsdjur försiktigt, Hygien överallt.","ty":"s","src":"s. 214–215","id":"k12c5ytmet"},{"f":"Provfälla: är det motsägelsefullt att hålla tillbaka antibiotika och samtidigt ge höga doser?","b":"Nej. Använd antibiotika mer sällan, men när det behövs: rätt dos och hela tiden.","ty":"f","src":"s. 214–215","id":"k12c12dyx4o"},{"f":"Hur är MRSA resistent?","b":"Ett hoppande genpaket, en transposon, bär en förändrad version av det enzym som cellväggsantibiotika binder. Enzymet blir helt okänsligt.","ty":"v","t":["vagg","nyckel"],"src":"s. 215","id":"k12c1yh4y2r"},{"f":"Vad betyder multiresistent enligt boken?","b":"Att bakterien har fler än tre ytterligare resistensgener.","ty":"b","src":"s. 215","id":"k12c1ewxzea"},{"f":"Varför har MRSA blivit vanligt i sjukvården?","b":"Många har gula stafylokocker på huden, och de kan infektera sår. Man använder antibiotika mot sårinfektioner vid operationer, och därför har man selekterat för MRSA världen över.","ty":"v","src":"s. 215","id":"k12c147p9v2"},{"f":"Bokens siffror för MRSA?","b":"Sverige 2010: 1 500 fall, men bara i femton hade bakterierna trängt djupt in i kroppen.","ty":"s","src":"s. 215","id":"k12c12vpkq0"},{"f":"Vad är ESBL-producerande enterobakterier?","b":"Gramnegativa stavar, ofta E. coli, som normalt bor i tarmen. En plasmid får dem att bilda ett protein som klipper sönder penicillin och många andra cellväggsantibiotika.","ty":"b","t":["plasmid"],"src":"s. 215","id":"k12c2pb78"},{"f":"Bokens siffror för ESBL?","b":"Sverige 2010: 5 000 fall, varav 200 infektioner som gått på djupet.","ty":"s","src":"s. 215","id":"k12c1e1c4br"},{"f":"MRSA eller ESBL: var sitter resistensen?","b":"MRSA: transposon (hoppande genpaket). ESBL: plasmid.","ty":"j","t":["plasmid"],"src":"s. 215","id":"k12ce0w5uw"},{"f":"Varför är resistent tuberkulos ett globalt problem?","b":"Bakterien samlar på sig resistensgener och bara ett fåtal antibiotika biter. En mycket stor andel är resistent mot förstahandsvalen, allt fler även mot andrahandsvalen, och under 2000-talet cirkulerar stammar som tål alla antibiotika.","ty":"v","src":"s. 215","id":"k12c1j6ilf5"},{"f":"Vilka två antibiotika är de traditionella förstahandsvalen mot tuberkulos?","b":"Rifampicin och isoniazid.","ty":"s","src":"s. 215","id":"k12c5dnxc4"},{"f":"Varför ska man ta hela kuren enligt läraren?","b":"Det tar ett tag innan alla bakterier har försvunnit. Slutar man för tidigt kan några överleva och föröka sig, och infektionen kan komma tillbaka.","ty":"v","src":"PPT Antibiotika bild 12 · s. 214","p":1,"id":"k12ci97nzn"},{"f":"Boken och läraren förklarar \"hela kuren\" olika. Hur?","b":"Boken: svagt motståndskraftiga bakterier överlever låga doser och blir allt mer resistenta. Läraren: infektionen kan komma tillbaka. Samma råd.","ty":"j","src":"s. 214–215 · PPT Antibiotika bild 12","id":"k12c1wbf75w"},{"f":"Vilka orsaker ger läraren till att man inte blir frisk av antibiotika?","b":"Vanligast: infektionen beror på virus. Annars fel sorts antibiotika, för låg dos eller för kort behandling.","ty":"s","src":"PPT Antibiotika bild 12","id":"k12csgyupo"},{"f":"Bildfrågan: vad visar figuren Selektion i en patient i tre steg? (ritad efter bokens text, boken har ingen bild här)","b":"1 Före: många känsliga och en resistent. 2 Antibiotika: de känsliga dör. 3 Efter: de resistenta har delat sig och fyllt de lediga platserna.","ty":"i","src":"s. 214","id":"k12c1qrlzb2"},{"f":"Bildfrågan: i figuren med tre försvar, vad sitter i cellmembranet?","b":"Proteinet som transporterar ut antibiotikan ur bakterien, utkastaren.","ty":"i","t":["membran"],"src":"s. 213","id":"k12c190c2nw"}],"quiz":{"f":[{"q":"Vilka tre bakteriesjukdomar erbjuds alla barn vaccin mot enligt boken?","o":["Difteri, stelkramp, halsfluss","Mässling, röda hund, påssjuka","Tuberkulos, kolera, polio","Influensa, hepatit B, gula febern"],"why":"DiSH. Mässling, röda hund och påssjuka är de tre virussjukdomarna.","src":"s. 212","id":"k12q10vt2jd"},{"q":"Vilka erbjuds vaccin mot tuberkulos och hepatit B enligt boken?","o":["Barn med ökad risk att smittas","Alla barn","Bara äldre","Bara resenärer"],"why":"Faktarutan s. 212.","src":"s. 212","id":"k12q1jyqh8l"},{"q":"Varför uppmanas riskgrupperna att vaccinera sig mot influensa varje år?","o":["Influensa ökar risken för allvarlig lunginflammation","Influensa orsakar livmoderhalscancer","Influensavaccinet ersätter antibiotika","Influensa är en bakterie"],"why":"Lunginflammationen kostar varje år tusentals personer i riskgrupperna livet.","src":"s. 212","id":"k12qe5rmd9"},{"q":"Vilket smittämne nämner boken som vaccin inför resor?","o":["Gula febern","Stelkramp","Påssjuka","Papillomavirus"],"why":"Gula febern och kolera (s. 212).","src":"s. 212","id":"k12qe37ote"},{"q":"Var produceras de flesta antibiotika ursprungligen?","o":["Naturligt i bakterier eller svampar","Bara i laboratorier","I människans tarm","I virus"],"why":"Boken s. 213.","src":"s. 213","id":"k12q1j22m0t"},{"q":"Vad kallar boken den konkurrens som antibiotika varit ett vapen i?","o":["Kemisk krigsföring","Horisontell spridning","Fotosyntes","Endosymbios"],"why":"Bakterier bär gener för motståndskraft mot \"sådan kemisk krigsföring\" (s. 213).","src":"s. 213","id":"k12q1qiiq86"},{"q":"Vilket är INTE ett av bokens tre sätt att bli resistent?","o":["Bakterien bygger en tjockare cellkärna","Ett protein klipper sönder antibiotikan","Ett protein transporterar ut antibiotikan","Målproteinet är förändrat"],"why":"Bakterier har ingen cellkärna. De tre sätten är sax, utkastare och nytt lås.","src":"s. 213","t":["nyckel"],"id":"k12q1gjkove"},{"q":"Vem blir resistent mot antibiotika enligt läraren?","o":["Bakterierna","Människorna","Djuren","Både människor och bakterier"],"why":"Lärarens bild 2.","src":"PPT Antibiotika bild 2","id":"k12qyigutw"},{"q":"Vad är horisontell spridning?","o":["Från en bakterie till en annan genom konjugation, transduktion eller transformation","Från modercell till två dotterceller","Från människa till människa","Från djur till människa"],"why":"Lärarens bild 7. Vertikal spridning är från modercell till dotterceller.","src":"PPT Antibiotika bild 7","t":["plasmid"],"id":"k12q1mnwga6"},{"q":"Vilken av dessa är en av lärarens spridningsvägar i samhället?","o":["I miljön, via antibiotikarester från avlopp och jordbruk","Via mobiltelefoner","Via solljus","Via vaccin"],"why":"Lärarens bild 6: mellan människor, via djur och livsmedel, i miljön.","src":"PPT Antibiotika bild 6","id":"k12q1pvslu5"},{"q":"Var är resistenta bakterier enligt boken särskilt besvärliga att bli av med?","o":["På sjukhusens operationsavdelningar","I skogen","Hos växter","I kylskåp"],"why":"Där används mycket antibiotika (s. 214).","src":"s. 214","id":"k12q786z4m"},{"q":"Hos vilka djur runt stora djurbesättningar har man hittat bakterier med resistensgener?","o":["Fåglar och smågnagare","Fiskar och grodor","Hundar och katter","Insekter"],"why":"Boken s. 214.","src":"s. 214","id":"k12qk09ci7"},{"q":"Vad gör inget maskineri i bakterien vid delningen?","o":["Ser till att båda dotterbakterierna får en plasmid","Kopierar kromosomen","Kopierar plasmiden","Bygger cellväggen"],"why":"Plasmiderna kopieras, men fördelas inte säkert (s. 214).","src":"s. 214","t":["plasmid"],"id":"k12qz7h13x"},{"q":"Vilken infektion använder boken som exempel på en som normalt läker av sig själv?","o":["Öroninflammation","Tuberkulos","Hjärnhinneinflammation","MRSA-infektion"],"why":"Råd 1 (s. 214).","src":"s. 214","id":"k12q1o8lup3"},{"q":"Vad är det viktigaste rådet mot resistens enligt boken?","o":["Följa hygienråden överallt","Ta antibiotika vid varje förkylning","Ge antibiotika till alla djur","Byta antibiotikum varje dag"],"why":"\"Det viktigaste ... är därför också det enklaste\" (s. 215).","src":"s. 215","id":"k12qrbtq3t"},{"q":"Var sitter MRSA:s resistensgener?","o":["I en transposon, ett hoppande genpaket","På en plasmid","I cellkärnan","I ett virus"],"why":"Faktarutan s. 215. ESBL har plasmid.","src":"s. 215","id":"k12q1palacf"},{"q":"Hur många MRSA-fall hittade man i Sverige 2010 enligt boken?","o":["1 500, varav 15 djupa","5 000, varav 200 djupa","15 000, varav 1 500 djupa","200, varav 15 djupa"],"why":"5 000/200 är ESBL.","src":"s. 215","id":"k12qlc8w16"},{"q":"Vad är ESBL-bakterierna oftast?","o":["E. coli, gramnegativa stavar i tarmen","Gula stafylokocker på huden","Tuberkulosbakterier","Pneumokocker"],"why":"Faktarutan s. 215.","src":"s. 215","id":"k12qp59mf1"},{"q":"Vilka två antibiotika är traditionella förstahandsval mot tuberkulos?","o":["Rifampicin och isoniazid","Penicillin och ampicillin","Tetracyklin och makrolid","Meticillin och kinolon"],"why":"Faktarutan s. 215.","src":"s. 215","id":"k12qqa88qa"},{"q":"Vad är enligt läraren den vanligaste orsaken till att antibiotika inte hjälper?","o":["Infektionen beror på virus","Fel sorts antibiotika","För låg dos","För kort behandling"],"why":"De andra tre är också orsaker, men virus är vanligast (bild 12).","src":"PPT Antibiotika bild 12","id":"k12qkh1cf8"},{"q":"Vad betyder multiresistent bakterie enligt boken?","o":["Fler än tre ytterligare resistensgener","Resistent mot ett antibiotikum","Resistent mot alla vaccin","En bakterie med många plasmider utan resistensgener"],"why":"MRSA-texten s. 215.","src":"s. 215","id":"k12qxw6l2n"}],"u":[{"q":"En patient med en känslig bakterieinfektion och en enda resistent bakterie får antibiotika i två veckor. Vad är troligast efteråt?","o":["De resistenta har blivit många, eftersom konkurrenterna dog","Alla bakterier är döda","De känsliga har blivit resistenta","Ingenting har förändrats"],"why":"Selektion: den resistenta får fritt fram att dela sig och fylla den lediga platsen (s. 214).","src":"s. 214","id":"k12q1wktun5"},{"q":"Varför är antibiotika ingen hjälp mot mässling, men vaccin är det?","o":["Mässling är ett virus, och antibiotika verkar bara mot bakterier","Mässlingsbakterien är alltid resistent","Antibiotika förstör vaccinet","Mässling läker alltid av sig själv"],"why":"Mässling är en av bokens tre virussjukdomar. Antibiotika hjälper inte mot virus (PPT bild 2–3).","src":"s. 212 · PPT Antibiotika bild 2–3","id":"k12qqnp9x1"},{"q":"Varför finns resistensgener även hos bakterier som aldrig har mött mediciner?","o":["Antibiotika är naturliga vapen, och bakterier har länge haft skydd mot dem","Resistens smittar via luften från sjukhus","Gener för resistens bildas av antibiotikan","Alla bakterier har samma gener"],"why":"Kemisk krigsföring i naturen (s. 213).","src":"s. 213","id":"k12q1h1ocxk"},{"q":"En bakteries målprotein har ändrat form så att antibiotikan inte kan fästa. Vilket av bokens exempel liknar det mest?","o":["MRSA","ESBL","Resistent tuberkulos","Haemophilus influenzae"],"why":"MRSA har en förändrad version av enzymet som cellväggsantibiotika binder (nytt lås).","src":"s. 213, 215","t":["nyckel","vagg"],"id":"k12qcx9ksv"},{"q":"En bakterie bildar ett protein som klipper sönder penicillin. Vilken mördarbakterie liknar den?","o":["ESBL-producerande enterobakterie","MRSA","Resistent tuberkulos","Pneumokock"],"why":"ESBL-plasmiden ger ett protein som klipper sönder penicillin (sax).","src":"s. 215","t":["plasmid"],"id":"k12qvjth9h"},{"q":"Om all antibiotika i en miljö försvinner under lång tid, vad händer med plasmiderna som bär resistensgener?","o":["De blir långsamt färre, eftersom en dotterbakterie ibland blir utan","De blir fler","De förvandlas till kromosomer","De blir virus"],"why":"Ingen fördel och ingen säker fördelning, så de förloras i det långa loppet (s. 214).","src":"s. 214","t":["plasmid"],"id":"k12qg9cqpu"},{"q":"En patient tar halva dosen och glömmer tabletter ibland. Vad kan hända enligt boken?","o":["Svagt motståndskraftiga bakterier överlever och kan bli allt mer resistenta","Alla bakterier dör snabbare","Bakterierna blir virus","Patienten blir immun"],"why":"Låga doser eller oregelbundet intag (s. 215).","src":"s. 214–215","id":"k12q155cjvv"},{"q":"Varför är rådet att följa hygienråden effektivt mot resistens?","o":["Färre smittas, färre behöver antibiotika och mindre resistens sprids","Tvål dödar bara resistenta bakterier","Hygien gör bakterier känsliga igen","Hygien ersätter alla antibiotika"],"why":"Råd 5 (s. 215) och lärarens bild 6.","src":"s. 215 · PPT Antibiotika bild 6","id":"k12q1v5zqjr"},{"q":"Varför kan resistens hos en hund bli ett problem för familjen?","o":["Bakterier eller resistensgener kan föras över till husse, matte och deras umgänge","Hunden blir resistent och smittar resistens som virus","Hundar kan inte få antibiotika","Hundens vaccin slutar verka"],"why":"Råd 4 (s. 215).","src":"s. 215","id":"k12qadc6y"},{"q":"Varför kan resistens i ett land bli ett problem i hela världen?","o":["Resistenta bakterier sprids globalt genom resor och handel","Alla länder har samma sjukhus","Antibiotika tillverkas av samma svamp","Bakterier flyger med vinden mellan kontinenter"],"why":"\"Bakterier känner inga gränser\" (PPT bild 6).","src":"PPT Antibiotika bild 6","id":"k12qj1xnvr"},{"q":"Varför är resistenta bakterier ett hot mot transplantationer och cancerbehandlingar?","o":["De behandlingarna ger ökad infektionsrisk och kräver effektiva antibiotika","Resistenta bakterier angriper bara organ","Cancerceller blir resistenta mot antibiotika","Transplantationer görs med antibiotika i stället för kirurgi"],"why":"Lärarens bild 5.","src":"PPT Antibiotika bild 5","id":"k12q15xd16"},{"q":"Antibiotika i djurfoder för att öka tillväxten. Vad förutspår boken?","o":["Bakterier hos vilda fåglar och smågnagare runt besättningen får resistensgener","Djuren får starkare immunförsvar","Bakterierna i jorden dör ut","Resistensen stannar inne i djuren"],"why":"Boken s. 214.","src":"s. 214","id":"k12q1rny311"},{"q":"Varför har man selekterat fram MRSA just i sjukvården?","o":["Man ger antibiotika mot sårinfektioner vid operationer, och gula stafylokocker finns på huden","MRSA lever bara i sjukhusens vatten","Sjukhus använder inga antibiotika","MRSA sprids med vaccin"],"why":"Faktarutan s. 215.","src":"s. 215","id":"k12qaujcgl"}],"o":[{"q":"Förklara varför användningen av antibiotika leder till fler resistenta bakterier. Använd orden konkurrenter och selektivt tryck.","model":"Resistensgener finns redan i naturen och nya kan uppkomma slumpmässigt genom mutationer. Om en resistent bakterie finns i en patient som behandlas med dess antibiotikum dödas dess konkurrenter, men den själv överlever. Den får fritt fram att dela sig och fylla upp den lediga platsen, och avkomman ärver resistensen. Användning av antibiotika skapar alltså ett starkt selektivt tryck för bakterier med resistensgener. Ju mer antibiotika, desto vanligare blir resistenta bakterier.","kw":[["konkurrent"],["selektivt tryck","selektion","urval"],["dela","föröka"],["ledig","plats"],["muta","resistensgen"]],"src":"s. 213–214 · PPT Antibiotika bild 7","id":"k12ohto40l"},{"q":"Beskriv tre sätt en resistensgen kan göra en bakterie resistent, och ge exempel på bakterier som använder två av dem.","model":"Genen kan beskriva ett protein som klipper sönder antibiotikan, ett protein som transporterar ut antibiotikan ur bakterien, eller vara en förändrad gen för det protein antibiotikumet normalt binder, så att antibiotikan inte kan fästa. ESBL-producerande enterobakterier har en plasmid med gen för ett protein som klipper sönder penicillin. MRSA har en transposon med en förändrad version av enzymet som cellväggsantibiotika binder.","kw":[["klipp"],["transporter","ut"],["förändr"],["esbl"],["mrsa"]],"src":"s. 213, 215","t":["nyckel"],"id":"k12o1lknncu"},{"q":"Förklara varför plasmider med resistensgener kan försvinna, och vad det betyder för hur vi bör använda antibiotika.","model":"Resistensgener ligger i många fall på plasmider. Plasmiderna kopieras inför varje celldelning, men inget maskineri ser till att båda dotterbakterierna får en, så ibland blir en utan. Utan antibiotika ger plasmiden ingen fördel, och därför förloras den i det långa loppet. Förekomsten av resistenta bakterier minskar så länge vi inte selekterar för dem. Därför bör man hålla tillbaka antibiotika, inte använda det vid infektioner som läker av sig själva och begränsa det i djurhållning.","kw":[["plasmid"],["delning","kopier"],["maskineri","utan plasmid","båda"],["minska","försvinn","förlor"],["hålla tillbaka","selekter","begränsa"]],"src":"s. 214–215","t":["plasmid"],"id":"k12o1sh31vg"},{"q":"Beskriv bokens fem råd för att motverka antibiotikaresistens, med en förklaring till varje.","model":"1. Håll tillbaka antibiotika i sjukvården, t.ex. inte vid öroninflammation, eftersom all användning selekterar för resistens. 2. Relativt höga doser och behandlingen tiden ut, eftersom bakterier med svag motståndskraft dödas av höga doser men överlever låga och kan bli allt mer resistenta. 3. Begränsa antibiotika i djurhållning till behandling, eftersom användning för tillväxt och förebyggande sprider resistensgener till bakterier i ekosystemen. 4. Försiktighet med sällskapsdjur, eftersom resistenta bakterier eller gener kan föras över till husse och matte. 5. Undvik smittspridning med hygien, eftersom färre smittade behöver färre antibiotika och resistenta bakterier sprids mindre.","kw":[["sjukvård","öroninflammation"],["dos","tiden ut"],["djurhållning"],["sällskapsdjur"],["hygien","sprid"]],"src":"s. 214–215","id":"k12oz5fwpl"}]},"kan":[{"q":"Kan du räkna upp vad alla barn i Sverige erbjuds vaccin mot enligt boken, och vilka som är bakterier?","a":"Alla barn erbjuds vaccin mot de tre bakteriesjukdomarna difteri, stelkramp och halsfluss, de tre virussjukdomarna mässling, röda hund och påssjuka, virussjukdomen polio, papillomavirus (vårtor, kondylom, ökad risk för livmoderhalscancer) och två bakterier som kan orsaka lunginflammation, pneumokocker och Haemophilus influenzae. Barn med ökad risk erbjuds dessutom vaccin mot tuberkulos och hepatit B.","kw":[["difteri"],["stelkramp"],["halsfluss"],["mässling","röda hund","påssjuka"],["polio","papillom"],["pneumokock","haemophilus"]],"src":"s. 212","id":"k12ka0jsle"},{"q":"Kan du förklara varför många bakterier i naturen bär på resistensgener?","a":"De flesta antibiotika produceras naturligt av bakterier eller svampar. Under evolutionen har de varit redskap i konkurrensen mellan arter om resurserna i olika ekologiska nischer, eftersom den som dödar konkurrenter förökar sig bättre. Därför bär många bakterier gener som ger motståndskraft mot sådan kemisk krigsföring, och mängder av resistensgener finns runt om i ekosystemen.","kw":[["naturlig","naturen"],["bakterier","svamp"],["konkurren"],["krigsföring","vapen","motståndskraft"],["ekosystem","nisch"]],"src":"s. 213","id":"k12k191g380"},{"q":"Kan du beskriva bokens tre sätt som en resistensgen kan göra en bakterie resistent?","a":"Genen beskriver ett protein. En del resistensgener beskriver proteiner som klipper sönder antibiotikan. Andra beskriver proteiner som transporterar ut antibiotikan ur bakterien. Ytterligare andra är förändrade gener för det protein som antibiotikumet normalt binder, och då kan antibiotikan inte längre fästa vid det. ESBL är exempel på det första och MRSA på det tredje.","kw":[["klipp"],["transporter","ut ur","pump"],["förändr","ändrad"],["binder","fäst"],["protein"]],"src":"s. 213","t":["nyckel"],"id":"k12k1mc0khf"},{"q":"Kan du förklara steg för steg vad som händer när en resistent bakterie finns i en patient som behandlas med antibiotika?","a":"Om en resistent bakterie dyker upp i en patient som behandlas med dess antibiotikum dödas den resistenta bakteriens konkurrenter. Den resistenta bakterien får då fritt fram att dela sig och fylla upp den lediga platsen. Användning av antibiotika skapar därför ett starkt selektivt tryck för bakterier som bär på resistensgener, och på sjukhusens operationsavdelningar, där man använder mycket antibiotika, är de besvärliga att bli av med.","kw":[["konkurrent"],["död"],["dela","föröka"],["ledig","plats"],["selekt","urval"]],"src":"s. 214","id":"k12kxgnz4n"},{"q":"Kan du förklara hur antibiotika används i boskapsskötsel och vad det leder till?","a":"Antibiotika används för att behandla djur som fått infektioner, för att förebygga smitta om en infektion tagit sig in i en besättning och i många länder för att snabba på djurens tillväxt, även om det är oklart varför det fungerar. Därför ser man i många delar av världen att bakterier hos fåglar och smågnagare runt stora djurbesättningar bär gener för resistens mot de antibiotika som getts till boskapen.","kw":[["behandla"],["förebygg"],["tillväxt"],["fåglar","smågnagare"],["resistensgen","resisten"]],"src":"s. 214","id":"k12k1mxfpgx"},{"q":"Kan du förklara varför antibiotikaresistenta bakterier blir färre om vi slutar selektera för dem?","a":"Gener för antibiotikaresistens ligger i många fall på plasmider. Plasmiderna kopieras inför varje celldelning, men det finns inget maskineri som ser till att båda dotterbakterierna får en plasmid, så ibland blir en utan. Om bakterierna får växa utan den antibiotika som plasmiden ger resistens mot förlorar de därför plasmiderna i det långa loppet, och förekomsten av resistenta bakterier minskar.","kw":[["plasmid"],["kopier","delning"],["maskineri","båda","utan"],["långa loppet","försvinn","förlor"],["selekt","utan antibiotika"]],"src":"s. 214","t":["plasmid"],"id":"k12krouay7"},{"q":"Kan du ge bokens fem råd för att minska risken för antibiotikaresistenta infektioner?","a":"Håll tillbaka antibiotika i sjukvården, alltså inte vid infektioner som normalt läker av sig själva, som öroninflammation. Ge relativt höga doser och fortsätt behandlingen tiden ut. Begränsa antibiotika i djurhållning till att behandla infektioner som verkligen bryter ut. Var försiktig med antibiotika till sällskapsdjur. Undvik att sprida bakterier genom att följa hygienråden överallt.","kw":[["sjukvård","hålla tillbaka"],["hög","dos"],["tiden ut","hela"],["djurhållning","djur"],["sällskapsdjur","hund","katt"],["hygien","sprida"]],"src":"s. 214–215","id":"k12k79y2bb"},{"q":"Kan du beskriva MRSA och ESBL och jämföra dem?","a":"MRSA är meticillinresistenta gula stafylokocker. De bär en transposon, ett hoppande genpaket, med en förändrad version av det enzym som cellväggsantibiotika binder, och därför är enzymet helt okänsligt. ESBL-producerande enterobakterier är gramnegativa stavar, ofta E. coli, som bor i tarmen. De bär en plasmid som ger ett protein som klipper sönder penicillin och många andra cellväggsantibiotika. Sverige 2010: MRSA 1 500 fall varav 15 djupa, ESBL 5 000 fall varav 200 djupa.","kw":[["stafylokock"],["transposon"],["enzym"],["plasmid"],["klipp"],["1 500","1500","5 000","5000"]],"src":"s. 215","t":["plasmid","vagg"],"id":"k12kmphlkb"},{"q":"Kan du förklara varför man ska ta hela kuren, enligt både boken och läraren?","a":"Boken: genvarianter som ger svag motståndskraft uppstår och cirkulerar relativt ofta. De dödas av höga doser, men vid låga doser eller oregelbundet intag kan de överleva, föröka sig, sprida sig och sedan mutera vidare eller kombinera sina gener, så att allt mer resistenta bakterier uppkommer. Läraren: slutar man för tidigt kan några bakterier överleva och föröka sig, och infektionen kan komma tillbaka.","kw":[["svag motståndskraft","svagt"],["hög","dos"],["överlev"],["muter","kombiner"],["tillbaka","återfall"]],"src":"s. 214–215 · PPT Antibiotika bild 12","id":"k12k14aub3y"}],"kompis":[{"q":"Förklara för en kompis hur en antibiotikakur kan göra att resistenta bakterier tar över i kroppen.","model":"I kroppen lever många bakterier sida vid sida, och de konkurrerar om platsen. Någon enstaka kan bära en resistensgen, från en mutation eller lånad från en annan bakterie. När patienten får antibiotika dör alla känsliga bakterier, men den resistenta överlever. Konkurrenterna är borta, så den får fritt fram att dela sig och fylla upp den lediga platsen. Antibiotikan har alltså inte gjort någon bakterie resistent. Den har valt ut den som redan var det. Därför ger antibiotika ett starkt selektivt tryck.","kw":[["konkurren"],["resistensgen","resistent"],["känsliga","dör","död"],["dela","föröka"],["ledig","plats"],["selekt","urval","välj"]],"src":"s. 214","id":"k12ehisbvr"},{"q":"Förklara för en kompis varför man både ska använda antibiotika sällan och ge höga doser när man väl gör det.","model":"Varje gång man använder antibiotika selekterar man för resistenta bakterier, och därför ska man inte ge det vid infektioner som läker av sig själva, som öroninflammation. När antibiotika verkligen behövs ska dosen vara relativt hög och behandlingen fortsätta tiden ut. Det beror på att bakterier med svag motståndskraft uppstår ganska ofta. De dör av höga doser, men vid låga doser eller oregelbundet intag överlever de och kan mutera vidare eller kombinera sina gener till allt mer resistenta bakterier.","kw":[["selekt"],["öroninflammation","läker"],["hög"],["tiden ut","hela"],["svag"],["muter","kombiner"]],"src":"s. 214–215","id":"k12e1v0ep8c"},{"q":"Förklara för en kompis hur resistenta bakterier sprids, både mellan bakterier och i samhället.","model":"Resistensgener kan hoppa mellan ställen i arvsmassan och flyttas från en bakterie till en annan, även över artgränser, till exempel med plasmider vid konjugation. Läraren kallar det horisontell spridning, medan vertikal spridning går från modercell till dotterceller. I samhället sprids resistenta bakterier mellan människor via nära kontakt och bristande handhygien, via djur och livsmedel eftersom djurhållning använder antibiotika, i miljön via antibiotikarester från avlopp och jordbruk, och över gränser via resor och handel.","kw":[["horisontell","konjugation","plasmid"],["art"],["handhygien","kontakt"],["djur","livsmedel"],["miljö","avlopp"],["resor","handel"]],"src":"s. 213–214 · PPT Antibiotika bild 6–7","id":"k12e17io7y0"}],"gloss":[{"w":"Vaccin","d":"Ges för att förebygga en sjukdom innan man smittats. Finns mot både bakterie- och virussjukdomar.","src":"Bok s. 212"},{"w":"Difteri, stelkramp, halsfluss","d":"Bokens tre bakteriesjukdomar i barnvaccinationsprogrammet.","src":"Bok s. 212"},{"w":"Mässling, röda hund, påssjuka","d":"Bokens tre virussjukdomar i barnvaccinationsprogrammet.","src":"Bok s. 212"},{"w":"Polio","d":"Virussjukdom som alla barn vaccineras mot.","src":"Bok s. 212"},{"w":"Papillomavirus","d":"Virus som kan orsaka vårtor och kondylom och öka risken för livmoderhalscancer. Alla barn erbjuds vaccin.","src":"Bok s. 212"},{"w":"Pneumokocker","d":"Bakterier som kan orsaka lunginflammation. Alla barn erbjuds vaccin.","src":"Bok s. 212"},{"w":"Haemophilus influenzae","d":"Bakterie (inte virus) som kan orsaka lunginflammation. Boken stavar Haemophilius.","src":"Bok s. 212"},{"w":"Hepatit B","d":"Gulsotsviruset. Barn med ökad risk erbjuds vaccin.","src":"Bok s. 212"},{"w":"Influensa","d":"Virus. Äldre och riskgrupper vaccineras varje år, eftersom det ökar risken för allvarlig lunginflammation.","src":"Bok s. 212"},{"w":"Antibiotikaresistens","d":"Att bakterier tål antibiotika som annars skulle döda dem. Ett naturligt fenomen. Det är bakterierna som blir resistenta, inte människor.","src":"Bok s. 212–213 · PPT Antibiotika bild 2"},{"w":"Resistensgen","d":"Gen som gör en bakterie resistent, t.ex. genom att beskriva ett protein som klipper sönder eller transporterar ut antibiotikan.","src":"Bok s. 213"},{"w":"Kemisk krigsföring","d":"Bokens ord för hur bakterier och svampar använder antibiotika som vapen mot konkurrenter i naturen.","src":"Bok s. 213"},{"w":"Ekologisk nisch","d":"Den plats och de resurser en art konkurrerar om i ett ekosystem.","src":"Bok s. 213"},{"w":"Selektivt tryck","d":"När en miljö, t.ex. med antibiotika, gynnar bakterier med en viss egenskap, så att de blir fler.","src":"Bok s. 213–214"},{"w":"Selektera","d":"Välja ut. Antibiotika selekterar för resistenta bakterier genom att döda deras konkurrenter.","src":"Bok s. 212, 214"},{"w":"Mutation","d":"Slumpmässig förändring i arvsmassan. Kan ge resistens som avkomman ärver.","src":"Bok s. 213 · PPT Antibiotika bild 7"},{"w":"Naturligt urval","d":"De som har en överlevnadsfördel, t.ex. resistens, överlever och för den vidare till sin avkomma.","src":"PPT Antibiotika bild 7","lek":1},{"w":"Vertikal spridning","d":"Från en modercell till två dotterceller.","src":"PPT Antibiotika bild 7","lek":1},{"w":"Horisontell spridning","d":"Från en bakterie till en annan genom konjugation, transduktion eller transformation.","src":"PPT Antibiotika bild 7","lek":1},{"w":"Plasmid","d":"Liten extra DNA-molekyl i bakterier. Bär i många fall resistensgener. Kopieras men fördelas inte säkert vid delning.","src":"Bok s. 214"},{"w":"Transposon","d":"Hoppande genpaket som kan flytta sig i arvsmassan. MRSA bär sin resistens i en transposon.","src":"Bok s. 215"},{"w":"Boskapsskötsel","d":"Djurhållning. Där används antibiotika för att behandla, förebygga och i många länder för att öka tillväxten.","src":"Bok s. 214"},{"w":"Folkhälsoproblem","d":"Problem som berör hälsan i hela befolkningen. Läraren kallar antibiotikaresistens ett allvarligt och växande folkhälsoproblem.","src":"PPT Antibiotika bild 5","lek":1},{"w":"Handhygien","d":"Att hålla händerna rena. Bristande handhygien sprider resistenta bakterier mellan människor.","src":"PPT Antibiotika bild 6","lek":1},{"w":"MRSA","d":"Meticillinresistenta gula stafylokocker. Transposon med förändrat enzym för cellväggsbygget.","src":"Bok s. 215"},{"w":"Meticillin","d":"Ett antibiotikum som slår mot cellväggssyntesen. MRSA är resistent mot det.","src":"Bok s. 215"},{"w":"Gula stafylokocker","d":"Bakterier som många har på huden och som kan infektera sår.","src":"Bok s. 215"},{"w":"Multiresistent bakterie","d":"Bakterie med fler än tre ytterligare resistensgener.","src":"Bok s. 215"},{"w":"ESBL-producerande enterobakterier","d":"Gramnegativa stavar, ofta E. coli, i tarmen. Plasmid med gen för ett protein som klipper sönder penicillin och andra cellväggsantibiotika.","src":"Bok s. 215"},{"w":"Enterobakterier","d":"Tarmbakterier, t.ex. E. coli.","src":"Bok s. 215"},{"w":"Isoniazid","d":"Ett av de två traditionella förstahandsvalen mot tuberkulos, tillsammans med rifampicin.","src":"Bok s. 215"},{"w":"Hela kuren","d":"Att ta antibiotika så länge läkaren har ordinerat, även om man känner sig bättre tidigare.","src":"PPT Antibiotika bild 12 · Bok s. 214"},{"w":"MDR-TB","d":"Multiresistent tuberkulos, resistent mot både rifampicin och isoniazid. Står inte i boken.","src":"Extra"}],"snabb":{"keys":["Alla barn, bakterier :: difteri, stelkramp, halsfluss + pneumokocker, Haemophilus influenzae","Alla barn, virus :: mässling, röda hund, påssjuka, polio, papillomavirus","Barn med ökad risk :: tuberkulos och hepatit B","Influensa varje år :: äldre, nedsatt immunförsvar, lungsjukdomar","Tre resistenssätt :: sax (klipper), utkastare (transporterar ut), nytt lås (förändrat målprotein)","Antibiotikans roll vid resistens :: selekterar, dödar konkurrenterna","Resistensgener ligger i många fall :: på plasmider","Plasmider försvinner :: inget maskineri fördelar dem vid delning","Fem råd :: sjukvård, dos, djurhållning, sällskapsdjur, hygien","Viktigaste rådet :: hygien, också det enklaste","MRSA :: transposon, nytt lås på enzymet för cellväggen","ESBL :: plasmid, sax mot penicillin, E. coli i tarmen","Resistent TB :: rifampicin + isoniazid, stammar som tål alla","Spridning i samhället :: människor, djur och livsmedel, miljön, resor och handel"],"nums":[["1 500","MRSA-fall i Sverige 2010 (boken)"],["15","av MRSA-fallen hade trängt djupt in (2010)"],["5 000","ESBL-fall i Sverige 2010"],["200","av ESBL-fallen var djupa infektioner (2010)"],["fler än 3","ytterligare resistensgener = multiresistent"],["2","förstahandsval mot TB: rifampicin och isoniazid"],["5","bokens råd mot resistens"],["3","bokens sätt att bli resistent"],["1986 / 2006","förbud mot antibiotika för tillväxt i Sverige / EU (extra)"],["2020","HPV-vaccin till alla barn (extra)"]],"chains":[["Resistent bakterie + antibiotika","konkurrenterna dör","den resistenta delar sig","fyller den lediga platsen","starkt selektivt tryck"],["Plasmid med resistensgen","kopieras men fördelas inte säkert","en dotterbakterie blir ibland utan","utan antibiotika: plasmiden förloras","resistenta blir färre"],["Låg dos eller oregelbundet intag","svagt motståndskraftiga överlever","förökar sig och sprids","muterar eller kombinerar gener","allt mer resistenta bakterier"],["Hygien","färre smittas","färre behöver antibiotika","mindre spridning av resistenta bakterier"],["Gula stafylokocker på huden","infekterar operationssår","antibiotika mot sårinfektioner","selektion för MRSA"],["Antibiotika till boskap","resistensgener i ekosystemet","bakterier hos fåglar och smågnagare blir resistenta"]],"traps":["Haemophilus influenzae är en bakterie, influensa ett virus.","Antibiotikan gör inte bakterier resistenta. Den väljer ut dem.","Det är bakterierna som blir resistenta, inte människan.","Resistensgener på plasmider \"i många fall\", inte alltid (MRSA = transposon).","MRSA 1 500 / 15, ESBL 5 000 / 200. Blanda inte ihop.","Plasmider försvinner för att de inte fördelas säkert, inte för att antibiotikan förstör dem.","Vanligaste orsaken till att antibiotika inte hjälper: virus.","Hålla tillbaka antibiotika och ge höga doser är ingen motsägelse."]}},"k13":{"pre":[{"q":"Vilken del har en växtcell som en djurcell saknar?","o":["Cellvägg","Mitokondrier","Cellmembran","Ribosomer"],"why":"Växtcellen har cellvägg, stor vakuol och kloroplaster som djurcellen saknar. Mitokondrier, cellmembran och ribosomer har båda.","src":"s. 244","id":"k13p132xk7x"},{"q":"Hur stor del av en växtcell kan vakuolen fylla?","o":["Upp till 90 %","Upp till 10 %","Ungefär 25 %","Ungefär 50 %"],"why":"Vakuolen kan uppta upp till 90 % av cellens volym.","src":"s. 245","id":"k13pmitb2p"},{"q":"Varför ser växter gröna ut?","o":["Grönt ljus reflekteras","Grönt ljus absorberas","Cellväggen är grön","Vakuolen är grön"],"why":"Klorofyllet absorberar violett, blått och rött ljus, medan grönt reflekteras.","src":"s. 247","id":"k13p11dd0el"},{"q":"Vad händer med en växtcell i destillerat vatten?","o":["Den tar upp vatten men spricker inte","Den spricker","Den krymper","Ingenting, eftersom vatten inte kan passera"],"why":"Vatten går in, men cellväggen hindrar cellen från att spricka. En djurcell skulle spricka.","src":"s. 245","t":["osmos","vagg"],"id":"k13p1xuw5r1"},{"q":"Vad lagrar leukoplasterna i potatisens stamknölar?","o":["Stärkelse","Klorofyll","Fett","Cellulosa"],"why":"Leukoplaster är färglösa plastider som lagrar stärkelse.","src":"s. 247","id":"k13p158uybi"}],"cards":[{"f":"Vad betyder fotoautotrof?","b":"Att kunna skapa organiska föreningar med hjälp av solljus och koldioxid. Det skiljer en växt från ett djur.","ty":"b","src":"s. 244","id":"k13c1ehx3wa"},{"f":"Vad är närsalter?","b":"Kväve, fosfor och andra mineraler som växten måste ta upp från omgivningen. Läraren kallar dem också mineralämnen (oorganiska ämnen).","ty":"b","src":"s. 244 · PPT Bi2 bild 3","p":1,"id":"k13cgyvddi"},{"f":"Varför behöver en växt inte äta energirika organiska molekyler?","b":"Eftersom den kan bilda dem själv genom fotosyntes.","ty":"v","src":"s. 244","id":"k13cw1dijh"},{"f":"Vad behöver en växt ta upp från omgivningen enligt boken?","b":"Vatten, koldioxid och solljus, och dessutom kväve, fosfor och andra mineraler (närsalter).","ty":"s","src":"s. 244","id":"k13c6ou7f6"},{"f":"Vilka tre uppgifter, förutom att få energi, måste en växt klara enligt boken?","b":"Lagra energi, transportera ämnen och reproducera sig.","ty":"s","src":"s. 244","id":"k13c1gbf6nv"},{"f":"Från vilka organismer härstammar alla växter?","b":"Från vattenlevande grönalger.","ty":"s","src":"s. 244","id":"k13c14d7gqj"},{"f":"Varför tar mossor inte upp vatten från marken?","b":"Eftersom de saknar både rötter och ledningsvävnad. De tar vatten och närsalter från vattnet som hamnar på bladen, t.ex. regn.","ty":"v","src":"s. 244","id":"k13c1jlf4iv"},{"f":"Vad är rhizoider?","b":"Rotliknande strukturer hos mossor. De har bara en förankrande funktion och kan inte suga upp vatten och närsalter.","ty":"b","src":"s. 244","id":"k13c1vdccjr"},{"f":"Varför klarar kärlväxter torka bättre än mossor?","b":"Eftersom de har rötter och en speciell vävnad för transport, och därför kan ta upp vatten och närsalter ur marken.","ty":"v","src":"s. 244","id":"k13c175tgnr"},{"f":"Vilka var de tidigaste kärlväxterna, och hur förökar de sig?","b":"Ormbunks- och lummerväxter. De förökar sig med sporer.","ty":"s","src":"s. 244","id":"k13covt1ll"},{"f":"Gömfröiga eller nakenfröiga: vilka är blommande växter och vilka är t.ex. barrträd?","b":"Gömfröiga = blommande växter. Nakenfröiga = t.ex. barrträd. Båda är fröbildande växter.","ty":"j","src":"s. 244","id":"k13c16svscr"},{"f":"Vad bildar celler med olika specialiseringar hos en växt?","b":"Olika typer av vävnader. Läraren: likadana celler bildar vävnad, och olika vävnader bildar tillsammans ett organ.","ty":"b","src":"s. 244 · PPT Bi2 bild 18","p":1,"id":"k13c1imlxiq"},{"f":"Generalist eller specialist: vad är skillnaden?","b":"Encelliga organismers celler är generalister som gör alla funktioner. Flercelliga organismers celler är specialister, vilket effektiviserar energin.","ty":"j","src":"PPT Bi2 bild 20","id":"k13c5m2qc3"},{"f":"Fälla: ormbunkar har rötter. Har de också frön?","b":"Nej. Ormbunks- och lummerväxter är kärlväxter men förökar sig med sporer.","ty":"f","src":"s. 244","id":"k13c11kz2e3"},{"f":"Vilka tre delar har växtcellen som djurcellen saknar?","b":"Cellvägg, stor vakuol och kloroplaster.","ty":"j","src":"s. 244 · PPT Bi2 bild 25","p":1,"id":"k13c7o824p"},{"f":"Vilka två delar saknar växtcellen som djurcellen har?","b":"Lysosomer och centrioler.","ty":"j","src":"s. 244 · PPT Bi2 bild 21","p":1,"id":"k13c16vpmgr"},{"f":"Har växtceller mitokondrier?","b":"Ja. Kloroplasten ersätter inte mitokondrien, och båda finns i bokens och lärarens bilder av växtcellen.","ty":"f","src":"s. 245 · PPT Bi2 bild 23–25","p":1,"id":"k13c1k40foz"},{"f":"Vilka tre etiketter hör till kärnan i bokens bild av växtcellen?","b":"Kärna, kärnmembran och DNA.","ty":"i","src":"s. 245","id":"k13c1vuuzoe"},{"f":"Vilka två sorters ER finns i bokens bild av växtcellen?","b":"ER (utan ribosomer) och ER med ribosomer.","ty":"i","src":"s. 245","id":"k13c3nymxl"},{"f":"Vad menar läraren med cellsaftrum?","b":"Vakuolen, en vätskefylld blåsa.","ty":"b","src":"PPT Bi2 bild 25","id":"k13c1p6f14q"},{"f":"Vad kallar läraren cytoplasman?","b":"Cellplasma. Den innehåller specialiserade celldelar och mycket vatten.","ty":"b","src":"PPT Bi2 bild 22, 25","id":"k13c19elzdr"},{"f":"Vilket är växtcellens yttersta lager?","b":"Cellväggen. Cellmembranet ligger innanför cellväggen.","ty":"f","src":"s. 245","id":"k13cjnp302"},{"f":"Är växtcellen eukaryot eller prokaryot?","b":"Eukaryot, eftersom den har en cellkärna.","ty":"b","src":"PPT Bi2 bild 20, 26","id":"k13c1x4cu0m"},{"f":"Vad består växtens cellvägg av?","b":"Cellulosa. Cellväggen är växtcellens extracellulära matrix.","ty":"b","src":"s. 244 · PPT Bi2 bild 7, 25","p":1,"t":["vagg"],"id":"k13cwh4box"},{"f":"Nämn cellväggens tre uppgifter enligt boken.","b":"Ger cellen form och skydd. Ger växten stadga så att den kan stå upprätt, eftersom väggarna hänger ihop i ett nätverk. Hindrar cellen från att spricka när den tar upp vatten.","ty":"s","src":"s. 244–245","t":["vagg"],"id":"k13czfvlvt"},{"f":"Varför spricker inte en växtcell i destillerat vatten?","b":"Eftersom cellväggen hindrar cellen från att spricka när den tar upp vatten. En djurcell skulle spricka.","ty":"v","src":"s. 245","t":["osmos","vagg"],"id":"k13c14vht5n"},{"f":"Hur är cellväggen uppbyggd?","b":"Cellulosafibriller bildar tillsammans tjockare fibrer, som är inbäddade i en matrix av andra polysackarider och proteiner.","ty":"b","src":"s. 245","t":["vagg"],"id":"k13c1xae9kc"},{"f":"Vad är plasmodesmata?","b":"Cellmembranklädda kanaler fyllda med cytoplasma i cellväggen. Genom dem kan cellerna kommunicera och ämnen föras från cell till cell.","ty":"b","src":"s. 245","t":["vagg","membran"],"id":"k13c143680g"},{"f":"Varför ger cellväggarna stadga åt hela växten?","b":"Eftersom cellväggarna hänger ihop och bildar ett nätverk med \"hål\" för varje cell.","ty":"v","src":"s. 244–245","t":["vagg"],"id":"k13c1mvc18r"},{"f":"Vilken sorts kolhydrat är cellulosa?","b":"En polysackarid, många sockerringar i en kedja. Stärkelse är också en polysackarid.","ty":"b","src":"PPT Bi2 bild 7","id":"k13c1bzko54"},{"f":"Varför kallas cellulosa kostfiber?","b":"Eftersom människan inte kan bryta ner den. Den är ändå nyttig, eftersom den motverkar förstoppning och ger mättnadskänsla.","ty":"v","src":"PPT Bi2 bild 7","id":"k13c1iwewd8"},{"f":"Cellulosa eller peptidoglykan: vilken vägg har växten och vilken har bakterien?","b":"Växten har cellulosa. Bakterien har peptidoglykan (s. 213 stavar peptidoglukan). Djurceller har ingen cellvägg.","ty":"j","src":"s. 244 · s. 180","t":["vagg"],"id":"k13c1s0indx"},{"f":"Är plasmodesmata tomma hål i cellväggen?","b":"Nej. De är kanaler klädda med cellmembran och fyllda med cytoplasma.","ty":"f","src":"s. 245","t":["vagg"],"id":"k13cw63lki"},{"f":"Cellvägg eller cellmembran: vad gör vad i växtcellen?","b":"Cellväggen (cellulosa) ligger ytterst och ger form, skydd och stadga. Cellmembranet ligger innanför och släpper in och ut vissa ämnen.","ty":"j","src":"s. 244–245 · PPT Bi2 bild 25","t":["vagg","membran"],"id":"k13c1j81sz3"},{"f":"Hur stor del av växtcellens volym kan vakuolen uppta?","b":"Upp till 90 %.","ty":"s","src":"s. 245","p":1,"id":"k13c901b4v"},{"f":"Hur bildas den stora vakuolen?","b":"Hos äldre celler, genom att många små vakuoler smälter samman.","ty":"b","src":"s. 245","id":"k13ckvie3d"},{"f":"Vad är fördelen med en stor vakuol?","b":"Cellen kan öka i storlek utan att behöva öka mängden cytoplasma särskilt mycket.","ty":"v","src":"s. 245","id":"k13c1x5f0o"},{"f":"Vad innehåller vakuolen?","b":"En vattenlösning med många lösta joner, och enzymer som kan spjälka makromolekyler.","ty":"s","src":"s. 245–246","id":"k13c1jxf2lg"},{"f":"Varför säger man att vakuolen gör lysosomens jobb?","b":"Eftersom den innehåller enzymer som kan spjälka makromolekyler. Växtcellen saknar lysosomer.","ty":"v","src":"s. 246","id":"k13c18hys7i"},{"f":"Vad är turgor?","b":"Trycket mot cellväggarna, som vakuolen hjälper cellen att upprätthålla.","ty":"b","src":"s. 246 · PPT Bi2 bild 25","p":1,"t":["osmos"],"id":"k13c1n94fqc"},{"f":"Hur kan en växt stå upprätt utan skelett och muskler?","b":"Tack vare turgor. Vakuolen anpassar sin storlek så att cellen fyller hela utrymmet i cellväggen och trycker mot den.","ty":"v","src":"s. 246 · PPT Bi2 bild 25","p":1,"id":"k13c87vwl8"},{"f":"Varför slokar en växt vid vattenbrist?","b":"Eftersom vakuolen inte innehåller tillräckligt mycket vatten, och därför minskar turgor.","ty":"v","src":"s. 246","p":1,"id":"k13c1sg5clx"},{"f":"Vad är bildtexten till bokens foto av slokande tulpaner?","b":"\"Tomma vakuoler.\"","ty":"i","src":"s. 246","id":"k13csw968k"},{"f":"Har djurceller vakuoler?","b":"De kan ha det, men de är inte lika stora som hos växter och fyller andra funktioner.","ty":"f","src":"s. 245","id":"k13c1ikiphc"},{"f":"Boken eller läraren: har växten ett skelett?","b":"Boken: växten saknar skelett och muskler och står upprätt tack vare turgor. Läraren: vakuolen utgör tillsammans med cellväggarna \"växternas skelett\" (bildligt).","ty":"j","src":"s. 246 · PPT Bi2 bild 25","id":"k13cb5z3w2"},{"f":"Röd blodkropp eller växtcell i destillerat vatten: vad händer?","b":"Båda tar upp vatten genom osmos. Blodkroppen sväller och kan spricka. Växtcellen spricker inte, eftersom cellväggen håller emot.","ty":"j","src":"s. 33 · s. 245","t":["osmos","vagg"],"id":"k13chbdjjf"},{"f":"Vad betyder hypoton lösning, och vad händer med en växtcell i en sådan?","b":"Låg halt av lösta ämnen, t.ex. destillerat vatten. Vatten går in i cellen, men cellväggen hindrar den från att spricka.","ty":"b","src":"s. 33 · s. 245","t":["osmos"],"id":"k13c188n07e"},{"f":"Vad är plastider?","b":"En grupp organeller som bara finns i celler hos växter och alger, t.ex. kloroplaster, leukoplaster och kromoplaster.","ty":"b","src":"s. 246–247","id":"k13cvm8nxd"},{"f":"Var i växten finns kloroplaster?","b":"I alla celler i växtens (eller algens) gröna delar.","ty":"s","src":"s. 246–247","id":"k13c1oboa8r"},{"f":"Vad gör kloroplasten?","b":"Den innehåller klorofyll som gör att växterna kan utnyttja ljusenergi från solen (fotosyntes). Kloroplaster finns hos växter och alger.","ty":"b","src":"s. 246–247 · PPT Bi2 bild 25","p":1,"id":"k13c1s9z5am"},{"f":"Vad är tylakoider?","b":"Platta membranblåsor i packar innanför kloroplastens två membran. Inuti dem finns klorofyllet.","ty":"b","src":"s. 247","t":["membran"],"id":"k13c1auy9p3"},{"f":"Vad är ett granum?","b":"En packe tylakoider.","ty":"b","src":"s. 247","id":"k13c1z11eg4"},{"f":"Vad är stroma?","b":"Vattenlösningen runt tylakoiderna. Den innehåller en ringformad DNA-molekyl, ribosomer och enzymer och kan jämföras med mitokondriens matrix.","ty":"b","src":"s. 247","t":["endo"],"id":"k13c1wapmvh"},{"f":"Varför ser växter gröna ut?","b":"Eftersom klorofyllet absorberar violett, blått och rött ljus men reflekterar grönt ljus.","ty":"v","src":"s. 247","id":"k13c11dd0el"},{"f":"Varför tror man att kloroplasten uppkom genom endosymbios?","b":"Eftersom den liksom mitokondrien har dubbla membran, en egen ringformad DNA-molekyl och ribosomer, och kan dela sig själv.","ty":"v","src":"s. 247","t":["endo"],"id":"k13c1ail1v7"},{"f":"Hur sköter kloroplasterna sin egen reproduktion?","b":"Deras DNA kan replikeras, och kloroplasterna kan dela sig.","ty":"v","src":"s. 247","t":["endo"],"id":"k13cmyth7k"},{"f":"Hur kan kloroplasterna flytta mot ljuset?","b":"De transporteras med hjälp av mikrotubuli till den del av cellen som träffas av mest ljus. Det syns i ett vanligt ljusmikroskop.","ty":"v","src":"s. 247","id":"k13c3bt7dz"},{"f":"Vad är leukoplaster?","b":"Färglösa plastider som lagrar stärkelse, framför allt i delar som lagrar energi, t.ex. potatisens stamknölar.","ty":"b","src":"s. 247 · PPT Bi2 bild 7","p":1,"id":"k13cq1u69a"},{"f":"Vad är kromoplaster?","b":"Plastider med pigment som ger blommor och frukter, och även rötter och blad, orange eller röd färg.","ty":"b","src":"s. 247","id":"k13cz471fo"},{"f":"Stroma eller matrix: vad är skillnaden?","b":"Stroma är vätskan i kloroplasten, matrix är vätskan i mitokondrien. Båda innehåller ringformat DNA, ribosomer och enzymer.","ty":"j","src":"s. 247 · s. 27","t":["endo"],"id":"k13czg7zl"},{"f":"Var sitter klorofyllet, i stroma eller i tylakoiderna?","b":"Inuti tylakoiderna.","ty":"f","src":"s. 247","id":"k13c16wukog"},{"f":"Absorberas grönt ljus av klorofyllet?","b":"Nej, grönt ljus reflekteras. Violett, blått och rött absorberas.","ty":"f","src":"s. 247","id":"k13czbzriz"},{"f":"Vilka sex etiketter har bokens bild av kloroplasten?","b":"Kloroplast, innermembran, yttermembran, granum, stroma och tylakoid. Bildtext: \"I kloroplastens tylakoider fångas ljusenergi in.\"","ty":"i","src":"s. 247","id":"k13c8rdu87"},{"f":"Kloroplast eller mitokondrie: vem gör vad?","b":"Kloroplasten fångar in solljus (fotosyntes) och finns bara hos växter och alger. Mitokondrien är kraftverket där energirik näring förbränns (cellandningen). Växtceller har båda.","ty":"j","src":"s. 247 · PPT Bi2 bild 25","t":["atp","endo"],"id":"k13czohzgw"},{"f":"Vad är cellandning enligt läraren?","b":"Att energirik näring förbränns i mitokondrien, cellens kraftverk.","ty":"b","src":"PPT Bi2 bild 22, 25","t":["atp"],"id":"k13c18xaarj"},{"f":"Var lagras stärkelsen i en potatis?","b":"I leukoplaster i potatisens stamknölar. Läraren: stärkelse är ett av våra viktigaste näringsämnen och finns t.ex. i potatis.","ty":"s","src":"s. 247 · PPT Bi2 bild 7","p":1,"id":"k13c1mbrire"},{"f":"Var på bokens bild av växtcellen pekar etiketten \"ER med ribosomer\"?","b":"På det prickiga membranet runt kärnan. Prickarna är ribosomer.","ty":"i","src":"s. 245","id":"k13c1xqps1o"},{"f":"Var finns plastider, och var finns de inte?","b":"Bara i celler hos växter och alger. Djurceller har inga plastider.","ty":"f","src":"s. 246","id":"k13c1kq4bn"}],"quiz":{"f":[{"q":"Vad betyder det att växten är fotoautotrof?","o":["Den kan skapa organiska föreningar med hjälp av solljus och koldioxid","Den måste äta andra organismer för att få energi","Den tar upp all sin näring genom rötterna","Den kan leva helt utan vatten"],"why":"Fotoautotrof = skapar organiska föreningar med solljus och koldioxid. Den behöver ändå vatten och närsalter.","src":"s. 244","id":"k13q1m5csgx"},{"q":"Vilka ämnen kallas tillsammans för närsalter?","o":["Kväve, fosfor och andra mineraler","Vatten och koldioxid","Glukos och stärkelse","Klorofyll och andra pigment"],"why":"Närsalter är mineraler som kväve och fosfor. Vatten och koldioxid nämns separat i boken.","src":"s. 244 · PPT Bi2 bild 3","id":"k13q1c8ggcv"},{"q":"Vad har mossor för att fästa sig i marken?","o":["Rhizoider","Rötter","Plasmodesmata","Ledningsvävnad"],"why":"Mossor saknar rötter. Rhizoiderna ser ut som rötter men förankrar bara.","src":"s. 244","id":"k13qyt06x6"},{"q":"Hur förökar sig ormbunks- och lummerväxter?","o":["Med sporer","Med frön","Med blommor","Bara genom delning"],"why":"De tidigaste kärlväxterna förökar sig med sporer. Frön har först de fröbildande växterna.","src":"s. 244","id":"k13quu6ljr"},{"q":"Vilka växter är nakenfröiga enligt boken?","o":["Barrträd","Mossor","Ormbunkar","Blommande växter"],"why":"Nakenfröiga = t.ex. barrträd. Blommande växter är gömfröiga.","src":"s. 244","id":"k13q1xbqlko"},{"q":"Vad har kärlväxter som mossor saknar?","o":["Rötter och ledningsvävnad","Klorofyll","Cellväggar","Kloroplaster"],"why":"Mossor saknar rötter och ledningsvävnad. Klorofyll, cellväggar och kloroplaster har båda.","src":"s. 244","id":"k13q1rn74os"},{"q":"Vilka tre delar har växtcellen men inte djurcellen?","o":["Cellvägg, stor vakuol och kloroplaster","Cellvägg, mitokondrier och lysosomer","Kloroplaster, centrioler och ribosomer","Cellmembran, cellkärna och vakuol"],"why":"Bokens svar på s. 244. Mitokondrier, ribosomer och cellmembran har båda celltyperna.","src":"s. 244","id":"k13ql2b2ww"},{"q":"Vilka två delar saknar växtcellen enligt boken?","o":["Lysosomer och centrioler","Mitokondrier och ribosomer","Golgiapparat och ER","Cellmembran och cellkärna"],"why":"Växtcellen saknar lysosomer och centrioler. Vakuolen gör ungefär lysosomens jobb.","src":"s. 244","id":"k13qzhk3lx"},{"q":"Vad består växtens cellvägg av?","o":["Cellulosa","Peptidoglykan","Stärkelse","Kollagen"],"why":"Cellulosa. Peptidoglykan finns i bakteriers väggar, och kollagen finns i djurcellers extracellulära matrix.","src":"s. 244 · PPT Bi2 bild 25","t":["vagg"],"id":"k13qwh4box"},{"q":"Vad kallas kanalerna genom cellväggen som förbinder grannceller?","o":["Plasmodesmata","Tylakoider","Aquaporiner","Rhizoider"],"why":"Plasmodesmata är cellmembranklädda kanaler fyllda med cytoplasma. Aquaporiner är vattenkanaler i membranet.","src":"s. 245","t":["vagg"],"id":"k13q7wvxhr"},{"q":"Vad är cellulosafibrerna inbäddade i?","o":["En matrix av andra polysackarider och proteiner","Ett dubbelt lager av fosfolipider","Stroma","Cytoplasma"],"why":"Boken: fibrerna är inbäddade i en matrix av andra polysackarider och proteiner.","src":"s. 245","t":["vagg"],"id":"k13qed8bm0"},{"q":"Hur stor del av cellens volym kan växtcellens vakuol uppta?","o":["Upp till 90 %","Upp till 10 %","Ungefär 50 %","Exakt 100 %"],"why":"Upp till 90 %.","src":"s. 245","id":"k13qvkxwkm"},{"q":"Vad kallas trycket mot cellväggarna som gör att växten kan stå upprätt?","o":["Turgor","Osmos","Diffusion","Fotosyntes"],"why":"Turgor är trycket mot cellväggarna. Osmos är vattnets diffusion över ett membran.","src":"s. 246","t":["osmos"],"id":"k13q12xh3hm"},{"q":"Vad står det under bokens bild av slokande tulpaner?","o":["\"Tomma vakuoler.\"","\"Fulla vakuoler.\"","\"Trasiga cellväggar.\"","\"För lite ljus.\""],"why":"Tulpanerna slokar eftersom vakuolerna inte har tillräckligt med vatten.","src":"s. 246","id":"k13q1gnxhi"},{"q":"Vilket ord använder läraren för vakuolen?","o":["Cellsaftrum","Cellplasma","Kraftverk","Stroma"],"why":"Bi2 bild 25: vakuol = en vätskefylld blåsa (cellsaftrum). Cellplasma är cytoplasman.","src":"PPT Bi2 bild 25","id":"k13qx6e4uv"},{"q":"Vad kallas en packe tylakoider?","o":["Ett granum","Stroma","En leukoplast","En vakuol"],"why":"Varje packe tylakoider kallas ett granum. Stroma är vätskan runt omkring.","src":"s. 247","id":"k13q4eobi6"},{"q":"Vad finns i kloroplastens stroma?","o":["En ringformad DNA-molekyl, ribosomer och enzymer","Klorofyllmolekylerna","Stärkelse och röda pigment","Kärnmembran och nukleol"],"why":"Klorofyllet sitter i tylakoiderna. Stroma har DNA, ribosomer och enzymer, precis som mitokondriens matrix.","src":"s. 247","t":["endo"],"id":"k13q16k0oox"},{"q":"Vilka färger av ljus absorberar klorofyllet?","o":["Violett, blått och rött","Bara grönt","Grönt och gult","Alla färger lika mycket"],"why":"Violett, blått och rött absorberas, grönt reflekteras.","src":"s. 247","id":"k13q11i2pci"},{"q":"Vad lagrar leukoplasterna?","o":["Stärkelse","Klorofyll","Pigment som ger röd färg","Cellulosa"],"why":"Leukoplaster är färglösa och lagrar stärkelse, t.ex. i potatisens stamknölar.","src":"s. 247","id":"k13q1at4rxu"},{"q":"Vad gör kromoplasterna?","o":["Ger blommor och frukter orange eller röd färg","Ger bladen grön färg","Ger stadga åt cellväggen","Förbränner energirik näring"],"why":"Kromoplaster innehåller pigment som ger orange eller röd färg.","src":"s. 247","id":"k13q6v22ak"},{"q":"Med hjälp av vad flyttas kloroplasterna mot ljuset?","o":["Mikrotubuli","Plasmodesmata","Vakuolen","Cellväggen"],"why":"Kloroplasterna transporteras med mikrotubuli, som många andra organeller.","src":"s. 247","id":"k13qyfi5yj"},{"q":"I vilka organismer finns plastider?","o":["Bara hos växter och alger","Hos alla eukaryoter","Hos bakterier och arkéer","Bara hos djur"],"why":"Plastider finns bara i celler hos växter och alger.","src":"s. 246","id":"k13ql76sxr"}],"u":[{"q":"En växtcell och en röd blodkropp läggs i destillerat vatten. Vad händer?","o":["Båda tar upp vatten, men bara blodkroppen kan spricka, eftersom växtcellen har en cellvägg","Båda spricker, eftersom vatten går in genom osmos","Ingen tar upp vatten, eftersom destillerat vatten saknar lösta ämnen","Växtcellen spricker men inte blodkroppen, eftersom vakuolen sväller"],"why":"Destillerat vatten är hypotont, så vatten går in i båda. Cellväggen hindrar växtcellen från att spricka (s. 245). Blodkroppen sväller och kan spricka (s. 33).","src":"s. 33 · s. 245","t":["osmos","vagg"],"id":"k13q1s6kt90"},{"q":"En krukväxt har inte vattnats på två veckor och bladen hänger. Varför?","o":["Vakuolerna innehåller för lite vatten, så turgor mot cellväggarna minskar","Cellväggarna har gått sönder","Kloroplasterna har slutat fånga ljus","Cellerna har fått fler lysosomer"],"why":"Vid vattenbrist innehåller vakuolen inte tillräckligt mycket vatten, och därför slokar växten.","src":"s. 246","id":"k13qz6na6b"},{"q":"Varför kan en växtcell bli större utan att tillverka särskilt mycket mer cytoplasma?","o":["Den stora vakuolen tar upp det mesta av volymen","Cellväggen tänjs ut av sig själv","Kloroplasterna delar sig och fyller cellen","Cytoplasman späds ut med vatten utan gräns"],"why":"Den stora vakuolen kan uppta upp till 90 % av volymen.","src":"s. 245","id":"k13q1kc4yv6"},{"q":"Växtcellen saknar lysosomer. Hur bryter den ändå ner makromolekyler?","o":["Vakuolen innehåller enzymer som kan spjälka makromolekyler","Kloroplasterna bryter ner dem i stroma","Cellväggen bryter ner dem","Den kan inte bryta ner makromolekyler alls"],"why":"Vakuolens enzymer gör att den fyller ungefär samma funktion som djurcellens lysosomer.","src":"s. 246","id":"k13q40leqk"},{"q":"En elev säger: \"Växtceller behöver inga mitokondrier, eftersom de har kloroplaster.\" Vad är fel?","o":["Växtceller har mitokondrier också, och kloroplasten ersätter dem inte","Inget, kloroplasten är växtens enda kraftverk","Mitokondrierna finns bara i rötterna","Mitokondrier finns bara i de gröna delarna"],"why":"Båda organellerna finns i bokens och lärarens bilder av växtcellen. Mitokondrien är kraftverket där energirik näring förbränns.","src":"s. 245 · PPT Bi2 bild 23–25","t":["atp"],"id":"k13q18ki7i4"},{"q":"Vad visar att kloroplasten och mitokondrien liknar varandra?","o":["Båda har dubbla membran och en ringformad DNA-molekyl, ribosomer och enzymer i sin vätska","Båda innehåller klorofyll","Båda finns bara hos växter","Båda bildas i golgiapparaten"],"why":"Likheterna är skälet till att man tror att båda uppkom genom endosymbios.","src":"s. 247","t":["endo"],"id":"k13q1u1ulp8"},{"q":"Varför uppfattar vi bladen som gröna?","o":["Grönt ljus reflekteras i stället för att absorberas","Grönt ljus absorberas mest av klorofyllet","Stroma är grönt","Cellväggen av cellulosa är grön"],"why":"Klorofyllet absorberar violett, blått och rött. Det gröna ljuset studsar tillbaka till ögat.","src":"s. 247","id":"k13q1k11ca0"},{"q":"Vilka plastider finns framför allt i potatisens stamknölar, och varför?","o":["Leukoplaster, eftersom knölen lagrar energi i form av stärkelse","Kloroplaster, eftersom knölen gör fotosyntes","Kromoplaster, eftersom knölen ska vara färgad","Inga plastider, eftersom knölen inte är grön"],"why":"Leukoplaster finns framför allt i delar som lagrar energi. Kloroplaster finns i de gröna delarna.","src":"s. 247 · PPT Bi2 bild 7","id":"k13q9irfmf"},{"q":"Varför tar mossor vatten från bladen och inte från marken?","o":["De saknar rötter och ledningsvävnad, och rhizoiderna kan inte suga upp vatten","Rhizoiderna suger upp för mycket vatten","Marken innehåller inga närsalter","Mossor behöver inget vatten"],"why":"Utan rötter och ledningsvävnad kan mossan inte ta upp vatten ur marken.","src":"s. 244","id":"k13q1yvnmsn"},{"q":"Ett blad belyses bara från vänster. Vad händer med kloroplasterna?","o":["De transporteras längs mikrotubuli till den del av cellen som får mest ljus","De delar sig tills hela cellen är full","De stannar där de är, eftersom de sitter fast i cellväggen","De flyttar till den mörka sidan för att skydda sig"],"why":"Kloroplasterna kan förflyttas till den del av cellen som träffas av mest ljus.","src":"s. 247","id":"k13qdem607"},{"q":"Varför har penicillin inget väggbygge att stoppa i dina egna celler?","o":["Djurceller har ingen cellvägg, och penicillin slår mot bakteriens bygge av peptidoglykan","Dina celler har cellväggar av cellulosa som penicillin inte når","Penicillin bryts ner av vakuolen","Dina cellväggar är för tjocka"],"why":"Djurceller saknar cellvägg. Penicillin blockerar ett enzym som bakterier behöver för att bygga sin vägg.","src":"s. 212–213 · s. 244","t":["vagg"],"id":"k13qe0i3vb"},{"q":"Hur kan ämnen ta sig från en växtcell till grannen trots cellväggen?","o":["Genom plasmodesmata, kanaler med cytoplasma som är klädda med cellmembran","Genom tomma hål i cellulosan","Genom att cellväggen löses upp","De kan inte det, eftersom cellerna är helt isolerade"],"why":"Plasmodesmata gör att cellerna kan kommunicera och föra över ämnen.","src":"s. 245","t":["vagg","membran"],"id":"k13q1u6n5oi"},{"q":"Vilket påstående stämmer med både boken och lärarens powerpoint?","o":["Kloroplasten innehåller klorofyll och finns hos växter och alger","Växten har ett skelett av vakuoler och cellväggar","Cellmembranet är växtcellens yttersta lager","Växtcellen saknar mitokondrier"],"why":"Kloroplasten står i både boken (s. 246–247) och Bi2 bild 25. \"Skelett\" är lärarens bildliga ord, och boken säger att växten saknar skelett.","src":"s. 246–247 · PPT Bi2 bild 25","id":"k13q178l3vx"},{"q":"Varför klarar ett barrträd torka bättre än en mossa?","o":["Det är en kärlväxt med rötter och transportvävnad som tar upp vatten ur marken","Det har rhizoider som suger upp vatten","Det saknar kloroplaster och behöver mindre vatten","Det är fotoautotroft, men det är inte mossan"],"why":"Kärlväxter har rötter och ledningsvävnad. Båda växterna är fotoautotrofa.","src":"s. 244","id":"k13qeoyxum"},{"q":"Hur kan turgor finnas kvar fast cellen behöver olika mycket cytoplasma vid olika tider?","o":["Vakuolen anpassar sin storlek så att cellen alltid fyller hela utrymmet i cellväggen","Cytoplasman trycker alltid lika hårt","Cellväggen drar ihop sig när vakuolen krymper","Kloroplasterna fyller tomrummet"],"why":"Boken s. 246: vakuolen anpassar sin storlek så att cellen fyller hela utrymmet som cellväggen tilldelar den.","src":"s. 246","id":"k13q12gs6b7"},{"q":"Varför hjälper stora vakuoler och sammanhängande cellväggar en växt utan skelett?","o":["Vakuolerna trycker mot väggarna (turgor) och väggarna bildar ett nätverk som ger stadga","Vakuolerna innehåller kalk som gör växten hård","Cellväggarna drar ihop sig som muskler","Plasmodesmata håller cellerna på plats"],"why":"Turgor och cellväggarnas nätverk gör att växten står upprätt. Det är därför läraren bildligt kallar dem växternas skelett.","src":"s. 245–246 · PPT Bi2 bild 25","id":"k13qf289ow"}],"o":[{"q":"Hur skiljer sig en växtcell från en djurcell? Svara på bokens egen fråga till bilden på s. 245.","model":"Växtcellen är i stort sett uppbyggd som djurcellen, men den har en cellvägg av cellulosa, en stor vakuol (upp till 90 % av volymen) och kloroplaster med klorofyll. Den saknar lysosomer och centrioler, och vakuolens enzymer gör ungefär lysosomens jobb. Båda har cellmembran, cytoplasma, kärna med kärnmembran och DNA, ribosomer, ER, golgiapparat och mitokondrier.","kw":[["cellvägg"],["vakuol"],["kloroplast"],["lysosom"],["centriol"],["mitokondri"]],"src":"s. 244–245","id":"k13of1papi"},{"q":"Förklara hur en växt kan stå upprätt utan skelett och muskler, och varför den slokar vid vattenbrist.","model":"Cellväggarna hänger ihop i ett nätverk och ger stadga. Vakuolen anpassar sin storlek så att cellen fyller hela utrymmet i cellväggen, och den trycker mot väggarna. Trycket kallas turgor, och det gör att växten kan stå upprätt. Vid vattenbrist innehåller vakuolen inte tillräckligt mycket vatten, turgor minskar och växten slokar.","kw":[["turgor"],["vakuol"],["cellvägg","vägg"],["tryck"],["nätverk","stadga"],["slokar","sloka"]],"src":"s. 244–246","t":["osmos"],"id":"k13o1snzdq1"},{"q":"Beskriv kloroplastens uppbyggnad och förklara varför man tror att den uppkom genom endosymbios.","model":"Kloroplasten är en plastid med dubbla membran. Innanför finns tylakoider, platta membranblåsor i packar som kallas granum, och inuti tylakoiderna sitter klorofyllet som fångar in solljus. Runt tylakoiderna finns stroma med en ringformad DNA-molekyl, ribosomer och enzymer. DNA:t kan replikeras och kloroplasten kan dela sig. Liksom mitokondrien har den alltså dubbla membran, eget ringformat DNA och ribosomer, och därför tror man att den uppkom genom endosymbios.","kw":[["dubbla","två membran"],["tylakoid"],["granum"],["stroma"],["klorofyll"],["dna"],["endosymbios"]],"src":"s. 246–247","t":["endo"],"id":"k13o1jz9v78"},{"q":"Jämför mossor och kärlväxter. Använd orden rhizoider, rötter och ledningsvävnad.","model":"Mossor är de enklast uppbyggda växterna och saknar både rötter och ledningsvävnad. Därför tar de vatten och närsalter från vattnet som hamnar på bladen, och de fäster sig med rhizoider som bara förankrar. Kärlväxter har rötter och en speciell vävnad för transport, så de kan ta upp vatten och närsalter ur marken och klarar torka bättre. De tidigaste kärlväxterna, ormbunks- och lummerväxter, förökar sig med sporer, och från dem kommer fröväxterna.","kw":[["rhizoid"],["rötter","rot"],["ledningsvävnad","transport"],["blad","regn"],["torka"],["spor"]],"src":"s. 244","id":"k13o12uiy0o"},{"q":"Vad händer med en röd blodkropp och en växtcell i destillerat vatten? Förklara med osmos.","model":"Destillerat vatten är en hypoton lösning med låg halt lösta ämnen, alltså högre vattenkoncentration än i cellen. Vatten diffunderar därför in i båda cellerna genom osmos, vattnets diffusion över ett semipermeabelt membran. Blodkroppen sväller och kan till slut spricka. Växtcellen spricker inte, eftersom cellväggen hindrar det, och trycket från vakuolen mot väggen blir turgor.","kw":[["osmos"],["hypoton"],["vattenkoncentration","lösta ämnen"],["spricka","sprick"],["cellvägg"],["turgor"]],"src":"s. 33 · s. 245–246","t":["osmos","vagg"],"id":"k13oif8l19"}]},"kan":[{"q":"Kan du förklara vad fotoautotrof betyder och vad en växt behöver från omgivningen?","a":"Fotoautotrof betyder att växten kan skapa organiska föreningar med hjälp av solljus och koldioxid, eftersom den kan utföra fotosyntes. Den bildar alltså sina energirika organiska molekyler själv. Den behöver ändå vatten, koldioxid och solljus, och dessutom kväve, fosfor och andra mineraler, som kallas närsalter. Den måste också kunna lagra energi, transportera ämnen och reproducera sig.","kw":[["fotoautotrof"],["solljus","ljus"],["koldioxid"],["vatten"],["närsalt"],["kväve","fosfor"]],"src":"s. 244","id":"k13k18j3aby"},{"q":"Kan du beskriva växtgrupperna från grönalger till fröväxter och säga vad som är nytt i varje steg?","a":"Alla växter härstammar från vattenlevande grönalger. Mossorna är enklast och saknar rötter och ledningsvävnad, så de tar vatten från bladen och fäster med rhizoider. Kärlväxterna har rötter och transportvävnad, och därför kan de ta vatten och närsalter ur marken och klarar torka bättre. De tidigaste kärlväxterna, ormbunks- och lummerväxter, förökar sig med sporer. Från dem har fröbildande växter utvecklats: gömfröiga (blommande) och nakenfröiga (t.ex. barrträd).","kw":[["grönalg"],["moss"],["rhizoid"],["kärlväxt"],["spor"],["gömfröig","nakenfröig","frö"]],"src":"s. 244","id":"k13kqikae7"},{"q":"Kan du säga vilka tre delar växtcellen har och vilka två den saknar jämfört med djurcellen?","a":"Växtcellen har en cellvägg av cellulosa, en stor vakuol och kloroplaster. Den saknar lysosomer och centrioler. Allt annat har båda, till exempel mitokondrier, ribosomer, ER, golgiapparat och kärna.","kw":[["cellvägg"],["vakuol"],["kloroplast"],["lysosom"],["centriol"]],"src":"s. 244–245","id":"k13k1kppx2c"},{"q":"Kan du beskriva cellväggens byggnad och tre uppgifter?","a":"Cellväggen är växtcellens extracellulära matrix av cellulosa. Cellulosafibriller bildar tjockare fibrer som är inbäddade i en matrix av andra polysackarider och proteiner. Den ger cellen form och skydd, ger stadga åt växten eftersom väggarna hänger ihop i ett nätverk, och hindrar cellen från att spricka när den tar upp vatten.","kw":[["cellulosa"],["fibrill","fiber"],["polysackarid","protein"],["form","skydd"],["stadga","upprätt"],["spricka","sprick"]],"src":"s. 244–245","id":"k13k7r100l"},{"q":"Kan du förklara vad plasmodesmata är och vad de gör?","a":"Plasmodesmata är kanaler i cellväggen som är klädda med cellmembran och fyllda med cytoplasma. Genom dem kan cellerna kommunicera med varandra, och ämnen kan föras över från cell till cell.","kw":[["kanal"],["cellmembran"],["cytoplasma"],["kommunic","från cell till cell","ämnen"]],"src":"s. 245","id":"k13k8evakh"},{"q":"Kan du förklara hur den stora vakuolen bildas och vad den innehåller?","a":"Den stora vakuolen bildas hos äldre celler genom att många små vakuoler smälter samman. Den kan uppta upp till 90 % av cellens volym, så cellen kan växa utan att behöva mycket mer cytoplasma. Den innehåller en vattenlösning med många lösta joner och enzymer som kan spjälka makromolekyler, och därför fyller den ungefär samma funktion som djurcellens lysosomer.","kw":[["äldre"],["smälter samman","små vakuoler"],["90"],["joner"],["enzym"],["lysosom"]],"src":"s. 245–246","id":"k13k1ysya8z"},{"q":"Kan du förklara vad turgor är och varför växten slokar vid vattenbrist?","a":"Vakuolen anpassar sin storlek så att cellen alltid fyller hela utrymmet som cellväggen ger den. Därför trycker den mot cellväggarna, och trycket kallas turgor. Turgor gör att växten kan stå upprätt trots att den saknar skelett och muskler. Vid vattenbrist innehåller vakuolen inte tillräckligt mycket vatten, och därför slokar växten.","kw":[["turgor"],["vakuol"],["tryck"],["cellvägg","vägg"],["skelett","upprätt"],["vattenbrist","för lite vatten","slokar"]],"src":"s. 246","id":"k13kc2b5hb"},{"q":"Kan du beskriva kloroplastens byggnad och förklara varför växter är gröna?","a":"Kloroplasten har dubbla membran. Innanför finns packar av platta membranblåsor, tylakoider, och varje packe kallas ett granum. Inuti tylakoiderna sitter klorofyllet, som fångar in solljus. Runt tylakoiderna finns stroma, med en ringformad DNA-molekyl, ribosomer och enzymer. Klorofyllet absorberar violett, blått och rött ljus men reflekterar grönt, och därför ser växter gröna ut.","kw":[["dubbla","två membran"],["tylakoid"],["granum"],["stroma"],["klorofyll"],["reflekter"]],"src":"s. 247","id":"k13k13g2oro"},{"q":"Kan du förklara varför man tror att kloroplasten uppkom genom endosymbios?","a":"Kloroplasten liknar mitokondrien. Den har dubbla membran, och i stroma finns en egen ringformad DNA-molekyl, ribosomer och enzymer. DNA:t kan replikeras och kloroplasten kan dela sig, så den sköter sin egen reproduktion. Därför tror man att den, precis som mitokondrien, uppkom genom endosymbios.","kw":[["dubbla","två membran"],["ringformad","dna"],["ribosom"],["dela sig","delar sig"],["mitokondri"],["endosymbios"]],"src":"s. 247","t":["endo"],"id":"k13kf8qbh1"},{"q":"Kan du skilja på kloroplaster, leukoplaster och kromoplaster?","a":"Alla tre är plastider, organeller som bara finns hos växter och alger. Kloroplaster innehåller klorofyll och finns i växtens gröna delar. Leukoplaster är färglösa och lagrar stärkelse, till exempel i potatisens stamknölar. Kromoplaster innehåller pigment som ger blommor och frukter, och även rötter och blad, orange eller röd färg.","kw":[["plastid"],["klorofyll"],["stärkelse"],["potatis"],["pigment","orange","röd"]],"src":"s. 246–247","id":"k13kv0mzmy"}],"kompis":[{"q":"Förklara för en kompis varför en växtcell inte spricker i destillerat vatten men en röd blodkropp gör det.","model":"Destillerat vatten är en hypoton lösning, med låg halt av lösta ämnen och alltså hög vattenkoncentration. Därför diffunderar vatten in i cellerna genom osmos. Den röda blodkroppen har bara ett cellmembran, så den sväller och kan till slut spricka. Växtcellen har en cellvägg av cellulosa utanför membranet. Vakuolen sväller och trycker mot väggen, men väggen håller emot, och därför spricker växtcellen inte. Trycket mot väggen kallas turgor.","kw":[["hypoton","destillerat"],["osmos"],["vatten in","tar upp vatten","in i"],["cellvägg"],["spricker","sprick"],["turgor"]],"src":"s. 33 · s. 245–246","t":["osmos","vagg"],"id":"k13e1gtlv8z"},{"q":"Förklara för en kompis hur en tulpan kan stå upprätt och varför den slokar när den inte får vatten.","model":"Växter har inget skelett och inga muskler. Varje cell har i stället en stor vakuol som kan fylla upp till 90 % av cellen. Vakuolen anpassar sin storlek så att cellen fyller hela utrymmet i cellväggen, och den trycker mot väggen. Trycket kallas turgor. Cellväggarna hänger ihop i ett nätverk och ger stadga, så hela tulpanen står upprätt. Får den inte vatten innehåller vakuolerna för lite vatten, turgor minskar och tulpanen slokar. Boken kallar bilden av slokande tulpaner \"Tomma vakuoler.\"","kw":[["vakuol"],["turgor"],["tryck"],["cellvägg","vägg"],["skelett","muskler"],["slokar","för lite vatten"]],"src":"s. 244–246","t":["osmos"],"id":"k13e1n9ojiv"},{"q":"Förklara för en kompis varför man tror att kloroplasten en gång var en egen organism.","model":"Kloroplasten liknar mitokondrien, som enligt endosymbiosteorin var en bakterie som slukades av den eukaryota cellens föregångare. Kloroplasten har som mitokondrien dubbla membran, och i stroma finns en egen ringformad DNA-molekyl, ribosomer och enzymer. Dessutom kan dess DNA replikeras och kloroplasten kan dela sig själv. Därför tror man att även kloroplasten uppkom genom endosymbios.","kw":[["endosymbios"],["mitokondri"],["dubbla","två membran"],["ringformad","dna"],["ribosom"],["dela"]],"src":"s. 247 · s. 27","t":["endo"],"id":"k13e1n1mlzk"}],"gloss":[{"w":"Fotoautotrof","d":"Kan skapa organiska föreningar med hjälp av solljus och koldioxid. Det som skiljer en växt från ett djur.","src":"Bok s. 244"},{"w":"Fotosyntes","d":"Processen där växten med ljusenergi bildar energirika organiska molekyler. Klorofyllet i kloroplasterna gör att växten kan utnyttja ljusenergin.","src":"Bok s. 244 · PPT Bi2 bild 25"},{"w":"Närsalter","d":"Kväve, fosfor och andra mineraler som växten tar upp från omgivningen.","src":"Bok s. 244"},{"w":"Mineralämnen","d":"Lärarens ord för närsalter, oorganiska ämnen som celler behöver.","src":"PPT Bi2 bild 3","lek":1},{"w":"Vävnad","d":"Celler med samma specialisering som bildar en enhet. Olika vävnader bildar tillsammans ett organ.","src":"Bok s. 244 · PPT Bi2 bild 18"},{"w":"Generalist och specialist","d":"Encelliga organismers celler gör alla funktioner (generalister). Flercelligas celler är specialiserade (specialister), vilket effektiviserar energin.","src":"PPT Bi2 bild 20","lek":1},{"w":"Grönalger","d":"Vattenlevande alger som alla växter härstammar från.","src":"Bok s. 244"},{"w":"Mossor","d":"De enklast uppbyggda växterna. Saknar rötter och ledningsvävnad och fäster sig med rhizoider.","src":"Bok s. 244"},{"w":"Rhizoider","d":"Rotliknande strukturer hos mossor. Har bara en förankrande funktion och kan inte suga upp vatten och närsalter.","src":"Bok s. 244"},{"w":"Ledningsvävnad","d":"Vävnad för transport av vatten och näringsämnen inne i växten. Saknas hos mossor.","src":"Bok s. 244"},{"w":"Kärlväxter","d":"Växter med rötter och en speciell vävnad för transport. Klarar torka bättre än mossor.","src":"Bok s. 244"},{"w":"Ormbunks- och lummerväxter","d":"De tidigaste kärlväxterna. Förökar sig med sporer.","src":"Bok s. 244"},{"w":"Fröbildande växter","d":"Kärlväxter som förökar sig med frön: gömfröiga och nakenfröiga.","src":"Bok s. 244"},{"w":"Gömfröiga växter","d":"Fröbildande växter som blommar.","src":"Bok s. 244"},{"w":"Nakenfröiga växter","d":"Fröbildande växter, till exempel barrträd.","src":"Bok s. 244"},{"w":"Eukaryot cell","d":"En cell med cellkärna, t.ex. växtceller och djurceller.","src":"PPT Bi2 bild 20, 26"},{"w":"Cellvägg","d":"Växtcellens extracellulära matrix av cellulosa utanför cellmembranet. Ger form, skydd och stadga och hindrar cellen från att spricka.","src":"Bok s. 244–245 · PPT Bi2 bild 25"},{"w":"Cellulosa","d":"Polysackarid som växtens cellvägg består av. Kan inte brytas ner av människan och är därför kostfiber.","src":"Bok s. 244 · PPT Bi2 bild 7"},{"w":"Extracellulär matrix","d":"Material utanför cellmembranet. Hos växter i form av cellväggen.","src":"Bok s. 244"},{"w":"Cellulosafibriller","d":"Trådar av cellulosa som tillsammans bildar tjockare fibrer i cellväggen.","src":"Bok s. 245"},{"w":"Plasmodesmata","d":"Cellmembranklädda kanaler fyllda med cytoplasma i cellväggen. Genom dem kan ämnen föras från cell till cell.","src":"Bok s. 245"},{"w":"Polysackarid","d":"Kolhydrat av många sockerringar, t.ex. cellulosa och stärkelse.","src":"PPT Bi2 bild 7","lek":1},{"w":"Kostfiber","d":"Ämnen som cellulosa som människan inte kan bryta ner. Motverkar förstoppning och ger mättnadskänsla.","src":"PPT Bi2 bild 7","lek":1},{"w":"Vakuol","d":"Stor vätskefylld blåsa i växtcellen, upp till 90 % av volymen. Innehåller joner och enzymer och ger turgor.","src":"Bok s. 245–246"},{"w":"Cellsaftrum","d":"Lärarens ord för vakuolen, en vätskefylld blåsa.","src":"PPT Bi2 bild 25","lek":1},{"w":"Cellplasma","d":"Lärarens ord för cytoplasman. Innehåller specialiserade celldelar samt mycket vatten.","src":"PPT Bi2 bild 22, 25","lek":1},{"w":"Cytoplasma","d":"Vätskan innanför cellmembranet, där organellerna ligger.","src":"Bok s. 245"},{"w":"Turgor","d":"Trycket mot cellväggarna som vakuolen hjälper cellen att upprätthålla. Gör att växten kan stå upprätt.","src":"Bok s. 246"},{"w":"Hypoton lösning","d":"Lösning med låg halt av lösta ämnen, t.ex. destillerat vatten. En växtcell i en sådan spricker inte, men en djurcell kan spricka.","src":"Bok s. 33, 245"},{"w":"Plasmolys","d":"När en växtcell förlorar vatten i en hyperton lösning och cellmembranet drar sig bort från cellväggen.","src":"Extra","extra":1},{"w":"Lysosom","d":"Djurcellens blåsa med nedbrytande enzymer. Saknas i växtcellen, där vakuolen gör ungefär samma jobb.","src":"Bok s. 244, 246"},{"w":"Centrioler","d":"Strukturer som finns i djurcellen men saknas i växtcellen.","src":"Bok s. 244"},{"w":"Plastider","d":"Grupp organeller som bara finns hos växter och alger: kloroplaster, leukoplaster och kromoplaster.","src":"Bok s. 246–247"},{"w":"Kloroplast","d":"Plastid med klorofyll och dubbla membran. Finns i växtens gröna delar och fångar in ljusenergi.","src":"Bok s. 246–247 · PPT Bi2 bild 25"},{"w":"Klorofyll","d":"Pigment i tylakoiderna som fångar in solljus. Absorberar violett, blått och rött, reflekterar grönt.","src":"Bok s. 247"},{"w":"Tylakoid","d":"Platt membranblåsa i kloroplasten. Inuti finns klorofyllet.","src":"Bok s. 247"},{"w":"Granum","d":"En packe tylakoider.","src":"Bok s. 247"},{"w":"Stroma","d":"Vattenlösningen runt tylakoiderna, med ringformat DNA, ribosomer och enzymer. Jämförs med mitokondriens matrix.","src":"Bok s. 247"},{"w":"Endosymbios","d":"Teorin att mitokondrien och kloroplasten en gång var fria organismer som togs upp av en annan cell och började leva i symbios med den.","src":"Bok s. 27, 247"},{"w":"Mikrotubuli","d":"Trådar i cellskelettet som kloroplasterna transporteras längs, mot den del av cellen som får mest ljus.","src":"Bok s. 247"},{"w":"Leukoplast","d":"Färglös plastid som lagrar stärkelse, t.ex. i potatisens stamknölar.","src":"Bok s. 247"},{"w":"Kromoplast","d":"Plastid med pigment som ger blommor och frukter (även rötter och blad) orange eller röd färg.","src":"Bok s. 247"},{"w":"Stärkelse","d":"Polysackarid som växten lagrar energi i, t.ex. i potatisens leukoplaster. Ett av våra viktigaste näringsämnen.","src":"Bok s. 247 · PPT Bi2 bild 7"},{"w":"Cellandning","d":"Lärarens ord för när energirik näring förbränns i mitokondrien.","src":"PPT Bi2 bild 22, 25","lek":1}],"snabb":{"keys":["Fotoautotrof :: skapar organiska föreningar med solljus och koldioxid","Närsalter :: kväve, fosfor och andra mineraler","Mossor :: inga rötter, ingen ledningsvävnad, vatten via bladen, rhizoider förankrar bara","Kärlväxter :: rötter + transportvävnad, klarar torka bättre; ormbunks- och lummerväxter har sporer","Fröväxter :: gömfröiga (blommande) och nakenfröiga (t.ex. barrträd)","Växtcellen har :: cellvägg, stor vakuol, kloroplaster","Växtcellen saknar :: lysosomer och centrioler","Cellväggen :: cellulosa; form, skydd, stadga; spricker inte i hypoton lösning","Cellväggens byggnad :: cellulosafibriller → fibrer → i matrix av polysackarider och proteiner","Plasmodesmata :: cellmembranklädda kanaler med cytoplasma mellan cellerna","Vakuolen :: upp till 90 %, bildas av små vakuoler i äldre celler, joner + enzymer (som lysosom)","Turgor :: vakuolens tryck mot cellväggarna, växten står upprätt","Kloroplasten :: dubbla membran, tylakoider i granum, stroma med ringformat DNA, ribosomer, enzymer","Klorofyll :: absorberar violett, blått, rött; reflekterar grönt","Leukoplast / kromoplast :: stärkelse (potatisens stamknölar) / orange-röd färg"],"nums":[["90 %","av växtcellens volym kan vakuolen uppta (s. 245)"],["3 + 2","växtcellen har tre delar som djurcellen saknar och saknar två som djurcellen har (s. 244)"],["13","etiketter i bokens bild av växtcellen (s. 245)"],["2","membran runt kloroplasten, liksom runt mitokondrien (s. 247)"],["3","färger som klorofyllet absorberar: violett, blått och rött (s. 247)"],["Grönalger","alla växter härstammar från dem (s. 244)"],["Ormbunks- och lummerväxter","de tidigaste kärlväxterna, sporer (s. 244)"],["Potatisens stamknölar","leukoplaster som lagrar stärkelse (s. 247)"],["\"Tomma vakuoler.\"","bildtexten till de slokande tulpanerna (s. 246)"],["Cellsaftrum","lärarens ord för vakuolen (Bi2 bild 25)"]],"chains":[["Vattenbrist","vakuolen har för lite vatten","turgor minskar","växten slokar"],["Hypoton lösning","vatten in i cellen","vakuolen sväller","cellväggen håller emot","cellen spricker inte"],["Många små vakuoler i äldre cell","smälter samman","stor vakuol (upp till 90 %)","cellen växer utan mycket mer cytoplasma"],["Vakuolen anpassar sin storlek","cellen fyller utrymmet i cellväggen","tryck mot väggarna (turgor)","växten står upprätt"],["Solljus","violett, blått och rött absorberas","grönt reflekteras","växten ser grön ut"],["Ljus från ett håll","kloroplasterna transporteras längs mikrotubuli","de samlas där ljuset är starkast"],["Mossor saknar rötter och ledningsvävnad","vatten tas från bladen","klarar torka sämre än kärlväxter"]],"traps":["Rhizoider förankrar bara. De suger inte upp vatten.","Växtcellen har mitokondrier också. Kloroplasten ersätter dem inte.","Cellmembranet ligger innanför cellväggen.","Klorofyllet sitter i tylakoiderna, inte i stroma.","Grönt ljus reflekteras, det absorberas inte.","Plasmodesmata är kanaler med cellmembran och cytoplasma, inte tomma hål.","Växten slokar för att vakuolen har för lite vatten, inte för att cellväggen går sönder.","Boken: växten saknar skelett. Läraren: vakuol + cellväggar = \"växternas skelett\" (bildligt)."]}}});
G.STOPS=[{"t":"vagg","ch":"k1","sec":"kolhydrater","h":"Cellulosa","html":"Växtcellens vägg är byggd av polysackariden cellulosa ({{go:k13.cellvaggen|K13}}). Bakteriernas vägg är byggd av något annat, peptidoglykan, alltså kolhydratkedjor korsbundna med peptider ({{go:k8.byggnad|K8}}). Svamparnas vägg innehåller kitin."},{"t":"membran","ch":"k1","sec":"lipider","h":"Fettsyrorna styr flytet","html":"Fettsyrornas form avgör hur flytande cellmembranet är: knyckiga omättade svansar ger ett lättflytande membran, raka mättade ett trögt ({{go:k3.uppbyggnad|K3}}). Kolesterolet hjälper djurcellens membran att hålla sig lagom flytande."},{"t":"membran","ch":"k1","sec":"fosfolipider","h":"Huvud ut, svans in","html":"Fosfolipidens hydrofila huvud och hydrofoba svans förklarar varför den bildar ett dubbelt lager i vatten ({{go:k3.uppbyggnad|K3}}). Samma dubbla lager omger organellerna ({{go:k4|K4}}) och bakterier ({{go:k8.byggnad|K8}}), och det gör att fettlösliga ämnen passerar fritt men inte joner ({{go:k5.genom|K5}})."},{"t":"ribosom","ch":"k1","sec":"proteiner","h":"Där proteinerna byggs","html":"Alla proteiner, från hemoglobin till enzymer, byggs på ribosomerna ({{go:k4.ribosomer|K4}}). Bakterier har också ribosomer, men av en annan sort, och det utnyttjar vissa antibiotika ({{go:k11|K11}})."},{"t":"atp","ch":"k1","sec":"nukleotider","h":"ATP är en nukleotid","html":"ATP byggs av samma delar som en RNA-nukleotid: kvävebasen adenin, sockret ribos och fosfatgrupper, men med tre fosfat i rad. Det är fabrikens mynt ({{go:k6|K6}}) och betalar bland annat natrium-kaliumpumpen ({{go:k5.pumpen|K5}})."},{"t":"endo","ch":"k2","sec":"celltyper","h":"Kraftverk som flyttat in","html":"Mitokondrien och kloroplasten har dubbla membran och eget, ringformat DNA. Man tror att de en gång var fritt levande prokaryoter som flyttade in i en eukaryot cell, endosymbios ({{go:k4.mitokondrien|K4}}, {{go:k13.kloroplasten|K13}})."},{"t":"membran","ch":"k2","sec":"djurcell","h":"Djurcellens enda skydd","html":"Djurcellen har ingen vägg, så cellmembranet är den enda gränsen mot omgivningen (bok s. 21). Hur membranet är byggt och vad det gör finns i {{go:k3|K3}}, och hur ämnen tar sig igenom i {{go:k5|K5}}."},{"t":"vagg","ch":"k2","sec":"vaxtcell","h":"Växtens mur","html":"Växtcellens vägg är av cellulosa ({{go:k1.kolhydrater|K1}}) och ligger utanför cellmembranet. Bakterier har också en vägg, men av peptidoglykan ({{go:k8.byggnad|K8}}), och det är den som penicillin slår mot ({{go:k11|K11}}). Djurceller saknar vägg."},{"t":"osmos","ch":"k2","sec":"vaxtcell","h":"Väggen stoppar sprickan","html":"I rent vatten strömmar vatten in i cellen genom osmos. En djurcell kan spricka ({{go:k5.osmos|K5}}), men växtcellens vägg tar emot trycket. Vakuolen blir full och ger turgor, så att växten står upprätt ({{go:k13.vakuolen|K13}})."},{"t":"membran","ch":"k3","sec":"funktion","h":"Samma gräns överallt","html":"Cellmembranet är ett dubbelskikt av fosfolipider med proteiner. Samma byggsätt finns i organellernas membran i {{go:k4.er|K4}}, i bakteriens cellmembran i {{go:k8.byggnad|K8}} och i alla transportprocesser i {{go:k5.genom|K5}}."},{"t":"atp","ch":"k3","sec":"proteiner","h":"Portar som kostar energi","html":"Boken säger att vissa transportproteiner kräver energi. Energin kommer från ATP, fabrikens mynt, som mest tillverkas i {{go:k4.mitokondrien|mitokondrien}}. Natrium-kaliumpumpen i {{go:k5.pumpen|K5}} är det stora exemplet."},{"t":"nyckel","ch":"k3","sec":"proteiner","h":"Receptorn är låset","html":"Signalmolekylen passar i receptorn som en nyckel i ett lås och låser upp en aktivitet i cellen. Samma bild återkommer när LDL binder till sin receptor innan den tas upp i {{go:k5.ldl|K5}}."},{"t":"vagg","ch":"k3","sec":"ecm","h":"Djurcellen saknar vägg","html":"Djurcellen har ingen cellvägg. Dess skydd är cellmembranet och den extracellulära matrixen av glykoproteiner. Växtcellen har en cellvägg av cellulosa ({{go:k13.cellvaggen|K13}}) och bakterier har en cellvägg av ett annat material ({{go:k8.byggnad|K8}})."},{"t":"vagg","ch":"k4","sec":"djurcellen","h":"Bara membranet skyddar","html":"Djurcellen saknar cellvägg. Den skyddas av cellmembranet och den extracellulära matrixen ({{go:k3.ecm|K3}}). Växtcellen har en cellvägg av cellulosa utanför membranet ({{go:k13.cellvaggen|K13}})."},{"t":"ribosom","ch":"k4","sec":"ribosomer","h":"Två sorters ribosomer","html":"Mitokondrien har egna ribosomer av samma typ som bakterier ({{go:k4.mitokondrien|nedan}}). Bakteriernas ribosomer finns i {{go:k8.byggnad|K8}}, och flera antibiotika slår just mot dem ({{go:k11.ribosom|K11}})."},{"t":"membran","ch":"k4","sec":"er","h":"Organellernas membran","html":"ER, golgiapparaten, lysosomerna och blåsorna har samma sorts fosfolipidmembran som cellmembranet ({{go:k3.uppbyggnad|K3}}). Därför kan blåsor smälta ihop med organeller och med cellmembranet."},{"t":"atp","ch":"k4","sec":"mitokondrien","h":"Kraftverket gör mynten","html":"Mitokondrien bildar det mesta av cellens ATP, fabrikens mynt. Vad ATP är och hur det används går {{go:k6.atp|K6}} igenom, och pumparna som kostar ATP finns i {{go:k5.pumpen|K5}}."},{"t":"endo","ch":"k4","sec":"mitokondrien","h":"Slukade bakterier","html":"Mitokondrien var en bakterie med ringformat DNA ({{go:k8.byggnad|K8}}). Växtcellens kloroplast har en liknande historia och har också eget DNA ({{go:k13.kloroplasten|K13}})."},{"t":"membran","ch":"k5","sec":"genom","h":"Fettet är spärren","html":"Membranets inre består av fosfolipidernas hydrofoba svansar ({{go:k1.fosfolipider|K1}}, {{go:k3.uppbyggnad|K3}}). Därför släpps fettlösliga ämnen igenom, medan joner och stora polära molekyler behöver proteiner eller vesiklar. Samma dubbla lager finns i organellernas membran ({{go:k4|K4}})."},{"t":"nyckel","ch":"k5","sec":"underlattad","h":"Bara rätt ämne","html":"Transportproteinerna är specifika. Ett bärarprotein binder bara sitt eget ämne, ungefär som ett lås som bara passar en nyckel. Samma princip gäller receptorerna i cellmembranet ({{go:k3.proteiner|K3}}) och LDL-receptorn ({{go:k5.ldl|LDL}})."},{"t":"osmos","ch":"k5","sec":"osmos","h":"Röd blodkropp utan skydd","html":"Den röda blodkroppen har bara sitt cellmembran, och därför kan den spricka i en hypoton lösning. Växtcellen har en cellvägg som tar emot trycket och får turgor i stället ({{go:k13.vakuolen|K13}})."},{"t":"osmos","ch":"k5","sec":"osmosfilm","h":"Hemolys eller turgor","html":"I samma hypotona lösning spricker den röda blodkroppen (hemolys), medan växtcellen bara blir turgid, eftersom cellväggen tar emot trycket. Cellväggen och vakuolen går du igenom i {{go:k13.vakuolen|K13}}."},{"t":"osmos","ch":"k5","sec":"osmosfilm","h":"Koksalt i droppet","html":"Fysiologisk koksaltlösning, 0,9 % NaCl, är isoton med blodplasman. Därför sväller eller krymper blodkropparna inte, medan rent vatten i blodet skulle ge hemolys. Samma princip, lika mycket löst ämne på båda sidor, gäller för alla celler i guiden."},{"t":"atp","ch":"k5","sec":"aktiv","h":"Gratis eller betalt","html":"Passiv transport kostar ingenting. Aktiv transport kostar energi, och fabrikens mynt är ATP ({{go:k6.atp|K6}}). Det mesta av ATP:t bildas i mitokondrierna, fabrikens kraftverk ({{go:k4.mitokondrien|K4}})."},{"t":"atp","ch":"k5","sec":"kopplad","h":"ATP i andra hand","html":"Kopplad transport använder ingen ATP direkt. Ändå stannar den utan ATP, eftersom natrium-kaliumpumpen måste hålla natriumgradienten uppe ({{go:k5.pumpen|pumpen}}). Hur cellen får sin ATP ser du i {{go:k6.kraftverk|K6}}."},{"t":"atp","ch":"k5","sec":"pumpen","h":"Den största ATP-kunden","html":"Natrium-kaliumpumpen använder ungefär 40 % av cellens ATP, eftersom den hela tiden måste hålla jonbalansen uppe. Fler ATP-förbrukare hittar du i {{go:k6.forbrukare|K6}}."},{"t":"atp","ch":"k5","sec":"spanning","h":"Spänningen kostar ATP","html":"Laddningsskillnaden och jongradienterna byggs upp av natrium-kaliumpumpen, som drivs av ATP. Därför går så mycket av cellens ATP till just den pumpen ({{go:k6.forbrukare|K6}})."},{"t":"membran","ch":"k5","sec":"endocytos","h":"Membranet flyter","html":"Armarna vid fagocytos kan smälta samman, eftersom cellmembranet är som en trögflytande vätska. I {{go:k3.uppbyggnad|K3}} kallas membranet en tvådimensionell vätska där fosfolipiderna glider runt varandra."},{"t":"endo","ch":"k5","sec":"endocytos","h":"En slukad bakterie","html":"Enligt endosymbiosteorin var mitokondrien en gång en bakterie som slukades av den eukaryota cellens föregångare. Mitokondriens yttre membran kommer från den slukande cellens cellmembran, på samma sätt som fagosomens membran kommer från cellmembranet ({{go:k4.mitokondrien|K4}})."},{"t":"nyckel","ch":"k5","sec":"ldl","h":"LDL-receptorn","html":"LDL passar i sin receptor som en nyckel i ett lås. Är låset felbyggt på grund av en felaktig gen tas LDL inte upp, och halten i blodet stiger. Receptorer som lås för kemiska nycklar mötte du i {{go:k3.proteiner|K3}}."},{"t":"membran","ch":"k5","sec":"exocytos","h":"Membranet byggs om hela tiden","html":"Vid exocytos blir vesikelns membran en del av cellmembranet, och vid endocytos blir en bit cellmembran en vesikel. Membranet flyttas alltså hela tiden, från ER via golgiapparaten till cellmembranet ({{go:k4.resan|proteinets resa i K4}})."},{"t":"atp","ch":"k5","sec":"aktivfilm","h":"Pumpen betalar med ATP","html":"Varje varv i natrium-kaliumpumpen kostar ett ATP. Fosfatgruppen från ATP binds till pumpen och får den att ändra form, och därför kan jonerna flyttas mot sina gradienter. Mer om ATP i {{go:k6.atp|K6}}."},{"t":"nyckel","ch":"k5","sec":"aktivfilm","h":"Adresslappar på vesiklar","html":"Vesikelns markör passar i receptorn på målmembranet som en nyckel i ett lås. Det är samma princip som när LDL binder till sin receptor ({{go:k5.ldl|LDL}}) och när coronaviruset binder till ACE2."},{"t":"atp","ch":"k5","sec":"aktivfilm","h":"Vesiklar kostar ATP","html":"Att bilda en vesikel, flytta den längs mikrotubuli med motorproteiner och smälta ihop den med membranet kostar ATP. Därför räknas endocytos och exocytos till aktiv transport. Järnvägen, cellskelettet, finns i {{go:k4.cellskelettet|K4}}."},{"t":"nyckel","ch":"k5","sec":"aktivfilm","h":"ACE2, virusets lås","html":"Coronaviruset kommer bara in i celler som har ACE2-receptorer, eftersom viruset passar i receptorn som en nyckel i ett lås. Fler virus som kapar celler finns i {{go:k10.virus|K10}}."},{"t":"atp","ch":"k6","sec":"atp","h":"Myntet i hela guiden","html":"ATP är en nukleotid ({{go:k1.nukleotider|K1}}) som bildas mest i mitokondrien ({{go:k4.mitokondrien|K4}}) och betalar för pumparna i membranet ({{go:k5.pumpen|K5}}). Varje gång ATP används blir det ADP, som måste laddas igen."},{"t":"atp","ch":"k6","sec":"kreatin","h":"Två sätt att ladda myntet","html":"ADP blir ATP igen antingen med energi från födan i mitokondrien eller snabbt med fosfatet från kreatinfosfat i musklerna. Mitokondrien står för det mesta ({{go:k4.mitokondrien|K4}})."},{"t":"membran","ch":"k6","sec":"kraftverk","h":"Ett membran som tillverkar","html":"I mitokondrien gör membranet mer än att avgränsa. Det inre membranet bär enzymerna i elektrontransportkedjan, och därför är det veckat för att få stor yta. Samma dubbla lager av fosfolipider finns i cellmembranet ({{go:k3.uppbyggnad|K3}})."},{"t":"endo","ch":"k6","sec":"kraftverk","h":"Kraftverket var en bakterie","html":"Mitokondriens inre membran kommer från bakteriens cellmembran och det yttre från cellen som slukade den ({{go:k4.mitokondrien|K4}}). Kloroplasten tros ha uppkommit på samma sätt ({{go:k13.kloroplasten|K13}}). Fabrikens kraftverk var alltså från början en egen liten verkstad."},{"t":"atp","ch":"k6","sec":"forbrukare","h":"Den största kunden","html":"Natrium-kaliumpumpen i cellmembranet tar ungefär 40 % av cellens ATP ({{go:k5.pumpen|K5}}). Därför måste kraftverket ({{go:k4.mitokondrien|K4}}) hela tiden ladda nya mynt."},{"t":"membran","ch":"k6","sec":"forbrukare","h":"Membranet kostar","html":"Cellmembranet håller jonbalansen med pumpar som drivs av ATP, och mitokondriens inre membran bildar ATP:t. Membranen är alltså både den största förbrukaren och tillverkaren ({{go:k5.pumpen|K5}})."},{"t":"endo","ch":"k7","sec":"alger","h":"Fotosyntesen kom från bakterier","html":"Läraren säger att alla algers förmåga till fotosyntes härstammar från cyanobakterierna. Boken säger att kloroplasten, precis som mitokondrien, tros ha uppkommit genom endosymbios ({{go:k13.kloroplasten|K13}}, {{go:k4.mitokondrien|K4}}). Båda pekar mot samma sak: eukaryota celler har fått viktiga förmågor från bakterier."},{"t":"ribosom","ch":"k8","sec":"byggnad","h":"Bakteriens arbetsbänkar","html":"Bakterien har ribosomer som utför proteinsyntes, precis som våra celler ({{go:k4.ribosomer|K4}}). Bakteriernas ribosomer skiljer sig ändå från våra, och därför kan vissa antibiotika slå ut dem ({{go:k11.ribosom|K11}})."},{"t":"plasmid","ch":"k8","sec":"byggnad","h":"Lösa receptkort","html":"Utöver kromosomen kan bakterien ha små extra DNA-ringar, plasmider, som syns i lärarens bilder. De bär gener som är bra att ha ibland, t.ex. för antibiotikaresistens. Mer i {{go:k9.plasmider|K9}} och {{go:k12.resistens|K12}}."},{"t":"vagg","ch":"k8","sec":"gram","h":"Bakteriens vägg av peptidoglykan","html":"Bakteriens cellvägg är av peptidoglykan, kolhydratkedjor korsbundna med peptider. Växtens cellvägg är av cellulosa ({{go:k13.cellvaggen|K13}}), och djurceller har ingen cellvägg ({{go:k3.ecm|K3}}). Penicillin stoppar bygget av peptidoglykan, och därför skadar det bakterier men inte oss ({{go:k11.verkan|K11}})."},{"t":"membran","ch":"k8","sec":"gram","h":"Två membran hos gramnegativa","html":"Innermembranet är ett vanligt cellmembran av fosfolipider, med ungefär samma kemi som hos eukaryoter ({{go:k3.uppbyggnad|K3}}). Gramnegativa har dessutom ett yttre membran där en del fosfolipider är utbytta mot LPS. Arkéernas membran har en annan kemi ({{go:k10.arkeer|K10}})."},{"t":"plasmid","ch":"k9","sec":"plasmider","h":"Plasmidens hem","html":"Här hör plasmiden hemma: en liten extra ring av DNA med få gener, ofta för resistens. I K9 ser du hur den kopieras, tappas och flyttas mellan bakterier. I {{go:k12.mordare|K12}} bär ESBL-bakterierna sin resistens på en plasmid."},{"t":"endo","ch":"k9","sec":"plasmider","h":"Ringformat DNA","html":"Bakteriens kromosom är cirkulär. Mitokondrien och kloroplasten har också eget ringformat DNA, och det är ett av bevisen för att de en gång var bakterier ({{go:k4.mitokondrien|K4}}, {{go:k13.kloroplasten|K13}})."},{"t":"ribosom","ch":"k10","sec":"system","h":"Ribosomen ordnar livets träd","html":"Ribosomen är arbetsbänken i varje cell ({{go:k4.ribosomer|K4}}). En av dess RNA-molekyler, 16S rRNA, används för att avgöra vilken släkt och familj en bakterie hör till. Bakteriens ribosom är också måltavla för flera antibiotika ({{go:k11.ribosom|K11}})."},{"t":"membran","ch":"k10","sec":"arkeer","h":"Arkéns tullgräns i annat material","html":"Alla celler har ett cellmembran av fosfolipider ({{go:k1.fosfolipider|K1}}, {{go:k3.uppbyggnad|K3}}). Hos arkéerna är fosfolipiderna kemiskt helt annorlunda än hos bakterier och eukaryoter. Det är bokens viktigaste skillnad mellan arkéer och bakterier."},{"t":"nyckel","ch":"k10","sec":"virus","h":"Virusets falska nyckel","html":"Virusets ytproteiner passar i cellens membranproteiner som en nyckel i ett lås, eller som hand i handske. Samma princip används när signalmolekyler binder till receptorer ({{go:k3.proteiner|K3}}) och när antibiotika binder till bakteriens enzym ({{go:k11.verkan|K11}})."},{"t":"membran","ch":"k10","sec":"herpes","h":"Viruset stjäl en bit membran","html":"Herpesviruset kommer in genom att dess membran smälter ihop med cellmembranet, och de nya virusen knoppas av inslagna i en bit av cellens membran. Det liknar endocytos och exocytos i {{go:k5.endocytos|K5}}, där membran smälter ihop och snörs av."},{"t":"plasmid","ch":"k10","sec":"herpes","h":"Främmande DNA i arvsmassan","html":"När herpesviruset sätter in sitt DNA i värdcellens DNA kopieras det med vid varje delning. På samma sätt fogas virus-DNA in i bakteriens kromosom vid transduktion, och gener flyttas mellan plasmid och kromosom med transposoner ({{go:k9.overforing|K9}}, {{go:k9.transposoner|K9}})."},{"t":"plasmid","ch":"k10","sec":"betydelse","h":"Horisontella gener","html":"Plasmider och virus gör samma sak på olika sätt: de flyttar gener horisontellt mellan individer. Hos bakterier sprids resistensgener så ({{go:k12.spridning|K12}}), och genom evolutionen har virus flyttat gener mellan helt olika arter."},{"t":"vagg","ch":"k11","sec":"verkan","h":"Penicillin och bakteriens vägg","html":"Penicillin slår mot bygget av bakteriens cellvägg av peptidoglukan. Djurceller saknar cellvägg ({{go:k2|K2}}), och växtens cellvägg är byggd av cellulosa ({{go:k13.cellvaggen|K13}})."},{"t":"nyckel","ch":"k11","sec":"verkan","h":"Antibiotika passar i bakteriens lås","html":"Penicillin binder till ett enzym och tetracykliner till ribosomen. Antibiotikan måste passa exakt i sitt mål, som en nyckel i ett lås. Ändrar bakterien låset passar nyckeln inte längre, och det är ett av sätten att bli resistent ({{go:k12.resistens|K12}})."},{"t":"ribosom","ch":"k11","sec":"ribosom","h":"Bakteriens arbetsbänk är annorlunda","html":"Ribosomen bygger proteiner i alla celler, men bakteriens ribosom skiljer sig från vår. Därför kan tetracykliner, makrolider och linkosamider stoppa just bakteriens arbetsbänk."},{"t":"endo","ch":"k11","sec":"ribosom","h":"Mitokondriens ribosomer","html":"I {{go:k4.mitokondrien|K4}} såg du att mitokondrien har ribosomer av samma typ som bakterier. Det är ett av bevisen för att mitokondrien en gång var en fri bakterie."},{"t":"membran","ch":"k11","sec":"ampicillin","h":"Det yttre membranet hos gramnegativa","html":"Gramnegativa bakterier har ett yttre membran utanför sin tunna cellvägg ({{go:k8.byggnad|K8}}). {{extra}} Det yttre membranet gör det svårare för vanligt penicillin att nå fram till cellväggen, och ampicillin tar sig lättare förbi."},{"t":"nyckel","ch":"k12","sec":"resistens","h":"Nytt lås, nyckeln passar inte","html":"Antibiotikan måste passa i sitt målprotein som en nyckel i ett lås ({{go:k11.verkan|K11}}). Är genen för målproteinet förändrad passar inte nyckeln, och bakterien är resistent. Så gör MRSA med enzymet som bygger cellväggen."},{"t":"membran","ch":"k12","sec":"resistens","h":"Utkastaren sitter i membranet","html":"Ett protein som transporterar ut antibiotikan måste sitta i bakteriens cellmembran, precis som pumparna i {{go:k5.aktiv|K5}} flyttar ämnen genom membranet."},{"t":"plasmid","ch":"k12","sec":"spridning","h":"Receptkortet lånas ut","html":"Resistensgener ligger i många fall på plasmider ({{go:k9.plasmider|K9}}). Vid konjugation lånas receptkortet ut till grannen, och mottagaren kan sedan själv låna ut det. Därför kan några få plasmidbärare snabbt göra en hel population resistent {{lek:Antibiotika bild 8}}."},{"t":"plasmid","ch":"k12","sec":"motverka","h":"Det lösa receptkortet tappas","html":"Plasmiden är verkstadens lösa receptkort ({{go:k9.plasmider|K9}}). Det kopieras inför delningen men delas inte ut ordentligt, så ibland tappas det. Utan antibiotika behövs kortet inte, och därför försvinner det långsamt ur populationen."},{"t":"vagg","ch":"k12","sec":"mordare","h":"MRSA byter lås på väggbygget","html":"Penicillin och andra cellväggsantibiotika blockerar enzymet som bygger bakteriens cellvägg ({{go:k11.verkan|K11}}). MRSA har en förändrad version av just det enzymet, så väggbygget fortsätter trots antibiotikan."},{"t":"plasmid","ch":"k12","sec":"mordare","h":"ESBL på receptkortet","html":"ESBL-bakteriernas sax sitter på en plasmid, ofta tillsammans med andra resistensgener. Plasmider kan föras över mellan bakterier ({{go:k9.overforing|K9}}), och därför kan hela paketet av försvar lånas ut på en gång."},{"t":"vagg","ch":"k13","sec":"cellvaggen","h":"Cellulosa eller peptidoglykan","html":"Växtens cellvägg är av cellulosa. Bakteriens cellvägg är av peptidoglykan, långa kolhydratkedjor som är korsbundna med peptider ({{go:k8.byggnad|bakteriens byggnad i K8}}). Djurceller har ingen cellvägg alls."},{"t":"vagg","ch":"k13","sec":"cellvaggen","h":"Penicillin och väggbygget","html":"Penicillin blockerar ett enzym som bakterier behöver för att bygga sin cellvägg av peptidoglukan ({{go:k11.verkan|K11}}). Våra celler har ingen cellvägg, och därför har penicillin inget väggbygge att stoppa hos oss."},{"t":"osmos","ch":"k13","sec":"vakuolen","h":"Blodkropp eller växtcell","html":"I en hypoton lösning går vatten in i cellen genom osmos. Den röda blodkroppen har bara sitt cellmembran och kan spricka. Växtcellen har en cellvägg som tar emot trycket, och därför får den turgor i stället."},{"t":"endo","ch":"k13","sec":"kloroplasten","h":"Kloroplasten, den andra före detta bakterien","html":"Bevisen för att mitokondrien en gång var en bakterie är två membran, eget ringformat DNA och ribosomer av bakterietyp ({{go:k4.mitokondrien|mitokondrien i K4}}). Kloroplasten har samma kännetecken, alltså dubbla membran, en egen ringformad DNA-molekyl och ribosomer, och den kan dessutom dela sig själv."},{"t":"atp","ch":"k13","sec":"kloroplasten","h":"Från solljus till ATP","html":"Växten bildar sina energirika organiska molekyler själv genom fotosyntesen (s. 244), och det är klorofyllet i kloroplasterna som gör att den kan utnyttja ljusenergin (Bi2 bild 25). Sedan förbränns energirik näring i mitokondrierna (cellandningen), där det mesta av cellens ATP bildas ({{go:k6|ATP i K6}}). Växtcellen behöver alltså både solkraftverket och kraftverket."},{"t":"membran","ch":"k13","sec":"kloroplasten","h":"Membran i den gröna fabriken","html":"Kloroplasten har två membran, och tylakoiderna är platta membranblåsor. Plasmodesmata är klädda med cellmembran, så att grannceller hänger ihop genom väggen. Membranen avgränsar rum även i den gröna fabriken ({{go:k3|K3 Cellmembranet}})."}];
